import type { OpenPlay, PenaltyChoice, SetPiece } from '../sim/openPlay';
import { inScrumZone, JUMPERS, type Jumper, PLAY_CARDS, type PlayCard, scrumNeedle, throwMarker } from '../sim/setPieces';
import type { Tunables } from '../sim/tunables';
import { el, onTap } from './dom';

/** Card titles and the one-line idea of each play (GDD 6.3). */
const CARD_TEXT: Record<PlayCard, { name: string; line: string }> = {
  CRASH: { name: 'CRASH BALL', line: 'Hit it up hard off the 9' },
  WIDE: { name: 'GO WIDE', line: 'Skip it to the edge' },
  SWITCH: { name: 'SWITCH', line: 'Scissors back inside' },
  CHIP: { name: 'CHIP & CHASE', line: 'Chip over, wing chases' },
};

/** Running lines for each card's mini diagram: polylines in a 60 x 48 box, ball at the bottom middle. */
const CARD_LINES: Record<PlayCard, string[]> = {
  CRASH: ['30,44 30,6', '18,44 12,10', '42,44 48,10'],
  WIDE: ['30,44 46,40 58,10', '30,44 40,36', '20,44 16,12'],
  SWITCH: ['30,44 44,24 26,6', '40,44 22,22 34,6'],
  CHIP: ['30,44 30,30', '30,30 34,10', '54,44 52,6'],
};

const SVG = 'http://www.w3.org/2000/svg';

function svgEl<K extends keyof SVGElementTagNameMap>(tag: K, attrs: Record<string, string | number>): SVGElementTagNameMap[K] {
  const n = document.createElementNS(SVG, tag);
  for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
  return n;
}

/**
 * The set-piece screens (GDD 6.3, 6.10 to 6.12) over the pitch: play-call cards, the lineout jumper buttons and
 * throw bar, the scrum's CROUCH BIND SET and PUSH dial, the penalty options. Goal kicks use the KICK button's
 * power ring (see Controls); this only shows the distance. Reads the sim each frame, calls it on a tap.
 */
export class SetPieceUi {
  readonly root = el('div', 'sp');
  private readonly title = el('div', 'sp-title');
  private readonly sub = el('div', 'sp-sub');
  private readonly body = el('div', 'sp-body');
  private shown = '';
  private cards: HTMLElement[] = [];
  private clockArc: SVGCircleElement | null = null;
  private barMarker: HTMLElement | null = null;
  private needle: SVGLineElement | null = null;
  private pips: HTMLElement[] = [];
  private lastHits = -1;
  private lastTaps = -1;

  constructor(
    private readonly play: OpenPlay,
    private readonly t: Tunables,
  ) {
    this.root.append(this.title, this.sub, this.body);
    this.root.hidden = true;
    // A tap anywhere on the panel throws (lineout) or pushes (scrum).
    this.root.addEventListener('pointerdown', (e) => {
      const sp = this.play.setPiece;
      if (!sp || (e.target as HTMLElement).closest('button')) return;
      if (sp.kind === 'lineout' && sp.stage === 'throw') this.play.lineoutThrow();
      if (sp.kind === 'scrum' && sp.stage === 'push') this.play.scrumPush();
    });
  }

  /** Per frame. */
  update(): void {
    const sp = this.play.setPiece;
    const key = this.keyOf(sp);
    if (key !== this.shown) {
      this.shown = key;
      this.build(sp);
    }
    if (!sp) return;
    if (sp.kind === 'call' && this.clockArc) {
      const left = Math.max(0, 1 - sp.t / this.t.playCall.seconds);
      this.clockArc.setAttribute('stroke-dashoffset', String(113 * (1 - left)));
    }
    if (sp.kind === 'lineout' && sp.stage === 'throw' && this.barMarker) this.barMarker.style.left = `${throwMarker(sp.t, this.t) * 100}%`;
    if (sp.kind === 'scrum') {
      if (sp.stage === 'set') {
        const k = sp.t / this.t.scrum.setSeconds;
        this.title.textContent = k < 1 / 3 ? 'CROUCH' : k < 2 / 3 ? 'BIND' : 'SET';
      } else if (this.needle) {
        const a = scrumNeedle(sp.t, this.t) * 360;
        this.needle.setAttribute('transform', `rotate(${a} 50 50)`);
        this.needle.classList.toggle('in', inScrumZone(scrumNeedle(sp.t, this.t), this.t));
        if (sp.taps !== this.lastTaps || sp.hits !== this.lastHits) {
          this.lastTaps = sp.taps;
          this.lastHits = sp.hits;
          this.pips.forEach((p, i) => {
            p.className = 'sp-pip' + (i < sp.taps ? (i < sp.hits ? ' hit' : ' miss') : '');
          });
        }
      }
    }
  }

  /** What is on screen: rebuilt only when this changes. */
  private keyOf(sp: SetPiece | null): string {
    if (!sp) return '';
    if (sp.kind === 'call') return `call`;
    if (sp.kind === 'lineout') return `lineout:${sp.side}:${sp.stage}`;
    if (sp.kind === 'scrum') return `scrum:${sp.side}:${sp.stage}`;
    if (sp.kind === 'goal') return `goal:${sp.side}:${sp.stage}`;
    return sp.kind;
  }

  private build(sp: SetPiece | null): void {
    this.body.replaceChildren();
    this.cards = [];
    this.clockArc = null;
    this.barMarker = null;
    this.needle = null;
    this.pips = [];
    this.lastHits = this.lastTaps = -1;
    this.root.className = 'sp';
    if (!sp || sp.kind === 'tap' || (sp.kind === 'goal' && sp.stage === 'flight') || (sp.kind === 'lineout' && sp.stage === 'air')) {
      this.root.hidden = true;
      return;
    }
    this.root.hidden = false;
    this.sub.textContent = '';
    switch (sp.kind) {
      case 'call':
        return this.buildCall(sp);
      case 'lineout':
        return this.buildLineout(sp);
      case 'scrum':
        return this.buildScrum(sp);
      case 'goal':
        this.root.classList.add('sp-light', 'sp-goal');
        this.title.textContent = sp.side === 0 ? (sp.points === this.t.goal.conversionPoints ? 'CONVERSION' : 'KICK AT GOAL') : 'THEIR KICK';
        this.sub.textContent = sp.side === 0 ? `${Math.round(this.play.goalInfo?.distanceM ?? 0)} m: swipe from the ball to the posts` : '';
        return;
      case 'penalty':
        return this.buildPenalty(sp);
    }
  }

  private buildCall(sp: Extract<SetPiece, { kind: 'call' }>): void {
    this.title.textContent = 'CALL THE PLAY';
    this.sub.textContent = 'or the coach picks';
    const clock = svgEl('svg', { viewBox: '0 0 40 40', class: 'sp-clock' });
    clock.append(svgEl('circle', { cx: 20, cy: 20, r: 18, class: 'bg' }));
    this.clockArc = svgEl('circle', { cx: 20, cy: 20, r: 18, class: 'fg', 'stroke-dasharray': 113, 'stroke-dashoffset': 0 });
    clock.append(this.clockArc);
    const row = el('div', 'sp-cards');
    for (const card of PLAY_CARDS) {
      const b = el('button', 'sp-card' + (card === sp.coach ? ' coach' : ''));
      const fig = svgEl('svg', { viewBox: '0 0 60 48', class: 'sp-lines' });
      for (const pts of CARD_LINES[card]) fig.append(svgEl('polyline', { points: pts }));
      fig.append(svgEl('circle', { cx: 30, cy: 44, r: 2.5, class: 'ball' }));
      b.append(fig, el('span', 'sp-card-name', CARD_TEXT[card].name), el('span', 'sp-card-line', CARD_TEXT[card].line));
      if (card === sp.coach) b.append(el('span', 'sp-coach', 'COACH PICK'));
      onTap(b, () => this.play.callPlay(card));
      row.append(b);
      this.cards.push(b);
    }
    this.body.append(clock, row);
  }

  private buildLineout(sp: Extract<SetPiece, { kind: 'lineout' }>): void {
    const ours = sp.side === 0;
    if (sp.stage === 'pick') {
      this.title.textContent = ours ? 'LINEOUT: PICK YOUR JUMPER' : 'THEIR LINEOUT: GUESS THE JUMPER';
      const row = el('div', 'sp-row');
      JUMPERS.forEach((name, j) => {
        const b = el('button', 'sp-btn', name);
        onTap(b, () => this.play.lineoutPick(j as Jumper));
        row.append(b);
      });
      this.body.append(row);
      return;
    }
    if (!ours) {
      this.root.classList.add('sp-light');
      this.title.textContent = 'THEIR THROW';
      return;
    }
    this.title.textContent = 'TAP TO THROW';
    this.sub.textContent = 'in the green';
    const bar = el('div', 'sp-bar');
    const zone = el('div', 'sp-zone');
    const L = this.t.lineout;
    zone.style.left = `${(L.sweetCentre - L.sweetHalf) * 100}%`;
    zone.style.width = `${2 * L.sweetHalf * 100}%`;
    this.barMarker = el('div', 'sp-marker');
    bar.append(zone, this.barMarker);
    this.body.append(bar);
  }

  private buildScrum(sp: Extract<SetPiece, { kind: 'scrum' }>): void {
    if (sp.stage === 'set') {
      this.title.textContent = 'CROUCH';
      this.sub.textContent = sp.side === 0 ? 'our feed' : 'their feed';
      return;
    }
    this.title.textContent = 'PUSH!';
    this.sub.textContent = 'tap when the needle is in the green, three times';
    const S = this.t.scrum;
    const dial = svgEl('svg', { viewBox: '0 0 100 100', class: 'sp-dial' });
    dial.append(svgEl('circle', { cx: 50, cy: 50, r: 40, class: 'rim' }));
    // The green zone: an arc round the dial at zoneCentre plus or minus zoneHalf (0 at the top, clockwise).
    const C = 2 * Math.PI * 40;
    const start = S.zoneCentre - S.zoneHalf;
    dial.append(svgEl('circle', { cx: 50, cy: 50, r: 40, class: 'zone', 'stroke-dasharray': `${C * 2 * S.zoneHalf} ${C}`, 'stroke-dashoffset': String(-C * start), transform: 'rotate(-90 50 50)' }));
    this.needle = svgEl('line', { x1: 50, y1: 50, x2: 50, y2: 14, class: 'needle' });
    dial.append(this.needle);
    const pips = el('div', 'sp-pips');
    for (let i = 0; i < S.taps; i++) {
      const p = el('span', 'sp-pip');
      pips.append(p);
      this.pips.push(p);
    }
    this.body.append(dial, pips);
  }

  private buildPenalty(sp: Extract<SetPiece, { kind: 'penalty' }>): void {
    if (sp.side !== 0) {
      this.root.classList.add('sp-light');
      this.title.textContent = 'PENALTY TO THEM';
      return;
    }
    this.title.textContent = 'PENALTY';
    const row = el('div', 'sp-row');
    const opts: [PenaltyChoice, string][] = [
      ['tap', 'TAP AND GO'],
      ['touch', 'KICK TO TOUCH'],
      ['goal', 'KICK AT GOAL'],
    ];
    for (const [c, name] of opts) {
      const b = el('button', 'sp-btn', name);
      if (c === 'goal' && !this.play.canKickAtGoal) b.disabled = true;
      onTap(b, () => this.play.penaltyChoice(c));
      row.append(b);
    }
    this.body.append(row);
  }
}
