import * as THREE from 'three';
import type { Brand, Kit } from '../brand/types';
import { Bot } from '../sim/bot';
import { OpenPlay, type PlayEvent, SEVEN, type TackleShot } from '../sim/openPlay';
import { Rng, seedFrom } from '../sim/rng';
import { generateTeam } from '../sim/roster';
import teams from '../sim/teams.json';
import type { Tunables } from '../sim/tunables';
import type { Team, TeamInfo, TeamKit } from '../sim/types';
import { Controls } from '../ui/controls';
import { AddendumUi } from '../ui/addendumUi';
import { SetPieceUi } from '../ui/setPieceUi';
import { HowTo } from '../ui/howTo';
import { type MatchSetup, menuUrl } from '../app/setup';
import { opponentAt } from '../sim/difficulty';
import { GroundLines, RuckArc } from './groundLines';
import { el } from '../ui/dom';
import { type Action, type AthleteKit, type AthleteRig, AthletesView, type SquadSpec } from './athletes';
import type { AthleteModel } from './athleteModel';
import { crowdMood, GameAudio, haptic } from './audio';
import { CameraRig } from './camera';
import { createCrowdFans } from './crowdFans';
import { BallView, Confetti, Puff, ReachRing, TargetRing, YouMarker } from './fx';
import { createStage, type SceneStats } from './scene';
import { SkinnedAthletesView } from './skinnedAthletes';

export interface GameDebug {
  /** Players on the pitch (both teams and the referee). */
  onPitch: number;
  home: string;
  away: string;
  /** Live match state, for tests. */
  state(): { phase: string; score: [number, number]; carrier: number | null; events: string[]; nearestDefenderM: number; ballProgressM: number; ballX: number; attack: number; tackle: { t: number; carrier: string; tackler: string; carrierHeadY: number; tacklerHeadY: number } | null };
  /** Test hook: passes to an attacker as a tap on his icon would. */
  passTo(index: number): boolean;
  /** Test hook: start a home lineout, scrum, conversion or penalty at the ball. */
  setPiece(kind: 'lineout' | 'scrum' | 'goal' | 'penalty'): void;
  /** Test hook: our carrier is put over their try line (to see the try card). */
  tryNow(): boolean;
  /** Test hook: the game clock runs out (the half ends at the next stoppage). */
  timeUp(): void;
  /** Test hook: hand the ball to them at the ball's spot, so the user defends. */
  defend(): boolean;
  /** Where the camera is (world metres), for tests. */
  cam(): { x: number; y: number; z: number };
  /** The stick's output right now (x right, y up the screen), for tests. */
  stick(): { x: number; y: number };
}

export interface Game {
  stats: SceneStats;
  debug: GameDebug;
  athletes: 'rigged' | 'primitive';
}

export interface GameOptions {
  container: HTMLElement;
  uiRoot: HTMLElement;
  brand: Brand;
  logo: HTMLImageElement | null;
  mark: HTMLImageElement | null;
  tunables: Tunables;
  matchSeed: string;
  athleteModel: AthleteModel | null;
  /** The self-play bot drives the carrier instead of the controls. */
  selfPlay?: boolean;
  /** Show the 10 second how to play before kick-off. */
  howTo?: boolean;
  /** From team select: opponent, our kit and difficulty. */
  setup: MatchSetup;
}

/**
 * M1 (GDD section 14): open play from halfway. The user runs the carrier with the stick, sprints, passes by tap
 * or hold-and-drag to support runners marked OPEN / TIGHT / MARKED; the AI runs support lines and a defensive
 * line; tackles go to an auto-resolved ruck; carrying over the try line scores. Every outcome comes from
 * src/sim/openPlay.ts; this file only draws it and reads the controls.
 */
export function createGame(o: GameOptions): Game {
  const t = o.tunables;
  const stage = createStage(o.container, o.brand, o.logo, o.mark, t);
  const rng = new Rng(seedFrom(o.matchSeed));

  const infos = teams.teams as TeamInfo[];
  const homeInfo: TeamInfo = { ...infos.find((x) => x.id === 'brand')!, name: o.brand.teamName };
  const awayInfo = opponentAt(infos.find((x) => x.id === o.setup.opponentId) ?? infos[1]!, o.setup.difficulty, t);
  const home = generateTeam(rng, homeInfo, t);
  const away = generateTeam(rng, awayInfo, t);

  const starters = (team: Team) => team.roster.slice(0, SEVEN).map((p) => p.number);
  const squads: SquadSpec[] = [
    { uniform: brandKit(o.brand.kits[o.setup.kit], t), numbers: starters(home), branded: true },
    { uniform: teamKit(awayInfo.kit!, t), numbers: starters(away) },
    { uniform: refKit(t), numbers: [0] },
  ];
  const rig: AthleteRig = o.athleteModel
    ? new SkinnedAthletesView(squads, t, o.athleteModel, { word: o.logo, mark: o.mark })
    : new AthletesView(squads, t);
  stage.scene.add(rig.group);
  // Bodies swap places in the list when the ball changes hands, so a body's own side and shirt pick its athlete.
  const rigIndex = (body: number) => {
    const b = play.bodies[body]!;
    return rig.index(b.side, b.slot);
  };
  const refIndex = rig.index(2, 0);

  // The brand team attacks up the screen (toward -z) and the camera always looks that way: when the away side
  // attacks, it comes down the screen at you.
  const dir = -1 as const;
  const play = new OpenPlay(home, away, dir, t, rng);
  if (o.selfPlay) play.humanDefends = false;
  else play.human = true;
  play.setupKickoff(t.match.kickingTeam === 'home' ? 0 : 1, true);

  const ball = new BallView(t, o.brand.colors.accent);
  const confetti = new Confetti(o.brand, t);
  stage.scene.add(ball.mesh, ball.shadow, confetti.mesh);
  ball.show(true);

  const camera = new CameraRig(stage.camera, t);
  camera.setMode('carrier', dir);
  camera.snapTo(play.ball.x, play.ball.z);

  // UI: score bug, banner, controls. The next man each way is marked by a ring on the grass, not a floating icon.
  const hud = mountHud(o.uiRoot, o.brand, awayInfo.name, t);
  stage.stadium.setScore(homeInfo.name, awayInfo.name, play.score);
  const rings = [new TargetRing(o.brand, t.ui.targetOpacity), new TargetRing(o.brand, t.ui.targetOpacity)];
  const you = new YouMarker(o.brand, t);
  stage.scene.add(you.group);
  // The front rows in 3D, reacting to play (Jonny: "mainly the crowd").
  const fans = createCrowdFans(o.brand, awayInfo.kit!.jersey, t, stage.stadium.seats);
  stage.scene.add(fans.mesh);
  let goalSide: 0 | 1 = 0;
  let goalOn = false;
  /** The commentator: one "what a break" per run, and a tackle call every few tackles. */
  let breakCalled = false;
  let tackleCount = 0;
  const reach = new ReachRing(o.brand, t);
  stage.scene.add(reach.mesh);
  let seenSwitch = play.switchedAt;
  const puff = new Puff(t);
  for (const r of rings) {
    r.mesh.scale.setScalar(t.ui.targetRingM);
    stage.scene.add(r.mesh);
  }
  stage.scene.add(puff.points);

  const controls = new Controls(t, {
    onPass: (side) => {
      // In the moment of the tackle, PASS is an offload; otherwise a pass to the next man that way.
      if (play.offloadOpen ? play.offload(side) : play.passSide(side)) audio.whoosh();
    },
    onSwitch: () => {
      if (play.switchDefender()) audio.juke();
    },
    onTackle: () => {
      play.tackleButton();
    },
    onChase: (on) => play.setChase(on),
    onDive: () => {
      play.diveTackle();
    },
    onKick: (type) => {
      if (play.kick(type)) audio.snap();
    },
    onKickoff: (power) => {
      if (play.kickoffReady && play.kickoffKick(power)) audio.snap();
    },
    onSkip: (side) => {
      if (play.skipPass(side)) audio.whoosh();
    },
    onMove: (kind, side) => {
      const g = play.move(kind, side);
      if (g === null) return;
      audio.catchGrade(g === 'PERFECT' ? 'perfect' : g === 'GOOD' ? 'good' : g === 'MISS' ? 'miss' : 'none');
      if (g === 'NONE') audio.juke();
      else showGrade(g === 'MISS' ? 'EARLY' : g === 'PERFECT' ? 'PERFECT!' : 'GOOD', g === 'MISS');
    },
  });

  // The timing ring (GDD 6.4, reference/28): a lime ring round the carrier shrinking to the inner ring at contact.
  const ringOuter = new THREE.Mesh(
    new THREE.RingGeometry(0.92, 1, 48).rotateX(-Math.PI / 2),
    new THREE.MeshBasicMaterial({ color: o.brand.colors.accent, transparent: true, opacity: 0.95, depthWrite: false }),
  );
  const ringInner = new THREE.Mesh(
    new THREE.RingGeometry(0.85, 1, 48).rotateX(-Math.PI / 2),
    new THREE.MeshBasicMaterial({ color: o.brand.colors.accent, transparent: true, opacity: 0.35, depthWrite: false }),
  );
  ringInner.scale.setScalar(t.ui.ringInnerM);
  for (const m of [ringOuter, ringInner]) {
    m.visible = false;
    m.renderOrder = 5;
    stage.scene.add(m);
  }
  const gradeEl = el('div', 'grade');
  const hintEl = el('div', 'hint', 'SWIPE ON THE RIGHT TO SIDESTEP');
  gradeEl.hidden = hintEl.hidden = true;
  o.uiRoot.append(gradeEl, hintEl);
  let gradeLeft = 0;
  let hintsShown = readHints();
  let ringWasUp = false;
  function showGrade(text: string, miss: boolean): void {
    gradeEl.textContent = text;
    gradeEl.classList.toggle('miss', miss);
    gradeEl.hidden = false;
    gradeLeft = t.ui.gradeSeconds;
  }
  o.uiRoot.append(controls.root);
  // The 10 second how to play (?nohowto skips it); the match holds until it closes.
  const howTo = !o.howTo || o.selfPlay ? null : new HowTo(t, controls.root, () => {});
  if (howTo) o.uiRoot.append(howTo.root);

  const audio = new GameAudio(t);
  const unlock = () => {
    audio.unlock();
    audio.crowd(t.audio.kickoffCrowd);
    window.removeEventListener('pointerdown', unlock);
    window.removeEventListener('keydown', unlock);
  };
  window.addEventListener('pointerdown', unlock);
  window.addEventListener('keydown', unlock);
  stage.stadium.setExcitement(t.stadium.kickoffExcitement);

  const v = new THREE.Vector3();




  // The why strip (GDD 6.13): the numbers behind each big moment, for a couple of seconds.
  const whyEl = el('div', 'why');
  whyEl.hidden = true;
  let whyLeft = 0;
  // Prompts for the moments a thumb has to catch: kick-off aim, intercept.
  const promptEl = el('div', 'prompt');
  promptEl.hidden = true;
  o.uiRoot.append(promptEl);
  const aimRing = new TargetRing(o.brand, 0.95);
  /** Over the landing ring of their kick: the number of our man going for it. */
  const catchTag = el('div', 'catch-tag');
  catchTag.hidden = true;
  o.uiRoot.append(catchTag);
  aimRing.mesh.scale.setScalar(t.ui.targetRingM * 2);
  stage.scene.add(aimRing.mesh);
  o.uiRoot.append(whyEl);
  // Addendum 13 Nov: ruck arc with ADD PLAYER and CALL PLAY, the swipe at goal, the wind, the chase line.
  const toScreen = (x: number, y: number, z: number) => {
    v.set(x, y, z).project(stage.camera);
    return { x: ((v.x + 1) / 2) * o.uiRoot.clientWidth, y: ((1 - v.y) / 2) * o.uiRoot.clientHeight };
  };
  const addUi = new AddendumUi(t, {
    onAddPlayer: () => {
      if (play.addPlayer()) audio.hit(false);
    },
    onCallPlay: () => {
      if (play.openRuckCall()) audio.snap();
    },
    onSwipe: (dx, dy, speed) => {
      // Kick-off (Jonny, 14 Nov 2026): swipe from the ball where it should go; the angle aims, the speed is the power.
      if (play.kickoffReady) {
        const c = play.carrierBody;
        if (!c) return;
        const b0 = toScreen(c.x, 0, c.z);
        const right = toScreen(c.x + 1, 0, c.z).x - b0.x;
        const ko = t.kickoff;
        const power = Math.max(0, Math.min(1, speed / ko.swipeFullPxPerSecond));
        const metres = ko.minM + power * (ko.maxM - ko.minM);
        const aimX = c.x + Math.sign(right || 1) * Math.tan(Math.atan2(dx, dy)) * metres;
        if (play.kickoffSwipe(aimX, power)) audio.snap();
        return;
      }
      const aim = play.goalAim;
      if (!aim) return;
      // The swipe is read against the line from the ball to the posts on screen: along it is dead straight.
      const ball = toScreen(aim.spot.x, t.ball.radiusM, aim.spot.z);
      const posts = toScreen(aim.posts.x, t.goalpost.crossbarHeightM, aim.posts.z);
      const err = Math.atan2(dx, dy) - Math.atan2(posts.x - ball.x, ball.y - posts.y);
      if (play.goalSwipe(aim.angle + err * t.goal.swipeAngleScale * -play.homeDir, speed / t.goal.fullPowerPxPerSecond)) audio.snap();
    },
    onStraightKick: () => {
      const aim = play.goalAim;
      if (aim && play.goalSwipe(aim.angle, aim.power + t.goal.aiOffsetSpread)) audio.snap();
    },
  });
  const lines = new GroundLines(o.brand, t);
  stage.scene.add(lines.group);
  const ruckArc = new RuckArc(t);
  stage.scene.add(ruckArc.group);
  const WHY: readonly PlayEvent['kind'][] = ['broke', 'tackled', 'offload', 'knockOn', 'forward', 'turnover', 'gathered', 'lineout', 'scrum', 'goal', 'call', 'penalty'];
  const setUi = new SetPieceUi(play, t);
  o.uiRoot.append(setUi.root, addUi.root);

  // Name tag over the ball carrier and the try card along the bottom (the reference game's broadcast touches).
  const nameTag = el('div', 'name-tag');
  nameTag.hidden = true;
  const tryCard = el('div', 'try-card');
  tryCard.hidden = true;
  o.uiRoot.append(nameTag, tryCard);
  let tryCardLeft = 0;
  let penCutWas = false;
  /** The try scorer's athlete (fixed through any possession swap) for the close-up, or -1. */
  let scorerRig = -1;
  let closeWas = false;
  const ordinal = (n: number) => `${n}${n % 10 === 1 && n % 100 !== 11 ? 'st' : n % 10 === 2 && n % 100 !== 12 ? 'nd' : n % 10 === 3 && n % 100 !== 13 ? 'rd' : 'th'}`;
  const showTryCard = (who: number | undefined) => {
    const b = who === undefined ? null : play.bodies[who];
    if (!b) return;
    const team = b.side === 0 ? homeInfo.name : awayInfo.name;
    const n = play.log.filter((x) => x.kind === 'try' && x.who !== undefined && play.bodies[x.who]?.side === b.side).length;
    tryCard.replaceChildren(
      el('span', 'tc-num', String(b.player.number)),
      el('span', 'tc-name', `${b.player.firstName.charAt(0)}. ${b.player.lastName}`.toUpperCase()),
      el('span', 'tc-what', 'TRY'),
      el('span', 'tc-stat', `${ordinal(Math.max(1, n))} try for ${team} this match`),
    );
    tryCard.classList.toggle('away', b.side === 1);
    tryCard.hidden = false;
    tryCardLeft = t.ui.tryCardSeconds;
  };
  const wipe = el('div', 'wipe');
  wipe.hidden = true;
  const wipeBand = el('div', 'wipe-band');
  if (o.logo) {
    const img = o.logo.cloneNode() as HTMLImageElement;
    img.className = 'wipe-logo';
    wipeBand.append(img);
  }
  wipe.append(el('div', 'wipe-stripe'), wipeBand, el('div', 'wipe-stripe late'));
  o.uiRoot.append(wipe);
  // Half time and full time (GDD 6.13, addendum 2).
  const breakCard = el('div', 'match-card');
  breakCard.hidden = true;
  breakCard.dataset.testid = 'match-card';
  o.uiRoot.append(breakCard);
  const statRow = (label: string, a: string | number, b: string | number) => {
    const row = el('div', 'mc-row');
    row.append(el('span', 'mc-a', String(a)), el('span', 'mc-label', label), el('span', 'mc-b', String(b)));
    return row;
  };
  const scoreLine = () => {
    const line = el('div', 'mc-score');
    line.append(el('span', 'mc-team', homeInfo.name.toUpperCase()), el('span', 'mc-pts', `${play.score[0]}`), el('span', 'mc-dash', ':'), el('span', 'mc-pts', `${play.score[1]}`), el('span', 'mc-team', awayInfo.name.toUpperCase()));
    return line;
  };
  const showHalftime = () => {
    breakCard.className = 'match-card half';
    breakCard.replaceChildren(el('div', 'mc-title', 'HALF TIME'), scoreLine(), el('div', 'mc-hint', 'TAP TO START THE SECOND HALF'));
    breakCard.hidden = false;
    breakCard.onpointerdown = () => play.skipHalftime();
  };
  const showFulltime = () => {
    const st = play.stats;
    const [h, a] = play.score;
    const result = h > a ? 'WIN' : h < a ? 'LOSS' : 'DRAW';
    const pct = (side: 0 | 1) => (st.passes[side] ? `${Math.round((100 * st.passesCaught[side]) / st.passes[side])}%` : '-');
    const potm = play.playerOfTheMatch;
    const stars = el('div', 'mc-stars');
    for (let k = 1; k <= 3; k++) stars.append(el('span', k <= play.stars ? 'mc-star on' : 'mc-star', '★'));
    const again = el('button', 'mc-btn', 'REMATCH');
    again.dataset.testid = 'rematch';
    again.onclick = () => {
      // A new match: the same page with a fresh seed.
      const u = new URL(location.href);
      u.searchParams.delete('seed');
      location.href = u.toString();
    };
    const menu = el('button', 'mc-btn mc-btn-ghost', 'MENU');
    menu.dataset.testid = 'to-menu';
    menu.onclick = () => {
      location.href = menuUrl(location.href);
    };
    const buttons = el('div', 'mc-btns');
    buttons.append(menu, again);
    breakCard.className = 'match-card full';
    breakCard.replaceChildren(
      el('div', 'mc-title', 'FULL TIME'),
      el('div', `mc-badge ${result.toLowerCase()}`, result),
      scoreLine(),
      stars,
      statRow('TRIES', st.tries[0], st.tries[1]),
      statRow('LINE BREAKS', st.breaks[0], st.breaks[1]),
      statRow('TACKLES MADE', st.tackles[0], st.tackles[1]),
      statRow('PASSES CAUGHT', pct(0), pct(1)),
      statRow('RUCKS WON', st.rucksWon[0], st.rucksWon[1]),
      el('div', 'mc-potm', potm ? `PLAYER OF THE MATCH: ${potm.number} ${potm.name.toUpperCase()} (${potm.side === 0 ? homeInfo.name : awayInfo.name})` : ''),
      buttons,
    );
    breakCard.onpointerdown = null;
    breakCard.hidden = false;
  };
  const playWipe = () => {
    wipe.hidden = false;
    wipe.classList.remove('go');
    void wipe.offsetWidth;
    wipe.classList.add('go');
  };
  wipe.addEventListener('animationend', (ev) => {
    if ((ev.target as HTMLElement).classList.contains('wipe-band')) wipe.hidden = true;
  });
  /** The man kicking (rig index) and how long ago, for the kick clip; and who had the ball last frame. */
  let kickAnim = { ri: -1, t: Infinity };
  /** The passer (rig index), how long ago, and which way: 1 to his own left, -1 to his right. */
  let passAnim = { ri: -1, t: Infinity, side: 1 };
  let lastCarrierRig = -1;
  const onEvent = (e: PlayEvent) => {
    if (e.call) hud.banner(e.call, e.kind === 'try');
    if (WHY.includes(e.kind) && e.detail) {
      const why = e.detail.replace(/ percent/g, '%');
      whyEl.textContent = why.charAt(0).toUpperCase() + why.slice(1);
      whyEl.hidden = false;
      whyLeft = t.ui.whySeconds;
    }
    switch (e.kind) {
      case 'halftime':
        audio.whistle(0, 'long');
        showHalftime();
        break;
      case 'fulltime': {
        // Three blasts for full time; the crowd says how it went.
        audio.whistle(0, 'short');
        audio.whistle(0.4, 'short');
        audio.whistle(0.8, 'long');
        if (play.score[0] > play.score[1]) {
          audio.win();
          fans.react('homeJoy');
        } else if (play.score[0] < play.score[1]) {
          audio.groan();
          fans.react('awayJoy');
        } else audio.applause(true);
        showFulltime();
        break;
      }
      case 'caught':
        audio.catchThud();
        break;
      case 'tackled':
        audio.hit(play.lastTackle?.big ?? false);
        tackleCount++;
        if (play.lastTackle?.big) audio.say('bighit');
        else if (tackleCount % t.audio.tackleCallEvery === 0) audio.say('tackle');
        haptic(t.fx.hapticHitMs);
        camera.addShake(t.fx.shakeTackle, true);
        if (play.lastTackle) {
          // Athletes, not body indices: a big hit can swap possession (and the body list) in the same step.
          tackle = { shot: play.lastTackle, t: 0, rc: rigIndex(play.lastTackle.carrier), rt: rigIndex(play.lastTackle.tackler) };
          puff.burst(play.lastTackle.from.cx, play.lastTackle.from.cz);
          hitStop = t.fx.hitStopSeconds;
        }
        break;
      case 'pass':
        if (lastCarrierRig >= 0 && e.who !== undefined) {
          // Which side of the passer the receiver is, as he faces: left is + across his facing.
          const yaw = rig.facing(lastCarrierRig);
          const r = play.bodies[e.who]!;
          rig.headPosition(lastCarrierRig, v);
          const dx = r.x - v.x;
          const dz = r.z - v.z;
          passAnim = { ri: lastCarrierRig, t: 0, side: Math.cos(yaw) * dx - Math.sin(yaw) * dz >= 0 ? 1 : -1 };
        }
        break;
      case 'kick':
        kickAnim = { ri: e.who !== undefined ? rigIndex(e.who) : lastCarrierRig, t: 0 };
        break;
      case 'broke':
        audio.hit(false);
        if (play.attackSide === 0) audio.say('through');
        camera.addShake(t.fx.shakeBroke);
        break;
      case 'try': {
        showTryCard(e.who);
        if (e.who !== undefined) scorerRig = rigIndex(e.who);
        replayWait = t.replay.delaySeconds;
        audio.try(play.attackSide === 0);
        audio.say(play.attackSide === 0 ? 'try' : 'tryaway', true);
        fans.react(play.attackSide === 0 ? 'homeJoy' : 'awayJoy');
        haptic(t.fx.hapticTdMs);
        stage.stadium.setExcitement(1);
        confetti.burst(play.ball.x, play.ball.z);
        hud.setScore(play.score);
        stage.stadium.setScore(homeInfo.name, awayInfo.name, play.score);
        break;
      }
      case 'goal':
        // Conversions and penalty goals count too: the score bug and the big screens follow.
        hud.setScore(play.score);
        stage.stadium.setScore(homeInfo.name, awayInfo.name, play.score);
        if (e.call === 'CONVERTED!' || e.call === 'GOAL!' || e.call === 'MISSED') audio.say(e.call === 'MISSED' ? 'wide' : 'over');
        if (e.call === 'CONVERTED!' || e.call === 'GOAL!') {
          if (goalSide === 0) {
            audio.applause(true);
            fans.react('homeJoy');
          } else audio.groan();
          stage.stadium.setExcitement(1);
        } else if (e.call === 'MISSED') {
          if (goalSide === 0) {
            audio.groan();
            fans.react('groan');
          } else audio.applause(false);
        }
        break;
      case 'forward':
      case 'knockOn':
        audio.whistle();
        audio.say(e.kind === 'forward' ? 'forward' : 'knockon');
        // Our mistake: hands on heads and a groan; theirs: a cheer.
        if (play.attackSide === 0) {
          fans.react('groan');
          audio.groan();
        } else audio.applause(false);
        break;
      case 'turnover':
        audio.whistle();
        audio.say('turnover');
        if (play.attackSide === 0) {
          // We just won it back.
          fans.react('applause');
          audio.applause(false);
        } else {
          fans.react('groan');
          audio.groan();
        }
        break;
      case 'touch':
        audio.whistle();
        audio.say('touch');
        break;
      case 'offload':
        audio.say('offload');
        break;
      case 'penalty': {
        if (e.call.startsWith('PENALTY')) {
          audio.whistle();
          audio.say('penalty');
          // Given against us: the home crowd boos the referee; for us, a cheer.
          if (play.penaltyTo === 1) audio.boo();
          else if (play.penaltyTo === 0) audio.applause(false);
        }
        break;
      }
      default:
        break;
    }
  };

  /** The tackle being drawn, and the brief freeze on impact. */
  let tackle: { shot: TackleShot; t: number; rc: number; rt: number } | null = null;
  let hitStop = 0;

  const step = t.openPlay.fixedStepSeconds;
  const bot = o.selfPlay ? new Bot(t) : null;
  let acc = 0;
  let lastPhase = play.phase;
  // The try replay (Jonny, 14 Nov 2026): the last few seconds as drawn, played back once after a try.
  const replayBuf: ReplayFrame[] = [];
  let replayWait = -1;
  let replay: { frames: ReplayFrame[]; t: number; k: number } | null = null;
  let rec = new Map<number, Placed>();
  const place = (ri: number, x: number, z: number, action?: Action, face?: number | null) => {
    rec.set(ri, { x, z, action, face });
    rig.place(ri, x, z, action, face);
  };
  const replayBadge = el('div', 'replay-badge', 'REPLAY');
  replayBadge.hidden = true;
  o.uiRoot.append(replayBadge);
  stage.start((dt) => {
    controls.update();
    // Hit stop: the world holds for a beat on a big tackle.
    if (hitStop > 0) {
      hitStop -= dt;
      dt *= t.fx.slowmoScale;
    }
    if (howTo?.active) howTo.update(dt);
    else if (!replay) acc += dt;
    // A try waits a beat, then the replay starts; the match holds until it ends.
    if (replayWait >= 0) {
      replayWait -= dt;
      if (replayWait < 0 && replayBuf.length > 0) {
        replay = { frames: replayBuf.splice(0), t: 0, k: 0 };
        const f0 = replay.frames[0]!;
        for (const [ri, p] of f0.rigs) rig.teleport(ri, p.x, p.z, p.action ?? 'idle', p.face ?? rig.facing(ri));
        replayBadge.hidden = false;
        tryCard.hidden = true;
        camera.setMode('call', dir);
        camera.snapTo(f0.focus.x, f0.focus.z);
      }
    }
    while (acc >= step) {
      acc -= step;
      if (bot && play.attackSide === 0) {
        if (play.kickoffReady) play.kickoffKick(0.75);
        const d = bot.decide(play, step);
        if (d.passSide !== null && play.passSide(d.passSide)) audio.whoosh();
        if (d.step !== null) play.move('step', d.step);
        if (d.addPlayer) play.addPlayer();
        play.step(step, d.input);
      } else {
        play.step(step, { sx: controls.stick.x, sy: controls.stick.y, sprint: controls.sprint });
      }
      for (const e of play.events.splice(0)) onEvent(e);
    }
    if (play.phase !== lastPhase) {
      // A branded wipe covers the cut into a set piece or kick-off after a stoppage (as the reference game does).
      if ((play.phase === 'setpiece' && lastPhase === 'dead') || (play.phase === 'kickoff' && (lastPhase === 'dead' || lastPhase === 'setpiece'))) playWipe();
      if (play.phase === 'play' && lastPhase === 'dead') {
        stage.stadium.setExcitement(t.stadium.kickoffExcitement);
        camera.snapTo(play.ball.x, play.ball.z);
      }
      if (lastPhase === 'halftime') breakCard.hidden = true;
      // The referee starts each kick-off with two quick pips.
      if (play.phase === 'kickoff') audio.whistle(t.audio.whistleDelaySeconds, 'start');
      lastPhase = play.phase;
    }
    // The crowd follows play: breaks and closing on the line lift it (GDD audio: crowd tied to play intensity).
    {
      const c = play.carrierBody;
      const mood = crowdMood(
        {
          live: play.phase === 'play' && !!c && !replay,
          homeAttacking: play.attackSide === 0,
          gapM: c ? play.nearestDefender(c.x, c.z) : Infinity,
          nearLine: c ? play.progress(c.z) / play.tryLine : 0,
        },
        t,
      );
      audio.mood(mood);
      // Our man clear of every defender: the commentator calls the break, once a run.
      if (mood !== null && play.attackSide === 0 && c && play.nearestDefender(c.x, c.z) >= t.audio.mood.breakFullM) {
        if (!breakCalled) audio.say('break');
        breakCalled = true;
      } else if (play.phase !== 'play') breakCalled = false;
      if (mood !== null) {
        stage.stadium.setExcitement(mood);
        fans.setCheer(mood);
      }
      // A kick at goal: the crowd hushes, then claps the kicker up.
      const sp = play.setPiece;
      if (sp?.kind === 'goal') {
        if (!goalOn) fans.react('applause');
        goalOn = true;
        goalSide = sp.side;
      } else goalOn = false;
    }
    // Controls by situation: attacking, defending, lined up to kick off or at goal, or a set piece (its own panel).
    const kickingOff = play.phase === 'kickoff' && play.attackSide === 0;
    // While the how to play is up, the buttons read as the card says, all lit.
    const intro = howTo?.active ? howTo : null;
    controls.setMode(intro ? intro.mode : kickingOff ? 'kickoff' : play.attackSide === 1 ? 'defence' : 'attack');
    controls.setSweet(null);
    controls.setKickOn(intro ? intro.kickShown : play.kickOn);
    controls.setEnabled(
      intro ? true : play.phase === 'setpiece' ? false : kickingOff ? play.kickoffReady : play.attackSide === 1 ? play.userDefending : play.phase === 'play' || play.offloadOpen,
    );
    setUi.update();
    // A penalty opens on the referee for a moment (the reference game's ref cut-in), then the choices appear.
    const spNow = play.setPiece;
    const penCut = !!spNow && spNow.kind === 'penalty' && spNow.t < t.penalty.cutSeconds;
    setUi.root.style.visibility = penCut ? 'hidden' : '';
    controls.setOffload(play.offloadOpen);
    const cb = play.carrierBody;
    controls.setTouchFinder(!!cb && play.attackSide === 0 && t.field.widthM / 2 - Math.abs(cb.x) < t.kicks.touchFinderM);
    const meD = play.userDefending ? play.bodies[play.userDef]! : null;
    // Tackle reach: the ring round the user's defender lights when the carrier is inside it (dive reach while
    // TACKLE is held), and the button pulses with it.
    const reachM = play.chasing ? t.userDefence.diveReachM : t.userDefence.reachM;
    const gap = meD && cb ? Math.hypot(cb.x - meD.x, cb.z - meD.z) : Infinity;
    const inReach = !!meD && play.phase === 'play' && gap <= t.userDefence.reachM;
    const diveNow = !!meD && play.phase === 'play' && play.chasing && gap <= t.userDefence.diveReachM;
    controls.setTackleReady(inReach || diveNow || play.interceptOpen);
    if (meD && cb && play.phase === 'play' && !howTo?.active && meD.down <= 0) reach.show(meD.x, meD.z, reachM, inReach || diveNow, dt);
    else reach.hide();
    if (play.switchedAt !== seenSwitch) {
      seenSwitch = play.switchedAt;
      you.pop();
    }
    // The ruck arc (the chance the attack keeps it), ADD PLAYER, CALL PLAY, the swipe at goal and the wind.
    const live = play.phase === 'ruck' && play.ruckLive && play.setPiece === null;
    const rb = play.ruckBar;
    const rs = toScreen(play.ball.x, 0, play.ball.z);
    const gi = play.goalInfo;
    addUi.update({
      // The arc is painted on the grass now; the screen layer keeps the word and the ADD PLAYER button.
      ruck: live || play.ruckWordLeft > 0 ? { on: false, chance: rb.chance, defending: rb.defending, canAdd: live && play.canAddPlayer && !play.offloadOpen, x: rs.x, y: rs.y - t.ui.ruckArcLiftPx } : null,
      ruckWord: play.ruckWordLeft > 0 ? play.ruckWord : '',
      callChip: play.callChipOn,
      goalSwipe: (!!gi && gi.side === 0) || kickingOff && play.kickoffReady,
      swipeKind: kickingOff ? 'kickoff' : 'goal',
      goalLine: (() => {
        if (kickingOff) {
          const c = play.carrierBody;
          if (!c || !play.kickoffReady) return null;
          const b = toScreen(c.x, t.ball.radiusM, c.z);
          const p = toScreen(play.kickoffAimX, 0, c.z + play.dir * t.kickoff.handAheadM);
          return { bx: b.x, by: b.y, px: p.x, py: p.y };
        }
        const aim = play.goalAim;
        if (!aim || !gi || gi.side !== 0) return null;
        const b = toScreen(aim.spot.x, t.ball.radiusM, aim.spot.z);
        const p = toScreen(aim.posts.x, t.goalpost.crossbarHeightM, aim.posts.z);
        return { bx: b.x, by: b.y, px: p.x, py: p.y };
      })(),
      wind: { mph: play.wind.mph, arrowDeg: play.wind.mph === 0 ? 0 : play.wind.dirX * -play.homeDir > 0 ? 90 : -90 },
    });
    if (live) {
      // Filled in the attack's colour (lime when it is ours) by the chance they keep it.
      const atkHome = play.attackSide === 0;
      ruckArc.show(play.ball.x, play.ball.z, play.dir, rb.chance / 100, atkHome ? o.brand.colors.accent : awayInfo.kit!.jersey, atkHome ? awayInfo.kit!.jersey : o.brand.colors.accent);
    } else ruckArc.hide();
    lines.setChase(play.chaseLine);
    lines.setPlay([], 0);
    lines.update(dt);
    // Prompts and the kick-off aim ring.
    const prompt = kickingOff ? (play.kickoffReady ? 'SWIPE FROM THE BALL TO KICK' : '') : play.interceptOpen ? 'INTERCEPT! TAP TACKLE' : diveNow ? 'LET GO TO DIVE' : '';
    promptEl.hidden = !prompt;
    if (prompt) promptEl.textContent = prompt;
    if (kickingOff && cb) {
      const ko = t.kickoff;
      const metres = ko.minM + (controls.power || 0.5) * (ko.maxM - ko.minM);
      aimRing.show(play.kickoffAimX, cb.z + play.dir * metres);
      aimRing.update(dt);
      aimRing.mesh.scale.multiplyScalar(t.ui.targetRingM * 2);
    } else if (play.phase === 'kick' && play.kickBall) {
      // Any kick in the air: a ring where it comes down; their kick also names our man going for it.
      const kb = play.kickBall;
      aimRing.show(kb.tx, kb.tz);
      aimRing.update(dt);
      aimRing.mesh.scale.multiplyScalar(t.ui.targetRingM * 2);
      const ci = play.kickCatcher;
      if (ci >= 0) {
        const p = toScreen(kb.tx, 0, kb.tz);
        catchTag.textContent = `${play.bodies[ci]!.player.number}`;
        catchTag.style.left = `${p.x}px`;
        catchTag.style.top = `${p.y}px`;
        catchTag.hidden = false;
      } else catchTag.hidden = true;
    } else aimRing.hide();
    if (!(play.phase === 'kick' && play.kickCatcher >= 0)) catchTag.hidden = true;
    if (whyLeft > 0) {
      whyLeft -= dt;
      if (whyLeft <= 0) whyEl.hidden = true;
    }
    const carrier = play.carrierBody;
    // The stamina ring belongs to whoever the stick runs: the carrier attacking, the user's defender defending.
    const mine = play.userDefending ? play.bodies[play.userDef]! : carrier && carrier.side === 0 ? carrier : null;
    controls.setStamina(mine ? mine.stamina : 100, mine?.exhausted ?? false);

    // Players. The two in a tackle are drawn from the tackle shot. The tackler closes in low with his arms out
    // and wraps the carrier round the legs; on the hit the carrier's momentum carries them on together and he
    // topples forward, ball out in front, while the tackler goes to ground with his arms locked round the legs.
    // After a try: a close-up of the scorer for the stoppage (the reference game's celebration shot).
    const tryClose = play.phase === 'dead' && scorerRig >= 0 && play.log.at(-1)?.kind === 'try';
    if (!tryClose && play.phase !== 'dead') scorerRig = -1;
    if (tackle) tackle.t += dt;
    const tk = tackle && tackle.t < t.formation.tackledDownSeconds ? tackle : null;
    rec = new Map();
    const r = t.referee;
    const refX = play.ball.x * r.followX + r.offsetX;
    const refZ = play.ball.z - play.dir * r.trailM;
    const rf = replay ? replayFrame(replay, dt * t.replay.speed) : null;
    if (rf) {
      for (const [ri, p] of rf.rigs) rig.place(ri, p.x, p.z, p.action, p.face);
    } else {
      for (const [i, b] of play.bodies.entries()) {
        const ri = rigIndex(i);
        if (tk && (ri === tk.rc || ri === tk.rt)) {
          const sh = tk.shot;
          const T = t.tackle;
          const hit = T.staggerSeconds;
          const pre = Math.min(1, tk.t / hit);
          const post = easeOut(Math.max(0, Math.min(1, (tk.t - hit) / (T.animSeconds - hit))));
          let ux = sh.to.cx - sh.from.cx;
          let uz = sh.to.cz - sh.from.cz;
          const ul = Math.hypot(ux, uz);
          if (ul > 1e-3) {
            ux /= ul;
            uz /= ul;
          } else {
            ux = 0;
            uz = play.dir;
          }
          // From the tackler toward the carrier at contact.
          let nx = sh.from.cx - sh.from.tx;
          let nz = sh.from.cz - sh.from.tz;
          const nl = Math.hypot(nx, nz) || 1;
          nx /= nl;
          nz /= nl;
          const headOn = nx * ux + nz * uz < T.headOnDot;
          const drive = headOn ? 0 : T.sideDriveM * post;
          const cx = sh.from.cx + (sh.to.cx - sh.from.cx) * post + nx * drive;
          const cz = sh.from.cz + (sh.to.cz - sh.from.cz) * post + nz * drive;
          if (ri === tk.rc) {
            // He is turned by the hit as he goes, away from the tackler, so he lands on his side (a fall straight
            // away from the camera barely shows).
            const away = Math.sign(ux * nz - uz * nx) || 1;
            place(rigIndex(i), cx, cz, tk.t < hit ? 'carry' : 'tackled', Math.atan2(ux, uz) + away * T.twistRad * post);
          } else {
            const face = Math.atan2(nx, nz);
            const gx = cx - nx * T.wrapGapM;
            const gz = cz - nz * T.wrapGapM;
            if (tk.t < hit) {
              const e = easeOut(pre);
              place(rigIndex(i), sh.from.tx + (gx - sh.from.tx) * e, sh.from.tz + (gz - sh.from.tz) * e, 'wrap', face);
            } else place(rigIndex(i), gx, gz, 'tackling', face);
          }
          continue;
        }
        const speed = Math.hypot(b.vx, b.vz);
        let action: Action = b.down > 0 ? 'down' : i === play.carrier ? 'carry' : speed > t.athlete.movingMps ? 'run' : 'stance';
        let face = speed > t.athlete.movingMps ? null : b.team === 0 ? attackFace(play.dir) : attackFace(play.dir) + Math.PI;
        // Set pieces: the front rows bind and push, the jumper goes up for it, the thrower faces in from touch.
        const role = play.phase === 'setpiece' ? play.setPieceRole[i] : null;
        if (role === 'scrum') action = 'block';
      else if (role === 'kicker' && play.setPiece?.kind === 'goal' && play.setPiece.stage === 'flight') action = 'kick';
        else if (role === 'jumper') action = 'catch';
        else if (role === 'thrower') {
          action = play.setPiece?.kind === 'lineout' && play.setPiece.stage === 'air' ? 'throw' : 'catch';
          face = b.x > 0 ? -Math.PI / 2 : Math.PI / 2;
        }
        // The try scorer celebrates, turned to the close-up camera.
        if (rigIndex(i) === kickAnim.ri && kickAnim.t < t.athlete.kickHoldSeconds) action = 'kick';
        if (rigIndex(i) === passAnim.ri && passAnim.t < t.athlete.passHoldSeconds && action !== 'down') action = passAnim.side > 0 ? 'passL' : 'passR';
        // The receiver shows his hands as the pass comes.
        if (play.phase === 'flight' && play.flight && i === play.flight.to && play.flight.dur - play.flight.t < t.athlete.receiveLeadSeconds) action = 'receive';
        if (tryClose && rigIndex(i) === scorerRig) {
          action = 'stance';
          face = attackFace(play.homeDir);
        }
        place(rigIndex(i), b.x, b.z, action, face);
      }
      place(refIndex, refX, refZ, penCut ? 'idle' : undefined, penCut ? attackFace(play.homeDir) : null);
    }
    rig.update(rf ? dt * t.replay.speed : dt);
    if (!rf) {
      kickAnim.t += dt;
      passAnim.t += dt;
    }
    lastCarrierRig = play.carrier !== null ? rigIndex(play.carrier) : -1;

    // Ball.
    let ballRec: ReplayFrame['ball'];
    if (rf) {
      ballRec = rf.ball;
      if (rf.ball.held >= 0) ball.hold(rig.carryPosition(rf.ball.held, v), rig.facing(rf.ball.held));
      else ball.set(rf.ball.x, rf.ball.h, rf.ball.z, rf.ball.fly);
    } else if (carrier && play.carrier !== null) {
      const ri = rigIndex(play.carrier);
      ball.hold(rig.carryPosition(ri, v), rig.facing(ri));
      ballRec = { held: ri, x: 0, h: 0, z: 0, fly: false };
    } else {
      const fly = play.phase === 'flight' || (play.phase === 'kick' && play.ball.h > t.ball.radiusM * 2);
      ball.set(play.ball.x, play.ball.h, play.ball.z, fly);
      ballRec = { held: -1, x: play.ball.x, h: play.ball.h, z: play.ball.z, fly };
    }
    ball.update(dt);
    // Record the frame as drawn, keeping the last few seconds (not while a replay or the try stoppage runs).
    if (!rf && play.phase !== 'dead') {
      replayBuf.push({ dt, rigs: rec, ball: ballRec, focus: { x: play.ball.x, z: play.ball.z } });
      let total = replayBuf.reduce((n, f) => n + f.dt, 0);
      while (total > t.replay.seconds && replayBuf.length > 1) total -= replayBuf.shift()!.dt;
    }

    // Rings on the grass under the next man each way: who PASS◀ and PASS▶ throw to.
    const targets = play.phase === 'play' && carrier && play.attackSide === 0 ? [play.sideTarget(-1), play.sideTarget(1)] : [-1, -1];
    targets.forEach((ti, k) => {
      const ring = rings[k]!;
      if (ti >= 0) {
        const b = play.bodies[ti]!;
        ring.show(b.x, b.z);
      } else ring.hide();
      ring.update(dt);
      ring.mesh.scale.multiplyScalar(t.ui.targetRingM);
    });
    if (play.phase === 'play' && carrier) controls.setPassable(targets[0]! >= 0, targets[1]! >= 0);
    // The man you control: the carrier, or the man the ball is flying to.
    // Defending, the marker sits under the user's defender; attacking, under the home carrier.
    const youAt = play.userDefending ? play.bodies[play.userDef]! : carrier && play.carrier !== null && carrier.side === 0 && play.phase !== 'kickoff' ? carrier : null;
    // Cut-ins (try close-up, the kick at goal, the referee) are clean shots: no controls, no marker.
    const cutIn = tryClose || penCut || (play.setPiece?.kind === 'goal');
    const held = play.phase === 'halftime' || play.phase === 'fulltime';
    controls.root.style.visibility = cutIn || held ? 'hidden' : '';
    hud.setClock(play.clockText);
    if (youAt && !cutIn && !(tk && play.carrier !== null && rigIndex(play.carrier) === tk.rc)) you.show(youAt.x, youAt.z);
    else you.hide();
    you.update(dt);
    puff.update(dt);

    // Timing ring and the first-times hint.
    // The sidestep ring and its hint are for our carrier only: defending, the move is theirs, not the user's.
    const rc = play.carrierBody;
    const rk = rc && rc.side === 0 ? play.ringK() : null;
    if (rk !== null && rc) {
      const r = t.ui.ringInnerM + (t.ui.ringOuterM - t.ui.ringInnerM) * rk;
      ringOuter.scale.set(r, 1, r);
      ringOuter.position.set(rc.x, 0.04, rc.z);
      ringInner.position.set(rc.x, 0.035, rc.z);
      ringOuter.visible = ringInner.visible = true;
      if (!ringWasUp) {
        hintEl.hidden = hintsShown >= t.ui.hintTimes;
        hintsShown++;
        writeHints(hintsShown);
      }
    } else {
      ringOuter.visible = ringInner.visible = false;
      hintEl.hidden = true;
    }
    ringWasUp = rk !== null;
    if (gradeLeft > 0) {
      gradeLeft -= dt;
      if (gradeLeft <= 0) gradeEl.hidden = true;
    }
    confetti.update(dt);
    stage.stadium.update(dt);
    fans.update(dt);
    // The camera stops short of the try line so a try is framed from the field, not from inside the posts.
    const camLimit = play.tryLine - t.camera.tryLineMarginM;
    // Frame the ball and the attacking line together: aim between the ball and the middle of the line, so the
    // backline is in shot, not just the man with the ball.
    let lineX = 0;
    for (let i = 0; i < SEVEN; i++) lineX += play.bodies[i]!.x / SEVEN;
    const k = t.camera.lineFrameFraction;
    let fx = play.ball.x * (1 - k) + lineX * k;
    let fz = play.ball.z;
    if (kickingOff && cb) {
      // Kick-off: frame the kicker and where the kick will land.
      fz = cb.z + play.dir * (t.kickoff.minM + (controls.power || 0.5) * (t.kickoff.maxM - t.kickoff.minM)) * t.camera.kickoffFrame;
      fx = play.kickoffAimX * t.camera.kickoffFrame;
    } else if (play.phase === 'kick' && play.kickBall && play.kickCatcher >= 0) {
      // Their kick in the air: frame where it comes down, our catcher under it and their chasers coming.
      fx = play.kickBall.tx;
      fz = play.kickBall.tz + play.homeDir * t.camera.catchAheadM;
    } else if (meD) {
      // Defending: between the user's defender and the ball, from higher and further back, so the carrier and
      // the attacking line coming at him are both in shot (the reference game defends from a wide view).
      fx = meD.x * t.camera.defenceFrame + play.ball.x * (1 - t.camera.defenceFrame);
      fz = meD.z * t.camera.defenceFrame + play.ball.z * (1 - t.camera.defenceFrame);
    }
    const sp = play.setPiece;
    const theirKick = !!sp && sp.kind === 'goal' && sp.side === 1;
    if (theirKick) {
      // Their kick at goal comes toward our posts: frame the kicker from the wide view, not from on our line.
      fx = sp.x;
      fz = sp.z;
    }
    // Their try and their kick at goal happen at our end: high above our posts, so the in-goal does not fill the shot.
    const theirScore = theirKick || (play.phase === 'dead' && play.attackSide === 1 && play.log.at(-1)?.kind === 'try');
    const wide = theirScore || kickingOff || (!!meD && play.phase !== 'setpiece');
    camera.setMode(wide ? 'ball' : 'carrier', dir);
    // Our kick-off sits back far enough to show our whole chase line beside the kicker (Jonny, 14 Nov 2026).
    camera.setPullback(wide ? (theirScore ? t.camera.theirKickPullbackM : kickingOff ? t.camera.kickoffPullbackM : t.camera.defencePullbackM) : 0);
    // Only the far (attacking) end is held short; at your own end the camera can sit back over the in-goal.
    const lo = play.homeDir < 0 ? -camLimit : -play.tryLine;
    const hi = play.homeDir < 0 ? play.tryLine : camLimit;
    camera.follow(fx, Math.max(lo, Math.min(hi, fz)));
    if (penCut) {
      camera.setMode('celebrate', dir);
      camera.setPullback(0);
      // A cut, not a pan: jump straight to the referee, and straight back out when it ends.
      if (!penCutWas) camera.snapTo(refX, refZ);
      else camera.follow(refX, refZ);
    } else if (penCutWas) camera.snapTo(fx, Math.max(lo, Math.min(hi, fz)));
    penCutWas = penCut;
    // The kick at goal: low behind the kicker on the line to the posts.
    const aim = play.goalAim;
    if (aim && play.setPiece?.kind === 'goal' && play.setPiece.side === 0) {
      camera.setMode('aim', dir);
      camera.setAim(aim.posts.x - aim.spot.x, aim.posts.z - aim.spot.z);
      camera.follow(aim.spot.x, aim.spot.z);
    }
    // The try close-up: cut in on the scorer, cut back out after.
    if (tryClose) {
      const sb = play.bodies.find((_, k) => rigIndex(k) === scorerRig);
      if (sb) {
        camera.setMode('celebrate', dir);
        camera.setPullback(0);
        if (!closeWas) camera.snapTo(sb.x, sb.z);
        else camera.follow(sb.x, sb.z);
      }
    }
    closeWas = tryClose;
    if (rf) {
      camera.setMode('call', dir);
      camera.setPullback(0);
      camera.follow(rf.focus.x, rf.focus.z);
    } else if (replay) {
      // The replay has run out: back to the live picture.
      replay = null;
      replayBadge.hidden = true;
      camera.snapTo(play.ball.x, play.ball.z);
    }
    camera.update(dt);
    stage.shadowFocus(play.ball.x, play.ball.z);
    // Name tag: over the man with the ball in open play.
    const tagged = (play.phase === 'play' || play.phase === 'ruck') && play.carrier !== null ? play.carrier : null;
    if (tagged !== null) {
      const p = play.bodies[tagged]!.player;
      const head = rig.headPosition(rigIndex(tagged), v);
      const at = toScreen(head.x, head.y + t.ui.nameTagLiftM, head.z);
      nameTag.textContent = `${p.firstName.charAt(0)}. ${p.lastName}`;
      nameTag.style.transform = `translate(${at.x}px, ${at.y}px) translate(-50%, -100%)`;
      nameTag.hidden = false;
    } else nameTag.hidden = true;
    if (tryCardLeft > 0) {
      tryCardLeft -= dt;
      if (tryCardLeft <= 0) tryCard.hidden = true;
    }
    hud.update(dt);
  });

  return {
    stats: stage.stats,
    debug: {
      onPitch: SEVEN * 2 + 1,
      stick: () => ({ x: controls.stick.x, y: controls.stick.y }),
      cam: () => ({ x: stage.camera.position.x, y: stage.camera.position.y, z: stage.camera.position.z }),
      home: home.name,
      away: away.name,
      state: () => {
        const c = play.carrierBody;
        return {
          phase: play.phase,
          score: [play.score[0], play.score[1]],
          carrier: play.carrier,
          events: play.log.map((e) => e.kind),
          nearestDefenderM: c ? play.nearestDefender(c.x, c.z) : Infinity,
          ballProgressM: play.progress(play.ball.z),
          ballX: play.ball.x,
          attack: play.attackSide,
          tackle: tackle ? { t: tackle.t, carrier: rig.actionOf(rigIndex(tackle.shot.carrier)), tackler: rig.actionOf(rigIndex(tackle.shot.tackler)), carrierHeadY: rig.headPosition(rigIndex(tackle.shot.carrier), v).y, tacklerHeadY: rig.headPosition(rigIndex(tackle.shot.tackler), v).y } : null,
        };
      },
      passTo: (i) => play.pass(i, null),
      tryNow: () => {
        const c = play.carrierBody;
        if (!c || play.attackSide !== 0) return false;
        c.z = play.homeDir * (play.tryLine + 1);
        return true;
      },
      timeUp: () => {
        play.match.gameLeft = 0;
      },
      defend: () => {
        if (play.attackSide !== 0 || play.phase !== 'play') return false;
        play.swapPossession(play.ball.x, play.ball.z, null);
        return true;
      },
      setPiece: (kind) => {
        const x = play.ball.x;
        const z = play.ball.z;
        const g = t.goal;
        play.startSetPiece(
          kind === 'lineout'
            ? { kind: 'lineout', side: 0, x: t.field.widthM / 2, z, stage: 'pick', jumper: null, guess: null, t: 0 }
            : kind === 'scrum'
              ? { kind: 'scrum', side: 0, x, z, stage: 'set', hits: 0, taps: 0, t: 0 }
              : kind === 'goal'
                ? { kind: 'goal', side: 0, x: 8, z: play.homeDir * (play.tryLine - g.conversionBackM), points: g.conversionPoints, stage: 'aim', t: 0, made: false, aimX: 0, then: 1 }
                : { kind: 'penalty', side: 0, x, z, t: 0 },
        );
      },
    },
    athletes: o.athleteModel ? 'rigged' : 'primitive',
  };
}

/** How many times the swipe hint has shown (per device; a convenience, so failures are ignored). */
function readHints(): number {
  try {
    return Number(localStorage.getItem('rugby.hints.step') ?? 0) || 0;
  } catch {
    return 0;
  }
}

function writeHints(n: number): void {
  try {
    localStorage.setItem('rugby.hints.step', String(n));
  } catch {
    // Storage blocked: the hint just shows again next time.
  }
}

function easeOut(u: number): number {
  return 1 - (1 - u) * (1 - u);
}

/** Facing (radians, 0 = +z) for a player looking toward the try line his team attacks. */
function attackFace(dir: -1 | 1): number {
  return dir < 0 ? Math.PI : 0;
}

/** The brand team's kit from brand.json. */
function brandKit(k: Kit, t: Tunables): AthleteKit {
  return { jersey: k.jersey, numbers: k.numbers, helmet: t.look.headgear, facemask: t.look.headgear, pants: k.shorts, stripe: k.panels, socks: k.socks };
}

function teamKit(k: TeamKit, t: Tunables): AthleteKit {
  return { jersey: k.jersey, numbers: k.numbers, helmet: t.look.headgear, facemask: t.look.headgear, pants: k.shorts, stripe: k.panels, socks: k.socks };
}

/** Plain charcoal referee kit (reference/14). */
function refKit(t: Tunables): AthleteKit {
  const l = t.look;
  return { jersey: l.refShirt, numbers: l.refNumbers, helmet: l.headgear, facemask: l.headgear, pants: l.refShorts, stripe: l.refShirt, socks: l.refShirt };
}

/** Score bug (reference/24) and the big-moment banner (BRAND placement 14). Colours from CSS brand tokens. */
function mountHud(root: HTMLElement, brand: Brand, opponent: string, t: Tunables) {
  const bug = el('div', 'score-bug');
  const homeScore = el('span', 'score', '0');
  const awayScore = el('span', 'score', '0');
  const clock = el('span', 'clock', `1ST HALF ${t.match.halfMinutes}:00`);
  bug.append(el('span', 'team home', brand.teamName.toUpperCase()), homeScore, el('span', 'team away', opponent.toUpperCase()), awayScore, clock);
  const banner = el('div', 'banner');
  banner.dataset.testid = 'banner';
  banner.hidden = true;
  root.append(bug, banner);
  let left = 0;
  return {
    setClock(text: string) {
      if (clock.textContent !== text) clock.textContent = text;
    },
    setScore(s: [number, number]) {
      homeScore.textContent = String(s[0]);
      awayScore.textContent = String(s[1]);
    },
    banner(text: string, big: boolean) {
      banner.textContent = text;
      banner.classList.toggle('big', big);
      banner.hidden = false;
      // Restart the pop animation.
      banner.classList.remove('pop');
      void banner.offsetWidth;
      banner.classList.add('pop');
      left = t.ui.bannerSeconds * (big ? 2 : 1);
    },
    update(dt: number) {
      if (left <= 0) return;
      left -= dt;
      if (left <= 0) banner.hidden = true;
    },
  };
}

/** What was drawn for one athlete in one frame. */
interface Placed {
  x: number;
  z: number;
  action?: Action;
  face?: number | null;
}

/** One drawn frame, for the try replay. */
interface ReplayFrame {
  dt: number;
  rigs: Map<number, Placed>;
  ball: { held: number; x: number; h: number; z: number; fly: boolean };
  focus: { x: number; z: number };
}

/** Steps the replay on by dt; the frame to draw, or null once it has played out. */
function replayFrame(r: { frames: ReplayFrame[]; t: number; k: number }, dt: number): ReplayFrame | null {
  r.t += dt;
  while (r.k < r.frames.length && r.t > r.frames[r.k]!.dt) {
    r.t -= r.frames[r.k]!.dt;
    r.k++;
  }
  return r.frames[r.k] ?? null;
}
