import * as THREE from 'three';
import type { Brand } from '../brand/types';
import type { Tunables } from '../sim/tunables';
import { blobTexture } from './athletes';

/** The rugby ball at its real size (about 29 cm long): a rounded ellipsoid with a stripe in the brand accent (BRAND placement 5). */
export class BallView {
  readonly mesh = new THREE.Group();
  /** Shadow on the grass, smaller and fainter the higher the ball is: how players read where it comes down. */
  readonly shadow: THREE.Mesh;
  private readonly spin = new THREE.Group();
  private readonly prev = new THREE.Vector3();
  private spinRate = 0;

  constructor(
    private readonly t: Tunables,
    stripe: string,
  ) {
    const b = t.ball;
    const geo = new THREE.SphereGeometry(b.radiusM, b.widthSegments * 2, b.heightSegments * 2);
    const p = geo.attributes['position'] as THREE.BufferAttribute;
    // Prolate spheroid along z, rounder at the tips than a football.
    for (let i = 0; i < p.count; i++) {
      const z = p.getZ(i) / b.radiusM;
      p.setXYZ(i, p.getX(i), p.getY(i), (z * b.lengthM) / 2);
    }
    geo.computeVertexNormals();
    const ball = new THREE.Mesh(geo, new THREE.MeshPhongMaterial({ color: t.look.ball, shininess: 40 }));
    // Two accent bands around the ball, a third of the way from each tip.
    const bandMat = new THREE.MeshBasicMaterial({ color: stripe });
    this.spin.add(ball);
    for (const side of [-1, 1]) {
      const at = side * b.stripeAtFraction;
      const r = b.radiusM * Math.sqrt(1 - at * at) * 1.02;
      const band = new THREE.Mesh(new THREE.CylinderGeometry(r, r, b.stripeWidthM, b.widthSegments * 2, 1, true), bandMat);
      band.rotation.x = Math.PI / 2;
      band.position.z = (at * b.lengthM) / 2;
      this.spin.add(band);
    }
    this.mesh.add(this.spin);
    this.mesh.scale.setScalar(b.displayScale);
    this.mesh.visible = false;
    this.shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ map: blobTexture(), transparent: true, depthWrite: false }),
    );
    this.shadow.renderOrder = -1;
    this.shadow.visible = false;
  }

  /** Places the ball; in flight it points along its path and spirals. */
  set(x: number, y: number, z: number, flying = false): void {
    this.prev.copy(this.mesh.position);
    this.mesh.position.set(x, y, z);
    const fx = this.t.fx;
    const k = Math.max(0, 1 - y / fx.ballShadowFadeM);
    this.shadow.position.set(x, 0.025, z);
    this.shadow.scale.setScalar(fx.ballShadowM * (0.45 + 0.55 * k));
    (this.shadow.material as THREE.MeshBasicMaterial).opacity = 0.25 + 0.6 * k;
    if (flying) {
      const dx = x - this.prev.x;
      const dy = y - this.prev.y;
      const dz = z - this.prev.z;
      if (dx * dx + dy * dy + dz * dz > 1e-6) this.mesh.lookAt(x + dx, y + dy, z + dz);
      this.spinRate = 30;
    } else {
      this.spinRate = 0;
      this.mesh.rotation.set(0.4, 0, 0.3);
    }
  }

  /**
   * In a player's hands: at the hand, turned with the body and tipped nose up, as a ball is carried high and
   * tight. The centre sits a little behind the hand so the front point is in the fingers.
   */
  /** At = the ball's centre from the rig's carryPosition. */
  hold(at: THREE.Vector3, yaw: number): void {
    const b = this.t.ball;
    this.set(at.x, at.y, at.z);
    this.mesh.rotation.set(-b.carryTiltRad, yaw, 0, 'YXZ');
    this.spin.rotation.z = 0;
  }

  update(dt: number): void {
    this.spin.rotation.z += this.spinRate * dt;
  }

  show(on: boolean): void {
    this.mesh.visible = on;
    this.shadow.visible = on;
  }
}

/**
 * Thick dotted pass arc from the carrier to the receiver's lead point (GDD 6.5, reference/27): round brand-colour dots
 * that march toward the target. Shape follows power: low = lob, high = bullet.
 */
export class ArcPreview {
  readonly object: THREE.Points;
  private readonly pos: Float32Array;
  private time = 0;
  private readonly from = new THREE.Vector3();
  private readonly to = new THREE.Vector3();
  private peak = 0;
  private readonly okMap: THREE.Texture;
  private readonly warnMap: THREE.Texture;

  constructor(
    brand: Brand,
    private readonly t: Tunables,
  ) {
    const n = t.fx.arcDots;
    this.pos = new Float32Array(n * 3);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    const mat = new THREE.PointsMaterial({
      size: t.fx.arcDotM,
      map: dotTexture(brand.colors.accent),
      transparent: true,
      depthTest: false,
      depthWrite: false,
    });
    this.object = new THREE.Points(geo, mat);
    this.okMap = mat.map!;
    this.warnMap = dotTexture(t.look.forwardWarn);
    this.object.frustumCulled = false;
    this.object.renderOrder = 10;
    this.object.visible = false;
  }

  /** power 0 to 100. */
  set(from: THREE.Vector3, to: THREE.Vector3, power: number): void {
    const c = this.t.controls;
    const k = Math.min(1, Math.max(0, power / 100));
    this.from.copy(from);
    this.to.copy(to);
    this.peak = from.distanceTo(to) * (c.lobArcPerM + (c.bulletArcPerM - c.lobArcPerM) * k);
    this.layout();
    this.object.visible = true;
  }

  hide(): void {
    this.object.visible = false;
  }

  /** Red dots when the pass would go forward (GDD 6.5 forward pass guard). */
  setWarning(on: boolean): void {
    const mat = this.object.material as THREE.PointsMaterial;
    const map = on ? this.warnMap : this.okMap;
    if (mat.map !== map) {
      mat.map = map;
      mat.needsUpdate = true;
    }
  }

  update(dt: number): void {
    this.time += dt;
    if (this.object.visible) this.layout();
  }

  private layout(): void {
    const n = this.t.fx.arcDots;
    const shift = (this.time * this.t.fx.arcDotSpeed) % 1;
    const a = this.from;
    const b = this.to;
    for (let i = 0; i < n; i++) {
      const u = Math.min(1, (i + shift) / n);
      this.pos[i * 3] = a.x + (b.x - a.x) * u;
      this.pos[i * 3 + 1] = a.y + (b.y - a.y) * u + 4 * this.peak * u * (1 - u);
      this.pos[i * 3 + 2] = a.z + (b.z - a.z) * u;
    }
    (this.object.geometry.attributes['position'] as THREE.BufferAttribute).needsUpdate = true;
  }
}

/** A soft round dot in one colour, for point sprites. */
function dotTexture(color: string): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  if (!ctx) throw new Error('2D canvas not available');
  ctx.fillStyle = color;
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;
  ctx.beginPath();
  ctx.arc(32, 32, 20, 0, Math.PI * 2);
  ctx.fill();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

/** Pulsing ring on the turf where the ball will land. */
/** A thin white ring on the grass under the next man each way: who PASS◀ and PASS▶ throw to. */
export class TargetRing {
  readonly mesh: THREE.Mesh;
  private time = 0;

  constructor(brand: Brand, opacity: number) {
    this.mesh = new THREE.Mesh(
      new THREE.RingGeometry(0.86, 1, 40).rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ color: brand.colors.text, transparent: true, opacity, depthWrite: false }),
    );
    this.mesh.visible = false;
  }

  show(x: number, z: number): void {
    this.mesh.position.set(x, 0.03, z);
    this.mesh.visible = true;
  }

  hide(): void {
    this.mesh.visible = false;
  }

  update(dt: number): void {
    this.time += dt;
    const s = 1 + 0.08 * Math.sin(this.time * 6);
    this.mesh.scale.set(s, 1, s);
  }
}

/**
 * Tackle reach on defence: a ring on the grass round the user's defender, as wide as his tackle reach (the dive
 * reach while TACKLE is held). Faint white while the carrier is outside it; accent and pulsing once he is in, the
 * moment to tap (or let go).
 */
export class ReachRing {
  readonly mesh: THREE.Mesh;
  private readonly mat: THREE.MeshBasicMaterial;
  private readonly idle: THREE.Color;
  private readonly hot: THREE.Color;
  private time = 0;

  constructor(
    brand: Brand,
    private readonly t: Tunables,
  ) {
    this.idle = new THREE.Color(brand.colors.text);
    this.hot = new THREE.Color(brand.colors.accent);
    this.mat = new THREE.MeshBasicMaterial({ color: this.idle, transparent: true, depthWrite: false });
    this.mesh = new THREE.Mesh(new THREE.RingGeometry(1 - t.ui.reachRingWidth, 1, 56).rotateX(-Math.PI / 2), this.mat);
    this.mesh.renderOrder = 3;
    this.mesh.visible = false;
  }

  show(x: number, z: number, radiusM: number, inReach: boolean, dt: number): void {
    const u = this.t.ui;
    this.time += dt;
    const pulse = inReach ? 1 + u.reachPulse * Math.sin(this.time * u.reachPulseHz * 2 * Math.PI) : 1;
    this.mesh.position.set(x, 0.031, z);
    this.mesh.scale.set(radiusM * pulse, 1, radiusM * pulse);
    this.mat.color.copy(inReach ? this.hot : this.idle);
    this.mat.opacity = inReach ? u.reachHotOpacity : u.reachIdleOpacity;
    this.mesh.visible = true;
  }

  hide(): void {
    this.mesh.visible = false;
  }
}

/**
 * The player you control: a solid accent disc and ring under his feet and an accent arrow bobbing over his
 * head, so he stands out from the pass targets at a glance.
 */
export class YouMarker {
  readonly group = new THREE.Group();
  private readonly arrow: THREE.Mesh;
  private time = 0;
  private popLeft = 0;

  constructor(
    brand: Brand,
    private readonly t: Tunables,
  ) {
    const u = t.ui;
    const accent = brand.colors.accent;
    const disc = new THREE.Mesh(
      new THREE.CircleGeometry(1, 40).rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: u.youDiscOpacity, depthWrite: false }),
    );
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.8, 1, 48).rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.95, depthWrite: false }),
    );
    for (const m of [disc, ring]) {
      m.scale.setScalar(u.youRingM);
      m.position.y = 0.032;
      m.renderOrder = 4;
      this.group.add(m);
    }
    this.arrow = new THREE.Mesh(
      new THREE.ConeGeometry(u.youArrowSizeM, u.youArrowSizeM * 1.6, 3).rotateX(Math.PI),
      new THREE.MeshBasicMaterial({ color: accent, fog: false }),
    );
    this.group.add(this.arrow);
    this.group.visible = false;
  }

  show(x: number, z: number): void {
    this.group.position.set(x, 0, z);
    this.group.visible = true;
  }

  hide(): void {
    this.group.visible = false;
  }

  /** A quick swell when the user takes a new defender, so the eye finds him. */
  pop(): void {
    this.popLeft = this.t.ui.switchPopSeconds;
  }

  update(dt: number): void {
    const u = this.t.ui;
    this.time += dt;
    this.popLeft = Math.max(0, this.popLeft - dt);
    this.group.scale.setScalar(1 + u.switchPopScale * (this.popLeft / u.switchPopSeconds));
    this.arrow.position.y = u.youArrowHeightM + u.youArrowBobM * Math.sin(this.time * u.youArrowHz * 2 * Math.PI);
    this.arrow.rotation.y = this.time * 1.5;
  }
}

/** Tapered glowing ribbon behind the ball in flight, turned to face the camera. */
export class BallTrail {
  readonly mesh: THREE.Mesh;
  private readonly pts: Float32Array;
  private readonly verts: Float32Array;
  private count = 0;
  private readonly a = new THREE.Vector3();
  private readonly b = new THREE.Vector3();
  private readonly side = new THREE.Vector3();
  private readonly view = new THREE.Vector3();

  constructor(
    brand: Brand,
    private readonly n: number,
    private readonly width: number,
  ) {
    this.pts = new Float32Array(n * 3);
    this.verts = new Float32Array(n * 2 * 3);
    const col = new Float32Array(n * 2 * 3);
    const c = new THREE.Color(brand.colors.accent);
    for (let i = 0; i < n; i++) {
      const f = (1 - i / (n - 1)) ** 1.5;
      for (let k = 0; k < 2; k++) col.set([c.r * f, c.g * f, c.b * f], (i * 2 + k) * 3);
    }
    const index: number[] = [];
    for (let i = 0; i < n - 1; i++) {
      const v = i * 2;
      index.push(v, v + 1, v + 2, v + 1, v + 3, v + 2);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.verts, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    geo.setIndex(index);
    this.mesh = new THREE.Mesh(
      geo,
      new THREE.MeshBasicMaterial({ vertexColors: true, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false, side: THREE.DoubleSide }),
    );
    this.mesh.frustumCulled = false;
    this.mesh.visible = false;
  }

  reset(): void {
    this.count = 0;
    this.mesh.visible = false;
  }

  push(p: THREE.Vector3): void {
    this.pts.copyWithin(3, 0, (this.n - 1) * 3);
    this.pts.set([p.x, p.y, p.z], 0);
    if (this.count === 0) for (let i = 1; i < this.n; i++) this.pts.set([p.x, p.y, p.z], i * 3);
    this.count = Math.min(this.n, this.count + 1);
    this.mesh.visible = true;
  }

  /** Rebuilds the ribbon so its flat side faces the camera. */
  update(camera: THREE.Camera): void {
    if (!this.mesh.visible) return;
    for (let i = 0; i < this.n; i++) {
      this.a.fromArray(this.pts, i * 3);
      this.b.fromArray(this.pts, Math.min(this.n - 1, i + 1) * 3);
      if (i === this.n - 1) this.b.fromArray(this.pts, (i - 1) * 3).sub(this.a).negate().add(this.a);
      this.view.copy(camera.position).sub(this.a);
      this.side.copy(this.b).sub(this.a).cross(this.view);
      const len = this.side.length();
      const half = (this.width / 2) * (1 - i / (this.n - 1));
      if (len > 1e-6) this.side.multiplyScalar(half / len);
      else this.side.set(0, 0, 0);
      this.verts.set([this.a.x + this.side.x, this.a.y + this.side.y, this.a.z + this.side.z], i * 6);
      this.verts.set([this.a.x - this.side.x, this.a.y - this.side.y, this.a.z - this.side.z], i * 6 + 3);
    }
    (this.mesh.geometry.attributes['position'] as THREE.BufferAttribute).needsUpdate = true;
  }
}

/** Touchdown confetti in the brand colours. */
export class Confetti {
  readonly mesh: THREE.InstancedMesh;
  private readonly p: Float32Array;
  private readonly v: Float32Array;
  private readonly r: Float32Array;
  private life = 0;
  private readonly m = new THREE.Matrix4();
  private readonly q = new THREE.Quaternion();
  private readonly e = new THREE.Euler();
  private readonly s = new THREE.Vector3(1, 1, 1);
  private readonly pos = new THREE.Vector3();

  constructor(
    brand: Brand,
    private readonly t: Tunables,
  ) {
    const n = t.fx.confettiCount;
    this.mesh = new THREE.InstancedMesh(new THREE.PlaneGeometry(0.18, 0.1), new THREE.MeshBasicMaterial({ side: THREE.DoubleSide }), n);
    this.mesh.frustumCulled = false;
    this.p = new Float32Array(n * 3);
    this.v = new Float32Array(n * 3);
    this.r = new Float32Array(n * 3);
    const colors = [brand.colors.accent, brand.colors.text, brand.colors.accent, brand.colors.primary];
    const c = new THREE.Color();
    for (let i = 0; i < n; i++) this.mesh.setColorAt(i, c.set(colors[i % colors.length]!));
    this.mesh.visible = false;
  }

  /** Visual only, so Math.random is fine here: it never touches an outcome. */
  burst(x: number, z: number): void {
    const n = this.t.fx.confettiCount;
    for (let i = 0; i < n; i++) {
      this.p[i * 3] = x + (Math.random() - 0.5) * 8;
      this.p[i * 3 + 1] = 6 + Math.random() * 6;
      this.p[i * 3 + 2] = z + (Math.random() - 0.5) * 8;
      this.v[i * 3] = (Math.random() - 0.5) * 6;
      this.v[i * 3 + 1] = Math.random() * 4;
      this.v[i * 3 + 2] = (Math.random() - 0.5) * 6;
      this.r[i * 3] = Math.random() * 6;
      this.r[i * 3 + 1] = Math.random() * 6;
      this.r[i * 3 + 2] = Math.random() * 6;
    }
    this.life = this.t.fx.confettiSeconds;
    this.mesh.visible = true;
  }

  update(dt: number): void {
    if (this.life <= 0) return;
    this.life -= dt;
    const n = this.t.fx.confettiCount;
    for (let i = 0; i < n; i++) {
      this.v[i * 3 + 1] = Math.max(-2.2, this.v[i * 3 + 1]! - 9 * dt);
      this.v[i * 3]! *= 0.98;
      this.v[i * 3 + 2]! *= 0.98;
      for (let k = 0; k < 3; k++) this.p[i * 3 + k]! += this.v[i * 3 + k]! * dt;
      this.e.set(this.r[i * 3]! * this.life * 3, this.r[i * 3 + 1]! * this.life * 3, this.r[i * 3 + 2]!);
      this.q.setFromEuler(this.e);
      this.pos.set(this.p[i * 3]!, Math.max(0.02, this.p[i * 3 + 1]!), this.p[i * 3 + 2]!);
      this.m.compose(this.pos, this.q, this.s);
      this.mesh.setMatrixAt(i, this.m);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.life <= 0) this.mesh.visible = false;
  }
}

/** A puff of turf and dust where a tackle lands. */
export class Puff {
  readonly points: THREE.Points;
  private readonly p: Float32Array;
  private readonly v: Float32Array;
  private readonly mat: THREE.PointsMaterial;
  private life = 0;

  constructor(private readonly t: Tunables) {
    const n = t.fx.puffCount;
    this.p = new Float32Array(n * 3);
    this.v = new Float32Array(n * 3);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.p, 3));
    this.mat = new THREE.PointsMaterial({ map: dotTexture(t.look.turfPuff), size: t.fx.puffSizeM * 1.6, transparent: true, depthWrite: false });
    this.points = new THREE.Points(geo, this.mat);
    this.points.frustumCulled = false;
    this.points.visible = false;
  }

  /** Visual only, so Math.random is fine: it never touches an outcome. */
  burst(x: number, z: number): void {
    const n = this.t.fx.puffCount;
    const sp = this.t.fx.puffSpeedMps;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = sp * (0.4 + Math.random() * 0.6);
      this.p[i * 3] = x + Math.cos(a) * 0.3;
      this.p[i * 3 + 1] = 0.1 + Math.random() * 0.2;
      this.p[i * 3 + 2] = z + Math.sin(a) * 0.3;
      this.v[i * 3] = Math.cos(a) * r;
      this.v[i * 3 + 1] = 1 + Math.random() * sp;
      this.v[i * 3 + 2] = Math.sin(a) * r;
    }
    this.life = this.t.fx.puffSeconds;
    this.mat.opacity = 1;
    this.points.visible = true;
  }

  update(dt: number): void {
    if (this.life <= 0) return;
    this.life -= dt;
    const n = this.t.fx.puffCount;
    for (let i = 0; i < n; i++) {
      this.v[i * 3 + 1]! -= 9 * dt;
      for (let k = 0; k < 3; k++) this.p[i * 3 + k]! += this.v[i * 3 + k]! * dt;
      this.p[i * 3 + 1] = Math.max(0.05, this.p[i * 3 + 1]!);
    }
    (this.points.geometry.attributes['position'] as THREE.BufferAttribute).needsUpdate = true;
    this.mat.opacity = Math.max(0, this.life / this.t.fx.puffSeconds);
    if (this.life <= 0) this.points.visible = false;
  }
}
