import { randomName } from './names';
import type { Rng } from './rng';
import type { Tunables } from './tunables';
import { type Player, type Position, RATING_KEYS, type Ratings, type Team, type TeamInfo } from './types';

/** Shirt numbers 1 to 7 start (reference/12: prop, hooker, prop, scrum-half, fly-half, centre, wing); 8 to 12 are the bench. */
export const POSITION_BY_NUMBER: readonly Position[] = [
  'PROP', 'HOOKER', 'PROP', 'SCRUMHALF', 'FLYHALF', 'CENTRE', 'WING',
  'PROP', 'HOOKER', 'SCRUMHALF', 'CENTRE', 'WING',
];

/** A squad of 12 with seeded names and ratings: position profile plus the team's rating offset plus a little spread. */
export function generateTeam(rng: Rng, info: TeamInfo, t: Tunables): Team {
  const r = t.roster;
  const offset = (info.ratings.attack + info.ratings.defence + info.ratings.speed) / 3 - r.ratingCentre;
  const roster: Player[] = POSITION_BY_NUMBER.map((pos, i) => {
    const profile = r.profiles[pos] as Record<string, number>;
    const ratings = {} as Ratings;
    for (const k of RATING_KEYS) {
      const base = profile[k] ?? r.defaultRating;
      ratings[k] = Math.round(Math.max(r.min, Math.min(r.max, base + offset + rng.range(-r.spread, r.spread))));
    }
    return { id: `${info.id}-${i + 1}`, ...randomName(rng), number: i + 1, pos, ratings, stamina: 100 };
  });
  return { ...info, roster };
}
