import * as THREE from 'three';
import type { Brand } from '../brand/types';
import { Rng } from '../sim/rng';
import type { Tunables } from '../sim/tunables';
import type { Seat } from './crowdFans';

export interface StadiumView {
  group: THREE.Group;
  /** 0 calm, 1 on its feet. Eases toward the target each frame. */
  setExcitement(level: number): void;
  /** The big screens: team names and score. */
  setScore(home: string, away: string, score: readonly [number, number]): void;
  update(dt: number): void;
  /** The front-row seats of the lower tiers, for the 3D fans (crowdFans.ts). */
  seats: Seat[];
}

/**
 * Night stadium (GDD section 10): two tiers of stands around the field with a generated crowd in the
 * brand colours, a brand fascia, LED sideline boards, a roof with floodlights along its edge, big screens at both ends and a gradient sky.
 * Everything is generated at startup from brand.json; no image files.
 */
export function createStadium(brand: Brand, t: Tunables, logo: HTMLImageElement | null, maxAnisotropy: number): StadiumView {
  const anisotropy = Math.min(maxAnisotropy, t.render.anisotropy);
  const group = new THREE.Group();
  const f = t.field;
  const s = t.stadium;
  const halfW = f.widthM / 2 + f.wallOffsetM;
  const halfL = f.lengthM / 2 + f.wallOffsetM;

  group.add(sky(t));

  // Crowd material. The texture holds the same fans twice: seated (top half) and on their feet with their
  // arms up (bottom half). Each fan picks a half from its own hash and the excitement, so the crowd rises
  // fan by fan as the play gets bigger; each also bobs on its own beat. Tiles are mirrored at random and
  // vary a little in brightness so the repeat does not show.
  const crowdTex = crowdTexture(brand, t);
  crowdTex.anisotropy = anisotropy;
  const uniforms = { uTime: { value: 0 }, uCheer: { value: 0 } };
  const crowdMat = new THREE.MeshLambertMaterial({ map: crowdTex });
  const cols = s.crowdCols.toFixed(1);
  const rows = (s.crowdRows / 2).toFixed(1);
  const glsl = (v: number) => v.toFixed(4);
  crowdMat.onBeforeCompile = (shader) => {
    shader.uniforms['uTime'] = uniforms.uTime;
    shader.uniforms['uCheer'] = uniforms.uCheer;
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        uniform float uTime;
        uniform float uCheer;
        float crowdHash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }`,
      )
      .replace(
        '#include <map_fragment>',
        `vec2 tile = floor(vMapUv);
        vec2 f = fract(vMapUv);
        float th = crowdHash(tile);
        if (th > 0.5) f.x = 1.0 - f.x;
        vec2 cell = floor(f * vec2(${cols}, ${rows}));
        float h = crowdHash(cell + tile * 41.0);
        float standing = step(h, ${glsl(s.crowdStandingShare)} + uCheer * ${glsl(s.crowdCheerStandShare)});
        float bob = sin(uTime * ${glsl(s.crowdBounceHz * 2 * Math.PI)} * (1.0 + uCheer) + h * 6.2832) * (${glsl(s.crowdBounceCalm)} + ${glsl(s.crowdBounceCheer)} * uCheer);
        float ry = clamp(fract(f.y * ${rows}) - bob, 0.0, 0.999);
        float v = (cell.y + ry) / ${rows};
        vec2 suv = vec2(f.x, mix(0.5 + v * 0.5, v * 0.5, standing));
        vec2 gx = dFdx(vMapUv) * vec2(1.0, 0.5);
        vec2 gy = dFdy(vMapUv) * vec2(1.0, 0.5);
        vec4 sampledDiffuseColor = textureGrad(map, suv, gx, gy);
        diffuseColor *= sampledDiffuseColor * (${glsl(1 - s.crowdTileShade)} + ${glsl(2 * s.crowdTileShade)} * th);`,
      );
  };

  const concrete = new THREE.MeshLambertMaterial({ color: t.look.standConcrete });
  const fasciaTex = fasciaTexture(brand, logo, t);
  fasciaTex.anisotropy = anisotropy;

  const roofMat = new THREE.MeshLambertMaterial({ color: t.look.roofSteel });
  const lightMat = new THREE.MeshBasicMaterial({ color: t.look.lightPanel, fog: false });
  const glowMat = new THREE.SpriteMaterial({ map: glowTexture(), color: t.look.lightGlow, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, fog: false });
  const seats: Seat[] = [];
  const c3 = t.crowd3d;
  const seatRng = new Rng(c3.seed + 1);
  const tops: { side: { len: number; pos: (d: number, y: number) => [number, number, number]; rotY: number }; base: number; roofY: number }[] = [];

  // Sideline stands (along z) and end stands (along x), two tiers each.
  const sides: { len: number; pos: (d: number, y: number) => [number, number, number]; rotY: number }[] = [
    { len: 2 * halfL + 30, pos: (d, y) => [halfW + d, y, 0], rotY: -Math.PI / 2 },
    { len: 2 * halfL + 30, pos: (d, y) => [-halfW - d, y, 0], rotY: Math.PI / 2 },
    { len: 2 * halfW + 30, pos: (d, y) => [0, y, -halfL - d], rotY: 0 },
    { len: 2 * halfW + 30, pos: (d, y) => [0, y, halfL + d], rotY: Math.PI },
  ];
  for (const side of sides) {
    let base = s.firstTierGapM;
    let y0 = f.wallHeightM;
    for (let tier = 0; tier < 2; tier++) {
      const depth = s.tierDepthM * (tier === 0 ? 1 : 0.8);
      const rise = s.tierRiseM * (tier === 0 ? 1 : 1.1);
      const slope = Math.hypot(depth, rise);
      const tex = crowdTex.clone();
      tex.repeat.set(side.len / 14, s.standRows * (tier === 0 ? 1 : 0.8));
      tex.needsUpdate = true;
      const mat = crowdMat.clone();
      mat.map = tex;
      mat.onBeforeCompile = crowdMat.onBeforeCompile;
      // Darker toward the back rows: the floodlights fall on the front of the stand.
      const geo = new THREE.PlaneGeometry(side.len, slope);
      const top = s.crowdTopShade;
      geo.setAttribute('color', new THREE.Float32BufferAttribute([top, top, top, top, top, top, 1, 1, 1, 1, 1, 1], 3));
      mat.vertexColors = true;
      const stand = new THREE.Mesh(geo, mat);
      const [x, y, z] = side.pos(base + depth / 2, y0 + rise / 2);
      stand.position.set(x, y, z);
      stand.rotation.order = 'YXZ';
      stand.rotation.y = side.rotY;
      stand.rotation.x = -(Math.PI / 2 - Math.atan2(rise, depth));
      group.add(stand);
      // Front rows of the lower tier: seats for the 3D fans, on the slope of the stand.
      if (tier === 0) {
        const rows = side.len > 2 * halfW + 30 ? c3.rowsSide : c3.rowsEnd;
        const ax = Math.cos(side.rotY);
        const az = -Math.sin(side.rotY);
        for (let r = 0; r < rows; r++) {
          const d = c3.rowM * (r + 0.5);
          const [px, py, pz] = side.pos(base + d, y0 + (rise * d) / depth + c3.lift);
          let k = 0;
          for (let u = -side.len / 2 + c3.edgeM; u < side.len / 2 - c3.edgeM; u += c3.seatM, k++) {
            if (k % c3.stairEvery === 0 || seatRng.next() < c3.emptyShare) continue;
            seats.push({ x: px + ax * u, y: py, z: pz + az * u, rotY: side.rotY });
          }
        }
      }
      // Front wall of the tier.
      const front = new THREE.Mesh(new THREE.PlaneGeometry(side.len, y0 + 0.01), concrete);
      const [fx, fy, fz] = side.pos(base, y0 / 2);
      front.position.set(fx, fy, fz);
      front.rotation.y = side.rotY;
      group.add(front);
      // Fascia band (brand) between tiers.
      if (tier === 0) {
        const ft = fasciaTex.clone();
        ft.repeat.set(side.len / 40, 1);
        ft.needsUpdate = true;
        const fascia = new THREE.Mesh(new THREE.PlaneGeometry(side.len, s.fasciaHeightM), new THREE.MeshBasicMaterial({ map: ft }));
        const [ax, ay, az] = side.pos(base + depth + s.upperGapM, y0 + rise + s.fasciaHeightM / 2 + 0.5);
        fascia.position.set(ax, ay, az);
        fascia.rotation.y = side.rotY;
        group.add(fascia);
      }
      base += depth + s.upperGapM;
      y0 += rise + s.fasciaHeightM + 1;
    }
    // Roof over the stand: a cantilever reaching in over the upper tier, steel underside, a row of
    // floodlights along its front edge, and a back wall so no sky shows between stand and roof.
    const roofY = y0 + s.roofClearM;
    const roof = new THREE.Mesh(new THREE.BoxGeometry(side.len, s.roofThickM, s.roofDepthM), roofMat);
    const [rx, ry, rz] = side.pos(base - s.roofDepthM / 2, roofY);
    roof.position.set(rx, ry, rz);
    roof.rotation.y = side.rotY;
    group.add(roof);
    const back = new THREE.Mesh(new THREE.PlaneGeometry(side.len, roofY), concrete);
    const [bx, by, bz] = side.pos(base, roofY / 2);
    back.position.set(bx, by, bz);
    back.rotation.y = side.rotY;
    group.add(back);
    const edge = new THREE.Mesh(new THREE.BoxGeometry(side.len, s.roofLightM, 0.4), lightMat);
    const [ex, ey, ez] = side.pos(base - s.roofDepthM, roofY - s.roofThickM / 2 - s.roofLightM / 2);
    edge.position.set(ex, ey, ez);
    edge.rotation.y = side.rotY;
    group.add(edge);
    for (let d = -side.len / 2 + s.roofLightEveryM / 2; d < side.len / 2; d += s.roofLightEveryM) {
      const glow = new THREE.Sprite(glowMat);
      // Along the edge: the side's own x axis after its turn.
      glow.position.set(ex + Math.cos(side.rotY) * d, ey, ez - Math.sin(side.rotY) * d);
      glow.scale.setScalar(s.roofGlowM);
      group.add(glow);
    }
    tops.push({ side, base, roofY });
  }

  // Big screens hung under the roof at both ends (BRAND placement 11): the logo and the score.
  const screen = scoreScreen(brand, logo, t);
  for (const k of [2, 3]) {
    const top = tops[k]!;
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(s.screenWM, s.screenHM), screen.material);
    const [sx, sy, sz] = top.side.pos(top.base - s.roofDepthM + 1, top.roofY - s.roofThickM - s.screenHM / 2 - s.screenDropM);
    mesh.position.set(sx, sy, sz);
    mesh.rotation.y = top.side.rotY;
    group.add(mesh);
  }

  group.add(sidelineBoards(brand, logo, t, anisotropy));

  let cheer = 0;
  let cheerTarget = 0;
  return {
    group,
    seats,
    setExcitement(level) {
      cheerTarget = Math.max(0, Math.min(1, level));
    },
    setScore(home, away, score) {
      screen.draw(home, away, score);
    },
    update(dt) {
      uniforms.uTime.value += dt;
      cheer += (cheerTarget - cheer) * (1 - Math.exp(-3 * dt));
      uniforms.uCheer.value = cheer;
    },
  };
}

function sky(t: Tunables): THREE.Mesh {
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      top: { value: new THREE.Color(t.look.skyTop) },
      horizon: { value: new THREE.Color(t.look.skyHorizon) },
    },
    vertexShader: 'varying vec3 vP; void main(){ vP = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
    fragmentShader:
      'uniform vec3 top; uniform vec3 horizon; varying vec3 vP; void main(){ float h = clamp(vP.y * 2.2, 0.0, 1.0); gl_FragColor = vec4(mix(horizon, top, pow(h, 0.6)), 1.0); }',
  });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(t.camera.far * 0.9, 24, 12), mat);
  mesh.renderOrder = -10;
  return mesh;
}

interface Fan {
  x: number;
  shirt: string;
  skin: string;
  /** Hair or cap colour, or null for none. */
  top: string | null;
  cap: boolean;
  scarf: string | null;
  clap: boolean;
  shade: number;
}

/**
 * Rows of fans, drawn twice: seated in the top half, standing with arms up in the bottom half (the crowd
 * shader picks per fan). Some fans wear the brand colours; most wear ordinary clothes, so the stands read as
 * people rather than a pattern.
 */
function crowdTexture(brand: Brand, t: Tunables): THREE.CanvasTexture {
  const s = t.stadium;
  const W = s.crowdTilePx;
  const H = s.crowdTilePx;
  const half = H / 2;
  const c = document.createElement('canvas');
  c.width = W;
  c.height = H;
  const ctx = c.getContext('2d')!;
  const rng = new Rng(s.crowdSeed);
  const rows = s.crowdRows / 2;
  const cols = s.crowdCols;
  const cw = W / cols;
  const rh = half / rows;
  // Home supporters mostly in the dark kit and white; the accent is kept to a few, or the stand speckles.
  const brandCols = [brand.colors.primary, brand.colors.primary, brand.colors.text];
  const plain = t.look.crowdClothes;
  const hair = t.look.crowdHair;
  const fans: (Fan | null)[][] = [];
  const sectionShare = Array.from({ length: Math.ceil(cols / s.crowdSectionCols) }, () => Math.min(1, rng.next() * 2 * s.crowdBrandShare));
  for (let r = 0; r < rows; r++) {
    const row: (Fan | null)[] = [];
    for (let k = 0; k < cols; k++) {
      // A stairway between blocks of seats, as in a real stand.
      if (k % s.crowdSectionCols === 0 || r === s.crowdWalkwayRow || rng.next() < s.crowdEmptyShare) {
        row.push(null);
        continue;
      }
      // Supporters sit in blocks: some sections are mostly in the brand colours, some mostly not, so the
      // stands read as a crowd rather than confetti.
      const section = sectionShare[Math.floor(k / s.crowdSectionCols)]!;
      const branded = rng.next() < section;
      const capped = rng.next() < 0.22;
      row.push({
        x: k * cw + cw / 2 + rng.range(-cw * 0.08, cw * 0.08),
        shirt: branded ? (rng.next() < s.crowdAccentShare ? brand.colors.accent : brandCols[rng.int(0, brandCols.length - 1)]!) : plain[rng.int(0, plain.length - 1)]!,
        skin: t.look.skinTones[rng.int(0, t.look.skinTones.length - 1)]!,
        top: capped ? (rng.next() < 0.5 ? brand.colors.accent : plain[rng.int(0, plain.length - 1)]!) : rng.next() < 0.85 ? hair[rng.int(0, hair.length - 1)]! : null,
        cap: capped,
        scarf: rng.next() < 0.18 ? (rng.next() < 0.7 ? brand.colors.accent : brand.colors.text) : null,
        clap: rng.next() < 0.12,
        shade: rng.range(0.78, 1.05),
      });
    }
    fans.push(row);
  }

  for (const standing of [false, true]) {
    const y0 = standing ? half : 0;
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y0, W, half);
    ctx.clip();
    ctx.fillStyle = t.look.standShadow;
    ctx.fillRect(0, y0, W, half);
    // Back rows first, so a fan's head overlaps the row behind.
    for (let r = 0; r < rows; r++) {
      const top = y0 + r * rh;
      // Seat backs.
      ctx.fillStyle = t.look.standConcrete;
      ctx.fillRect(0, top + rh * 0.82, W, rh * 0.18);
      if (r === s.crowdWalkwayRow) {
        // A walkway across the stand between the lower and upper rows: concrete with a shadowed front wall.
        ctx.fillStyle = t.look.standConcrete;
        ctx.fillRect(0, top, W, rh);
        ctx.fillStyle = t.look.standShadow;
        ctx.fillRect(0, top + rh * 0.62, W, rh * 0.38);
        continue;
      }
      for (const fan of fans[r]!) {
        if (fan) drawFan(ctx, fan, top, cw, rh, standing);
      }
      // The stairway steps: a lighter tread and a shadowed riser in the aisle column of each block.
      for (let k = 0; k < cols; k += s.crowdSectionCols) {
        ctx.fillStyle = t.look.standConcrete;
        ctx.fillRect(k * cw + cw * 0.15, top, cw * 0.7, rh);
        ctx.fillStyle = t.look.standShadow;
        ctx.fillRect(k * cw + cw * 0.15, top + rh * 0.78, cw * 0.7, rh * 0.22);
      }
    }
    ctx.restore();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

function drawFan(ctx: CanvasRenderingContext2D, f: Fan, top: number, cw: number, rh: number, standing: boolean): void {
  const lift = standing ? rh * 0.14 : 0;
  const x = f.x;
  const shoulder = top + rh * 0.42 - lift;
  const headY = shoulder - rh * 0.16;
  const headR = cw * 0.17;
  const bodyW = cw * 0.74;
  // Torso, lit from above.
  const g = ctx.createLinearGradient(0, shoulder, 0, top + rh);
  g.addColorStop(0, shadeHex(f.shirt, f.shade * 1.15));
  g.addColorStop(1, shadeHex(f.shirt, f.shade * 0.55));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.roundRect(x - bodyW / 2, shoulder, bodyW, top + rh - shoulder, [cw * 0.2, cw * 0.2, 0, 0]);
  ctx.fill();
  // Arms: up when standing, a few clapping when seated.
  ctx.lineCap = 'round';
  ctx.lineWidth = cw * 0.13;
  if (standing) {
    const spread = cw * 0.32;
    const reach = rh * 0.5;
    ctx.strokeStyle = shadeHex(f.shirt, f.shade);
    ctx.beginPath();
    ctx.moveTo(x - bodyW * 0.38, shoulder + rh * 0.05);
    ctx.lineTo(x - spread, shoulder - reach);
    ctx.moveTo(x + bodyW * 0.38, shoulder + rh * 0.05);
    ctx.lineTo(x + spread, shoulder - reach);
    ctx.stroke();
    if (f.scarf) {
      ctx.strokeStyle = f.scarf;
      ctx.lineWidth = rh * 0.09;
      ctx.beginPath();
      ctx.moveTo(x - spread, shoulder - reach);
      ctx.lineTo(x + spread, shoulder - reach);
      ctx.stroke();
    }
    ctx.fillStyle = f.skin;
    for (const sx of [-spread, spread]) {
      ctx.beginPath();
      ctx.arc(x + sx, shoulder - reach, cw * 0.075, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (f.scarf) {
    ctx.fillStyle = f.scarf;
    ctx.fillRect(x - bodyW * 0.3, shoulder, bodyW * 0.6, rh * 0.08);
  } else if (f.clap) {
    ctx.fillStyle = f.skin;
    ctx.beginPath();
    ctx.arc(x, shoulder + rh * 0.16, cw * 0.08, 0, Math.PI * 2);
    ctx.fill();
  }
  // Head, then hair or a cap.
  ctx.fillStyle = shadeHex(f.skin, f.shade);
  ctx.beginPath();
  ctx.arc(x, headY, headR, 0, Math.PI * 2);
  ctx.fill();
  if (f.top) {
    ctx.fillStyle = f.top;
    ctx.beginPath();
    ctx.arc(x, headY - headR * 0.15, headR * 1.02, Math.PI, Math.PI * 2);
    ctx.fill();
    if (f.cap) ctx.fillRect(x - headR * 1.1, headY - headR * 0.25, headR * 2.2, headR * 0.3);
  }
}

/** A #rrggbb colour scaled by k (k above 1 lightens, clamped). */
function shadeHex(hex: string, k: number): string {
  const n = parseInt(hex.slice(1, 7), 16);
  const ch = (v: number) => Math.max(0, Math.min(255, Math.round(v * k)));
  return `rgb(${ch((n >> 16) & 255)} ${ch((n >> 8) & 255)} ${ch(n & 255)})`;
}

function drawLogo(ctx: CanvasRenderingContext2D, logo: HTMLImageElement | null, x: number, y: number, h: number): number {
  if (!logo || !logo.naturalWidth) return 0;
  const w = (logo.naturalWidth / logo.naturalHeight) * h;
  ctx.drawImage(logo, x, y, w, h);
  return w;
}

function fasciaTexture(brand: Brand, logo: HTMLImageElement | null, t: Tunables): THREE.CanvasTexture {
  const k = t.stadium.signTextureScale;
  const c = document.createElement('canvas');
  c.width = 1024 * k;
  c.height = 64 * k;
  const ctx = c.getContext('2d')!;
  // Drawn in the 1024 x 64 layout, at k times the pixels.
  ctx.scale(k, k);
  ctx.fillStyle = brand.colors.primary;
  ctx.fillRect(0, 0, 1024, 64);
  ctx.fillStyle = brand.colors.accent;
  ctx.fillRect(0, 0, 1024, 5);
  ctx.fillRect(0, 59, 1024, 5);
  ctx.font = `800 italic 34px ${t.look.numberFont}`;
  ctx.textBaseline = 'middle';
  ctx.fillStyle = brand.colors.accent;
  ctx.fillText(brand.tagline.toUpperCase(), 40, 33);
  drawLogo(ctx, logo, 640, 12, 40);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  return tex;
}

/** LED boards on the field wall: logo and team name on the brand primary. */
function sidelineBoards(brand: Brand, logo: HTMLImageElement | null, t: Tunables, anisotropy: number): THREE.Group {
  const f = t.field;
  const g = new THREE.Group();
  const k = t.stadium.signTextureScale;
  const c = document.createElement('canvas');
  c.width = 512 * k;
  c.height = 64 * k;
  const ctx = c.getContext('2d')!;
  // Drawn in the 512 x 64 layout, at k times the pixels.
  ctx.scale(k, k);
  ctx.fillStyle = brand.colors.primary;
  ctx.fillRect(0, 0, 512, 64);
  ctx.fillStyle = brand.colors.accent;
  ctx.fillRect(0, 58, 512, 6);
  const w = drawLogo(ctx, logo, 24, 10, 40);
  ctx.font = `800 italic 36px ${t.look.numberFont}`;
  ctx.textBaseline = 'middle';
  ctx.fillStyle = brand.colors.text;
  ctx.fillText(brand.teamName.toUpperCase(), 48 + w, 32);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = anisotropy;
  tex.wrapS = THREE.RepeatWrapping;
  const halfW = f.widthM / 2 + f.wallOffsetM - 0.05;
  const halfL = f.lengthM / 2 + f.wallOffsetM - 0.05;
  const h = t.stadium.boardHeightM;
  const runs: [number, number, number, number][] = [
    [2 * halfL, halfW, 0, -Math.PI / 2],
    [2 * halfL, -halfW, 0, Math.PI / 2],
    [2 * halfW, 0, -halfL, 0],
    [2 * halfW, 0, halfL, Math.PI],
  ];
  for (const [len, x, z, rotY] of runs) {
    const tx = tex.clone();
    tx.repeat.set(len / t.stadium.boardEveryM, 1);
    tx.needsUpdate = true;
    const m = new THREE.Mesh(new THREE.PlaneGeometry(len, h), new THREE.MeshBasicMaterial({ map: tx }));
    m.position.set(x, h / 2 + 0.05, z);
    m.rotation.y = rotY;
    g.add(m);
  }
  return g;
}

function glowTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d')!;
  const gr = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  gr.addColorStop(0, 'rgba(255,255,255,1)');
  gr.addColorStop(0.15, 'rgba(255,255,255,0.6)');
  gr.addColorStop(0.5, 'rgba(255,255,255,0.12)');
  gr.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = gr;
  ctx.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}

/** The big screen face: the brand logo over the two team names and the score, redrawn when the score changes. */
function scoreScreen(brand: Brand, logo: HTMLImageElement | null, t: Tunables): { material: THREE.MeshBasicMaterial; draw(home: string, away: string, score: readonly [number, number]): void } {
  const c = document.createElement('canvas');
  c.width = 1024;
  c.height = 512;
  const ctx = c.getContext('2d')!;
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const material = new THREE.MeshBasicMaterial({ map: tex, fog: false, side: THREE.DoubleSide });
  const font = t.look.numberFont;
  const draw = (home: string, away: string, score: readonly [number, number]) => {
    ctx.fillStyle = brand.colors.primary;
    ctx.fillRect(0, 0, c.width, c.height);
    ctx.strokeStyle = brand.colors.accent;
    ctx.lineWidth = 16;
    ctx.strokeRect(8, 8, c.width - 16, c.height - 16);
    if (logo && logo.naturalWidth) drawLogo(ctx, logo, (c.width - (logo.naturalWidth / logo.naturalHeight) * 120) / 2, 50, 120);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = brand.colors.text;
    ctx.font = `700 64px ${font}`;
    ctx.fillText(home.toUpperCase(), c.width * 0.25, 260);
    ctx.fillText(away.toUpperCase(), c.width * 0.75, 260);
    ctx.fillStyle = brand.colors.accent;
    ctx.font = `800 150px ${font}`;
    ctx.fillText(`${score[0]}  :  ${score[1]}`, c.width / 2, 390);
    tex.needsUpdate = true;
  };
  draw('', '', [0, 0]);
  return { material, draw };
}
