import type { Tunables } from './tunables';
import type { Ratings } from './types';

/**
 * The GDD section 7 formulas for M1: movement, passing, catching, forward passes, contact and the ruck.
 * Pure functions of ratings, tunables and the situation; every roll happens in the caller with the match Rng.
 */

export type RunnerState = 'OPEN' | 'TIGHT' | 'MARKED';

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

/** Top running speed in m/s (GDD: 6.8 + 0.035 x SPD), before sprint. */
export function topSpeed(r: Ratings, t: Tunables): number {
  const m = t.movement;
  return m.baseSpeed + m.perSpd * r.SPD;
}

/** Seconds from standing to top speed (GDD: 1.6 - 0.008 x ACC). */
export function accelSeconds(r: Ratings, t: Tunables): number {
  const m = t.movement;
  return Math.max(m.minAccelSeconds, m.accelBase - m.accelPerAcc * r.ACC);
}

/** OPEN: no defender within openM of the catch point; MARKED: one within markedM; else TIGHT (GDD 6.5). */
export function runnerState(nearestDefenderM: number, t: Tunables): RunnerState {
  const p = t.passing;
  if (nearestDefenderM > p.openM) return 'OPEN';
  if (nearestDefenderM < p.markedM) return 'MARKED';
  return 'TIGHT';
}

/** Where the power ring should be for a pass of this length (GDD: 30 + 4 x metres, clamp 30 to 90). */
export function powerBandCentre(metres: number, t: Tunables): number {
  const p = t.passing;
  return clamp(p.bandBase + p.bandPerM * metres, p.bandMin, p.bandMax);
}

/** 1.0 inside the band, 1 - 0.03 per point outside it, floor 0.5. A tap pass is always judged on the band. */
export function powerFit(power: number, metres: number, t: Tunables): number {
  const p = t.passing;
  const off = Math.max(0, Math.abs(power - powerBandCentre(metres, t)) - p.bandHalfWidth);
  return Math.max(p.fitFloor, 1 - p.fitPerPoint * off);
}

/** Pressure on the passer: set when a defender is within pressureM at release. */
export function pressureAt(nearestDefenderM: number, t: Tunables): number {
  return nearestDefenderM < t.passing.pressureM ? t.passing.pressure : 0;
}

/** passQuality = PAS / 100 x powerFit x (1 - pressure). */
export function passQuality(passer: Ratings, fit: number, pressure: number): number {
  return (passer.PAS / 100) * fit * (1 - pressure);
}

/** catchChance = 60 + 0.3 x HND + 25 x (passQuality - 0.7) + state bonus, clamp 15 to 98. */
export function catchChance(receiver: Ratings, quality: number, state: RunnerState, t: Tunables): number {
  const c = t.catching;
  const bonus = state === 'OPEN' ? c.openBonus : state === 'MARKED' ? c.markedBonus : c.tightBonus;
  return clamp(c.base + c.perHnd * receiver.HND + c.perQuality * (quality - c.qualityPivot) + bonus, c.min, c.max);
}

/**
 * Forward pass law: the target point is ahead of the passer's hands by more than the tolerance (metres, measured
 * along the attacking direction). This is what the red arc shows before release.
 */
export function isForwardTarget(passerProgress: number, targetProgress: number, t: Tunables): boolean {
  return targetProgress - passerProgress > t.passing.forwardToleranceM;
}

/** Chance (percent) that a legal-looking pass drifts forward under pressure: pressure x 10. */
export function forwardRisk(pressure: number, t: Tunables): number {
  return pressure * t.passing.forwardRiskPerPressure;
}

export type Move = 'none' | 'step' | 'spin' | 'fend';
export type MoveGrade = 'PERFECT' | 'GOOD' | 'MISS' | 'NONE';

/** The stat a move tests (GDD 7): agility for a step or spin, strength for a fend, avg(STR, SPD) for no move. */
export function moveStat(carrier: Ratings, move: Move): number {
  if (move === 'step' || move === 'spin') return carrier.AGI;
  if (move === 'fend') return carrier.STR;
  return (carrier.STR + carrier.SPD) / 2;
}

/** The timing bonus (GDD 6.4): PERFECT +30, GOOD +12, MISS -10, no move 0. */
export function timingBonus(grade: MoveGrade, t: Tunables): number {
  const m = t.moves;
  return grade === 'PERFECT' ? m.perfectBonus : grade === 'GOOD' ? m.goodBonus : grade === 'MISS' ? m.missBonus : 0;
}

/** Grade a move by the time left before contact when it was made (the shrinking ring): inner 20 percent, next 40. */
export function gradeTiming(secondsToContact: number, t: Tunables): MoveGrade {
  const m = t.moves;
  if (secondsToContact < 0 || secondsToContact > m.ringSeconds) return 'MISS';
  const k = secondsToContact / m.ringSeconds;
  if (k <= m.perfectFraction) return 'PERFECT';
  if (k <= m.perfectFraction + m.goodFraction) return 'GOOD';
  return 'MISS';
}

/**
 * Chance (percent) the carrier breaks a tackle (GDD 7): 18 + 0.5 x (carrierStat - TAK) + moveTiming + sprint
 * + fatigue, minus 18 for each extra defender in contact, clamp 5 to 85.
 */
export function breakChance(
  carrier: Ratings,
  tackler: Ratings,
  sprinting: boolean,
  staminaPct: number,
  extraDefenders: number,
  t: Tunables,
  move: Move = 'none',
  grade: MoveGrade = 'NONE',
): number {
  const k = t.tackle;
  let c = k.base + k.perPoint * (moveStat(carrier, move) - tackler.TAK) + timingBonus(grade, t);
  if (sprinting) c += k.sprintBonus;
  if (staminaPct < k.fatigueBelow) c += k.fatiguePenalty;
  c -= k.extraDefenderPenalty * extraDefenders;
  return clamp(c, k.min, k.max);
}

/** Chance (percent) the attacking side wins the ruck in M1's auto-resolve (Arcade: a flat 70). */
export function ruckWinChance(t: Tunables, adds = 0): number {
  return Math.min(t.ruck.maxPct, t.ruck.basePct + t.ruck.addPct * adds);
}
