/** Rating keys (GDD section 7), each 40 to 99. */
export const RATING_KEYS = ['SPD', 'ACC', 'AGI', 'STR', 'PAS', 'HND', 'KCK', 'TAK', 'BRK', 'STA', 'LIN', 'SCR'] as const;
export type RatingKey = (typeof RATING_KEYS)[number];
export type Ratings = Record<RatingKey, number>;

export type Position = 'PROP' | 'HOOKER' | 'SCRUMHALF' | 'FLYHALF' | 'CENTRE' | 'WING';

export interface Player {
  id: string;
  firstName: string;
  lastName: string;
  number: number;
  pos: Position;
  ratings: Ratings;
  stamina: number;
}

/** A team's kit colours for teams that are not the brand team (the brand team's come from brand.json). */
export interface TeamKit {
  jersey: string;
  panels: string;
  numbers: string;
  shorts: string;
  socks: string;
}

export interface TeamInfo {
  id: string;
  name: string;
  /** A simple geometric glyph, never an animal or mascot (GDD section 4). */
  glyph: 'triangle' | 'wave' | 'hexagon' | 'diamond' | 'circle' | 'square' | 'chevron' | 'bolt';
  /** Absent for the brand team: its kit comes from brand.json. */
  kit?: TeamKit;
  ratings: { attack: number; defence: number; speed: number };
}

export interface Team extends TeamInfo {
  roster: Player[];
}

/** A spot in a set-up shape: shirt number and where he stands, in metres from the centre spot, x across, z toward his own try line. */
export interface Spot {
  number: number;
  x: number;
  z: number;
}
