import type { Tunables } from './tunables';
import type { Spot } from './types';

export interface KickoffShape {
  kicking: Spot[];
  receiving: Spot[];
}

/**
 * Where all fourteen players stand for a kick-off (GDD 6.9, reference/24), in world metres.
 * dir is the way the kicking team attacks: -1 toward -z (up the screen from the home end), +1 the other way.
 * The kicking team stands just behind halfway; the receivers start at least the 10 m line back (sevens law).
 */
export function kickoffShape(t: Tunables, dir: -1 | 1): KickoffShape {
  const k = t.kickoff;
  const place = (s: { number: number; x: number; back: number }, sign: number): Spot => ({ number: s.number, x: s.x * -dir, z: sign * s.back * -dir });
  return {
    kicking: k.kicking.map((s) => place(s, 1)),
    receiving: k.receiving.map((s) => place(s, -1)),
  };
}

/** Closest distance from any receiver to halfway (metres). Law: at least 10. */
export function receiverGap(shape: KickoffShape): number {
  return Math.min(...shape.receiving.map((s) => Math.abs(s.z)));
}
