import type { OpenPlay, StickInput } from './openPlay';
import type { Tunables } from './tunables';

/**
 * A simple player for self-play (?bot in the browser, and the balance tests): runs at the biggest gap in front,
 * sprints while there is stamina to spare, and passes to an open runner once a defender closes in, as a player
 * draws the man and gives the ball. Not part of the game rules; it only produces inputs a thumb could.
 */
export class Bot {
  private held = 0;
  private last: number | null = null;
  private steps = 0;

  /** Contacts seen (a timing ring appearing), and whether to step on this one. */
  private contacts = 0;
  private ringUp = false;
  private stepThis = true;

  /**
   * skill: how often it steps (every stepEvery-th contact) and how late (ring fraction left when it swipes). The
   * self-play bot steps on every contact near the PERFECT moment; the away side's AI is a fair opponent, not that.
   */
  constructor(
    private readonly t: Tunables,
    private readonly skill: { stepEvery: number; stepAtRing: number; sprintAbove: number } = { stepEvery: 1, stepAtRing: t.bot.stepAtRing, sprintAbove: t.bot.sprintAbove },
  ) {}

  /** The stick for this step, and PASS LEFT (-1) or PASS RIGHT (1) to press, or null. */
  decide(play: OpenPlay, dt: number): { input: StickInput; passSide: -1 | 1 | null; step: -1 | 1 | null; addPlayer: boolean } {
    const r = this.pick(play, dt);
    this.steps++;
    // At its own ruck it commits a set number of extra players.
    return { ...r, addPlayer: play.attackSide === 0 && play.canAddPlayer && play.ruckBar.adds < this.t.bot.addPlayers };
  }

  private pick(play: OpenPlay, dt: number): { input: StickInput; passSide: -1 | 1 | null; step: -1 | 1 | null } {
    const b = this.t.bot;
    this.held = play.carrier === this.last ? this.held + dt : 0;
    this.last = play.carrier;
    const c = play.carrierBody;
    if (!c || play.phase !== 'play') return { input: { sx: 0, sy: 0, sprint: false }, passSide: null, step: null };

    // Score lanes across the screen by the room in front of each; head for the best.
    let bestSx = 0;
    let bestRoom = -Infinity;
    for (let k = -b.lanes; k <= b.lanes; k++) {
      const sx = k / b.lanes;
      const x = c.x + sx * -play.dir * b.laneLookM;
      if (Math.abs(x) > this.t.field.widthM / 2 - b.touchMarginM) continue;
      const z = c.z + play.dir * b.lookAheadM;
      const room = play.nearestDefender(x, z) - Math.abs(sx) * b.turnCost;
      if (room > bestRoom) {
        bestRoom = room;
        bestSx = sx;
      }
    }
    const input: StickInput = { sx: bestSx, sy: 1, sprint: c.stamina > this.skill.sprintAbove };
    const near = play.nearestDefender(c.x, c.z);
    if (this.held > b.holdSeconds && near < b.passAtM) {
      // Press the pass button for the side whose next man has more room than the carrier.
      let side: -1 | 1 | null = null;
      let room = near + b.passGainM;
      for (const sd of [-1, 1] as const) {
        const to = play.sideTarget(sd);
        if (to < 0) continue;
        const r = play.bodies[to]!;
        const rr = play.nearestDefender(r.x, r.z);
        if (rr > room) {
          room = rr;
          side = sd;
        }
      }
      if (side !== null) return { input, passSide: side, step: null };
    }
    // Step off the defender stepping up when the ring is nearly closed, away from his side.
    const k = play.ringK();
    if (k !== null && !this.ringUp) {
      this.contacts++;
      this.stepThis = this.contacts % this.skill.stepEvery === 0;
    }
    this.ringUp = k !== null;
    if (k !== null && this.stepThis && k <= this.skill.stepAtRing) {
      this.stepThis = false;
      let dx = 0;
      let best = Infinity;
      for (const d of play.bodies.slice(7)) {
        const dd = Math.hypot(d.x - c.x, d.z - c.z);
        if (dd < best) {
          best = dd;
          dx = (d.x - c.x) * -play.dir;
        }
      }
      return { input, passSide: null, step: dx > 0 ? -1 : 1 };
    }
    return { input, passSide: null, step: null };
  }
}
