import type { Tunables } from './tunables';
import type { TeamInfo } from './types';

export const DIFFICULTIES = ['rookie', 'pro', 'legend'] as const;
export type Difficulty = (typeof DIFFICULTIES)[number];

export function isDifficulty(s: string | null | undefined): s is Difficulty {
  return (DIFFICULTIES as readonly string[]).includes(s ?? '');
}

/**
 * ROOKIE / PRO / LEGEND (addendum 5): sets how often their carriers break our tackles (tunables ai.breakMod) for
 * the match. PRO is the game as tuned before team select existed.
 */
export function applyDifficulty(t: Tunables, level: Difficulty): void {
  t.ai.breakMod = t.difficulty.levels[level].breakMod;
}

/** The opponent as the level plays them: every rating shifted by the level's ratingShift. */
export function opponentAt(info: TeamInfo, level: Difficulty, t: Tunables): TeamInfo {
  const s = t.difficulty.levels[level].ratingShift;
  const r = info.ratings;
  return { ...info, ratings: { attack: r.attack + s, defence: r.defence + s, speed: r.speed + s } };
}
