import { type Difficulty, isDifficulty } from '../sim/difficulty';
import teams from '../sim/teams.json';
import type { Tunables } from '../sim/tunables';

/** Who we play, which of our kits, and how hard. */
export interface MatchSetup {
  opponentId: string;
  kit: 'home' | 'away';
  difficulty: Difficulty;
}

/** Every team but the brand's own. */
export const OPPONENT_IDS: readonly string[] = teams.teams.filter((x) => x.id !== 'brand').map((x) => x.id);

/**
 * The match is set in tunables (match.opponentId, PRO); there is no team select (Jonny, 16 Nov: the game just
 * starts). ?opp=, ?kit= and ?level= still override it, for testing.
 */
export function readSetup(params: URLSearchParams, t: Tunables): MatchSetup {
  const opp = params.get('opp');
  const level = params.get('level');
  return {
    opponentId: opp && OPPONENT_IDS.includes(opp) ? opp : t.match.opponentId,
    kit: params.get('kit') === 'away' ? 'away' : 'home',
    difficulty: isDifficulty(level) ? level : (t.difficulty.default as Difficulty),
  };
}

/** Adds ?play to the address, so a reload or REMATCH goes straight into the next match. */
export function playUrl(href: string): string {
  const u = new URL(href);
  u.searchParams.set('play', '');
  // Bare flags (?play, ?nohowto) read better without a trailing "=".
  return u.toString().replace(/=(?=&|$)/g, '');
}

/** The title screen's address: ?play goes; ?seed and the rest stay. */
export function menuUrl(href: string): string {
  const u = new URL(href);
  u.searchParams.delete('play');
  return u.toString();
}
