import type { Tunables } from '../sim/tunables';

type Sample = 'crowd' | 'cheer' | 'groan' | 'boo' | 'applause' | 'ooh';
const SAMPLES: readonly Sample[] = ['crowd', 'cheer', 'groan', 'boo', 'applause', 'ooh'];

/**
 * The crowd is recorded-style audio (short files: a looping murmur and a cheer). Every other
 * sound is synthesised with Web Audio at runtime. Until the files arrive, or if they never do, a filtered
 * noise stands in for the crowd.
 * The context starts on the first tap (browsers block audio until then).
 */
export class GameAudio {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private crowdGain: GainNode | null = null;
  /** Opens as the crowd gets louder, so a roar is brighter than a murmur, not just louder. */
  private crowdTone: BiquadFilterNode | null = null;
  private noiseBed: { src: AudioBufferSourceNode; gain: GainNode } | null = null;
  private noise: AudioBuffer | null = null;
  private readonly files: Partial<Record<Sample, Promise<ArrayBuffer | null>>> = {};
  private readonly samples: Partial<Record<Sample, AudioBuffer>> = {};
  private muted = false;

  private readonly callFiles: Record<string, Promise<ArrayBuffer | null>> = {};
  private readonly callBufs: Record<string, AudioBuffer> = {};
  /** The commentator is talking until then (context seconds): calls in that window are dropped. */
  private callUntil = 0;

  constructor(private readonly t: Tunables) {
    for (const [k, url] of Object.entries(t.audio.calls)) {
      this.callFiles[k] = fetch(url)
        .then((r) => (r.ok ? r.arrayBuffer() : null))
        .catch(() => null);
    }
    // Start downloading now so the files are ready by the first tap; they are decoded once the context exists.
    const urls = t.audio.samples;
    for (const k of SAMPLES) {
      const url = (urls as Partial<Record<Sample, string>>)[k];
      if (!url) continue;
      this.files[k] = fetch(url)
        .then((r) => (r.ok ? r.arrayBuffer() : null))
        .catch(() => null);
    }
  }

  /** Call from a user gesture. */
  unlock(): void {
    if (this.ctx) {
      void this.ctx.resume();
      return;
    }
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    const ctx = new Ctor();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.t.audio.master;
    this.master.connect(ctx.destination);
    // Two seconds of noise, reused by every noisy sound.
    const len = ctx.sampleRate * 2;
    this.noise = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noise.getChannelData(0);
    let b = 0;
    for (let i = 0; i < len; i++) {
      // Slightly pink noise sounds more like a crowd than white noise.
      b = 0.97 * b + 0.03 * (Math.random() * 2 - 1);
      d[i] = b * 6 + (Math.random() * 2 - 1) * 0.15;
    }
    this.startCrowd();
    for (const k of SAMPLES) void this.decode(k);
    for (const k of Object.keys(this.callFiles)) void this.decodeCall(k);
  }

  private async decodeCall(k: string): Promise<void> {
    const data = await this.callFiles[k];
    if (!data || !this.ctx) return;
    try {
      this.callBufs[k] = await this.ctx.decodeAudioData(data.slice(0));
    } catch {
      // A clip that will not decode is just never said.
    }
  }

  /**
   * The commentator (ElevenLabs lines, docs/LICENSES.md). One line at a time with a gap after it, so he does
   * not chatter; `urgent` lines (a try) talk over whatever he was saying.
   */
  say(key: keyof Tunables['audio']['calls'], urgent = false): void {
    const buf = this.callBufs[key];
    if (!buf || !this.ctx || !this.master) return;
    const a = this.t.audio;
    const now = this.ctx.currentTime;
    if (now < this.callUntil && !urgent) return;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const g = this.ctx.createGain();
    g.gain.value = a.callGain;
    src.connect(g).connect(this.master);
    src.start(now + a.callDelaySeconds);
    this.callUntil = now + a.callDelaySeconds + buf.duration + a.callGapSeconds;
  }

  private async decode(k: Sample): Promise<void> {
    const data = await this.files[k];
    if (!data || !this.ctx) return;
    try {
      // decodeAudioData takes ownership of the bytes; the copy keeps a second unlock (or a test) safe.
      this.samples[k] = await this.ctx.decodeAudioData(data.slice(0));
    } catch {
      return;
    }
    if (k === 'crowd') this.swapCrowdBed();
  }

  setMuted(m: boolean): void {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : this.t.audio.master;
  }

  get isMuted(): boolean {
    return this.muted;
  }

  private startCrowd(): void {
    const ctx = this.ctx!;
    this.crowdGain = ctx.createGain();
    this.crowdGain.gain.value = this.t.audio.crowdBase;
    this.crowdGain.connect(this.master!);
    // The stand-in: band-passed noise, until the recorded crowd is decoded.
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = this.t.audio.crowdFilterHz;
    bp.Q.value = 0.6;
    const gain = ctx.createGain();
    src.connect(bp).connect(gain).connect(this.crowdGain);
    src.start();
    this.noiseBed = { src, gain };
  }

  /** Fades the recorded crowd in over the noise, then stops the noise. */
  private swapCrowdBed(): void {
    const ctx = this.ctx;
    const buf = this.samples.crowd;
    if (!ctx || !buf || !this.crowdGain || !this.noiseBed) return;
    const a = this.t.audio;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.loop = true;
    const [start, end] = audibleSpan(buf, a.loopTrimThreshold);
    src.loopStart = start;
    src.loopEnd = end;
    this.crowdTone = ctx.createBiquadFilter();
    this.crowdTone.type = 'lowpass';
    this.crowdTone.frequency.value = a.crowdMuffledHz;
    const gain = ctx.createGain();
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(a.crowdSampleGain, now + a.crowdSwapSeconds);
    src.connect(this.crowdTone).connect(gain).connect(this.crowdGain);
    src.start(now, start);
    const old = this.noiseBed;
    old.gain.gain.setValueAtTime(1, now);
    old.gain.gain.linearRampToValueAtTime(0, now + a.crowdSwapSeconds);
    old.src.stop(now + a.crowdSwapSeconds + 0.05);
    this.noiseBed = null;
  }

  /** 0 murmur to 1 roar, eased. */
  crowd(level: number, seconds = 0.6): void {
    if (!this.ctx || !this.crowdGain) return;
    const a = this.t.audio;
    const k = Math.max(0, Math.min(1, level));
    const g = a.crowdBase + (a.crowdCheer - a.crowdBase) * k;
    this.crowdGain.gain.setTargetAtTime(g, this.ctx.currentTime, seconds / 3);
    // Exponential between the two cut-offs: equal steps of excitement sound like equal steps of brightness.
    const hz = a.crowdMuffledHz * Math.pow(a.crowdOpenHz / a.crowdMuffledHz, k);
    this.crowdTone?.frequency.setTargetAtTime(hz, this.ctx.currentTime, seconds / 3);
  }

  /** One recorded sound (a crowd reaction or an announcer call), on top of the murmur. False until the file is decoded. */
  private reaction(k: Exclude<Sample, 'crowd'>, gain: number): boolean {
    const buf = this.samples[k];
    if (!buf || !this.ctx || !this.master) return false;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const g = this.ctx.createGain();
    g.gain.value = gain;
    src.connect(g).connect(this.master);
    src.start();
    return true;
  }

  private env(gain: number, attack: number, decay: number, at = 0): GainNode | null {
    if (!this.ctx || !this.master) return null;
    const g = this.ctx.createGain();
    const t0 = this.ctx.currentTime + at;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + attack + decay);
    g.connect(this.master);
    return g;
  }

  private noiseHit(gain: number, freq: number, q: number, decay: number, type: BiquadFilterType = 'lowpass', at = 0): void {
    const g = this.env(gain, 0.004, decay, at);
    if (!g || !this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    src.connect(f).connect(g);
    const t0 = this.ctx.currentTime + at;
    src.start(t0, Math.random());
    src.stop(t0 + decay + 0.05);
  }

  private tone(type: OscillatorType, freq: number, gain: number, attack: number, decay: number, at = 0, slideTo?: number): void {
    const g = this.env(gain, attack, decay, at);
    if (!g || !this.ctx) return;
    const o = this.ctx.createOscillator();
    o.type = type;
    const t0 = this.ctx.currentTime + at;
    o.frequency.setValueAtTime(freq, t0);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t0 + attack + decay);
    o.connect(g);
    o.start(t0);
    o.stop(t0 + attack + decay + 0.05);
  }

  /**
   * The referee's pea whistle: a trilled tone (the pea rattling makes the pitch flutter). 'short' stops play,
   * 'long' gives a try, 'start' is two quick pips to start a kick-off. at: seconds from now.
   */
  whistle(at = 0, kind: 'short' | 'long' | 'start' = 'short'): void {
    const a = this.t.audio;
    if (kind === 'start') {
      this.trill(a.whistleShortSeconds * 0.5, at);
      this.trill(a.whistleShortSeconds * 0.5, at + a.whistleShortSeconds * 0.7);
      return;
    }
    this.trill(kind === 'long' ? a.whistleLongSeconds : a.whistleShortSeconds, at);
  }

  private trill(seconds: number, at: number): void {
    const a = this.t.audio;
    const g = this.env(0.28, 0.01, seconds, at);
    if (!g || !this.ctx) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + at;
    const o = ctx.createOscillator();
    o.type = 'sine';
    o.frequency.value = a.whistleHz;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = a.whistleTrillHz;
    const depth = ctx.createGain();
    depth.gain.value = a.whistleHz * a.whistleTrillDepth;
    lfo.connect(depth).connect(o.frequency);
    o.connect(g);
    // A breathy edge: a little high band noise under the tone.
    this.noiseHit(0.05, a.whistleHz, 2, seconds, 'bandpass', at);
    for (const n of [o, lfo]) {
      n.start(t0);
      n.stop(t0 + seconds + 0.06);
    }
  }

  snap(): void {
    this.noiseHit(0.5, 400, 1, 0.12);
    this.tone('triangle', 140, 0.4, 0.005, 0.1);
  }

  whoosh(): void {
    this.noiseHit(this.t.audio.whooshGain, 1800, 0.8, 0.35, 'bandpass');
  }

  catchThud(): void {
    this.noiseHit(this.t.audio.catchGain, 700, 1, 0.09);
    this.tone('sine', 180, 0.5, 0.003, 0.12, 0, 90);
  }

  /**
   * Pads crack (a bright transient a phone speaker can play), a mid thump, then the low body. A big hit adds a
   * deep boom and the crowd's "ooh" (a swell that falls away).
   */
  hit(big = false): void {
    const a = this.t.audio;
    const k = big ? 1 : 0.7;
    this.noiseHit(a.crackGain * k, a.crackHz, 1.4, 0.05, 'bandpass');
    this.tone('triangle', big ? 240 : 280, a.thumpGain * k, 0.002, 0.09, 0, 120);
    this.noiseHit(a.hitGain * k, big ? 900 : 600, 0.7, big ? 0.28 : 0.18);
    this.tone('sine', big ? 90 : 120, a.hitGain * 0.8, 0.003, 0.22, 0, 45);
    if (big) {
      this.tone('sine', a.bigHitBoomHz * 2, a.bigHitBoomGain, 0.004, a.bigHitBoomSeconds, 0, a.bigHitBoomHz);
      this.ooh();
    }
  }

  /** The crowd reacts: up to `oohLevel` at once, then back to where the mood had it. */
  private ooh(): void {
    if (!this.ctx || !this.crowdGain) return;
    const a = this.t.audio;
    const back = this.moodLevel;
    this.crowd(Math.max(back, a.oohLevel), 0.15);
    if (!this.reaction('ooh', a.react.oohGain)) this.swell(a.react.oohFromHz, a.react.oohToHz, a.react.oohGain * 0.5, a.oohSeconds, 3);
    this.moodLevel = -1;
    this.oohUntil = this.ctx.currentTime + a.oohSeconds;
  }

  private moodLevel = -1;
  private oohUntil = 0;

  /**
   * The crowd following play, called every frame with the level `crowdMood` gives (null leaves it alone, for
   * stoppages and the try roar). Rises quickly, falls slowly, and only touches the audio graph on a real change.
   */
  mood(level: number | null): void {
    if (level === null || !this.ctx) return;
    if (this.ctx.currentTime < this.oohUntil) return;
    const m = this.t.audio.mood;
    if (Math.abs(level - this.moodLevel) < m.stepEpsilon) return;
    this.crowd(level, level > this.moodLevel ? m.riseSeconds : m.fallSeconds);
    this.moodLevel = level;
  }

  juke(): void {
    this.noiseHit(0.3, 2400, 1.2, 0.12, 'bandpass');
  }

  /** A different sound for each catch tap grade. */
  catchGrade(grade: 'perfect' | 'good' | 'miss' | 'none'): void {
    const a = this.t.audio;
    if (grade === 'perfect') {
      a.gradePerfectHz.forEach((f, i) => this.tone('sine', f, 0.3, 0.004, 0.18, i * 0.07));
    } else if (grade === 'good') {
      this.tone('square', a.gradeGoodHz, 0.06, 0.002, 0.04);
    } else {
      this.tone('sawtooth', a.gradeMissHz, 0.14, 0.004, 0.16, 0, a.gradeMissHz * 0.7);
    }
  }

  ui(): void {
    this.tone('triangle', 660, 0.12, 0.003, 0.06);
  }

  incomplete(): void {
    this.tone('sawtooth', 200, 0.12, 0.01, 0.4, 0, 110);
    this.crowd(0.05, 0.3);
  }

  /**
   * A try: the referee's long blast. Ours: the crowd roars and cheers (the synthesised horn stands in if the
   * cheer has not loaded). Theirs: a groan, and the crowd sinks.
   */
  try(home = true): void {
    this.whistle(0, 'long');
    if (!home) {
      this.groan();
      this.crowd(this.t.audio.mood.idle, 0.6);
      this.moodLevel = this.t.audio.mood.idle;
      return;
    }
    this.crowd(1, 0.3);
    this.moodLevel = 1;
    if (!this.reaction('cheer', this.t.audio.cheerGain)) this.horn();
  }

  /** The crowd's groan at our mistake: a recorded one if there is one, else a falling, vowel-like swell. */
  groan(): void {
    const a = this.t.audio.react;
    if (this.reaction('groan', a.groanGain)) return;
    this.swell(a.groanFromHz, a.groanToHz, a.groanGain * 0.6, a.groanSeconds, 2.5);
  }

  /** Boos for a penalty against us. */
  boo(): void {
    const a = this.t.audio.react;
    if (this.reaction('boo', a.booGain)) return;
    this.swell(a.booHz, a.booHz * 0.92, a.booGain * 0.6, a.booSeconds, 4);
  }

  /** Applause: a short ripple, or a long one (big = a goal kick over). */
  applause(big: boolean): void {
    const a = this.t.audio.react;
    if (this.reaction('applause', big ? a.applauseGain : a.applauseGain * 0.6)) return;
    if (!this.ctx || !this.master || !this.noise) return;
    this.applauseBuf ??= applauseBuffer(this.ctx, a.applauseClapsPerSecond, a.applauseSeconds);
    const src = this.ctx.createBufferSource();
    src.buffer = this.applauseBuf;
    const g = this.ctx.createGain();
    const t0 = this.ctx.currentTime;
    const dur = big ? a.applauseSeconds : a.applauseSeconds * 0.5;
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(big ? a.applauseGain : a.applauseGain * 0.6, t0 + 0.25);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(g).connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  private applauseBuf: AudioBuffer | null = null;

  /** Many voices as one: noise through a resonant band that slides, swelling in and dying away. */
  private swell(fromHz: number, toHz: number, gain: number, seconds: number, q: number): void {
    if (!this.ctx || !this.master || !this.noise) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + seconds * 0.25);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + seconds);
    g.connect(this.master);
    // Two formants, like a crowd's "oh".
    for (const mult of [1, 2.4]) {
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass';
      f.Q.value = q;
      f.frequency.setValueAtTime(fromHz * mult, t0);
      f.frequency.exponentialRampToValueAtTime(toHz * mult, t0 + seconds);
      src.connect(f).connect(g);
    }
    src.start(t0, Math.random());
    src.stop(t0 + seconds + 0.05);
  }

  /** The final whistle on a win: the crowd, no call. */
  win(): void {
    this.crowd(1, 0.3);
    this.reaction('cheer', this.t.audio.cheerGain);
  }

  private horn(): void {
    const a = this.t.audio;
    for (const [f, at] of [[262, 0], [330, 0.12], [392, 0.24], [523, 0.36]] as const) this.tone('sawtooth', f, a.hornGain, 0.02, 0.5, at);
    this.tone('sawtooth', 523, a.hornGain, 0.02, 1.2, 0.5);
    this.tone('sawtooth', 659, a.hornGain * 0.8, 0.02, 1.2, 0.5);
  }
}

/** What the crowd sees in open play, for `crowdMood`. */
export interface CrowdView {
  /** True while the ball is in hand in open play. */
  live: boolean;
  homeAttacking: boolean;
  /** Metres from the carrier to the nearest defender. */
  gapM: number;
  /** 0 at halfway to 1 on the try line being attacked. */
  nearLine: number;
}

/**
 * How loud the crowd is in open play, 0 murmur to 1 roar (null outside open play: leave it). A break swells
 * it: no defender within `breakStartM`, full at `breakFullM`. Home breaks lift it most; away breaks draw a
 * nervous, smaller swell. Closing on the line adds to it.
 */
export function crowdMood(v: CrowdView, t: Tunables): number | null {
  if (!v.live) return null;
  const m = t.audio.mood;
  const gap = Number.isFinite(v.gapM) ? v.gapM : m.breakFullM;
  const brk = Math.max(0, Math.min(1, (gap - m.breakStartM) / (m.breakFullM - m.breakStartM)));
  const line = Math.max(0, Math.min(1, v.nearLine)) ** 2;
  const level = m.idle + brk * (v.homeAttacking ? m.breakHome : m.breakAway) + line * (v.homeAttacking ? m.nearLineHome : m.nearLineAway);
  return Math.max(0, Math.min(1, level));
}

/** A few seconds of applause: hundreds of short, bright claps at random, thinning toward the end. */
function applauseBuffer(ctx: BaseAudioContext, perSecond: number, seconds: number): AudioBuffer {
  const sr = ctx.sampleRate;
  const buf = ctx.createBuffer(1, Math.floor(sr * seconds), sr);
  const d = buf.getChannelData(0);
  const clapLen = Math.floor(sr * 0.012);
  const total = Math.floor(perSecond * seconds);
  for (let k = 0; k < total; k++) {
    const at = Math.random() ** 1.6 * seconds;
    const start = Math.floor(at * sr);
    const amp = 0.2 + Math.random() * 0.5;
    let lp = 0;
    for (let i = 0; i < clapLen && start + i < d.length; i++) {
      const env = Math.exp(-i / (clapLen * 0.25));
      const n = Math.random() * 2 - 1;
      lp = lp * 0.4 + n * 0.6;
      d[start + i]! += (n - lp) * env * amp;
    }
  }
  return buf;
}

/**
 * Seconds where the sound starts and stops, skipping near-silent samples at either end. MP3 encoders pad both
 * ends, and a loop over that padding clicks or gaps once a cycle.
 */
export function audibleSpan(buf: AudioBuffer, threshold: number): [number, number] {
  const n = buf.length;
  let first = n;
  let last = -1;
  for (let c = 0; c < buf.numberOfChannels; c++) {
    const d = buf.getChannelData(c);
    let i = 0;
    while (i < first && Math.abs(d[i]!) < threshold) i++;
    first = Math.min(first, i);
    let j = n - 1;
    while (j > last && Math.abs(d[j]!) < threshold) j--;
    last = Math.max(last, j);
  }
  if (last <= first) return [0, buf.duration];
  return [first / buf.sampleRate, (last + 1) / buf.sampleRate];
}

/** Short vibration where supported (Android). iOS Safari ignores it. */
export function haptic(pattern: number | number[]): void {
  try {
    navigator.vibrate?.(pattern);
  } catch {
    // Not supported: nothing to do.
  }
}
