/**
 * Open play (GDD sections 5, 6 and 7), built on two lines (Jonny, 12 Nov 2026: "two lines, like the gridiron game,
 * and after every tackle they go back to that line"):
 *
 * - Every restart and every tackle sets a formation. The attack stands in a staggered line behind the ball, one
 *   runner per channel across the pitch, the scrum-half at the base. The defence stands in a flat line opposite,
 *   one defender per attacker. Players run into it during a short reset, then the scrum-half passes out.
 * - In play every runner keeps his channel and runs up the pitch at the ball's pace. The defence comes up together
 *   as one flat line, each man opposite his attacker; only the defender nearest the ball carrier breaks the line
 *   to make the tackle.
 * - The user runs the carrier with the stick and passes with PASS left / PASS right to the next man in the line.
 *
 * Fixed-step and seeded: the same seed and inputs give the same match. Bodies 0 to 6 are the attacking seven
 * (shirts 1 to 7), 7 to 13 the defending seven. World metres: x across, z along the pitch; the attack runs toward
 * dir (-1: toward -z, up the screen).
 */

export const SEVEN = 7;

/** Per side (index 0 home, 1 away) counts for the full-time screen (GDD 6.13). */
export interface MatchStats {
  tries: [number, number];
  breaks: [number, number];
  tackles: [number, number];
  passes: [number, number];
  passesCaught: [number, number];
  rucksWon: [number, number];
  rucksLost: [number, number];
  /** Per player, keyed "side:number". */
  players: Record<string, { side: 0 | 1; number: number; name: string; tries: number; breaks: number; tackles: number; offloads: number }>;
}

/** The match clock (addendum 2): a 7:00 game clock per half at `clock.speed`, inside a wall-clock cap. */
export interface MatchClock {
  half: 1 | 2;
  /** Game seconds left in the half. */
  gameLeft: number;
  /** Real seconds played this half. */
  wall: number;
  /** Real seconds left on the half-time card. */
  breakLeft: number;
}

export interface Body {
  /** 0 attacking, 1 defending (swaps with possession). */
  team: 0 | 1;
  /** 0 home (the user's team), 1 away: fixed for the match. */
  side: 0 | 1;
  /** 0 to 6 within the team (shirt number - 1). */
  slot: number;
  player: Player;
  x: number;
  z: number;
  vx: number;
  vz: number;
  /** Seconds left on the ground after a tackle. */
  down: number;
  /** Seconds left stumbling after being beaten. */
  stun: number;
  /** Committed to the ruck (ADD PLAYER): over the ball, out of the line until bindLeft runs out. */
  bound: boolean;
  bindLeft: number;
  /** Out of the line (beaten): runs back to the line before he can tackle again. */
  offside: boolean;
  /** 0 to 100. */
  stamina: number;
  sprinting: boolean;
  /** Ran the tank dry: no sprint, and a little slower, until stamina is back to the recovery level. */
  exhausted: boolean;
}

/** The last tackle, for drawing it: where both players started and where they end up on the ground. */
export interface TackleShot {
  carrier: number;
  tackler: number;
  from: { cx: number; cz: number; tx: number; tz: number };
  to: { cx: number; cz: number; tx: number; tz: number };
  /** A big hit: the user's held TACKLE, or the two closing fast (`tackle.bigHitMps`). Louder, with a crowd "ooh". */
  big: boolean;
}

export type PlayEventKind = 'halftime' | 'fulltime' | 'pass' | 'caught' | 'knockOn' | 'forward' | 'broke' | 'tackled' | 'offload' | 'ruckWon' | 'turnover' | 'try' | 'touch' | 'kick' | 'kickoff' | 'gathered' | 'possession' | 'call' | 'lineout' | 'scrum' | 'goal' | 'penalty';

/** A restart in progress (GDD 6.3, 6.10 to 6.12): the sim waits on the user (or the AI) at each stage. */
export type SetPiece =
  | { kind: 'call'; side: 0 | 1; next: SetPiece | null; t: number; shape: DefenceShape; coach: PlayCard }
  | { kind: 'lineout'; side: 0 | 1; x: number; z: number; stage: 'pick' | 'throw' | 'air'; jumper: Jumper | null; guess: Jumper | null; t: number; won?: 0 | 1 }
  | { kind: 'scrum'; side: 0 | 1; x: number; z: number; stage: 'set' | 'push'; hits: number; taps: number; t: number }
  | { kind: 'goal'; side: 0 | 1; x: number; z: number; points: number; stage: 'aim' | 'flight'; t: number; made: boolean; aimX: number; then: 0 | 1 }
  | { kind: 'penalty'; side: 0 | 1; x: number; z: number; t: number }
  | { kind: 'tap'; side: 0 | 1; x: number; z: number };

export type PenaltyChoice = 'tap' | 'touch' | 'goal';

/** Kicks in play (GDD 6.6). */
export type KickType = 'grubber' | 'chip' | 'box' | 'touch';

/** A kick in the air (or rolling): from, to, how long, how high. */
export interface KickBall {
  type: KickType | 'kickoff';
  sx: number;
  sz: number;
  tx: number;
  tz: number;
  t: number;
  dur: number;
  peak: number;
}

/** One thing that happened, with the numbers behind it (GDD 6.13 "why"). */
export interface PlayEvent {
  kind: PlayEventKind;
  /** Short call for the banner, e.g. "TRY!", "FORWARD PASS"; empty for routine events. */
  call: string;
  /** The why: chance and roll where there was one. */
  detail: string;
  chance?: number;
  roll?: number;
  /** Body index the event is about. */
  who?: number;
}

export interface StickInput {
  /** -1 left to 1 right, as seen on screen. */
  sx: number;
  /** -1 back to 1 forward (up the screen). */
  sy: number;
  sprint: boolean;
}

/**
 * play: ball in hand. flight: a pass in the air. ruck: a tackle (or a restart): both lines are re-forming.
 * kickoff: lined up for a kick-off, the kicker waiting. kick: a kick in the air or loose on the ground.
 */
export type Phase = 'play' | 'flight' | 'ruck' | 'dead' | 'kickoff' | 'kick' | 'setpiece' | 'halftime' | 'fulltime';

export interface Flight {
  from: number;
  to: number;
  t: number;
  dur: number;
  sx: number;
  sz: number;
  tx: number;
  tz: number;
  quality: number;
  chance: number;
  state: RunnerState;
  forward: boolean;
  forwardWhy: string;
  peak: number;
  /** The pass button that threw it (-1 left, 1 right), 0 for any other pass. */
  side: -1 | 0 | 1;
  /** The user's defender is in its lane and may go for the intercept (GDD 6.7). */
  interceptable?: boolean;
  laneCloseness?: number;
}

/** A player's place in the formation: x across, and depth (attack: metres behind the ball; defence: on the line). */
interface Spot {
  x: number;
  depth: number;
}

export class OpenPlay {
  readonly bodies: Body[] = [];
  phase: Phase = 'dead';
  carrier: number | null = null;
  flight: Flight | null = null;
  /** Ball position (metres) and height. */
  readonly ball = { x: 0, z: 0, h: 1 };
  /** Points by side: [home, away]. */
  readonly score: [number, number] = [0, 0];
  /** The way the home side attacks this half; the camera always looks this way. */
  readonly homeDir: -1 | 1;
  /** The attacking side runs toward dir: home attacks homeDir, away the other way. */
  dir: -1 | 1;
  /** False in self-play: nobody steers the home defender, the defence AI does. */
  humanDefends = true;
  /** The home defender the user controls while the away side attacks (body index), -1 when attacking. */
  userDef = -1;
  /** A kick in the air or on the ground, or null. */
  kickBall: KickBall | null = null;
  /** Where the kick-off is aimed across the pitch (metres), moved by the stick while the user kicks off. */
  kickoffAimX = 0;
  /** The match's first kick-off by the away side: long and central, for the user to gather. */
  private openingKick = false;
  /** CHIP & CHASE: the first receiver chips as soon as he has the ball. */
  private chipOnCatch = false;
  /** The user's thumb is on the stick steering his defender (else the AI moves him). */
  private userSteering = false;
  /** Match clock when the user last changed defender (SWITCH or auto), for the marker's flash. */
  switchedAt = -Infinity;
  /** Seconds of play stepped, a clock for UI timing. */
  clock = 0;
  /** The match clock: halves, game time and the wall-clock cap. */
  readonly match: MatchClock;
  readonly stats: MatchStats = {
    tries: [0, 0],
    breaks: [0, 0],
    tackles: [0, 0],
    passes: [0, 0],
    passesCaught: [0, 0],
    rucksWon: [0, 0],
    rucksLost: [0, 0],
    players: {},
  };
  /** Who kicked off the match: the other side kicks off the second half. */
  private firstKicker: 0 | 1 = 1;
  /** Plays the away side's attack. */
  private readonly ai: Bot;
  /** What happens when a dead ball's timer runs out. */
  private restart: { kind: 'reset' } | { kind: 'swap'; x: number; z: number } | { kind: 'kickoff'; kicking: 0 | 1 } | { kind: 'set'; sp: SetPiece } = { kind: 'reset' };
  /** The restart being played (phase 'setpiece'), or null. */
  setPiece: SetPiece | null = null;
  /** True in the game: the user makes the home side's set-piece choices. False (tests, self-play): the AI does. */
  human = false;
  /** The play called for this restart, and whether it beats the defence's shape (GDD 6.3), until the next ruck. */
  callEffect: { card: PlayCard; shape: DefenceShape; match: boolean } | null = null;
  /** Each player's place at a lineout or scrum, by body index (null in open play). */
  setPieceRole: ('scrum' | 'jumper' | 'thrower' | 'kicker' | null)[] = [];
  readonly events: PlayEvent[] = [];
  /** Every event this match, in order (tests and the why strip read this). */
  readonly log: PlayEvent[] = [];
  /** Each player's formation spot, set at every restart and every tackle. */
  private readonly spots: Spot[] = [];
  /** Which attacker each defender stands opposite (body index), by defender body index. */
  private readonly marks: number[] = [];
  /** Where the play restarts from: the ruck or the restart point. */
  private base = { x: 0, p: 0 };
  /** Where the defensive line stands (progress metres). */
  private lineP = 0;
  private timer = 0;
  private ruckWon = true;
  private ruckRoll = { chance: 100, roll: 0 };
  /** Players committed to this ruck by ADD PLAYER (addendum 4). */
  private ruckAdds = 0;
  /** The last contested ruck's result word for the arc ("WON", "TURNOVER"), and how long it shows. */
  ruckWord = '';
  ruckWordLeft = 0;
  /** The user's defender is chasing the carrier on a held TACKLE (addendum 4). */
  chasing = false;
  /** Wind for the match (addendum 4). */
  wind: { mph: number; dirX: -1 | 1 } = { mph: 0, dirX: 1 };
  /** The man just tackled, and how long he can still get an offload away (GDD 6.6). */
  private offloadFrom: number | null = null;
  private offloadLeft = 0;
  private firstReceiver = -1;
  private tackleCooldown = 0;
  private slowed = 0;
  private frontTackler = -1;
  /** The step, spin or fend the user just made, waiting for the contact it was timed for. */
  private pendingMove: { kind: Move; grade: MoveGrade; t: number } | null = null;
  private moveCooldown = 0;
  private stepLeft = 0;
  private stepSide: -1 | 1 = 1;
  private spinLeft = 0;
  /** The last tackle made, for drawing it (null before the first). */
  lastTackle: TackleShot | null = null;

  /** attack is the home side (the user's), defence the away side; home attacks dir first. */
  constructor(
    attack: Team,
    defence: Team,
    dir: -1 | 1,
    private readonly t: Tunables,
    private readonly rng: Rng,
  ) {
    this.dir = dir;
    this.homeDir = dir;
    this.match = { half: 1, gameLeft: t.match.halfMinutes * 60, wall: 0, breakLeft: 0 };
    this.ai = new Bot(t, t.ai);
    this.wind = rollWind(rng, t);
    for (const [team, side] of [attack, defence].entries()) {
      for (let s = 0; s < SEVEN; s++) {
        this.bodies.push({
          team: team as 0 | 1,
          side: team as 0 | 1,
          slot: s,
          player: side.roster[s]!,
          x: 0,
          z: 0,
          vx: 0,
          vz: 0,
          down: 0,
          stun: 0,
          bound: false,
          bindLeft: 0,
          offside: false,
          stamina: 100,
          sprinting: false,
          exhausted: false,
        });
        this.spots.push({ x: 0, depth: 0 });
        this.marks.push(-1);
      }
    }
    this.resetAttack();
  }

  /** Metres gained toward the try line being attacked (0 at halfway). */
  progress(z: number): number {
    return z * this.dir;
  }

  private zAt(progress: number): number {
    return progress * this.dir;
  }

  get tryLine(): number {
    return this.t.field.lengthM / 2 - this.t.field.inGoalM;
  }

  get carrierBody(): Body | null {
    return this.carrier === null ? null : this.bodies[this.carrier]!;
  }

  /** A fresh possession from halfway: both lines set and standing, then the scrum-half passes out. */
  resetAttack(): void {
    for (const b of this.bodies) {
      b.vx = b.vz = 0;
      b.down = b.stun = 0;
      b.bound = b.offside = false;
      b.sprinting = false;
      b.exhausted = false;
      b.stamina = 100;
    }
    this.base = { x: 0, p: this.t.openPlay.startProgress };
    this.setFormation();
    for (const [i, b] of this.bodies.entries()) {
      const at = this.spotPosition(i);
      b.x = at.x;
      b.z = at.z;
    }
    this.flight = null;
    this.carrier = null;
    this.ruckWon = true;
    this.ruckRoll = { chance: 100, roll: 0 };
    this.phase = 'ruck';
    this.timer = this.t.formation.restartSeconds;
    this.tackleCooldown = 0;
    this.slowed = 0;
    this.placeBall();
  }

  /** Attackers other than the carrier, with their OPEN / TIGHT / MARKED state at where they are now. */
  runnerStates(): { index: number; state: RunnerState }[] {
    const out: { index: number; state: RunnerState }[] = [];
    for (let i = 0; i < SEVEN; i++) {
      const b = this.bodies[i]!;
      if (i === this.carrier || b.down > 0) continue;
      out.push({ index: i, state: runnerState(this.nearestDefender(b.x, b.z), this.t) });
    }
    return out;
  }

  /** True if a pass to this attacker right now would be aimed forward. */
  wouldBeForward(to: number): boolean {
    const c = this.carrierBody;
    if (!c) return false;
    const aim = this.leadPoint(to, this.passSeconds(c, to, null));
    return isForwardTarget(this.progress(c.z), this.progress(aim.z), this.t);
  }

  /** Where a pass to this attacker would be thrown (the receiver's lead point). */
  passTarget(to: number, power: number | null = null): { x: number; z: number } {
    const c = this.carrierBody;
    if (!c) return { x: 0, z: 0 };
    return this.leadPoint(to, this.passSeconds(c, to, power));
  }

  /** Who PASS LEFT (-1) or PASS RIGHT (1) would throw to now: the next man in the line on that side (-1 if nobody). */
  sideTarget(side: -1 | 1): number {
    const c = this.carrierBody;
    if (!c) return -1;
    let best = -1;
    let bestD = Infinity;
    for (let i = 0; i < SEVEN; i++) {
      const b = this.bodies[i]!;
      if (i === this.carrier || b.down > 0 || b.bound) continue;
      const sx = (b.x - c.x) * -this.dir;
      if (Math.sign(sx) !== side || Math.abs(sx) < this.t.passing.sideMinM) continue;
      const d = Math.abs(sx) + Math.max(0, this.progress(b.z) - this.progress(c.z)) * this.t.passing.aheadPenalty;
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  /** PASS LEFT / PASS RIGHT: a flat pass to the next man in the line on that side, never called forward. */
  /** True while the man just tackled can still get an offload away. */
  get offloadOpen(): boolean {
    return this.attackSide === 0 && this.phase === 'ruck' && this.offloadFrom !== null && this.offloadLeft > 0;
  }

  /**
   * The ruck arc (addendum 4, replaces the tap bar): the chance the attack keeps the ball and how many players
   * have been added. Home attacking, each ADD PLAYER adds push; defending, each one counter-rucks.
   */
  get ruckBar(): { adds: number; chance: number; defending: boolean } {
    const r = this.t.ruck;
    if (this.attackSide === 1) return { adds: this.ruckAdds, chance: Math.max(r.aiMinPct, r.aiBasePct - r.aiAddPct * this.ruckAdds), defending: true };
    return { adds: this.ruckAdds, chance: ruckWinChance(this.t, this.ruckAdds), defending: false };
  }

  /** True while a ruck from a tackle is being contested (not a restart) and the user has a say in it. */
  get ruckLive(): boolean {
    return this.phase === 'ruck' && this.offloadFrom !== null && (this.attackSide === 0 || this.userDefending);
  }

  /** ADD PLAYER can commit one more now. */
  get canAddPlayer(): boolean {
    return this.ruckLive && this.ruckAdds < this.t.ruck.maxAdds;
  }

  /**
   * ADD PLAYER (addendum 4): commits the nearest free team-mate to the ruck. He binds over the ball and stays out
   * of the line until a moment after it, so every add is push now and a man short next phase.
   */
  addPlayer(): boolean {
    if (!this.canAddPlayer) return false;
    const first = this.attackSide === 0 ? 0 : SEVEN;
    const bz = this.zAt(this.base.p);
    let best = -1;
    let bestD = Infinity;
    for (let i = first; i < first + SEVEN; i++) {
      const b = this.bodies[i]!;
      if (b.bound || b.down > 0 || i === this.offloadFrom || (first === 0 && i === this.t.openPlay.scrumHalfSlot)) continue;
      const d = Math.hypot(b.x - this.base.x, b.z - bz);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    if (best < 0) return false;
    const b = this.bodies[best]!;
    b.bound = true;
    b.bindLeft = this.timer + this.t.ruck.rejoinSeconds;
    this.ruckAdds++;
    if (best === this.userDef) this.pickUserDefender(best);
    return true;
  }

  /** Where a player committed to the ruck binds: over the ball on his own side of it. */
  private ruckPoint(i: number): { x: number; z: number } {
    const b = this.bodies[i]!;
    const back = b.team === 0 ? -1 : 1;
    return { x: this.base.x + ((b.slot % 3) - 1) * this.t.ruck.bindSpreadM, z: this.zAt(this.base.p + back * this.t.ruck.bindBackM) };
  }

  /** CALL PLAY at a home ruck (addendum 4, like the reference game's SET PLAYS): true while it can be tapped. */
  get callChipOn(): boolean {
    return this.human && this.attackSide === 0 && this.phase === 'ruck' && this.offloadFrom !== null && !this.offloadOpen && this.setPiece === null;
  }

  /** CALL PLAY tapped: the cards go up and the ruck waits; the play runs off the scrum-half's pass. */
  openRuckCall(): boolean {
    if (!this.callChipOn) return false;
    this.setPiece = this.callFor(null);
    return true;
  }

  /**
   * Offload (GDD 6.6): PASS in the moment the carrier goes to ground pops the ball to the next man that way
   * instead of setting a ruck. Harder to catch than a pass (catch minus the offload penalty). False if the window
   * has gone or nobody is near enough.
   */
  offload(side: -1 | 1): boolean {
    if (!this.offloadOpen) return false;
    const from = this.offloadFrom!;
    const prev = { carrier: this.carrier, phase: this.phase };
    this.carrier = from;
    this.phase = 'play';
    const to = this.sideTarget(side);
    const c = this.bodies[from]!;
    const r = to >= 0 ? this.bodies[to]! : null;
    if (!r || Math.hypot(r.x - c.x, r.z - c.z) > this.t.offload.maxM || !this.pass(to, null, false, true)) {
      this.carrier = prev.carrier;
      this.phase = prev.phase;
      return false;
    }
    const f = this.flight!;
    f.side = side;
    f.chance = Math.max(this.t.offload.minChance, f.chance - this.t.offload.catchPenalty);
    this.offloadFrom = null;
    this.offloadLeft = 0;
    this.emit({ kind: 'offload', call: 'OFFLOAD!', detail: `Offload to ${r.player.number}, catch ${Math.round(f.chance)} percent (offload minus ${this.t.offload.catchPenalty})`, chance: f.chance, who: to });
    return true;
  }

  passSide(side: -1 | 1): boolean {
    const to = this.sideTarget(side);
    if (to < 0 || !this.pass(to, null, false, true)) return false;
    this.flight!.side = side;
    return true;
  }

  /**
   * Double tap: the pass just thrown that way is re-aimed past its man to the next one out (a skip pass). Only
   * while the ball is still early in the air. False if there is nobody further out or it is too late.
   */
  skipPass(side: -1 | 1): boolean {
    const f = this.flight;
    if (this.phase !== 'flight' || !f || f.side !== side || f.t > f.dur * this.t.passing.skipWindowFraction) return false;
    const passer = this.bodies[f.from]!;
    const first = this.bodies[f.to]!;
    let best = -1;
    let bestD = Infinity;
    for (let i = 0; i < SEVEN; i++) {
      const b = this.bodies[i]!;
      if (i === f.from || i === f.to || b.down > 0) continue;
      const sx = (b.x - first.x) * -this.dir;
      if (Math.sign(sx) !== side) continue;
      if (Math.abs(sx) < bestD) {
        bestD = Math.abs(sx);
        best = i;
      }
    }
    if (best < 0) return false;
    const r = this.bodies[best]!;
    const bx = this.ball.x;
    const bz = this.ball.z;
    const metres0 = Math.hypot(r.x - bx, r.z - bz);
    const dur = Math.max(this.t.passing.minSeconds, metres0 / (this.t.passing.speedBase + this.t.passing.speedPerPower * this.t.passing.bandMax));
    const aim = { x: r.x + r.vx * dur, z: r.z + r.vz * dur };
    if (this.progress(aim.z) > this.progress(passer.z)) aim.z = passer.z;
    const metres = Math.hypot(aim.x - passer.x, aim.z - passer.z);
    const quality = passQuality(passer.player.ratings, 1, 0) * this.t.passing.skipQuality;
    const state = runnerState(this.nearestDefender(aim.x, aim.z), this.t);
    const chance = catchChance(r.player.ratings, quality, state, this.t);
    Object.assign(f, { to: best, t: 0, dur, sx: bx, sz: bz, tx: aim.x, tz: aim.z, quality, chance, state, peak: metres * this.t.passing.arcPerM });
    this.emit({ kind: 'pass', call: '', detail: `Skip pass to ${r.player.number} ${state}, catch ${Math.round(chance)} percent`, chance, who: best });
    return true;
  }

  /**
   * Seconds until the defender stepping up reaches the carrier, or null when nobody is closing. The timing ring
   * (GDD 6.4, reference/28) shows this from ringSeconds out, shrinking to the contact.
   */
  secondsToContact(): number | null {
    const c = this.carrierBody;
    if (!c || this.phase !== 'play' || this.frontTackler < 0) return null;
    const d = this.bodies[this.frontTackler]!;
    const dx = d.x - c.x;
    const dz = d.z - c.z;
    const dist = Math.hypot(dx, dz);
    if (dist > this.t.defence.engageM) return null;
    const closing = ((c.vx - d.vx) * dx + (c.vz - d.vz) * dz) / Math.max(dist, 1e-6);
    if (closing < this.t.moves.minClosingMps) return null;
    return Math.max(0, (dist - this.t.tackle.contactM) / closing);
  }

  /** The ring's size: 1 when it appears, 0 at contact; null when there is no ring. */
  ringK(): number | null {
    const s = this.secondsToContact();
    return s === null || s > this.t.moves.ringSeconds ? null : s / this.t.moves.ringSeconds;
  }

  /**
   * A swipe (GDD 6.4): step left or right, fend (up) or spin (down). Graded by the ring: PERFECT, GOOD, or MISS
   * (early, or no defender closing). The grade counts at the contact it was timed for. Returns the grade, or null
   * if no move can be made now.
   */
  move(kind: Exclude<Move, 'none'>, side: -1 | 1 = 1): MoveGrade | null {
    const c = this.carrierBody;
    if (this.phase !== 'play' || !c || this.moveCooldown > 0) return null;
    const ttc = this.secondsToContact();
    const grade: MoveGrade = ttc === null ? 'NONE' : gradeTiming(ttc, this.t);
    this.pendingMove = { kind, grade, t: 0 };
    this.moveCooldown = this.t.moves.cooldownSeconds;
    if (kind === 'step') {
      this.stepLeft = this.t.moves.stepSeconds;
      this.stepSide = side;
    } else if (kind === 'spin') this.spinLeft = this.t.moves.spinSeconds;
    if (grade === 'MISS') this.slowed = Math.max(this.slowed, this.t.moves.missStumbleSeconds);
    return grade;
  }

  /** The best open runner on a side (or anywhere if neutral); never one a pass would reach going forward. */
  pickReceiver(side: number): number | null {
    const c = this.carrierBody;
    if (!c) return null;
    const p = this.t.passing;
    let best: number | null = null;
    let bestScore = -Infinity;
    for (const { index, state } of this.runnerStates()) {
      const b = this.bodies[index]!;
      const sx = (b.x - c.x) * -this.dir;
      if (Math.abs(side) > p.sideDeadzone && Math.sign(sx) !== Math.sign(side)) continue;
      if (this.wouldBeForward(index)) continue;
      const d = Math.hypot(b.x - c.x, b.z - c.z);
      if (d > p.maxPassM) continue;
      const score = (state === 'OPEN' ? p.pickOpen : state === 'TIGHT' ? p.pickTight : 0) - d * p.pickPerM;
      if (score > bestScore) {
        bestScore = score;
        best = index;
      }
    }
    return best;
  }

  /**
   * Throws a pass. power null = a standard pass (always the right weight). flat = thrown level with the passer at
   * most, so never forward (the pass buttons and the scrum-half's pass). Returns false if no pass can be thrown now.
   */
  pass(to: number, power: number | null, fromBase = false, flat = false): boolean {
    const c = this.carrierBody;
    if (this.phase !== 'play' || !c || this.carrier === null || to === this.carrier || to < 0 || to >= SEVEN) return false;
    const r = this.bodies[to]!;
    if (r.down > 0) return false;
    const dur = this.passSeconds(c, to, power);
    const aim = this.leadPoint(to, dur);
    if ((flat || fromBase) && this.progress(aim.z) > this.progress(c.z)) aim.z = c.z;
    const metres = Math.hypot(aim.x - c.x, aim.z - c.z);
    const fit = power === null ? 1 : powerFit(power, metres, this.t);
    const pressure = fromBase ? 0 : pressureAt(this.nearestDefender(c.x, c.z), this.t);
    const quality = passQuality(c.player.ratings, fit, pressure);
    const state = runnerState(this.nearestDefender(aim.x, aim.z), this.t);
    const chance = catchChance(r.player.ratings, quality, state, this.t);
    let forward = isForwardTarget(this.progress(c.z), this.progress(aim.z), this.t);
    let forwardWhy = forward ? 'aimed ahead of the passer' : '';
    if (!forward && pressure > 0 && !flat) {
      const risk = forwardRisk(pressure, this.t);
      const { roll, hit } = this.rng.rollDetailed(risk);
      if (hit) {
        forward = true;
        forwardWhy = `drifted under pressure, risk ${Math.round(risk)} percent, roll ${Math.round(roll)}`;
      }
    }
    this.flight = { from: this.carrier, to, t: 0, dur, sx: c.x, sz: c.z, tx: aim.x, tz: aim.z, quality, chance, state, forward, forwardWhy, peak: metres * this.t.passing.arcPerM, side: 0 };
    this.carrier = null;
    this.phase = 'flight';
    this.emit({ kind: 'pass', call: '', detail: `Pass to ${r.player.number} ${state}, catch ${Math.round(chance)} percent`, chance, who: to });
    return true;
  }

  /** Advances the match by one fixed step. */
  step(dt: number, input: StickInput): void {
    this.clock += dt;
    if (this.stepMatchClock(dt)) return;
    this.moveCooldown = Math.max(0, this.moveCooldown - dt);
    this.stepLeft = Math.max(0, this.stepLeft - dt);
    this.spinLeft = Math.max(0, this.spinLeft - dt);
    if (this.pendingMove) {
      this.pendingMove.t += dt;
      if (this.pendingMove.t > this.t.moves.validSeconds) this.pendingMove = null;
    }
    this.tackleCooldown = Math.max(0, this.tackleCooldown - dt);
    this.slowed = Math.max(0, this.slowed - dt);
    for (const b of this.bodies) {
      b.down = Math.max(0, b.down - dt);
      b.stun = Math.max(0, b.stun - dt);
    }
    if (this.phase === 'dead') {
      this.timer -= dt;
      for (const b of this.bodies) this.accelerate(b, 0, 0, dt);
      this.integrate(dt);
      if (this.timer <= 0) this.doRestart();
      return;
    }
    if (this.phase === 'kickoff') {
      // Both sides stand; the away side kicks when its wait is up, the user when he presses KICK.
      this.timer -= dt;
      for (const b of this.bodies) this.accelerate(b, 0, 0, dt);
      this.integrate(dt);
      if (this.attackSide === 0) {
        const ko = this.t.kickoff;
        this.kickoffAimX = Math.max(-ko.aimMaxX, Math.min(ko.aimMaxX, this.kickoffAimX + input.sx * -this.homeDir * ko.aimSpeedMps * dt));
      } else if (this.timer <= 0) {
        const ko = this.t.kickoff;
        // The opening kick goes long and down the middle, so the user starts the match with the ball (Jonny, 14 Nov 2026).
        if (this.openingKick) {
          // The opening kick drops onto our deepest man down the middle, so the team is already where it lands and
          // nobody runs back for it (Jonny, 15 Nov 2026).
          this.openingKick = false;
          const c = this.carrierBody!;
          let best = -1;
          let bestD = -1;
          for (let i = SEVEN; i < 2 * SEVEN; i++) {
            const b = this.bodies[i]!;
            const d = (b.z - c.z) * this.dir;
            if (Math.abs(b.x) <= ko.openingAimMaxX && d > bestD) {
              bestD = d;
              best = i;
            }
          }
          const r = this.bodies[best]!;
          this.kickoffAimX = r.x;
          this.kickoffKick((Math.abs(r.z - c.z) - ko.minM) / (ko.maxM - ko.minM));
        } else {
          const short = this.rng.next() * 100 < ko.aiShortPct;
          this.kickoffAimX = (this.rng.next() * 2 - 1) * ko.aiXSpreadM;
          this.kickoffKick(((short ? ko.aiShortM : ko.aiLongM) - ko.minM) / (ko.maxM - ko.minM));
        }
      }
      this.placeBall();
      return;
    }
    if (this.phase === 'setpiece') {
      this.stepSetPiece(dt);
      this.placeBall();
      return;
    }
    if (this.phase === 'kick') {
      // Their kick: the user runs our man nearest where it lands, so he can get under it (Jonny, 15 Nov 2026).
      const catcher = this.kickCatcher;
      if (catcher >= 0 && this.userDefending && catcher !== this.userDef && !this.userSteering) this.userDef = catcher;
      this.userSteering = this.userDefending && Math.hypot(input.sx, input.sy) > this.t.openPlay.stickDeadzone;
      this.stepKick(dt, this.userSteering ? input : null);
      this.placeBall();
      return;
    }
    if (this.phase === 'ruck' && this.setPiece?.kind === 'call') {
      // CALL PLAY at the ruck: the match waits for the card (or the coach's pick on time-out).
      const sp = this.setPiece;
      sp.t += dt;
      if (!this.human || sp.t >= this.t.playCall.seconds) this.callPlay(sp.coach);
      return;
    }
    this.ruckWordLeft = Math.max(0, this.ruckWordLeft - dt);
    if (this.phase !== 'ruck') {
      for (const b of this.bodies) {
        if (!b.bound) continue;
        b.bindLeft -= dt;
        if (b.bindLeft <= 0) b.bound = false;
      }
    }
    if (this.phase === 'ruck') {
      this.offloadLeft = Math.max(0, this.offloadLeft - dt);
      this.timer -= dt;
      this.moveToFormation(dt);
      this.placeBall();
      if (this.timer <= 0) this.endRuck();
      return;
    }
    // Who steers what: home attacking, the stick runs the carrier; away attacking, the AI runs the carrier and the
    // stick runs the user's defender.
    let carrierInput: StickInput | null = this.phase === 'play' ? input : null;
    let defInput: StickInput | null = null;
    if (this.attackSide === 1) {
      const d = this.ai.decide(this, dt);
      if (d.passSide !== null) this.passSide(d.passSide);
      if (d.step !== null) this.move('step', d.step);
      carrierInput = this.phase === 'play' ? d.input : null;
      // Assist: with the thumb off the stick, the AI moves the user's defender like the rest of the line.
      this.userSteering = this.userDefending && Math.hypot(input.sx, input.sy) > this.t.openPlay.stickDeadzone;
      defInput = this.userSteering ? input : null;
    }
    this.moveInPlay(dt, carrierInput, defInput);
    if (this.phase === 'flight') this.stepFlight(dt);
    else this.checkCarrier();
    this.placeBall();
  }

  // Formation ------------------------------------------------------------------------------------------------

  /**
   * Sets both lines around the base (the ruck, or the restart point). Attack: scrum-half at the base, the other six
   * in channels across the pitch, more of them on the open (wider) side, each further out a little deeper.
   * Defence: a flat line ahead of the base, one man opposite each attacker, a little in toward the ball.
   */
  private setFormation(): void {
    const f = this.t.formation;
    const halfW = this.t.field.widthM / 2 - f.touchMarginM;
    const bx = this.base.x;
    // Work in screen x (right positive), then turn back into world x.
    const toS = (x: number) => x * -this.dir;
    const baseS = toS(bx);
    const open = baseS > 0 ? -1 : 1;
    const sh = this.t.openPlay.scrumHalfSlot;
    const roomOpen = halfW - open * baseS;
    const roomBlind = halfW + open * baseS;
    const runners = SEVEN - 1;
    let nOpen = Math.round((runners * roomOpen) / Math.max(1, roomOpen + roomBlind));
    nOpen = Math.max(f.minOpen, Math.min(runners, nOpen));
    const nBlind = runners - nOpen;
    const channels: { s: number; depth: number }[] = [];
    const lay = (side: number, n: number, room: number) => {
      const gap = Math.max(f.minChannelM, Math.min(f.channelM, (room - f.firstLateralM) / Math.max(1, n - 1)));
      for (let k = 0; k < n; k++) {
        channels.push({ s: Math.max(-halfW, Math.min(halfW, baseS + side * (f.firstLateralM + k * gap))), depth: f.firstDepthM + k * f.depthStepM });
      }
    };
    lay(open, nOpen, roomOpen);
    lay(-open, nBlind, roomBlind);
    channels.sort((a, b) => a.s - b.s);

    // Attackers other than the scrum-half fill the channels in their current left-to-right order, so nobody crosses.
    const attackers = this.bodies
      .map((b, i) => ({ b, i }))
      .filter((o) => o.b.team === 0 && o.i !== sh)
      .sort((a, b) => toS(a.b.x) - toS(b.b.x));
    attackers.forEach((o, k) => {
      const ch = channels[k]!;
      this.spots[o.i] = { x: ch.s * -this.dir, depth: ch.depth };
    });
    this.spots[sh] = { x: bx, depth: f.baseBackM };
    // The first receiver: the nearest channel on the open side.
    let first = -1;
    let firstD = Infinity;
    for (const o of attackers) {
      const s = toS(this.spots[o.i]!.x) - baseS;
      if (Math.sign(s) === open && Math.abs(s) < firstD) {
        firstD = Math.abs(s);
        first = o.i;
      }
    }
    this.firstReceiver = first;

    // Defenders: one opposite each attacker, both lines in left-to-right order.
    const atkOrder = this.bodies
      .slice(0, SEVEN)
      .map((_, i) => ({ i, s: toS(this.spots[i]!.x) }))
      .sort((a, b) => a.s - b.s);
    const defenders = this.bodies
      .map((b, i) => ({ b, i }))
      .filter((o) => o.b.team === 1)
      .sort((a, b) => toS(a.b.x) - toS(b.b.x));
    defenders.forEach((o, k) => {
      const mark = atkOrder[k]!.i;
      this.marks[o.i] = mark;
      const mx = this.spots[mark]!.x;
      const pull = f.defenceInFraction + (this.callEffect?.shape === 'NARROW' ? this.t.playCall.narrowPull : 0);
      this.spots[o.i] = { x: mx + (bx - mx) * pull, depth: 0 };
    });
    this.lineP = this.base.p + f.defenceGapM;
  }

  /** World position of a body's formation spot (attack behind the base, defence on the line). */
  private spotPosition(i: number): { x: number; z: number } {
    const s = this.spots[i]!;
    return this.bodies[i]!.team === 0 ? { x: s.x, z: this.zAt(this.base.p - s.depth) } : { x: s.x, z: this.zAt(this.lineP) };
  }

  /** The reset: everyone runs back to his spot; the tackled player and the tackler get up first. */
  private moveToFormation(dt: number): void {
    const f = this.t.formation;
    for (const [i, b] of this.bodies.entries()) {
      if (b.down > 0) {
        b.vx = b.vz = 0;
        continue;
      }
      const at = b.bound ? this.ruckPoint(i) : this.spotPosition(i);
      this.steer(b, at.x, at.z, f.resetSpeed, false, dt, true);
    }
    this.integrate(dt);
  }

  private endRuck(): void {
    // Anyone who has not reached his spot is put there: the next phase always starts from set lines. Players
    // added to the ruck stay over the ball until they rejoin.
    for (const [i, b] of this.bodies.entries()) {
      const at = b.bound ? this.ruckPoint(i) : this.spotPosition(i);
      b.x = at.x;
      b.z = at.z;
      b.vx = b.vz = 0;
      b.down = 0;
      b.offside = false;
    }
    const contested = this.offloadFrom !== null;
    if (this.offloadFrom !== null || this.ruckRoll.chance < 100) this.ruckRoll = { chance: this.ruckBar.chance, roll: 0 };
    this.offloadFrom = null;
    if (this.ruckRoll.chance >= 100) this.ruckWon = true;
    else {
      const ruck = this.rng.rollDetailed(this.ruckRoll.chance);
      this.ruckWon = ruck.hit;
      this.ruckRoll.roll = ruck.roll;
    }
    const r = this.ruckRoll;
    const why = `Ruck, ${this.ruckAdds} added, ${Math.round(r.chance)} percent, roll ${Math.round(r.roll)}`;
    const adds = this.ruckAdds;
    this.ruckAdds = 0;
    // A word only when it means something to the user: the ball changed hands, or his added players won it.
    const word = !contested ? '' : this.attackSide === 0 ? (this.ruckWon ? (adds > 0 ? 'WON' : '') : 'TURNOVER') : this.ruckWon ? '' : 'STOLEN!';
    if (word) {
      this.ruckWord = word;
      this.ruckWordLeft = this.t.ruck.resultSeconds;
    }
    if (!this.ruckWon) {
      this.restart = { kind: 'swap', x: this.base.x, z: this.zAt(this.base.p) };
      this.deadBall({ kind: 'turnover', call: this.attackSide === 1 ? 'TURNOVER WON' : 'TURNOVER', detail: `${why}: LOST`, chance: r.chance, roll: r.roll }, this.t.openPlay.turnoverSeconds, true);
      return;
    }
    // Now and then the away side is caught offside at the home side's ruck: a penalty.
    if (r.chance < 100 && this.attackSide === 0) {
      const off = this.rng.rollDetailed(this.t.penalty.ruckOffsidePct);
      if (off.hit) {
        this.restart = { kind: 'set', sp: { kind: 'penalty', side: 0, x: this.base.x, z: this.zAt(this.base.p), t: 0 } };
        this.deadBall({ kind: 'penalty', call: 'PENALTY: OFFSIDE', detail: `Offside at the ruck, ${this.t.penalty.ruckOffsidePct} percent, roll ${Math.round(off.roll)}` }, this.t.openPlay.deadSeconds, true);
        return;
      }
    }
    const sh = this.t.openPlay.scrumHalfSlot;
    this.carrier = sh;
    this.phase = 'play';
    if (r.chance < 100) this.emit({ kind: 'ruckWon', call: '', detail: `${why}: WON`, chance: r.chance, roll: r.roll, who: sh });
    this.passOut();
  }

  /** The first receiver, or the next man that way if he went into the ruck. */
  private receiverOut(): number {
    const fr = this.firstReceiver;
    if (fr < 0 || !this.bodies[fr]!.bound) return fr;
    const sh = this.bodies[this.carrier!]!;
    return this.sideTarget(Math.sign((this.bodies[fr]!.x - sh.x) * -this.dir) < 0 ? -1 : 1);
  }

  /**
   * The scrum-half's pass from the base. After a play call (GDD 6.3): GO WIDE skips to the next man out, SWITCH
   * brings the next runner back inside behind the first receiver, CHIP & CHASE has the first receiver chip on the
   * catch, CRASH BALL hits the first receiver flat. Otherwise the first receiver.
   */
  private passOut(): void {
    this.firstReceiver = this.receiverOut();
    if (this.firstReceiver < 0) return;
    const card = this.callEffect?.card;
    let to = this.firstReceiver;
    const sh = this.bodies[this.carrier!]!;
    const first = this.bodies[this.firstReceiver]!;
    const open = Math.sign((first.x - sh.x) * -this.dir) || 1;
    // The runners on the open side, nearest first.
    const outside = this.bodies
      .map((b, i) => ({ b, i }))
      .filter((o) => o.i < SEVEN && !o.b.bound && o.i !== this.carrier && o.i !== this.firstReceiver && Math.sign((this.spots[o.i]!.x - first.x) * -this.dir) === open)
      .sort((a, b) => Math.abs(a.b.x - first.x) - Math.abs(b.b.x - first.x));
    if (card === 'WIDE' && outside[0]) to = outside[0].i;
    if (card === 'SWITCH' && outside[0]) {
      // The scissors: the next man cuts back inside, behind the first receiver.
      const s = this.spots[outside[0].i]!;
      s.x = first.x - open * -this.dir * this.t.playCall.switchInsideM;
    }
    this.chipOnCatch = card === 'CHIP';
    this.pass(to, null, true, true);
  }

  // Open play ------------------------------------------------------------------------------------------------

  private stepFlight(dt: number): void {
    const f = this.flight!;
    f.t += dt;
    if (f.t < f.dur) return;
    const r = this.bodies[f.to]!;
    this.flight = null;
    if (f.forward) {
      this.deadBall({ kind: 'forward', call: 'FORWARD PASS', detail: `Pass ${f.forwardWhy}` }, this.t.openPlay.deadSeconds);
      return;
    }
    const { roll, hit } = this.rng.rollDetailed(f.chance);
    if (hit) {
      this.carrier = f.to;
      this.phase = 'play';
      if (this.attackSide === 1) this.autoSwitch();
      this.emit({ kind: 'caught', call: '', detail: `Pass to ${r.player.number} ${f.state}, catch ${Math.round(f.chance)} percent, roll ${Math.round(roll)}: CAUGHT`, chance: f.chance, roll, who: f.to });
      if (this.chipOnCatch) {
        this.chipOnCatch = false;
        this.kick('chip');
      }
    } else {
      this.deadBall(
        { kind: 'knockOn', call: 'KNOCK-ON', detail: `Pass to ${r.player.number} ${f.state}, catch ${Math.round(f.chance)} percent, roll ${Math.round(roll)}: DROPPED`, chance: f.chance, roll, who: f.to },
        this.t.openPlay.deadSeconds,
      );
    }
  }

  /** Try, touch and tackles for the ball carrier. */
  private checkCarrier(): void {
    const c = this.carrierBody;
    if (!c || this.carrier === null) return;
    const o = this.t.openPlay;
    if (this.progress(c.z) >= this.tryLine) {
      this.score[c.side] += o.tryPoints;
      // The conversion, in line with where it was grounded; then (sevens law) the side that scored kicks off, so
      // the side that conceded gets the ball back.
      const back = this.zAt(this.tryLine - this.t.goal.conversionBackM);
      this.restart = { kind: 'set', sp: { kind: 'goal', side: c.side, x: c.x, z: back, points: this.t.goal.conversionPoints, stage: 'aim', t: 0, made: false, aimX: 0, then: c.side } };
      this.deadBall({ kind: 'try', call: 'TRY!', detail: `${c.player.number} ${c.player.lastName.toUpperCase()} scores`, who: this.carrier }, o.trySeconds, true);
      return;
    }
    if (Math.abs(c.x) > this.t.field.widthM / 2) {
      // Lineout to the other side where it went out.
      this.restart = { kind: 'set', sp: this.lineoutFor(c.side === 0 ? 1 : 0, c.x, c.z) };
      this.deadBall({ kind: 'touch', call: 'INTO TOUCH', detail: `${c.player.number} carried over the touchline`, who: this.carrier }, o.deadSeconds, true);
      return;
    }
    if (this.tackleCooldown > 0) return;
    const reach = this.t.tackle.contactM;
    let tackler = -1;
    let nearest = Infinity;
    let others = 0;
    for (let i = SEVEN; i < 2 * SEVEN; i++) {
      const d = this.bodies[i]!;
      if (d.down > 0 || d.stun > 0 || d.offside || d.bound) continue;
      if (this.chasing && i === this.userDef) continue;
      const dist = Math.hypot(d.x - c.x, d.z - c.z);
      if (dist > reach) continue;
      if (dist < nearest) {
        if (tackler >= 0) others++;
        nearest = dist;
        tackler = i;
      } else others++;
    }
    if (tackler < 0) return;
    this.resolveTackle(tackler, others, 'plain');
  }

  /**
   * A tackle attempt by `tackler` on the carrier: the break roll, then either the carrier goes on or he goes
   * down and the ruck forms. 'dive' is the user's TACKLE tap (easier to make), 'big' his held big hit (harder,
   * but it can knock the ball loose: a turnover on the spot).
   */
  private resolveTackle(tackler: number, others: number, style: 'plain' | 'dive' | 'big'): void {
    const c = this.carrierBody!;
    const ci = this.carrier!;
    const def = this.bodies[tackler]!;
    const u = this.t.userDefence;
    const mv = this.pendingMove;
    this.pendingMove = null;
    const kind: Move = mv ? mv.kind : 'none';
    const grade: MoveGrade = mv ? mv.grade : 'NONE';
    const styleMod = (style === 'dive' ? -u.diveBonus : style === 'big' ? u.bigHitMiss : 0) + (this.callEffect?.match ? this.t.playCall.matchBonus : 0);
    // Difficulty (addendum 5: ROOKIE / PRO / LEGEND to come): the away side's carriers break tackles less often,
    // so a player still learning to defend gets the ball back.
    const aiMod = c.side === 1 ? this.t.ai.breakMod : 0;
    const chance = Math.max(this.t.tackle.min, Math.min(this.t.tackle.max, breakChance(c.player.ratings, def.player.ratings, c.sprinting, c.stamina, others, this.t, kind, grade) + styleMod + aiMod));
    const { roll, hit } = this.rng.rollDetailed(chance);
    const what = kind === 'none' ? '' : `${grade === 'NONE' ? '' : `${grade} `}${kind.toUpperCase()}, `;
    const how = style === 'big' ? 'big hit' : style === 'dive' ? 'dive tackle' : 'tackle';
    const why = `${what}${how} by ${def.player.number}, break ${Math.round(chance)} percent, roll ${Math.round(roll)}`;
    if (hit) {
      def.stun = this.t.tackle.beatenSeconds;
      def.down = this.t.tackle.beatenSeconds;
      def.offside = true;
      this.slowed = this.t.tackle.brokenSlowSeconds;
      if (tackler === this.userDef) this.autoSwitch();
      this.tackleCooldown = this.t.tackle.cooldownSeconds;
      const call = grade === 'PERFECT' ? `PERFECT ${kind === 'none' ? 'STEP' : kind.toUpperCase()}!` : 'BROKEN TACKLE';
      this.emit({ kind: 'broke', call, detail: `${why}: BROKE`, chance, roll, who: ci });
      return;
    }
    // Tackled: down goes the carrier, the ball is placed, and both lines re-form around the ruck.
    // The tackle as it is drawn: the tackler drives in low from his side, the carrier is carried forward by his
    // momentum and goes down; the tackler ends up wrapped round his legs beside him.
    const f = this.t.formation;
    const k = this.t.tackle;
    const v = Math.hypot(c.vx, c.vz);
    const ux = v > 0.5 ? c.vx / v : 0;
    const uz = v > 0.5 ? c.vz / v : this.dir;
    const from = { cx: c.x, cz: c.z, tx: def.x, tz: def.z };
    const slide = Math.min(k.slideMaxM, v * k.slidePerMps);
    c.x += ux * slide;
    c.z += uz * slide;
    const side = Math.sign((def.x - c.x) * uz - (def.z - c.z) * ux) || 1;
    def.x = c.x - ux * k.wrapBackM + uz * side * k.wrapSideM;
    def.z = c.z - uz * k.wrapBackM - ux * side * k.wrapSideM;
    // How hard they meet: the speed one runs into the other (head-on is both speeds, a chase from behind little).
    const closing = Math.hypot(def.vx - c.vx, def.vz - c.vz);
    this.lastTackle = { carrier: ci, tackler, from, to: { cx: c.x, cz: c.z, tx: def.x, tz: def.z }, big: style === 'big' || closing >= k.bigHitMps };
    c.down = f.tackledDownSeconds;
    def.down = f.tackledDownSeconds;
    c.vx = c.vz = 0;
    def.vx = def.vz = 0;
    this.emit({ kind: 'tackled', call: style === 'big' ? 'BIG HIT!' : '', detail: `${why}: TACKLED`, chance, roll, who: ci });
    this.callEffect = null;
    if (style === 'big') {
      // A big hit can be high: penalty to the attack.
      const high = this.rng.rollDetailed(this.t.penalty.bigHitHighPct);
      if (high.hit) {
        this.restart = { kind: 'set', sp: { kind: 'penalty', side: this.attackSide, x: c.x, z: c.z, t: 0 } };
        this.carrier = null;
        this.deadBall({ kind: 'penalty', call: 'PENALTY: HIGH TACKLE', detail: `High tackle ${this.t.penalty.bigHitHighPct} percent, roll ${Math.round(high.roll)}` }, this.t.openPlay.deadSeconds, true);
        return;
      }
      // The big hit can jolt the ball loose: the tackler's side picks it up and goes.
      const d = this.rng.rollDetailed(u.dislodgePct);
      if (d.hit) {
        let pick = -1;
        let pd = Infinity;
        for (let i = SEVEN; i < 2 * SEVEN; i++) {
          const b = this.bodies[i]!;
          if (b.down > 0) continue;
          const dist = Math.hypot(b.x - c.x, b.z - c.z);
          if (dist < pd) {
            pd = dist;
            pick = i;
          }
        }
        if (pick >= 0) {
          this.emit({ kind: 'turnover', call: 'TURNOVER', detail: `Big hit jolts it loose, ${u.dislodgePct} percent, roll ${Math.round(d.roll)}: picked up by ${this.bodies[pick]!.player.number}`, chance: u.dislodgePct, roll: d.roll, who: pick });
          this.carrier = null;
          this.swapPossession(this.bodies[pick]!.x, this.bodies[pick]!.z, pick);
          return;
        }
      }
    }
    this.ruckAdds = 0;
    this.chasing = false;
    this.offloadFrom = this.carrier;
    this.offloadLeft = this.t.offload.windowSeconds;
    const halfW = this.t.field.widthM / 2 - f.touchMarginM;
    this.base = { x: Math.max(-halfW, Math.min(halfW, c.x)), p: this.progress(c.z) };
    this.carrier = null;
    this.phase = 'ruck';
    this.timer = f.resetSeconds;
    this.setFormation();
  }

  /** A stoppage. Unless the caller set the restart, the other side gets the ball where it went dead. */
  private deadBall(e: PlayEvent, seconds: number, restartSet = false): void {
    // Knock-on and forward pass: scrum to the other side where it happened (sevens law).
    if (!restartSet) this.restart = { kind: 'set', sp: this.scrumFor(this.attackSide === 0 ? 1 : 0, this.ball.x, this.ball.z) };
    this.phase = 'dead';
    this.timer = seconds;
    this.flight = null;
    this.kickBall = null;
    this.chasing = false;
    if (e.kind !== 'try') this.carrier = null;
    this.emit(e);
  }

  private doRestart(): void {
    const r = this.restart;
    this.restart = { kind: 'reset' };
    if (r.kind === 'swap') this.swapPossession(r.x, r.z, null);
    else if (r.kind === 'set') this.startSetPiece(r.sp);
    else if (r.kind === 'kickoff') this.setupKickoff(r.kicking);
    else this.resetAttack();
  }

  /** The side attacking now (0 home, 1 away). */
  get attackSide(): 0 | 1 {
    return this.bodies[0]!.side;
  }

  /** True while the user's side defends with a defender of its own. */
  get userDefending(): boolean {
    return this.attackSide === 1 && this.humanDefends && this.userDef >= 0;
  }

  /**
   * The ball changes hands. The two sevens swap places in the body list (attack first), the attack direction
   * flips, and play restarts from (x, z): from set lines after a stoppage, or live with `liveCarrier` (old body
   * index) running with the ball after an intercept, a dislodged ball or a gathered kick.
   */
  swapPossession(x: number, z: number, liveCarrier: number | null): void {
    const remap = (i: number) => (i + SEVEN) % (2 * SEVEN);
    this.flipSides();
    const halfW = this.t.field.widthM / 2 - this.t.formation.touchMarginM;
    const lim = this.tryLine - this.t.formation.touchMarginM;
    this.base = { x: Math.max(-halfW, Math.min(halfW, x)), p: Math.max(-lim, Math.min(lim, this.progress(z))) };
    if (liveCarrier !== null) {
      this.carrier = remap(liveCarrier);
      this.phase = 'play';
      this.setFormation();
      this.lineP = Math.max(this.base.p + this.t.defence.minGapM, this.lineP);
    } else {
      this.carrier = null;
      this.ruckWon = true;
      this.ruckRoll = { chance: 100, roll: 0 };
      this.phase = 'ruck';
      this.timer = this.t.formation.resetSeconds;
      this.setFormation();
    }
    this.pickUserDefender();
    this.emit({ kind: 'possession', call: '', detail: `${this.attackSide === 0 ? 'Home' : 'Away'} ball` });
  }

  /** The two sevens swap places in the body list (attack first) and the attack direction flips. */
  private flipSides(): void {
    const bodies = [...this.bodies.slice(SEVEN), ...this.bodies.slice(0, SEVEN)];
    this.bodies.length = 0;
    this.bodies.push(...bodies);
    this.bodies.forEach((b, i) => {
      b.team = i < SEVEN ? 0 : 1;
      b.offside = b.bound = false;
      b.stun = 0;
    });
    this.dir = this.dir === 1 ? -1 : 1;
    this.flight = null;
    this.kickBall = null;
    this.pendingMove = null;
    this.offloadFrom = null;
    this.offloadLeft = 0;
    this.tackleCooldown = 0;
    this.slowed = 0;
    this.ruckAdds = 0;
    this.chasing = false;
    this.callEffect = null;
    this.chipOnCatch = false;
  }

  // Set pieces -------------------------------------------------------------------------------------------------

  private scrumFor(side: 0 | 1, x: number, z: number): SetPiece {
    const lim = this.t.field.widthM / 2 - this.t.scrum.fromTouchM;
    return { kind: 'scrum', side, x: Math.max(-lim, Math.min(lim, x)), z, stage: 'set', hits: 0, taps: 0, t: 0 };
  }

  private lineoutFor(side: 0 | 1, x: number, z: number): SetPiece {
    const lim = this.tryLine - this.t.lineout.fromTryLineM;
    return { kind: 'lineout', side, x: (x >= 0 ? 1 : -1) * (this.t.field.widthM / 2), z: Math.max(-lim, Math.min(lim, z)), stage: 'pick', jumper: null, guess: null, t: 0 };
  }

  /** Average rating of a side's three forwards (shirts 1 to 3). */
  private forwards(side: 0 | 1, key: 'LIN' | 'SCR'): number {
    return avgRating(this.bodies.filter((b) => b.side === side && b.slot <= 2).map((b) => b.player), key);
  }

  /**
   * Starts a restart: the side with the throw, the feed, the kick or the penalty becomes the attack, everyone
   * takes their place, and a home lineout, scrum or tap penalty begins with the play call (GDD 6.3).
   */
  startSetPiece(sp: SetPiece): void {
    this.flight = null;
    this.kickBall = null;
    this.carrier = null;
    if (this.attackSide !== sp.side) this.flipSides();
    this.callEffect = null;
    this.phase = 'setpiece';
    this.userDef = -1;
    this.layoutSetPiece(sp);
    this.setPiece = sp.side === 0 && (sp.kind === 'lineout' || sp.kind === 'scrum' || sp.kind === 'tap') ? this.callFor(sp) : sp;
    const who = sp.side === 0 ? 'Home' : 'Away';
    const call = sp.kind === 'lineout' ? 'LINEOUT' : sp.kind === 'scrum' ? 'SCRUM' : sp.kind === 'goal' ? (sp.points === this.t.goal.conversionPoints ? 'CONVERSION' : 'KICK AT GOAL') : '';
    // No banner: the set-piece panel shows the title.
    if (sp.kind !== 'tap' && sp.kind !== 'penalty') this.emit({ kind: sp.kind === 'call' ? 'call' : sp.kind, call: '', detail: `${who} ${call.toLowerCase()}` });
  }

  /** The play call before a home restart: the AI defence picks a shape; the coach's pick usually reads it. */
  private callFor(next: SetPiece | null): SetPiece {
    const shape = DEFENCE_SHAPES[this.rng.int(0, DEFENCE_SHAPES.length - 1)]!;
    const right = this.rng.next() * 100 < this.t.playCall.coachRightPct;
    const others = PLAY_CARDS.filter((c) => c !== STRONG_AGAINST[shape]);
    const coach = right ? STRONG_AGAINST[shape] : others[this.rng.int(0, others.length - 1)]!;
    return { kind: 'call', side: 0, next, t: 0, shape, coach };
  }

  /** Puts everyone in place for a lineout, scrum or goal kick (a penalty or tap is taken where they stand). */
  private layoutSetPiece(sp: SetPiece): void {
    this.setPieceRole = this.bodies.map(() => null);
    const d = this.dir;
    const halfW = this.t.field.widthM / 2;
    const put = (i: number, x: number, z: number) => {
      const b = this.bodies[i]!;
      b.x = x;
      b.z = z;
      b.vx = b.vz = 0;
      b.down = b.stun = 0;
      b.offside = b.bound = false;
    };
    const bySlot = (team: 0 | 1, slot: number) => this.bodies.findIndex((b) => b.team === team && b.slot === slot);
    if (sp.kind === 'lineout') {
      const L = this.t.lineout;
      const sg = sp.x >= 0 ? 1 : -1;
      const jumpers = [0, 2, 5];
      jumpers.forEach((slot, k) => {
        const ax = sg * (halfW - L.inFromTouchM - k * L.gapM);
        put(bySlot(0, slot), ax, sp.z - (d * L.linesApartM) / 2);
        put(bySlot(1, k), ax, sp.z + (d * L.linesApartM) / 2);
      });
      const thrower = bySlot(0, 1);
      put(thrower, sg * (halfW + 0.6), sp.z);
      this.setPieceRole[thrower] = 'thrower';
      put(bySlot(0, 3), sg * (halfW - L.inFromTouchM - 2 * L.gapM - 2), sp.z - d * 3);
      // Backs: lined out toward the middle, the defence 10 m back.
      const rest = (team: 0 | 1, slots: number[], back: number) =>
        slots.forEach((slot, k) => put(bySlot(team, slot), sg * (halfW - L.backsInM - k * L.backsGapM), sp.z + (team === 0 ? -d : d) * (back + k)));
      rest(0, [4, 6], 5);
      rest(1, [3, 4, 5, 6], 10);
    } else if (sp.kind === 'scrum') {
      const S = this.t.scrum;
      for (let k = 0; k < 3; k++) {
        const x = sp.x + (k - 1) * S.bindM;
        put(bySlot(0, k), x, sp.z - d * S.bindM);
        put(bySlot(1, k), x, sp.z + d * S.bindM);
        this.setPieceRole[bySlot(0, k)] = 'scrum';
        this.setPieceRole[bySlot(1, k)] = 'scrum';
      }
      put(bySlot(0, 3), sp.x + 1.6, sp.z - d * 1.4);
      const sideOf = sp.x > 0 ? -1 : 1;
      [4, 5, 6].forEach((slot, k) => put(bySlot(0, slot), sp.x + sideOf * (6 + k * 7), sp.z - d * (S.backsBackM + k)));
      [3, 4, 5, 6].forEach((slot, k) => put(bySlot(1, slot), sp.x + sideOf * (2 + k * 7), sp.z + d * S.backsBackM));
    } else if (sp.kind === 'goal') {
      // The best kicker takes it; his side stands back, the other side behind its posts.
      let kicker = 0;
      for (let i = 0; i < SEVEN; i++) if (this.bodies[i]!.player.ratings.KCK > this.bodies[kicker]!.player.ratings.KCK) kicker = i;
      put(kicker, sp.x, sp.z);
      this.setPieceRole[kicker] = 'kicker';
      let k = 0;
      for (let i = 0; i < SEVEN; i++) if (i !== kicker) put(i, sp.x + (k++ - 2.5) * 4, sp.z - d * 12);
      for (let i = SEVEN; i < 2 * SEVEN; i++) put(i, (i - SEVEN - 3) * 5, this.zAt(this.tryLine + 3));
    }
  }

  /** Each step of a restart: everyone holds still while the user (or the AI) makes the calls. */
  private stepSetPiece(dt: number): void {
    const sp = this.setPiece!;
    for (const b of this.bodies) this.accelerate(b, 0, 0, dt);
    this.integrate(dt);
    const ai = !this.human || sp.side === 1;
    switch (sp.kind) {
      case 'call':
        sp.t += dt;
        if (!this.human || sp.t >= this.t.playCall.seconds) this.callPlay(sp.coach);
        break;
      case 'tap':
        this.formUp(sp.side, sp.x, sp.z);
        break;
      case 'lineout': {
        const L = this.t.lineout;
        sp.t += dt;
        if (sp.stage === 'pick') {
          // Home throw: the user picks the jumper. Away throw: the user guesses theirs. Out of time: a random one.
          if (!this.human || sp.t >= L.pickSeconds) this.lineoutPick(this.rng.int(0, 2) as Jumper);
        } else if (sp.stage === 'throw') {
          if (ai ? sp.t >= L.aiThrowSeconds : sp.t >= L.maxThrowSeconds) {
            if (sp.side === 1) sp.jumper = this.rng.int(0, 2) as Jumper;
            this.resolveThrow(ai ? this.rng.next() * 100 < L.aiOnSpotPct : false);
          }
        } else if (sp.t >= L.airSeconds) {
          this.setPiece = null;
          this.formUp(sp.won!, this.lineoutRestartX(sp), sp.z);
        }
        break;
      }
      case 'scrum': {
        const S = this.t.scrum;
        sp.t += dt;
        if (sp.stage === 'set') {
          if (sp.t >= S.setSeconds) {
            sp.stage = 'push';
            sp.t = 0;
          }
        } else if (!this.human) {
          let hits = 0;
          for (let k = 0; k < S.taps; k++) if (this.rng.next() * 100 < S.aiHitPct) hits++;
          sp.hits = hits;
          this.resolveScrum(sp);
        } else if (sp.t >= S.maxSeconds) this.resolveScrum(sp);
        break;
      }
      case 'goal': {
        const G = this.t.goal;
        sp.t += dt;
        if (sp.stage === 'aim') {
          // The AI's kick; a home kick nobody swipes is taken by the kicker himself when the time is up.
          if ((ai && sp.t >= G.aiAimSeconds) || sp.t >= G.budgetSeconds) this.resolveGoal(sp, (this.rng.next() * 2 - 1) * G.aiOffsetSpread);
        } else if (sp.t >= G.flightSeconds) {
          if (sp.made) this.score[sp.side] += sp.points;
          this.emit({ kind: 'goal', call: sp.made ? (sp.points === G.conversionPoints ? 'CONVERTED!' : 'GOAL!') : 'MISSED', detail: sp.made ? 'Over the bar' : 'Wide' });
          this.setPiece = null;
          this.setPieceRole = [];
          this.phase = 'dead';
          this.timer = G.resultSeconds;
          this.restart = { kind: 'kickoff', kicking: sp.then };
        }
        break;
      }
      case 'penalty':
        sp.t += dt;
        // The AI's choice: at goal when in range, to touch from its own half for territory, else tap and go.
        if (ai) this.penaltyChoice(this.canKickAtGoal ? 'goal' : this.progress(sp.z) < 0 ? 'touch' : 'tap');
        else if (sp.t >= this.t.penalty.chooseSeconds) this.penaltyChoice('tap');
        break;
    }
  }

  /** PLAY CALL: the card the user tapped (or the coach's pick when the clock runs out). */
  callPlay(card: PlayCard): boolean {
    const sp = this.setPiece;
    if ((this.phase !== 'setpiece' && this.phase !== 'ruck') || !sp || sp.kind !== 'call') return false;
    const match = STRONG_AGAINST[sp.shape] === card;
    this.callEffect = { card, shape: sp.shape, match };
    this.emit({ kind: 'call', call: '', detail: `Called ${card}, defence ${sp.shape}${match ? ': the right call' : ''}` });
    this.setPiece = sp.next;
    return true;
  }

  /** LINEOUT: the jumper to throw to (home throw) or the jumper to contest (away throw). */
  lineoutPick(j: Jumper): boolean {
    const sp = this.setPiece;
    if (this.phase !== 'setpiece' || !sp || sp.kind !== 'lineout' || sp.stage !== 'pick') return false;
    if (sp.side === 0) {
      sp.jumper = j;
      // The away defence guesses, right some of the time.
      const right = this.rng.next() * 100 < this.t.lineout.aiGuessRightPct;
      sp.guess = right ? j : (((j + 1 + this.rng.int(0, 1)) % 3) as Jumper);
    } else sp.guess = j;
    sp.stage = 'throw';
    sp.t = 0;
    return true;
  }

  /** LINEOUT: the throw, on the timing bar's marker as it is now. */
  lineoutThrow(): boolean {
    const sp = this.setPiece;
    if (this.phase !== 'setpiece' || !sp || sp.kind !== 'lineout' || sp.stage !== 'throw' || sp.side !== 0) return false;
    this.resolveThrow(onSweetSpot(throwMarker(sp.t, this.t), this.t));
    return true;
  }

  private resolveThrow(onSpot: boolean): void {
    const sp = this.setPiece as Extract<SetPiece, { kind: 'lineout' }>;
    const L = this.t.lineout;
    const other: 0 | 1 = sp.side === 0 ? 1 : 0;
    if (!onSpot) {
      const ns = this.rng.rollDetailed(L.notStraightPct);
      if (ns.hit) {
        this.emit({ kind: 'lineout', call: 'NOT STRAIGHT', detail: `Throw off the sweet spot, not straight ${L.notStraightPct} percent, roll ${Math.round(ns.roll)}: scrum` });
        this.setPiece = null;
        this.startSetPiece(this.scrumFor(other, sp.x, sp.z));
        return;
      }
    }
    const guessed = sp.guess === sp.jumper;
    const chance = lineoutWinChance(this.forwards(sp.side, 'LIN'), this.forwards(other, 'LIN'), guessed, onSpot, this.t);
    const { roll, hit } = this.rng.rollDetailed(chance);
    sp.won = hit ? sp.side : other;
    sp.stage = 'air';
    sp.t = 0;
    const jumperBody = this.bodies.findIndex((b) => b.team === (hit ? 0 : 1) && b.slot === (hit ? [0, 2, 5][sp.jumper ?? 1] : (sp.jumper ?? 1)));
    if (jumperBody >= 0) this.setPieceRole[jumperBody] = 'jumper';
    const what = `${JUMPERS[sp.jumper ?? 1]} jumper, ${guessed ? 'contested' : 'not read'}${onSpot ? '' : ', off the sweet spot'}, ${Math.round(chance)} percent, roll ${Math.round(roll)}`;
    this.emit({ kind: 'lineout', call: hit ? '' : sp.side === 0 ? 'LINEOUT LOST' : 'LINEOUT STOLEN', detail: `${what}: ${hit ? 'WON' : 'LOST'}`, chance, roll });
  }

  /** Where play restarts after a lineout: in from the touchline on the same line. */
  private lineoutRestartX(sp: Extract<SetPiece, { kind: 'lineout' }>): number {
    return (sp.x >= 0 ? 1 : -1) * (this.t.field.widthM / 2 - this.t.lineout.restartInM);
  }

  /** SCRUM: one tap on the PUSH meter; a hit if the needle is in the zone. Three taps and it is decided. */
  scrumPush(): 'hit' | 'miss' | null {
    const sp = this.setPiece;
    if (this.phase !== 'setpiece' || !sp || sp.kind !== 'scrum' || sp.stage !== 'push') return null;
    const hit = inScrumZone(scrumNeedle(sp.t, this.t), this.t);
    sp.taps++;
    if (hit) sp.hits++;
    if (sp.taps >= this.t.scrum.taps) this.resolveScrum(sp);
    return hit ? 'hit' : 'miss';
  }

  private resolveScrum(sp: Extract<SetPiece, { kind: 'scrum' }>): void {
    const userFeeds = sp.side === 0;
    const out = scrumOutcome(sp.hits, userFeeds, this.forwards(0, 'SCR'), this.forwards(1, 'SCR'), this.t);
    const k = this.rng.rollDetailed(out.keepPct);
    const winner: 0 | 1 = k.hit ? sp.side : sp.side === 0 ? 1 : 0;
    const why = `Scrum ${sp.hits} of ${this.t.scrum.taps} hits, ${sp.side === 0 ? 'keep' : 'they keep'} ${Math.round(out.keepPct)} percent, roll ${Math.round(k.roll)}`;
    this.setPiece = null;
    this.setPieceRole = [];
    if (k.hit && out.penaltyPct > 0) {
      const p = this.rng.rollDetailed(out.penaltyPct);
      if (p.hit) {
        this.emit({ kind: 'scrum', call: 'SCRUM PENALTY', detail: `${why}: dominant, penalty ${out.penaltyPct} percent, roll ${Math.round(p.roll)}` });
        this.startSetPiece({ kind: 'penalty', side: winner, x: sp.x, z: sp.z, t: 0 });
        return;
      }
    }
    this.emit({ kind: 'scrum', call: winner === sp.side ? '' : sp.side === 0 ? 'SCRUM LOST' : 'SCRUM WON', detail: `${why}: ${winner === sp.side ? 'CLEAN BALL' : 'TURNED OVER'}`, chance: out.keepPct, roll: k.roll });
    this.formUp(winner, sp.x, sp.z);
  }

  /** Distance from a goal kick to the posts (metres). */
  private goalDistance(sp: { x: number; z: number }): number {
    return Math.hypot(sp.x, this.zAt(this.tryLine) - sp.z);
  }

  private goalPct(sp: Extract<SetPiece, { kind: 'goal' }>, offset: number): number {
    return goalChance(this.goalDistance(sp), offset, this.t);
  }

  /** The goal kick being lined up (for the HUD), or null. */
  get goalInfo(): { distanceM: number; side: 0 | 1; points: number } | null {
    const sp = this.setPiece;
    if (!sp || sp.kind !== 'goal' || sp.stage !== 'aim') return null;
    return { distanceM: this.goalDistance(sp), side: sp.side, points: sp.points };
  }

  /** Where the posts are for the kick being lined up. */
  private posts(): { x: number; z: number } {
    return { x: 0, z: this.zAt(this.tryLine) };
  }

  /** The heading straight at the posts and the power that just reaches them, for the home kick being lined up. */
  get goalAim(): { angle: number; power: number; metres: number; spot: { x: number; z: number }; posts: { x: number; z: number } } | null {
    const sp = this.setPiece;
    if (!sp || sp.kind !== 'goal' || sp.stage !== 'aim') return null;
    const posts = this.posts();
    const metres = this.goalDistance(sp);
    return { angle: aimAngle(sp, posts), power: powerFor(metres, this.t), metres, spot: { x: sp.x, z: sp.z }, posts };
  }

  /**
   * CONVERSION or PENALTY GOAL (addendum 4): one swipe. angle is the world heading from straight up the pitch
   * (positive toward +x), power 0 to 1 from the swipe speed. The wind drifts it.
   */
  goalSwipe(angle: number, power: number): boolean {
    const sp = this.setPiece;
    if (this.phase !== 'setpiece' || !sp || sp.kind !== 'goal' || sp.stage !== 'aim' || sp.side !== 0) return false;
    const kicker = this.bodies.find((b) => b.team === 0 && this.setPieceRole[this.bodies.indexOf(b)] === 'kicker') ?? this.bodies[4]!;
    const r = swipeKick(sp, this.posts(), angle, power, this.wind, kicker.player.ratings.KCK, this.rng, this.t);
    sp.made = r.good;
    sp.aimX = this.posts().x + r.missX;
    sp.stage = 'flight';
    sp.t = 0;
    this.emit({ kind: 'goal', call: '', detail: r.why });
    return true;
  }

  private resolveGoal(sp: Extract<SetPiece, { kind: 'goal' }>, offset: number): void {
    const chance = this.goalPct(sp, offset);
    const { roll, hit } = this.rng.rollDetailed(chance);
    sp.made = hit;
    sp.aimX = hit ? 0 : (offset >= 0 ? 1 : -1) * this.t.goal.wideM;
    sp.stage = 'flight';
    sp.t = 0;
    this.emit({ kind: 'goal', call: '', detail: `${sp.points === this.t.goal.conversionPoints ? 'Conversion' : 'Penalty goal'} ${Math.round(this.goalDistance(sp))} m, ${Math.round(chance)} percent, roll ${Math.round(roll)}: ${hit ? 'GOOD' : 'MISSED'}`, chance, roll });
  }

  /** True when the penalty is near enough to kick at goal (GDD 5: inside 30 m). */
  get canKickAtGoal(): boolean {
    const sp = this.setPiece;
    return !!sp && sp.kind === 'penalty' && this.goalDistance(sp) <= this.t.goal.kickInsideM;
  }

  /** PENALTY: tap and go, kick to touch (lineout to you 20 m up), or a kick at goal (inside 30 m). */
  penaltyChoice(c: PenaltyChoice): boolean {
    const sp = this.setPiece;
    if (this.phase !== 'setpiece' || !sp || sp.kind !== 'penalty') return false;
    if (c === 'goal' && !this.canKickAtGoal) return false;
    this.setPiece = null;
    this.emit({ kind: 'penalty', call: c === 'tap' ? 'TAP AND GO' : c === 'touch' ? 'KICK TO TOUCH' : 'KICK AT GOAL', detail: `Penalty: ${c}` });
    if (c === 'tap') this.startSetPiece({ kind: 'tap', side: sp.side, x: sp.x, z: sp.z });
    else if (c === 'touch') this.startSetPiece(this.lineoutFor(sp.side, sp.x, sp.z + this.dir * this.t.penalty.touchGainM));
    else this.startSetPiece({ kind: 'goal', side: sp.side, x: sp.x, z: sp.z, points: this.t.goal.penaltyPoints, stage: 'aim', t: 0, made: false, aimX: 0, then: sp.side });
    return true;
  }

  /** After a restart: `side` has the ball and both lines form up at (x, z); then the scrum-half passes out. */
  private formUp(side: 0 | 1, x: number, z: number): void {
    const effect = this.callEffect;
    if (this.attackSide !== side) this.flipSides();
    // A play call only counts for the side that called it.
    this.callEffect = side === 0 ? effect : null;
    this.setPiece = null;
    this.setPieceRole = [];
    const halfW = this.t.field.widthM / 2 - this.t.formation.touchMarginM;
    const lim = this.tryLine - this.t.formation.touchMarginM;
    this.base = { x: Math.max(-halfW, Math.min(halfW, x)), p: Math.max(-lim, Math.min(lim, this.progress(z))) };
    this.carrier = null;
    this.ruckWon = true;
    this.ruckRoll = { chance: 100, roll: 0 };
    this.offloadFrom = null;
    this.phase = 'ruck';
    this.timer = this.t.formation.resetSeconds;
    this.setFormation();
    this.pickUserDefender();
    this.emit({ kind: 'possession', call: '', detail: `${this.attackSide === 0 ? 'Home' : 'Away'} ball` });
  }

  /**
   * How far a home defender is from making the tackle: his distance to the carrier (the ball when nobody has it),
   * plus a penalty when the carrier is already past him, since he would have to turn and chase.
   */
  private tackleCost(i: number): number {
    const b = this.bodies[i]!;
    const c = this.carrierBody;
    const tx = c ? c.x : this.ball.x;
    const tz = c ? c.z : this.ball.z;
    const behind = c && this.progress(b.z) < this.progress(c.z) - this.t.defence.beatenM ? this.t.userDefence.switchBehindM : 0;
    return Math.hypot(b.x - tx, b.z - tz) + behind;
  }

  /** The home defender best placed to tackle becomes the user's (none while home attacks). */
  private pickUserDefender(exclude = -1): void {
    if (this.attackSide === 0) {
      this.userDef = -1;
      return;
    }
    const best = this.bestDefender(exclude);
    this.userDef = best >= 0 ? best : exclude;
  }

  /** The standing home defender nearest to making the tackle, skipping `exclude` (-1 if none). */
  private bestDefender(exclude = -1): number {
    let best = -1;
    let bestD = Infinity;
    for (let i = SEVEN; i < 2 * SEVEN; i++) {
      const b = this.bodies[i]!;
      if (i === exclude || b.down > 0 || b.bound) continue;
      const d = this.tackleCost(i);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  /**
   * Auto switch: after their pass is caught, or when the user's man is beaten or put down, the user takes the
   * defender best placed for the new carrier, if he is clearly closer (`userDefence.autoSwitchGainM`). Not while
   * TACKLE is held. Returns true if it switched.
   */
  private autoSwitch(): boolean {
    if (!this.userDefending || this.chasing || !this.t.userDefence.autoSwitch) return false;
    const best = this.bestDefender();
    if (best < 0 || best === this.userDef) return false;
    const me = this.bodies[this.userDef]!;
    const down = me.down > 0 || me.bound;
    if (!down && this.tackleCost(this.userDef) - this.tackleCost(best) < this.t.userDefence.autoSwitchGainM) return false;
    this.userDef = best;
    this.switchedAt = this.clock;
    return true;
  }

  /** Who a penalty just given goes to (0 home, 1 away), while the dead ball before it runs; null otherwise. */
  get penaltyTo(): 0 | 1 | null {
    const r = this.restart;
    return r.kind === 'set' && r.sp.kind === 'penalty' ? r.sp.side : null;
  }

  /** SWITCH (GDD 6.7): take over the defender best placed to tackle (the next best if that is him already). */
  switchDefender(): boolean {
    if (this.attackSide !== 1 || this.userDef < 0) return false;
    const before = this.userDef;
    this.pickUserDefender();
    if (this.userDef === before) this.pickUserDefender(before);
    if (this.userDef !== before) this.switchedAt = this.clock;
    return this.userDef !== before;
  }

  /**
   * TACKLE tapped (GDD 6.7, addendum 4): a safe standing tackle if the carrier is within reach. During an away
   * pass it is the intercept instead, when he stands in the lane. Returns what happened, or null if out of reach.
   */
  tackleButton(): 'tackle' | 'intercept' | null {
    if (!this.userDefending) return null;
    const me = this.bodies[this.userDef]!;
    if (me.down > 0 || me.stun > 0) return null;
    const f = this.flight;
    if (this.phase === 'flight' && f && f.interceptable && f.t < f.dur * this.t.userDefence.interceptWindow) {
      f.interceptable = false;
      const u = this.t.userDefence;
      const chance = Math.max(0, Math.min(u.interceptMax, u.interceptPerHnd * me.player.ratings.HND * (f.laneCloseness ?? 0)));
      const { roll, hit } = this.rng.rollDetailed(chance);
      const why = `Intercept ${Math.round(chance)} percent, roll ${Math.round(roll)}`;
      if (hit) {
        const at = this.userDef;
        this.emit({ kind: 'turnover', call: 'INTERCEPT!', detail: `${why}: TAKEN`, chance, roll, who: at });
        this.swapPossession(me.x, me.z, at);
        return 'intercept';
      }
      me.stun = u.missStunSeconds;
      this.emit({ kind: 'turnover', call: '', detail: `${why}: MISSED`, chance, roll, who: this.userDef });
      return 'intercept';
    }
    const c = this.carrierBody;
    if (this.phase !== 'play' || !c || this.carrier === null) return null;
    if (Math.hypot(c.x - me.x, c.z - me.z) > this.t.userDefence.reachM) return null;
    this.resolveTackle(this.userDef, 0, 'dive');
    return 'tackle';
  }
  /** TACKLE held (addendum 4): the user's defender chases the carrier by himself while it is held. */
  setChase(on: boolean): void {
    this.chasing = on && this.userDefending && this.phase === 'play' && this.carrier !== null;
  }

  /**
   * TACKLE let go after a chase: he dives at the carrier if within dive reach (the big hit: harder to make, can
   * jolt the ball loose). Null if out of reach: he pulls up.
   */
  diveTackle(): 'tackle' | null {
    const was = this.chasing;
    this.chasing = false;
    if (!was || !this.userDefending) return null;
    const me = this.bodies[this.userDef]!;
    const c = this.carrierBody;
    if (this.phase !== 'play' || !c || this.carrier === null || me.down > 0 || me.stun > 0) return null;
    if (Math.hypot(c.x - me.x, c.z - me.z) > this.t.userDefence.diveReachM) return null;
    this.resolveTackle(this.userDef, 0, 'big');
    return 'tackle';
  }

  /** The dashed chase line from the user's defender to the carrier while TACKLE is held, or null. */
  get chaseLine(): { x0: number; z0: number; x1: number; z1: number } | null {
    const c = this.carrierBody;
    if (!this.chasing || !c || !this.userDefending) return null;
    const me = this.bodies[this.userDef]!;
    return { x0: me.x, z0: me.z, x1: c.x, z1: c.z };
  }

  /**
   * KICK shows only when a kick is on (addendum 4): the home carrier in hand, nobody in contact, and short of
   * their 22 or, inside it, their line close enough to chip over.
   */
  get kickOn(): boolean {
    const c = this.carrierBody;
    if (this.phase !== 'play' || !c || this.attackSide !== 0) return false;
    const k = this.t.kicks;
    if (this.nearestDefender(c.x, c.z) < k.hideContactM) return false;
    if (this.progress(c.z) < this.tryLine - this.t.field.twentyTwoM) return true;
    return this.lineP - this.progress(c.z) < k.chipOnLineM;
  }


  /** True while the user's defender can go for the intercept of the pass in the air. */
  get interceptOpen(): boolean {
    const f = this.flight;
    return this.userDefending && this.phase === 'flight' && !!f?.interceptable && f.t < f.dur * this.t.userDefence.interceptWindow;
  }

  // Kicks ----------------------------------------------------------------------------------------------------

  /**
   * KICK (GDD 6.6): grubber along the ground, chip over the line, box kick high and long, or a touch finder out
   * over the nearer touchline. The nearest of each side chase it; whoever gets there first has the ball.
   */
  kick(type: KickType): boolean {
    const c = this.carrierBody;
    if (this.phase !== 'play' || !c || this.carrier === null) return false;
    const k = this.t.kicks;
    const spec = k[type];
    let tx = c.x;
    const tz = c.z + this.dir * spec.distM;
    if (type === 'touch') {
      const side = c.x >= 0 ? 1 : -1;
      tx = side * (this.t.field.widthM / 2 + k.touch.outM);
    }
    this.kickBall = { type, sx: c.x, sz: c.z, tx, tz, t: 0, dur: spec.seconds, peak: spec.peakM };
    this.emit({ kind: 'kick', call: `${type === 'touch' ? 'TOUCH FINDER' : type === 'box' ? 'BOX KICK' : type.toUpperCase()}`, detail: `${c.player.number} kicks ${type}`, who: this.carrier });
    this.carrier = null;
    this.phase = 'kick';
    return true;
  }

  /**
   * Lines up a kick-off (GDD 6.9; sevens law: the side that just scored kicks). The kicking side becomes the attack in the
   * body list; the kicker holds the ball at halfway. The away side kicks after a short wait; the user aims with
   * the stick and kicks with kickoffKick.
   */
  setupKickoff(kicking: 0 | 1, opening = false): void {
    if (opening) this.firstKicker = kicking;
    this.openingKick = opening && kicking === 1;
    if (this.attackSide !== kicking) this.swapPossession(0, 0, null);
    this.dir = kicking === 0 ? this.homeDir : this.homeDir === 1 ? -1 : 1;
    const shape = kickoffShape(this.t, this.dir);
    for (const [i, b] of this.bodies.entries()) {
      const list = b.team === 0 ? shape.kicking : shape.receiving;
      const at = list.find((s) => s.number === b.slot + 1) ?? list[0]!;
      b.x = at.x;
      b.z = at.z;
      b.vx = b.vz = 0;
      b.down = b.stun = 0;
      b.offside = b.bound = false;
      b.stamina = 100;
      b.exhausted = b.sprinting = false;
      void i;
    }
    // The kicker: the kicking side's man nearest the centre spot.
    let kicker = 0;
    for (let i = 0; i < SEVEN; i++) if (Math.hypot(this.bodies[i]!.x, this.bodies[i]!.z) < Math.hypot(this.bodies[kicker]!.x, this.bodies[kicker]!.z)) kicker = i;
    this.carrier = kicker;
    this.flight = null;
    this.kickBall = null;
    this.phase = 'kickoff';
    this.kickoffAimX = 0;
    this.timer = kicking === 0 ? this.t.kickoff.humanWaitSeconds : this.t.kickoff.aiDelaySeconds;
    this.pickUserDefender();
    this.placeBall();
    this.emit({ kind: 'kickoff', call: 'KICK-OFF', detail: `${kicking === 0 ? 'Home' : 'Away'} kick off` });
  }

  /** Their kick in the air: our man nearest where it comes down (-1 otherwise). */
  get kickCatcher(): number {
    const kb = this.kickBall;
    if (!kb || this.attackSide !== 1) return -1;
    let best = -1;
    let bestD = Infinity;
    for (let i = SEVEN; i < 2 * SEVEN; i++) {
      const b = this.bodies[i]!;
      if (b.down > 0) continue;
      const d = Math.hypot(b.x - kb.tx, b.z - kb.tz);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  /** True while the user is lined up to kick off and may kick. */
  get kickoffReady(): boolean {
    return this.phase === 'kickoff' && this.attackSide === 0 && this.timer <= 0;
  }

  /** The kick-off by swipe: aimed at x (clamped to the aim limits), power 0 to 1. */
  kickoffSwipe(aimX: number, power: number): boolean {
    if (!this.kickoffReady) return false;
    const ko = this.t.kickoff;
    this.kickoffAimX = Math.max(-ko.aimMaxX, Math.min(ko.aimMaxX, aimX));
    return this.kickoffKick(power);
  }

  /** The kick-off itself: power 0 to 1 sets the length (at least 10 m, sevens law). */
  kickoffKick(power: number): boolean {
    if (this.phase !== 'kickoff' || this.carrier === null) return false;
    const ko = this.t.kickoff;
    const metres = ko.minM + Math.max(0, Math.min(1, power)) * (ko.maxM - ko.minM);
    const c = this.carrierBody!;
    this.kickBall = { type: 'kickoff', sx: c.x, sz: c.z, tx: this.kickoffAimX, tz: c.z + this.dir * metres, t: 0, dur: ko.secondsBase + ko.secondsPerM * metres, peak: ko.peakM };
    this.carrier = null;
    this.phase = 'kick';
    this.emit({ kind: 'kick', call: '', detail: `Kick-off ${Math.round(metres)} m` });
    return true;
  }

  /** Each step of a kick: chasers run to where it comes down; the first to reach it once it lands has the ball. */
  private stepKick(dt: number, defInput: StickInput | null): void {
    const kb = this.kickBall!;
    kb.t += dt;
    const k = this.t.kicks;
    // Chasers: the nearest few of each side (the user's defender is steered by the stick instead).
    const near = (team: 0 | 1) =>
      this.bodies
        .map((b, i) => ({ i, b, d: Math.hypot(b.x - kb.tx, b.z - kb.tz) }))
        .filter((o) => o.b.team === team && o.b.down <= 0)
        .sort((a, b) => a.d - b.d)
        .slice(0, k.chasers)
        .map((o) => o.i);
    const chase = new Set([...near(0), ...near(1)]);
    const tp = this.progress(kb.tz);
    for (const [i, b] of this.bodies.entries()) {
      if (b.down > 0) {
        b.vx = b.vz = 0;
        continue;
      }
      if (defInput && i === this.userDef) {
        this.stickMove(b, defInput, dt);
        continue;
      }
      if (chase.has(i)) this.steer(b, kb.tx, kb.tz, Infinity, true, dt);
      else {
        // Everyone else follows up as a line toward where it lands.
        const s = this.spots[i]!;
        const z = b.team === 0 ? this.zAt(Math.min(tp, this.progress(b.z) + 20) - s.depth) : this.zAt(Math.max(tp + 6, this.lineP));
        this.steer(b, s.x, z, Infinity, false, dt);
      }
    }
    this.integrate(dt);
    if (kb.t < kb.dur) return;
    // Down: out over the touchline, dead beyond the dead-ball line, or there to be gathered.
    const halfW = this.t.field.widthM / 2;
    if (Math.abs(kb.tx) > halfW) {
      this.restart = { kind: 'set', sp: this.lineoutFor(this.attackSide === 0 ? 1 : 0, kb.tx, kb.tz) };
      this.deadBall({ kind: 'touch', call: 'INTO TOUCH', detail: `Kick out on the full at ${Math.round(this.progress(kb.tz))} m` }, this.t.openPlay.deadSeconds, true);
      return;
    }
    if (Math.abs(kb.tz) > this.t.field.lengthM / 2) {
      // Dead in goal: the defending side restarts from its 22.
      this.restart = { kind: 'swap', x: 0, z: this.zAt(this.tryLine - k.deadM) };
      this.deadBall({ kind: 'touch', call: 'DEAD BALL', detail: 'Kicked dead beyond the dead-ball line' }, this.t.openPlay.deadSeconds, true);
      return;
    }
    let who = -1;
    let best = k.gatherM;
    for (const [i, b] of this.bodies.entries()) {
      if (b.down > 0 || b.stun > 0) continue;
      const d = Math.hypot(b.x - kb.tx, b.z - kb.tz);
      if (d < best) {
        best = d;
        who = i;
      }
    }
    if (who < 0) return;
    const g = this.bodies[who]!;
    this.kickBall = null;
    if (g.team === 0) {
      if (this.progress(kb.tz) >= this.tryLine) {
        this.carrier = who;
        this.phase = 'play';
        this.checkCarrier();
        return;
      }
      this.carrier = who;
      this.phase = 'play';
      this.setFormation();
      this.emit({ kind: 'gathered', call: kb.type === 'kickoff' ? 'REGATHERED' : '', detail: `${g.player.number} gathers his side's kick`, who });
      return;
    }
    if (this.progress(kb.tz) >= this.tryLine) {
      this.restart = { kind: 'swap', x: 0, z: this.zAt(this.tryLine - k.deadM) };
      this.deadBall({ kind: 'touch', call: 'GROUNDED', detail: `${g.player.number} grounds it in goal: 22 restart` }, this.t.openPlay.deadSeconds, true);
      return;
    }
    this.emit({ kind: 'gathered', call: '', detail: `${g.player.number} takes the kick`, who });
    this.swapPossession(g.x, g.z, who);
  }

  /** The user steering a player with the stick (the camera always looks the way home attacks). */
  private stickMove(b: Body, input: StickInput, dt: number): void {
    const o = this.t.openPlay;
    const m = this.t.movement;
    const len = Math.min(1, Math.hypot(input.sx, input.sy));
    const canSprint = input.sprint && b.stamina > 0 && !b.exhausted;
    const speed = topSpeed(b.player.ratings, this.t) * (canSprint ? 1 + m.sprintBonus : b.exhausted ? m.exhaustedFactor : 1) * (b.stun > 0 ? this.t.tackle.brokenSlowFactor : 1);
    const mag = Math.hypot(input.sx, input.sy);
    const k = len > o.stickDeadzone ? (speed * len) / Math.max(mag, 1e-6) : 0;
    this.accelerate(b, input.sx * -this.homeDir * k, input.sy * this.homeDir * k, dt);
    b.sprinting = canSprint && len > o.stickDeadzone;
    this.drainStamina(b, dt);
  }

  private emit(e: PlayEvent): void {
    this.events.push(e);
    this.log.push(e);
    this.count(e);
  }

  /**
   * The match clock, each step (addendum 2). It runs in open play, rucks and short stoppages and stops for
   * set pieces, kick-offs and kicks at goal. A half ends at the next stoppage once the game clock reaches 0:00
   * or the half has used `clock.halfSoftCapSeconds` of real time, and at `clock.halfHardCapSeconds` whatever is
   * happening, so a match always fits in 5:00. Returns true while the match is held (half time, full time).
   */
  private stepMatchClock(dt: number): boolean {
    const m = this.match;
    const c = this.t.clock;
    if (this.phase === 'fulltime') return true;
    if (this.phase === 'halftime') {
      m.breakLeft -= dt;
      if (m.breakLeft <= 0) this.startSecondHalf();
      return true;
    }
    m.wall += dt;
    const conversionNext = this.phase === 'dead' && this.restart.kind === 'set' && this.restart.sp.kind === 'goal';
    const running = this.phase === 'play' || this.phase === 'flight' || this.phase === 'kick' || this.phase === 'ruck' || (this.phase === 'dead' && !conversionNext);
    if (running) m.gameLeft = Math.max(0, m.gameLeft - dt * c.speed);
    const stoppage = ((this.phase === 'dead' || this.phase === 'ruck') && !conversionNext) || this.phase === 'kickoff';
    const timeUp = m.gameLeft <= 0 || m.wall >= c.halfSoftCapSeconds;
    if ((timeUp && stoppage) || m.wall >= c.halfHardCapSeconds) {
      this.endHalf();
      return true;
    }
    return false;
  }

  /** The referee blows for half time or full time: the ball is dead and play holds. */
  private endHalf(): void {
    this.carrier = null;
    this.flight = null;
    this.kickBall = null;
    this.setPiece = null;
    this.chasing = false;
    for (const b of this.bodies) b.vx = b.vz = 0;
    if (this.match.half === 1) {
      this.phase = 'halftime';
      this.match.breakLeft = this.t.clock.halftimeSeconds;
      this.emit({ kind: 'halftime', call: '', detail: `Half time: ${this.score[0]} to ${this.score[1]}` });
    } else {
      this.phase = 'fulltime';
      this.emit({ kind: 'fulltime', call: '', detail: `Full time: ${this.score[0]} to ${this.score[1]}` });
    }
  }

  /** Skips the rest of the half-time card (a tap). */
  skipHalftime(): void {
    if (this.phase === 'halftime') this.match.breakLeft = 0;
  }

  private startSecondHalf(): void {
    this.match.half = 2;
    this.match.gameLeft = this.t.match.halfMinutes * 60;
    this.match.wall = 0;
    this.setupKickoff(this.firstKicker === 0 ? 1 : 0);
  }

  /** Clock text for the score bug: "1ST HALF 6:12". */
  get clockText(): string {
    const m = this.match;
    const s = Math.ceil(m.gameLeft);
    return `${m.half === 1 ? '1ST' : '2ND'} HALF ${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
  }

  /** Counts each event into the match stats. */
  private count(e: PlayEvent): void {
    const st = this.stats;
    const who = e.who !== undefined ? this.bodies[e.who] : undefined;
    const rec = (b: Body | undefined) => {
      if (!b) return null;
      const key = `${b.side}:${b.player.number}`;
      st.players[key] ??= { side: b.side, number: b.player.number, name: `${b.player.firstName.charAt(0)}. ${b.player.lastName}`, tries: 0, breaks: 0, tackles: 0, offloads: 0 };
      return st.players[key]!;
    };
    const atk = this.bodies[0]?.side ?? 0;
    switch (e.kind) {
      case 'try':
        if (who) {
          st.tries[who.side]++;
          rec(who)!.tries++;
        }
        break;
      case 'broke':
        if (who) {
          st.breaks[who.side]++;
          rec(who)!.breaks++;
        }
        break;
      case 'tackled': {
        const tk = this.lastTackle ? this.bodies[this.lastTackle.tackler] : undefined;
        if (tk) {
          st.tackles[tk.side]++;
          rec(tk)!.tackles++;
        }
        break;
      }
      case 'pass':
        st.passes[atk]++;
        break;
      case 'offload':
        st.passes[atk]++;
        if (this.offloadFrom !== null) rec(this.bodies[this.offloadFrom])!.offloads++;
        break;
      case 'caught':
        st.passesCaught[atk]++;
        break;
      case 'ruckWon':
        st.rucksWon[atk]++;
        break;
      case 'turnover':
        // A ruck lost: counted against the side that had the ball (attackSide is still theirs at the emit).
        if (e.detail.endsWith('LOST')) st.rucksLost[atk]++;
        break;
      default:
        break;
    }
  }

  /** Player of the Match: the most points for tries, breaks, tackles and offloads (`clock.potm*`). */
  get playerOfTheMatch(): MatchStats['players'][string] | null {
    const w = this.t.clock;
    let best: MatchStats['players'][string] | null = null;
    let bestScore = -1;
    const keys = Object.keys(this.stats.players).sort();
    for (const k of keys) {
      const p = this.stats.players[k]!;
      const score = p.tries * w.potmTry + p.breaks * w.potmBreak + p.tackles * w.potmTackle + p.offloads * w.potmOffload;
      if (score > bestScore) {
        bestScore = score;
        best = p;
      }
    }
    return best;
  }

  /** Stars for the home side: 1 for finishing, 2 for a win, 3 for a win by `clock.threeStarMargin` or more. */
  get stars(): 1 | 2 | 3 {
    const margin = this.score[0] - this.score[1];
    return margin >= this.t.clock.threeStarMargin ? 3 : margin > 0 ? 2 : 1;
  }

  /** Moves everyone one step of open play. */
  private moveInPlay(dt: number, input: StickInput | null, defInput: StickInput | null = null): void {
    const o = this.t.openPlay;
    const c = this.carrierBody;
    const ballX = c ? c.x : this.flight ? this.flight.tx : this.base.x;
    const ballZ = c ? c.z : this.flight ? this.flight.tz : this.zAt(this.base.p);
    const ballP = this.progress(ballZ);
    this.advanceLine(dt, ballP);
    this.frontTackler = this.nearestInFront();

    for (const [i, b] of this.bodies.entries()) {
      if (b.down > 0) {
        b.vx = b.vz = 0;
        continue;
      }
      if (b.bound && i !== this.carrier) {
        // Still over the ruck he was added to.
        const at = this.ruckPoint(i);
        this.steer(b, at.x, at.z, Infinity, false, dt);
        continue;
      }
      if (this.chasing && i === this.userDef && c) {
        // TACKLE held (addendum 4): he chases the carrier by himself, cutting to where he will be.
        const top = topSpeed(b.player.ratings, this.t) * this.t.userDefence.chaseSpeedFactor;
        const dist = Math.hypot(c.x - b.x, c.z - b.z);
        const lead = Math.min(this.t.defence.leadMaxSeconds, dist / Math.max(1, top + Math.hypot(c.vx, c.vz)));
        this.steer(b, c.x + c.vx * lead, c.z + c.vz * lead, top, true, dt);
        continue;
      }
      if (i === this.carrier && input) {
        // The user's carrier: direction from the stick, speed from how far it is pushed. Arcade auto-run keeps him
        // going up the pitch at a jog when the stick is at rest.
        const ix = input.sx;
        let iy = input.sy;
        if (o.autoRun && Math.hypot(ix, iy) <= o.stickDeadzone) iy = o.autoRunStick;
        const len = Math.min(1, Math.hypot(ix, iy));
        const m = this.t.movement;
        const canSprint = input.sprint && b.stamina > 0 && !b.exhausted;
        const speed =
          topSpeed(b.player.ratings, this.t) *
          (canSprint ? 1 + m.sprintBonus : b.exhausted ? m.exhaustedFactor : 1) *
          (this.slowed > 0 ? this.t.tackle.brokenSlowFactor : 1) *
          // The ball slows you a touch (Jonny, 14 Nov 2026): a chaser of the same pace slowly reels the carrier in.
          m.carrierFactor;
        const mag = Math.hypot(ix, iy);
        const k = len > o.stickDeadzone ? (speed * len) / Math.max(mag, 1e-6) : 0;
        const spin = this.spinLeft > 0 ? this.t.moves.spinSlowFactor : 1;
        this.accelerate(b, ix * -this.dir * k * spin, iy * this.dir * k * spin, dt);
        if (this.stepLeft > 0) {
          // The cut: a quick sideways burst on top of the run, stepMetres across in stepSeconds.
          const m = this.t.moves;
          b.x += this.stepSide * -this.dir * (m.stepM / m.stepSeconds) * dt;
        }
        b.sprinting = canSprint && len > o.stickDeadzone;
        this.drainStamina(b, dt);
        continue;
      }
      if (defInput && i === this.userDef) {
        this.stickMove(b, defInput, dt);
        continue;
      }
      if (b.team === 0) {
        if (this.phase === 'flight' && this.flight && i === this.flight.to) {
          // The receiver runs onto the ball.
          this.steer(b, this.flight.tx, this.flight.tz, Infinity, true, dt);
          continue;
        }
        // Hold the channel and the depth behind the ball: the line moves up the pitch as one.
        const s = this.spots[i]!;
        this.steer(b, s.x, this.zAt(ballP - s.depth), Infinity, true, dt);
        continue;
      }
      const d = this.defenceTarget(i, ballX);
      this.steer(b, d.x, d.z, d.speed, d.sprint, dt);
    }
    this.integrate(dt);
    if (c && this.carrier !== null) this.shiftChannels(c.x, dt);
  }

  /** The line's channels drift across with the carrier, so the support stays spaced off him. */
  private shiftChannels(carrierX: number, dt: number): void {
    const own = this.spots[this.carrier!]!;
    const dx = (carrierX - own.x) * Math.min(1, this.t.formation.channelFollow * dt);
    if (Math.abs(dx) < 1e-6) return;
    const halfW = this.t.field.widthM / 2 - this.t.formation.touchMarginM;
    for (let i = 0; i < SEVEN; i++) {
      const s = this.spots[i]!;
      s.x = Math.max(-halfW, Math.min(halfW, s.x + dx));
    }
  }

  /** Where a defender is heading and how fast. */
  private defenceTarget(i: number, ballX: number): { x: number; z: number; speed: number; sprint: boolean } {
    const d = this.t.defence;
    const c = this.carrierBody;
    const b = this.bodies[i]!;
    const top = topSpeed(b.player.ratings, this.t) * d.speedFactor;
    // Going for the carrier, a defender runs flat out: the full sprint, not the line's holding pace.
    const chase = topSpeed(b.player.ratings, this.t) * (1 + this.t.movement.sprintBonus);
    const mark = this.bodies[this.marks[i] ?? 0]!;
    const lineX = mark.x + (ballX - mark.x) * this.t.formation.defenceInFraction;
    if (b.offside) {
      if (this.progress(b.z) >= this.lineP - d.onsideToleranceM) b.offside = false;
      else return { x: lineX, z: this.zAt(this.lineP), speed: top, sprint: true };
    }
    if (c && this.carrier !== null && i === this.frontTackler) {
      const dist = Math.hypot(c.x - b.x, c.z - b.z);
      if (dist < d.engageM) {
        // The tackler breaks the line: aim where the carrier will be when they meet.
        const closing = top + Math.hypot(c.vx, c.vz);
        const lead = Math.min(d.leadMaxSeconds, dist / Math.max(1, closing));
        return { x: c.x + c.vx * lead, z: c.z + c.vz * lead, speed: chase, sprint: true };
      }
    }
    if (c && this.progress(c.z) > this.lineP) {
      // The carrier is through the line: everyone near enough chases.
      const dist = Math.hypot(c.x - b.x, c.z - b.z);
      if (dist < d.chaseM) return { x: c.x, z: c.z, speed: chase, sprint: true };
    }
    // Hold the line opposite his man.
    return { x: lineX, z: this.zAt(this.lineP), speed: top, sprint: false };
  }

  /** The nearest standing defender level with or in front of the carrier (-1 if none). */
  private nearestInFront(): number {
    const c = this.carrierBody;
    if (!c) return -1;
    let best = -1;
    let bestD = Infinity;
    for (let i = SEVEN; i < 2 * SEVEN; i++) {
      const b = this.bodies[i]!;
      if (b.down > 0 || b.stun > 0 || b.offside || b.bound || this.progress(b.z) < this.progress(c.z) - this.t.defence.beatenM) continue;
      // The user's own defender is his to steer: an AI team-mate still comes up to make the tackle.
      if ((this.userSteering || this.chasing) && i === this.userDef) continue;
      const d = Math.hypot(b.x - c.x, b.z - c.z);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    return best;
  }

  /** The defensive line comes up together toward the ball, stopping short of it; never back. */
  private advanceLine(dt: number, ballP: number): void {
    const d = this.t.defence;
    const shape = this.callEffect?.shape;
    const rush = shape === 'RUSH' || shape === 'HIGH' ? this.t.playCall.rushFactor : 1;
    const next = this.lineP - d.lineAdvanceMps * rush * dt;
    if (next >= ballP + d.minGapM) this.lineP = next;
  }

  private steer(b: Body, tx: number, tz: number, maxSpeed: number, sprint: boolean, dt: number, setting = false): void {
    const dx = tx - b.x;
    const dz = tz - b.z;
    const dist = Math.hypot(dx, dz);
    const top = setting ? maxSpeed : topSpeed(b.player.ratings, this.t) * (sprint && b.stamina > 0 && !b.exhausted ? 1 + this.t.movement.sprintBonus : 1);
    const speed = Math.min(top, maxSpeed, dist * this.t.openPlay.arriveGain) * (b.stun > 0 ? this.t.tackle.brokenSlowFactor : 1);
    const k = dist > 1e-4 ? speed / dist : 0;
    this.accelerate(b, dx * k, dz * k, dt);
    b.sprinting = !setting && sprint && speed > topSpeed(b.player.ratings, this.t);
    if (!setting) this.drainStamina(b, dt);
  }

  private accelerate(b: Body, vx: number, vz: number, dt: number): void {
    const gain = b.team === 1 ? this.t.defence.accelGain : this.t.movement.accelGain;
    const rate = Math.min(1, (dt * gain) / accelSeconds(b.player.ratings, this.t));
    b.vx += (vx - b.vx) * rate;
    b.vz += (vz - b.vz) * rate;
  }

  private integrate(dt: number): void {
    for (const b of this.bodies) {
      b.x += b.vx * dt;
      b.z += b.vz * dt;
    }
    this.separate();
  }

  /**
   * Nobody runs through anybody (Jonny, 15 Nov 2026): two players on their feet closer than
   * `movement.personalSpaceM` are pushed apart, half each, and lose the speed they had into each other. Players
   * on the ground or bound into a ruck, and set pieces (packed scrums, lineout lifts), are left as they are.
   */
  private separate(): void {
    if (this.phase === 'setpiece') return;
    const min = this.t.movement.personalSpaceM;
    const n = this.bodies.length;
    for (let i = 0; i < n; i++) {
      const a = this.bodies[i]!;
      if (a.down > 0 || a.bound) continue;
      for (let j = i + 1; j < n; j++) {
        const b = this.bodies[j]!;
        if (b.down > 0 || b.bound) continue;
        let dx = b.x - a.x;
        let dz = b.z - a.z;
        let d = Math.hypot(dx, dz);
        if (d >= min) continue;
        const push = (min - d) / 2;
        if (d < 1e-6) {
          // Exactly on top of each other: part them across the pitch.
          dx = 1;
          dz = 0;
          d = 1;
        }
        const nx = dx / d;
        const nz = dz / d;
        a.x -= nx * push;
        a.z -= nz * push;
        b.x += nx * push;
        b.z += nz * push;
        // Stop them running into each other; sliding past is fine.
        const closing = (b.vx - a.vx) * nx + (b.vz - a.vz) * nz;
        if (closing < 0) {
          a.vx += (nx * closing) / 2;
          a.vz += (nz * closing) / 2;
          b.vx -= (nx * closing) / 2;
          b.vz -= (nz * closing) / 2;
        }
      }
    }
  }

  /** Sprinting empties the tank in sprintSeconds; run dry and you are exhausted until it refills to the recovery level. */
  private drainStamina(b: Body, dt: number): void {
    const m = this.t.movement;
    if (b.sprinting) b.stamina = Math.max(0, b.stamina - (100 / m.sprintSeconds) * dt);
    else b.stamina = Math.min(100, b.stamina + m.staminaRefillPerSecond * dt);
    if (b.stamina <= 0) b.exhausted = true;
    else if (b.exhausted && b.stamina >= m.recoverPct) b.exhausted = false;
  }

  private placeBall(): void {
    const c = this.carrierBody;
    if (c) {
      this.ball.x = c.x;
      this.ball.z = c.z;
      this.ball.h = this.t.ball.carryHeightM;
    } else if (this.flight) {
      const f = this.flight;
      const u = Math.min(1, f.t / f.dur);
      this.ball.x = f.sx + (f.tx - f.sx) * u;
      this.ball.z = f.sz + (f.tz - f.sz) * u;
      this.ball.h = this.t.ball.carryHeightM + 4 * f.peak * u * (1 - u);
    } else if (this.setPiece) {
      this.placeSetPieceBall(this.setPiece);
    } else if (this.kickBall) {
      const k = this.kickBall;
      const u = Math.min(1, k.t / k.dur);
      this.ball.x = k.sx + (k.tx - k.sx) * u;
      this.ball.z = k.sz + (k.tz - k.sz) * u;
      this.ball.h = u >= 1 ? this.t.ball.radiusM : this.t.ball.radiusM + 4 * k.peak * u * (1 - u);
    } else if (this.phase === 'ruck') {
      this.ball.x = this.base.x;
      this.ball.z = this.zAt(this.base.p);
      this.ball.h = this.t.ball.radiusM;
    }
  }

  /** The ball at a restart: in the thrower's hands then in the air to the jumper, in the scrum, on the kicking tee. */
  private placeSetPieceBall(sp: SetPiece): void {
    const b = this.ball;
    b.h = this.t.ball.radiusM;
    const roleAt = (r: 'thrower' | 'jumper' | 'kicker') => this.setPieceRole.findIndex((x) => x === r);
    if (sp.kind === 'call') {
      if (sp.next) this.placeSetPieceBall(sp.next);
      return;
    }
    if (sp.kind === 'lineout') {
      const th = this.bodies[roleAt('thrower')] ?? this.bodies[1]!;
      const j = this.bodies[roleAt('jumper')];
      if (sp.stage === 'air' && j) {
        const u = Math.min(1, sp.t / this.t.lineout.airSeconds);
        b.x = th.x + (j.x - th.x) * u;
        b.z = th.z + (j.z - th.z) * u;
        b.h = 1.8 + 1.8 * Math.sin(u * Math.PI) + u * 1.0;
      } else {
        b.x = th.x;
        b.z = th.z;
        b.h = 2.0;
      }
    } else if (sp.kind === 'goal') {
      const k = this.bodies[roleAt('kicker')] ?? this.bodies[0]!;
      if (sp.stage === 'flight') {
        const u = Math.min(1, sp.t / this.t.goal.flightSeconds);
        const tz = this.zAt(this.tryLine + 2);
        b.x = k.x + (sp.aimX - k.x) * u;
        b.z = k.z + (tz - k.z) * u;
        b.h = this.t.ball.radiusM + 14 * u * (1 - u) + 4 * u;
      } else {
        b.x = k.x;
        b.z = k.z;
        b.h = 0.9;
      }
    } else {
      b.x = sp.x;
      b.z = sp.z;
    }
  }

  private passSeconds(c: Body, to: number, power: number | null): number {
    const p = this.t.passing;
    const r = this.bodies[to]!;
    const metres = Math.hypot(r.x - c.x, r.z - c.z);
    const pw = power ?? powerBandCentre(metres, this.t);
    const speed = p.speedBase + p.speedPerPower * pw;
    return Math.max(p.minSeconds, metres / speed);
  }

  /** Where the receiver will be after `seconds`, running on at his current velocity. */
  private leadPoint(to: number, seconds: number): { x: number; z: number } {
    const r = this.bodies[to]!;
    return { x: r.x + r.vx * seconds, z: r.z + r.vz * seconds };
  }

  nearestDefender(x: number, z: number): number {
    let best = Infinity;
    for (let i = SEVEN; i < 2 * SEVEN; i++) {
      const d = this.bodies[i]!;
      if (d.down > 0) continue;
      best = Math.min(best, Math.hypot(d.x - x, d.z - z));
    }
    return best;
  }
}
