import '@fontsource/barlow-condensed/latin-700.css';
import '@fontsource/barlow-condensed/latin-800-italic.css';
import '@fontsource/barlow-condensed/latin-900.css';
import '@fontsource/barlow-condensed/latin-900-italic.css';
import './style.css';
import { enablePortraitLock } from './app/orientation';
import { mountDebugOverlay } from './app/debug';
import { loadBrand, loadBrandImage } from './brand/loadBrand';
import { type AthleteModel, type AthleteVariant, loadAthleteModel } from './game/athleteModel';
import { createGame, type GameDebug } from './game/game';
import type { SceneStats } from './game/scene';
import { tunables } from './sim/tunables';
import { type MatchSetup, playUrl, readSetup } from './app/setup';
import { applyDifficulty } from './sim/difficulty';
import { FrontEnd } from './ui/frontEnd';

declare global {
  interface Window {
    /** Read by the Playwright smoke test. */
    __rugby?: { ready: boolean; stats?: SceneStats; game?: GameDebug; error?: string; athletes?: 'rigged' | 'primitive'; setup?: MatchSetup };
  }
}

/** Semantic UI tokens that are not brand colours (runner states) come from tunables. */
function applyUiTokens(): void {
  const root = document.documentElement.style;
  root.setProperty('--ui-open', tunables.look.iconOpen);
  root.setProperty('--ui-contested', tunables.look.iconContested);
  root.setProperty('--ui-covered', tunables.look.iconCovered);
  root.setProperty('--ui-grass', tunables.look.grass);
  root.setProperty('--ui-sky', tunables.look.sky);
}

async function start(): Promise<void> {
  window.__rugby = { ready: false };
  const container = document.getElementById('game');
  const uiRoot = document.getElementById('ui');
  if (!container || !uiRoot) throw new Error('#game or #ui element missing');

  const params = new URLSearchParams(location.search);
  // The rigged players load alongside the brand; if they fail or are slow, the game uses the primitive players.
  const athleteLoad = params.has('capsules') ? Promise.resolve(null) : loadAthletes(athleteVariant(params));
  const brand = await loadBrand();
  // Daytime by default, like the reference game; ?night keeps the floodlit look to compare.
  if (!params.has('night')) Object.assign(tunables.look, tunables.lookDay);
  applyUiTokens();
  const [logo, mark] = await Promise.all([
    loadBrandImage(brand, brand.logo.static).catch(() => null),
    loadBrandImage(brand, brand.logo.mark).catch(() => null),
  ]);
  // Generated textures (numbers) draw text, so the display font must be ready first.
  await Promise.all(['900 64px "Barlow Condensed"', 'italic 800 32px "Barlow Condensed"'].map((f) => document.fonts.load(f).catch(() => [])));
  enablePortraitLock(document.body);
  // The title screen, then straight into a match (Jonny, 16 Nov: no menu or team select), unless ?play asks for
  // the match at once (REMATCH, tests, screenshots). The players keep loading behind the title.
  const setup = readSetup(params, tunables);
  let fe: FrontEnd | null = null;
  if (!params.has('play')) {
    fe = new FrontEnd(brand);
    uiRoot.append(fe.root);
    await fe.run();
    history.replaceState(null, '', playUrl(location.href));
    fe.loading();
  }
  applyDifficulty(tunables, setup.difficulty);
  const athleteModel = await athleteLoad;
  const game = createGame({
    container,
    uiRoot,
    brand,
    logo,
    mark,
    tunables,
    // ?seed=abc replays a session exactly; otherwise every visit is new.
    matchSeed: params.get('seed') ?? `${Date.now()}`,
    athleteModel,
    // ?bot: the self-play bot holds the thumbs (for checking the flow of play; not a game mode).
    selfPlay: params.has('bot'),
    // The 10 second how to play opens every match; ?nohowto leaves it out.
    howTo: !params.has('nohowto'),
    setup,
  });

  // The loader stays over the first frame being built.
  fe?.close();
  mountDebugOverlay(game.stats);
  window.__rugby = { ready: true, stats: game.stats, game: game.debug, athletes: game.athletes, setup };
}

/** ?hd or ?standard picks the players; otherwise tunables athlete.defaultVariant. */
function athleteVariant(params: URLSearchParams): AthleteVariant {
  if (params.has('hd')) return 'hd';
  if (params.has('standard')) return 'standard';
  return tunables.athlete.defaultVariant === 'hd' ? 'hd' : 'standard';
}

function loadAthletes(variant: AthleteVariant): Promise<AthleteModel | null> {
  const timeout = new Promise<null>((resolve) => setTimeout(() => resolve(null), tunables.athlete.loadTimeoutSeconds * 1000));
  const files = variant === 'hd' ? tunables.athlete.hd : tunables.athlete;
  const looks = variant === 'hd' ? tunables.athlete.hd.looks : [];
  const load = Promise.all([
    loadAthleteModel(files, variant),
    // A look that fails to load is just left out.
    ...looks.map((f) => loadAthleteModel(f, variant).catch(() => null)),
  ]).then(([main, ...rest]) => {
    main!.looks = rest.filter((m): m is AthleteModel => m !== null);
    return main!;
  }).catch((err: unknown) => {
    console.warn('Rigged athletes unavailable, using primitives:', err);
    return null;
  });
  return Promise.race([load, timeout]);
}

start().catch((err: unknown) => {
  const message = err instanceof Error ? err.message : String(err);
  window.__rugby = { ready: false, error: message };
  const el = document.getElementById('fatal');
  if (el) {
    el.textContent = `Could not start: ${message}`;
    el.hidden = false;
  }
  console.error(err);
});
