import * as THREE from 'three';
import type { Brand } from '../brand/types';
import type { Tunables } from '../sim/tunables';
import { drawPitchCanvas, grassDetailCanvas, tintImage } from './pitchTexture';

export interface PitchView {
  group: THREE.Group;
}

/**
 * The rugby pitch (GDD section 10): painted grass with a grain texture over it, H posts on both try lines with
 * branded post pads (BRAND placement 8) and corner flags in the brand accent (placement 9).
 * World units are metres; x runs across, z along the pitch, the near (home) try line at +z.
 */
export function createPitch(brand: Brand, t: Tunables, logo: HTMLImageElement | null, mark: HTMLImageElement | null, maxAnisotropy: number): PitchView {
  const f = t.field;
  const group = new THREE.Group();

  const texture = new THREE.CanvasTexture(drawPitchCanvas(brand, t, logo, mark));
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = Math.min(maxAnisotropy, t.render.anisotropy);
  const detail = new THREE.CanvasTexture(grassDetailCanvas(128));
  detail.wrapS = detail.wrapT = THREE.RepeatWrapping;
  detail.anisotropy = texture.anisotropy;
  const mat = new THREE.MeshLambertMaterial({ map: texture });
  mat.onBeforeCompile = (shader) => {
    shader.uniforms['uDetail'] = { value: detail };
    shader.uniforms['uDetailRepeat'] = { value: new THREE.Vector2(f.widthM / f.detailRepeatM, f.lengthM / f.detailRepeatM) };
    shader.uniforms['uDetailStrength'] = { value: f.detailStrength };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform vec2 uDetailRepeat;\nvarying vec2 vDetailUv;')
      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvDetailUv = uv * uDetailRepeat;');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform sampler2D uDetail;\nuniform float uDetailStrength;\nvarying vec2 vDetailUv;')
      .replace('#include <map_fragment>', '#include <map_fragment>\ndiffuseColor.rgb *= 1.0 + (texture2D(uDetail, vDetailUv).r - 0.5) * 2.0 * uDetailStrength;');
  };
  const pitch = new THREE.Mesh(new THREE.PlaneGeometry(f.widthM, f.lengthM), mat);
  pitch.rotation.x = -Math.PI / 2;
  pitch.receiveShadow = true;
  group.add(pitch);

  const surround = new THREE.Mesh(
    new THREE.PlaneGeometry(f.widthM + 2 * f.surroundM, f.lengthM + 2 * f.surroundM),
    new THREE.MeshLambertMaterial({ color: t.look.surround }),
  );
  surround.rotation.x = -Math.PI / 2;
  surround.position.y = -f.surfaceLiftM;
  group.add(surround);

  const tryLine = f.lengthM / 2 - f.inGoalM;
  const padTexture = postPadTexture(brand, t, logo);
  for (const z of [-tryLine, tryLine]) group.add(createPosts(t, brand, padTexture, z));
  group.add(createCornerFlags(t, brand, tryLine));
  return { group };
}

/** H posts: two uprights and a crossbar, padded at the base. */
function createPosts(t: Tunables, brand: Brand, padTexture: THREE.Texture, z: number): THREE.Group {
  const g = t.goalpost;
  const group = new THREE.Group();
  const mat = new THREE.MeshLambertMaterial({ color: t.look.goalpost });
  const r = g.radiusM;
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(r, r, g.uprightGapM, g.radialSegments), mat);
  bar.rotation.z = Math.PI / 2;
  bar.position.y = g.crossbarHeightM;
  group.add(bar);
  // Pads: the texture's wordmark runs up the face toward the field on both sides.
  const padMats = [
    new THREE.MeshLambertMaterial({ map: padTexture }),
    new THREE.MeshLambertMaterial({ color: brand.colors.primary }),
    new THREE.MeshLambertMaterial({ color: brand.colors.primary }),
  ];
  for (const side of [-1, 1]) {
    const x = (side * g.uprightGapM) / 2;
    const up = new THREE.Mesh(new THREE.CylinderGeometry(r, r, g.uprightHeightM, g.radialSegments), mat);
    up.position.set(x, g.uprightHeightM / 2, 0);
    const pad = new THREE.Mesh(new THREE.CylinderGeometry(g.padRadiusM, g.padRadiusM, g.padHeightM, g.padSegments, 1, false), padMats);
    pad.position.set(x, g.padHeightM / 2, 0);
    group.add(up, pad);
  }
  group.position.z = z;
  return group;
}

/** Corner flags at the four corners of the field of play. */
function createCornerFlags(t: Tunables, brand: Brand, tryLine: number): THREE.Group {
  const c = t.cornerFlag;
  const group = new THREE.Group();
  const poleMat = new THREE.MeshLambertMaterial({ color: t.look.flagPole });
  const flagMat = new THREE.MeshLambertMaterial({ color: brand.colors.accent, side: THREE.DoubleSide });
  const pole = new THREE.CylinderGeometry(c.poleRadiusM, c.poleRadiusM, c.heightM, 6);
  const flag = new THREE.PlaneGeometry(c.flagM[0]!, c.flagM[1]!);
  const halfW = t.field.widthM / 2;
  for (const x of [-halfW, halfW]) {
    for (const z of [-tryLine, tryLine]) {
      const p = new THREE.Mesh(pole, poleMat);
      p.position.set(x, c.heightM / 2, z);
      const fl = new THREE.Mesh(flag, flagMat);
      fl.position.set(x + (x < 0 ? 1 : -1) * (c.flagM[0]! / 2), c.heightM - c.flagM[1]! / 2, z);
      group.add(p, fl);
    }
  }
  return group;
}

/** Post pad wrap: brand primary with the wordmark running vertically in the accent (BRAND placement 8). */
function postPadTexture(brand: Brand, t: Tunables, logo: HTMLImageElement | null): THREE.CanvasTexture {
  const g = t.goalpost;
  const c = document.createElement('canvas');
  c.width = g.padTexturePx;
  c.height = g.padTexturePx * 2;
  const ctx = c.getContext('2d');
  if (!ctx) throw new Error('2D canvas not available');
  ctx.fillStyle = brand.colors.primary;
  ctx.fillRect(0, 0, c.width, c.height);
  if (logo) {
    const tinted = tintImage(logo, brand.colors.accent);
    // Each half of the wrap carries one vertical wordmark, so it reads from both ends.
    for (const cx of [c.width * 0.25, c.width * 0.75]) {
      const s = Math.min((c.height * 0.85) / tinted.width, (c.width * 0.4) / tinted.height);
      ctx.save();
      ctx.translate(cx, c.height / 2);
      ctx.rotate(-Math.PI / 2);
      ctx.drawImage(tinted, (-tinted.width * s) / 2, (-tinted.height * s) / 2, tinted.width * s, tinted.height * s);
      ctx.restore();
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}
