import type { Rng } from './rng';

/**
 * Fictional player names (GDD section 4): first names from many regions so a sevens squad looks global,
 * surnames that are common words or plain family names. Any match to a real player is chance, never intended.
 */
export const FIRST_NAMES = [
  // Pacific
  'Sione', 'Tevita', 'Manu', 'Losa', 'Viliami', 'Ana', 'Mele', 'Kaveni', 'Tama', 'Lagi',
  // European
  'Liam', 'Oscar', 'Mathis', 'Elena', 'Hugo', 'Freya', 'Niall', 'Luca', 'Ines', 'Rhys',
  // African
  'Kwame', 'Thabo', 'Amara', 'Sipho', 'Zola', 'Femi', 'Nia', 'Tendai', 'Kofi', 'Ayo',
  // Asian
  'Kenji', 'Ravi', 'Mei', 'Arjun', 'Hana', 'Jin', 'Daichi', 'Priya', 'Tao', 'Yuto',
  // Americas
  'Mateo', 'Jordan', 'Camila', 'Diego', 'Riley', 'Santi', 'Kai', 'Tomas', 'Avery', 'Joaquin',
] as const;

export const LAST_NAMES = [
  'Rivers', 'Stone', 'Fale', 'Kato', 'Moreau', 'Okafor', 'Banda', 'Tanaka', 'Silva', 'Brennan',
  'Holt', 'Vaka', 'Ndlovu', 'Park', 'Castell', 'Ferro', 'Ashby', 'Mensah', 'Iwata', 'Lund',
  'Marsh', 'Tupou', 'Achebe', 'Rao', 'Delacroix', 'Okoro', 'Sato', 'Vidal', 'Quinlan', 'Hale',
  'Pike', 'Faleolo', 'Dube', 'Nakamura', 'Ortega', 'Brook', 'Kerr', 'Asante', 'Lin', 'Wilde',
] as const;

export function randomName(rng: Rng): { firstName: string; lastName: string } {
  return {
    firstName: FIRST_NAMES[rng.int(0, FIRST_NAMES.length - 1)]!,
    lastName: LAST_NAMES[rng.int(0, LAST_NAMES.length - 1)]!,
  };
}
