import type { Brand } from '../brand/types';
import { Rng } from '../sim/rng';
import type { Tunables } from '../sim/tunables';

/**
 * Draws the whole rugby pitch (both in-goal areas included) onto one canvas.
 * Canvas x runs touchline to touchline (world x); canvas y runs from the far dead-ball line (top, world -z)
 * to the near dead-ball line (bottom, world +z), so art drawn upright reads from the attacking camera.
 * Markings follow the real pitch: try lines, 22 m lines and halfway solid; 10 m, 5 m and 15 m lines dashed.
 */
export function drawPitchCanvas(brand: Brand, t: Tunables, logo: HTMLImageElement | null, mark: HTMLImageElement | null): HTMLCanvasElement {
  const f = t.field;
  const ppm = f.texturePxPerM;
  const w = Math.round(f.widthM * ppm);
  const h = Math.round(f.lengthM * ppm);
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('2D canvas not available');

  const ig = f.inGoalM * ppm;
  const line = Math.max(1, f.lineWidthM * ppm);
  const playing = f.lengthM - 2 * f.inGoalM;
  /** Canvas y of a distance (metres) from the far try line. */
  const yAt = (m: number) => ig + m * ppm;

  // Grass with mowing stripes, wear where the play happens, then fine grain.
  ctx.fillStyle = t.look.grass;
  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = t.look.grassStripe;
  for (let y = 0, i = 0; y < f.lengthM; y += f.stripeEveryM, i++) {
    if (i % 2 === 1) ctx.fillRect(0, y * ppm, w, f.stripeEveryM * ppm);
  }
  // Cross-mown: fainter stripes the other way, so the pitch reads as a cut broadcast surface (a checker).
  ctx.globalAlpha = f.crossStripeAlpha;
  for (let x = 0, i = 0; x < f.widthM; x += f.crossStripeEveryM, i++) {
    if (i % 2 === 1) ctx.fillRect(x * ppm, 0, f.crossStripeEveryM * ppm, h);
  }
  ctx.globalAlpha = 1;
  drawWear(ctx, w, h, ig, t);
  drawGrain(ctx, w, h, t);

  // In-goal areas in the brand's primary colour with the wordmark in the accent (BRAND placement 6).
  ctx.fillStyle = brand.colors.primary;
  ctx.fillRect(0, 0, w, ig);
  ctx.fillRect(0, h - ig, w, ig);
  if (logo) {
    const tinted = tintImage(logo, brand.colors.accent);
    const scale = Math.min((ig * f.inGoalLogoHeightFraction) / tinted.height, (w * f.inGoalLogoMaxWidthFraction) / tinted.width);
    const lw = tinted.width * scale;
    const lh = tinted.height * scale;
    // Far in-goal upright from the attacking camera; the near one turned to read from the other end.
    ctx.drawImage(tinted, (w - lw) / 2, (ig - lh) / 2, lw, lh);
    ctx.save();
    ctx.translate(w / 2, h - ig / 2);
    ctx.rotate(Math.PI);
    ctx.drawImage(tinted, -lw / 2, -lh / 2, lw, lh);
    ctx.restore();
  }

  // Halfway mark (BRAND placement 7): the pixel-grid mark in the accent, centred on halfway.
  if (mark) {
    const tinted = tintImage(mark, brand.colors.accent);
    const size = f.halfwayMarkM * ppm;
    const s = size / Math.max(tinted.width, tinted.height);
    ctx.globalAlpha = f.halfwayMarkAlpha;
    ctx.drawImage(tinted, w / 2 - (tinted.width * s) / 2, yAt(playing / 2) - (tinted.height * s) / 2, tinted.width * s, tinted.height * s);
    ctx.globalAlpha = 1;
  }

  ctx.fillStyle = brand.colors.pitchLine;
  // Touchlines and dead-ball lines.
  ctx.fillRect(0, 0, w, line);
  ctx.fillRect(0, h - line, w, line);
  ctx.fillRect(0, 0, line, h);
  ctx.fillRect(w - line, 0, line, h);

  const solid = (m: number) => ctx.fillRect(0, yAt(m) - line / 2, w, line);
  const dashedAcross = (m: number) => {
    const dash = f.dashM * ppm;
    for (let x = 0; x < w; x += dash * 2) ctx.fillRect(x, yAt(m) - line / 2, dash, line);
  };
  // Try lines, 22s and halfway solid.
  for (const m of [0, f.twentyTwoM, playing / 2, playing - f.twentyTwoM, playing]) solid(m);
  // 10 m lines either side of halfway and the 5 m lines in front of each try line, dashed.
  for (const m of [playing / 2 - f.tenM, playing / 2 + f.tenM, f.fiveM, playing - f.fiveM]) dashedAcross(m);

  // Dashed lines running the length of the pitch, 5 m and 15 m in from each touchline (try line to try line).
  const dash = f.dashM * ppm;
  for (const inM of [f.fiveM, f.fifteenM]) {
    for (const x of [inM * ppm, w - inM * ppm]) {
      for (let y = yAt(0); y < yAt(playing); y += dash * 2) ctx.fillRect(x - line / 2, y, line, Math.min(dash, yAt(playing) - y));
    }
  }
  return canvas;
}

/** Worn, browner patches: most through the middle of the pitch, fading toward the touchlines. */
function drawWear(ctx: CanvasRenderingContext2D, w: number, h: number, ig: number, t: Tunables): void {
  const f = t.field;
  const ppm = f.texturePxPerM;
  const rng = new Rng(7);
  ctx.save();
  ctx.fillStyle = t.look.grassWear;
  for (let i = 0; i < f.wearPatches; i++) {
    const x = w / 2 + (rng.next() + rng.next() - 1) * f.wearSpreadM * ppm;
    const y = ig + rng.next() * (h - 2 * ig);
    const r = (1.5 + rng.next() * 4) * ppm;
    ctx.globalAlpha = f.wearMaxAlpha * (0.3 + 0.7 * rng.next()) * Math.max(0, 1 - Math.abs(x - w / 2) / (w / 2));
    ctx.beginPath();
    ctx.ellipse(x, y, r, r * (0.6 + rng.next() * 0.8), rng.next() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

/** Per-pixel brightness noise so the grass is not a flat fill. */
function drawGrain(ctx: CanvasRenderingContext2D, w: number, h: number, t: Tunables): void {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  const rng = new Rng(11);
  const k = t.field.grassNoise * 255;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rng.next() - 0.5) * 2 * k;
    d[i] = d[i]! + n;
    d[i + 1] = d[i + 1]! + n;
    d[i + 2] = d[i + 2]! + n * 0.6;
  }
  ctx.putImageData(img, 0, 0);
}

/** A small tiling grass-blade texture, multiplied over the pitch up close. */
export function grassDetailCanvas(size: number): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = size;
  c.height = size;
  const ctx = c.getContext('2d');
  if (!ctx) throw new Error('2D canvas not available');
  const img = ctx.createImageData(size, size);
  const rng = new Rng(23);
  for (let i = 0; i < size * size; i++) {
    const v = 128 + (rng.next() - 0.5) * 120;
    img.data[i * 4] = v;
    img.data[i * 4 + 1] = v;
    img.data[i * 4 + 2] = v;
    img.data[i * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  ctx.globalAlpha = 0.25;
  for (let i = 0; i < size * 2; i++) {
    const x = rng.next() * size;
    const y = rng.next() * size;
    ctx.fillStyle = rng.next() < 0.5 ? 'black' : 'white';
    ctx.fillRect(x, y, 1, 2 + rng.next() * 4);
  }
  return c;
}

/** Recolours a single-colour logo image to the given colour, keeping its alpha. */
export function tintImage(img: HTMLImageElement, color: string): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = img.naturalWidth || img.width;
  c.height = img.naturalHeight || img.height;
  const ctx = c.getContext('2d');
  if (!ctx) throw new Error('2D canvas not available');
  ctx.drawImage(img, 0, 0, c.width, c.height);
  ctx.globalCompositeOperation = 'source-in';
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, c.width, c.height);
  return c;
}
