import * as THREE from 'three';
import type { Brand } from '../brand/types';
import type { Tunables } from '../sim/tunables';

type Seg = { x0: number; z0: number; x1: number; z1: number };

const MAX_LINES = 6;

/**
 * Lines painted on the grass in the brand accent: the dashed chase line from the user's defender to the carrier
 * while TACKLE is held (addendum 4), and the running lines of the play just called (GDD 6.3), which fade out.
 */
export class GroundLines {
  readonly group = new THREE.Group();
  private readonly chase: THREE.Mesh;
  private readonly dash: THREE.CanvasTexture;
  private readonly arrows: { body: THREE.Mesh; head: THREE.Mesh }[] = [];
  private readonly arrowMat: THREE.MeshBasicMaterial;
  private time = 0;

  constructor(
    brand: Brand,
    private readonly t: Tunables,
  ) {
    const c = document.createElement('canvas');
    c.width = 64;
    c.height = 4;
    const g = c.getContext('2d')!;
    g.fillStyle = brand.colors.accent;
    g.fillRect(0, 0, 36, 4);
    this.dash = new THREE.CanvasTexture(c);
    this.dash.wrapS = THREE.RepeatWrapping;
    this.chase = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ map: this.dash, transparent: true, depthWrite: false }),
    );
    this.chase.renderOrder = 6;
    this.chase.visible = false;
    this.group.add(this.chase);
    this.arrowMat = new THREE.MeshBasicMaterial({ color: brand.colors.accent, transparent: true, opacity: 0, depthWrite: false });
    const headShape = new THREE.Shape();
    headShape.moveTo(-0.6, 0);
    headShape.lineTo(0.6, 0);
    headShape.lineTo(0, 1.1);
    headShape.closePath();
    const headGeo = new THREE.ShapeGeometry(headShape).rotateX(-Math.PI / 2);
    const bodyGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
    for (let k = 0; k < MAX_LINES; k++) {
      const body = new THREE.Mesh(bodyGeo, this.arrowMat);
      const head = new THREE.Mesh(headGeo, this.arrowMat);
      body.renderOrder = head.renderOrder = 5;
      body.visible = head.visible = false;
      this.arrows.push({ body, head });
      this.group.add(body, head);
    }
  }

  /** The chase line, or null to hide it. */
  setChase(seg: Seg | null): void {
    this.chase.visible = !!seg;
    if (!seg) return;
    const len = place(this.chase, seg, this.t.ui.chaseLineWidthM, 0.05);
    this.dash.repeat.x = len / this.t.ui.chaseDashM;
  }

  /** The play's running lines and how strongly to show them (1 just called, fading to 0). */
  setPlay(segs: Seg[], k: number): void {
    this.arrowMat.opacity = this.t.ui.playLineOpacity * Math.max(0, Math.min(1, k * 2));
    this.arrows.forEach((a, i) => {
      const seg = segs[i];
      a.body.visible = a.head.visible = !!seg && k > 0;
      if (!seg) return;
      place(a.body, seg, this.t.ui.playLineWidthM, 0.04);
      const ang = Math.atan2(seg.x1 - seg.x0, seg.z1 - seg.z0);
      a.head.position.set(seg.x1, 0.045, seg.z1);
      a.head.rotation.set(0, ang + Math.PI, 0);
    });
  }

  update(dt: number): void {
    this.time += dt;
    // The dashes run toward the carrier.
    this.dash.offset.x = -this.time * 2;
  }
}

/** Stretches a unit plane along the segment; returns its length. */
function place(m: THREE.Mesh, s: Seg, width: number, y: number): number {
  const dx = s.x1 - s.x0;
  const dz = s.z1 - s.z0;
  const len = Math.max(0.01, Math.hypot(dx, dz));
  m.position.set((s.x0 + s.x1) / 2, y, (s.z0 + s.z1) / 2);
  m.rotation.set(0, Math.atan2(dx, dz) + Math.PI / 2, 0);
  m.scale.set(len, 1, width);
  return len;
}

/**
 * The ruck marker painted on the grass (Jonny's reference game): a white arc across the ruck, filled from the
 * attack's end in the attack's colour by the chance they keep it, the rest in the defence's.
 */
export class RuckArc {
  readonly group = new THREE.Group();
  private readonly back: THREE.Mesh;
  private readonly fill: THREE.Mesh;
  private readonly fillMat: THREE.MeshBasicMaterial;
  private readonly restMat: THREE.MeshBasicMaterial;

  constructor(private readonly t: Tunables) {
    const r = t.ruck;
    this.back = new THREE.Mesh(arcGeo(r.groundArcM, r.groundArcWidthM + 0.08, 1), new THREE.MeshBasicMaterial({ color: t.look.ruckArcEdge, transparent: true, opacity: 0.9, depthWrite: false }));
    this.restMat = new THREE.MeshBasicMaterial({ color: t.look.ruckArcEdge, transparent: true, opacity: 0.9, depthWrite: false });
    this.fillMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0.95, depthWrite: false });
    this.fill = new THREE.Mesh(arcGeo(r.groundArcM, r.groundArcWidthM, 1), this.fillMat);
    this.back.renderOrder = 6;
    this.fill.renderOrder = 7;
    this.back.material = this.restMat;
    this.group.add(this.back, this.fill);
    this.group.visible = false;
  }

  /** Shows the arc at the ruck (x, z), facing dir (the attack's way), filled to `k` (0 to 1) in `color`. */
  show(x: number, z: number, dir: number, k: number, color: string, rest: string): void {
    this.group.visible = true;
    this.group.position.set(x, 0.05, z - dir * this.t.ruck.groundArcBackM);
    this.group.rotation.y = dir < 0 ? 0 : Math.PI;
    this.fillMat.color.set(color);
    this.restMat.color.set(rest);
    const kk = Math.max(0.001, Math.min(1, k));
    this.fill.geometry.dispose();
    this.fill.geometry = arcGeo(this.t.ruck.groundArcM, this.t.ruck.groundArcWidthM, kk);
  }

  hide(): void {
    this.group.visible = false;
  }
}

/** A flat ring segment on the ground in front of the origin: radius r, width w, from the left end to fraction k. */
function arcGeo(r: number, w: number, k: number): THREE.BufferGeometry {
  const span = 0.6 * Math.PI;
  const a0 = Math.PI / 2 + span / 2;
  return new THREE.RingGeometry(r - w / 2, r + w / 2, 32, 1, a0 - span * k, span * k).rotateX(-Math.PI / 2);
}
