import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { clone as cloneSkinned } from 'three/examples/jsm/utils/SkeletonUtils.js';
import type { Tunables } from '../sim/tunables';
import {
  type Action,
  type AthleteRig,
  type KitLogos,
  type SquadSpec,
  blobTexture,
  helmetGeo,
  liftDark,
  maskGeo,
  numberAtlas,
  rimShader,
  stripeGeo,
} from './athletes';
import type { AthleteModel } from './athleteModel';
import { type DanceArm, danceAt } from './celebration';
import { stepHeading } from './heading';

/**
 * Rigged athletes (GDD section 10): one skinned CC0 body per player, coloured by kit region in the shader,
 * driven by a few clips (idle, jog, sprint, crouch, push, fall) blended by speed and action, with the arms
 * aimed in code on top for the football moves the clips do not have (carry, throw, catch, reach).
 * Helmet, shoulder pads and numbers are rigid instanced meshes that follow the head and chest bones.
 */

type Clip = 'idle' | 'jog' | 'sprint' | 'crouch' | 'push' | 'fall' | 'kick';
const CLIPS: readonly Clip[] = ['idle', 'jog', 'sprint', 'crouch', 'push', 'fall', 'kick'];
/** Kit regions: skin, jersey, pants, socks, glove, cleat (see kitCuts). */
const KIT_REGIONS = 6;

type GearName = 'helmet' | 'stripe' | 'mask' | 'pads' | 'numFront' | 'numBack' | 'shoeL' | 'shoeR';
type GearBone = 'head' | 'chest' | 'footL' | 'footR';
type LogoKind = 'word' | 'mark';
/** One logo patch on the kit: which artwork, which bone it rides on, and where relative to that bone. */
interface LogoSlot {
  kind: LogoKind;
  bone: GearBone;
  local: THREE.Matrix4;
}
type V3 = readonly [number, number, number];
/**
 * Arm aims in the torso's frame: x away from the body on that arm's side, y up the spine, z out of the chest.
 * `ground` aims in the upright body frame instead (a hand to the turf).
 */
interface ArmAim {
  up: V3;
  lo: V3;
  ground?: boolean;
}
interface Overlay {
  left: ArmAim | null;
  right: ArmAim | null;
}
/** Where an arm is aimed right now: eases toward each new ArmAim so poses blend, never pop. */
interface ArmPose {
  up: THREE.Vector3;
  lo: THREE.Vector3;
  ground: boolean;
}

const NO_OVERLAY: Overlay = { left: null, right: null };
/** Ball carried in the right hand, in front of the ribs. */
const TUCK: ArmAim = { up: [0.25, -0.8, 0.5], lo: [-0.4, 0.15, 0.9] };
const HANDS_UP: ArmAim = { up: [0.25, 0.9, 0.35], lo: [0.05, 0.95, 0.3] };
const REACH: ArmAim = { up: [0.2, 0.3, 0.95], lo: [0.05, 0.4, 0.95] };
const READY: ArmAim = { up: [0.15, -0.55, 0.75], lo: [-0.45, 0.25, 0.85] };
const HAND_DOWN: ArmAim = { up: [0.05, -0.75, 0.6], lo: [0, -1, 0.1], ground: true };
const DIVE: ArmAim = { up: [0.15, 0.1, 1], lo: [0.05, 0.1, 1] };
/** A tackler's arms out and closing round the carrier. */
const WRAP: ArmAim = { up: [0.45, -0.05, 0.9], lo: [-0.7, 0, 0.7] };
/** A tackled carrier reaching the ball out ahead as he goes to ground. */
const PRESENT: ArmAim = { up: [0.2, 0.15, 1], lo: [0, 0.2, 1] };
const THROW_WIND: ArmAim = { up: [0.75, 0.45, -0.5], lo: [0.1, 1, -0.35] };
const THROW_RELEASE: ArmAim = { up: [0.3, 0.6, 0.75], lo: [0, 0.45, 1] };
const THROW_FOLLOW: ArmAim = { up: [-0.25, -0.45, 0.85], lo: [-0.5, -0.55, 0.6] };
/**
 * The rugby pass, written for a pass to the athlete's own left (Jonny, 14 Nov 2026: better pass animations): the
 * ball loaded at the right hip, both hands swing it across the body, then the arms follow through at the target.
 * `own` is the arm on the side the ball goes, `far` the arm crossing over; a pass right swaps them.
 */
const PASS_LOAD = {
  own: { up: [-0.1, -0.8, 0.55], lo: [-0.75, -0.25, 0.6] } as ArmAim,
  far: { up: [0.4, -0.85, 0.2], lo: [-0.2, -0.45, 0.85] } as ArmAim,
};
const PASS_SWING = {
  own: { up: [0.65, -0.3, 0.7], lo: [0.55, -0.05, 0.85] } as ArmAim,
  far: { up: [-0.35, -0.25, 0.9], lo: [-0.7, -0.05, 0.7] } as ArmAim,
};
const PASS_FOLLOW = {
  own: { up: [0.7, -0.45, 0.55], lo: [0.6, -0.3, 0.75] } as ArmAim,
  far: { up: [-0.3, -0.4, 0.85], lo: [-0.75, -0.25, 0.6] } as ArmAim,
};
/** A receiver's target: arms out in front, palms up at the chest. */
const RECEIVE: ArmAim = { up: [0.25, -0.65, 0.72], lo: [-0.3, 0.2, 0.93] };
/** The wrap locked: forearms closed behind the carrier's legs. */
const WRAP_CLOSED: ArmAim = { up: [0.3, -0.2, 0.93], lo: [-0.9, -0.1, 0.4] };
/** Pass pro: hands at the chest, punching forward (the push clip alone holds them high). */
const BLOCK: ArmAim = { up: [0.3, -0.35, 0.9], lo: [-0.25, 0.25, 1] };
const GUIDE_HAND: ArmAim = { up: [0.25, 0.05, 1], lo: [-0.35, 0.1, 1] };
/** Touchdown dance arms (see celebration.ts). */
const DANCE_ARMS: Record<DanceArm, ArmAim> = {
  pumpUp: { up: [0.55, 0.75, 0.35], lo: [0.05, 1, 0.15] },
  pumpDown: { up: [0.45, -0.35, 0.6], lo: [-0.3, 0.55, 0.8] },
  out: { up: [1, 0.2, 0.05], lo: [1, 0.3, 0.1] },
  flex: { up: [1, 0.15, 0.15], lo: [0.15, 1, 0.1] },
};

interface Bones {
  head: THREE.Bone;
  chest: THREE.Bone;
  footL: THREE.Bone;
  footR: THREE.Bone;
  upL: THREE.Bone;
  loL: THREE.Bone;
  handL: THREE.Bone;
  palmL: THREE.Bone;
  upR: THREE.Bone;
  loR: THREE.Bone;
  handR: THREE.Bone;
  palmR: THREE.Bone;
}

interface Rigged {
  holder: THREE.Group;
  mixer: THREE.AnimationMixer;
  actions: Record<Clip, THREE.AnimationAction>;
  weights: Record<Clip, number>;
  bones: Bones;
  x: number;
  z: number;
  px: number;
  pz: number;
  yaw: number;
  faceYaw: number | null;
  /** Smoothed ground velocity (metres a second), see stepHeading. */
  vx: number;
  vz: number;
  speed: number;
  /** Run cycle position, 0 to 1. */
  cycle: number;
  action: Action;
  actionT: number;
  pitch: number;
  lift: number;
  /** The dance's turn and sway on top of the facing (zero outside a celebration). */
  danceYaw: number;
  roll: number;
  /** The chest turned on the hips (radians, + to the athlete's left), for the pass. */
  twist: number;
  /** The clip's own chest rotation, kept so the twist never builds on last frame's twist. */
  chestClip: THREE.Quaternion;
  overlayL: number;
  overlayR: number;
  poseL: ArmPose;
  poseR: ArmPose;
  /** The clip's own rotation of the four arm bones, kept so the aim never builds on last frame's aim. */
  armClip: THREE.Quaternion[];
  visible: boolean;
}

const v = new THREE.Vector3();
const v2 = new THREE.Vector3();
const qa = new THREE.Quaternion();
const qb = new THREE.Quaternion();
const qc = new THREE.Quaternion();
const qHolder = new THREE.Quaternion();
const qTorso = new THREE.Quaternion();
const euler = new THREE.Euler(0, 0, 0, 'YXZ');

export class SkinnedAthletesView implements AthleteRig {
  readonly group = new THREE.Group();
  private readonly list: Rigged[] = [];
  private readonly offsets: number[] = [];
  private readonly gear = {} as Record<GearName, THREE.InstancedMesh>;
  /** Gear placement relative to its bone, measured once in the bind pose. */
  private readonly gearLocal = {} as Record<GearName, THREE.Matrix4>;
  private readonly gearBone = {} as Record<GearName, GearBone>;
  private readonly shadow: THREE.InstancedMesh;
  private readonly logoMeshes: Partial<Record<LogoKind, THREE.InstancedMesh>> = {};
  private readonly logoSlots: LogoSlot[] = [];
  /** The brand wordmark sits on the chest (reference/11): the brand team then has no front number. */
  private frontWord = false;
  /** Per athlete: wears the brand logos. */
  private readonly branded: boolean[] = [];
  private readonly materials: THREE.Material[] = [];
  /** Bone axis (toward its child) in the bone's own frame, for aiming. */
  private readonly axisUpL = new THREE.Vector3();
  private readonly axisLoL = new THREE.Vector3();
  private readonly axisUpR = new THREE.Vector3();
  private readonly axisLoR = new THREE.Vector3();
  /** Inverse of the chest bone's bind rotation: turns the chest's rotation into the torso frame. */
  private readonly chestBindInv = new THREE.Quaternion();
  private readonly strideJog: number;
  private readonly strideSprint: number;
  private readonly speedJog: number;
  private readonly speedSprint: number;
  private readonly m = new THREE.Matrix4();
  private readonly hidden = new THREE.Matrix4().makeScale(0, 0, 0);

  constructor(
    squads: SquadSpec[],
    private readonly t: Tunables,
    model: AthleteModel,
    logos: KitLogos = { word: null, mark: null },
  ) {
    const A = t.athlete;
    const total = squads.reduce((n, s) => n + s.numbers.length, 0);
    const clips = {} as Record<Clip, THREE.AnimationClip>;
    for (const c of CLIPS) {
      // The kick came later than the others: a model built before it stands still instead.
      const clip = model.clips.get(c) ?? (c === 'kick' ? model.clips.get('idle') : undefined);
      if (!clip) throw new Error(`athlete model has no ${c} clip`);
      clips[c] = clip;
    }
    this.strideJog = A.jogStrideMetres * A.scale;
    this.strideSprint = A.sprintStrideMetres * A.scale;
    this.speedJog = this.strideJog / clips.jog.duration;
    this.speedSprint = this.strideSprint / clips.sprint.duration;

    // Bind-pose frames for the gear and the arm axes, from the template.
    const template = model.scene;
    template.updateMatrixWorld(true);
    const tb = findBones(template);
    this.axisUpL.copy(tb.loL.position).normalize();
    this.axisLoL.copy(tb.handL.position).normalize();
    this.axisUpR.copy(tb.loR.position).normalize();
    this.axisLoR.copy(tb.handR.position).normalize();
    tb.chest.getWorldQuaternion(this.chestBindInv).invert();
    const hd = model.variant === 'hd';
    // The HD athlete has its own helmet, mask, pads and cleats, and its own proportions for the numbers and logos.
    const g = hd ? { ...A.gear, ...A.hd.gear, logos: { ...A.gear.logos, ...A.hd.gear.logos } } : A.gear;
    /** A part's transform relative to its bone, from where it sits on the body in the bind pose (metres). */
    const local = (bone: GearBone, offset: number[], size: number[], turn: number[] = [0, 0, 0]): THREE.Matrix4 => {
      const b = tb[bone];
      b.getWorldPosition(v);
      const model = new THREE.Matrix4().compose(
        v.add(v2.fromArray(offset)),
        new THREE.Quaternion().setFromEuler(new THREE.Euler(turn[0], turn[1], turn[2])),
        new THREE.Vector3(size[0], size[1], size[2]),
      );
      return b.matrixWorld.clone().invert().multiply(model);
    };
    const place = (name: GearName, bone: GearBone, offset: number[], size: number[]) => {
      this.gearLocal[name] = local(bone, offset, size);
      this.gearBone[name] = bone;
    };
    place('helmet', 'head', g.helmetOffset, [g.helmetScale, g.helmetScale, g.helmetScale]);
    place('stripe', 'head', g.helmetOffset, [g.helmetScale, g.helmetScale, g.helmetScale]);
    place('mask', 'head', g.helmetOffset, [g.helmetScale, g.helmetScale, g.helmetScale]);
    place('pads', 'chest', g.padsOffset, [g.padsScale, g.padsScale, g.padsScale]);
    place('numFront', 'chest', g.numberFrontOffset, [g.numberSize[0]!, g.numberSize[1]!, 1]);
    place('numBack', 'chest', g.numberBackOffset, [g.numberSize[0]!, g.numberSize[1]!, 1]);
    place('shoeL', 'footL', g.shoeOffset, [1, 1, 1]);
    place('shoeR', 'footR', [-g.shoeOffset[0]!, g.shoeOffset[1]!, g.shoeOffset[2]!], [1, 1, 1]);

    // Gear meshes, one instance per athlete.
    const shiny = new THREE.MeshPhongMaterial({ shininess: 90, specular: new THREE.Color(t.look.helmetSpecular) });
    shiny.onBeforeCompile = (s) => rimShader(s, t);
    const matte = new THREE.MeshLambertMaterial();
    matte.onBeforeCompile = (s) => rimShader(s, t);
    const gearParts: [GearName, THREE.BufferGeometry, THREE.Material][] = [
      ['helmet', helmetGeo(), shiny],
      ['stripe', stripeGeo(), shiny],
      ['mask', maskGeo(), matte],
      ['pads', padsGeo(), matte],
      ['shoeL', shoeGeo(t), matte],
      ['shoeR', shoeGeo(t), matte],
    ];
    for (const [name, geo, mat] of gearParts) this.addGear(name, geo, mat, total);
    // Still placed every frame (headPosition reads the helmet), just not drawn.
    // Rugby: no helmet, facemask or shoulder pads; the HD body brings its own boots too.
    for (const [name] of gearParts) if (hd || !name.startsWith('shoe')) this.gear[name].visible = false;
    const atlas = numberAtlas(squads, t);
    for (const side of ['numFront', 'numBack'] as const) {
      const geo = new THREE.PlaneGeometry(1, 1);
      if (side === 'numBack') geo.rotateY(Math.PI);
      const offsets = new Float32Array(total * 2);
      for (let i = 0; i < total; i++) {
        offsets[i * 2] = (i % atlas.cols) / atlas.cols;
        offsets[i * 2 + 1] = 1 - (Math.floor(i / atlas.cols) + 1) / atlas.rows;
      }
      geo.setAttribute('instUv', new THREE.InstancedBufferAttribute(offsets, 2));
      const mat = new THREE.MeshLambertMaterial({ map: atlas.texture, transparent: true, alphaTest: 0.3 });
      mat.onBeforeCompile = (shader) => {
        rimShader(shader, t);
        shader.uniforms['uvScale'] = { value: new THREE.Vector2(1 / atlas.cols, 1 / atlas.rows) };
        shader.vertexShader = shader.vertexShader
          .replace('#include <common>', '#include <common>\nattribute vec2 instUv;\nuniform vec2 uvScale;')
          .replace('#include <uv_vertex>', '#include <uv_vertex>\nvMapUv = uv * uvScale + instUv;');
      };
      this.addGear(side, geo, mat, total);
    }
    // Brand logos on the kit: the wordmark across the back above the number, the mark on each side of the
    // helmet and, where shoulderMarks is set, on top of each shoulder pad (top of the art toward the front,
    // upright from behind; off for the HD athlete, whose pads move with its arms). Tinted with the kit's number colour.
    const L = g.logos;
    // Planes keep the artwork's own proportions: the wordmark is backSize[0] wide, the mark markSize tall.
    const word = [L.backSize[0]!, L.backSize[0]! / imageAspect(logos.word), 1];
    const mark = [L.markSize * imageAspect(logos.mark), L.markSize, 1];
    const chest = (L as { chestOffset?: number[]; chestWidth?: number }).chestOffset;
    const chestW = (L as { chestWidth?: number }).chestWidth;
    // The wordmark goes on the chest where the kit has a place for it (the HD rugby kit), else across the back.
    if (logos.word && !(chest && chestW)) this.logoSlots.push({ kind: 'word', bone: 'chest', local: local('chest', L.backOffset, word, [0, Math.PI, 0]) });
    if (logos.word && chest && chestW) {
      this.logoSlots.push({ kind: 'word', bone: 'chest', local: local('chest', chest, [chestW, chestW / imageAspect(logos.word), 1]) });
      this.frontWord = true;
    }
    if (logos.mark) {
      for (const side of [1, -1]) {
        const [hx, hy, hz] = L.helmetOffset as [number, number, number];
        const [sx, sy, sz] = L.shoulderOffset as [number, number, number];
        if (L.helmetMarks) this.logoSlots.push({ kind: 'mark', bone: 'head', local: local('head', [hx * side, hy, hz], mark, [0, (side * Math.PI) / 2, 0]) });
        if (L.shoulderMarks) this.logoSlots.push({ kind: 'mark', bone: 'chest', local: local('chest', [sx * side, sy, sz], mark, [-Math.PI / 2, 0, Math.PI]) });
      }
    }
    for (const kind of ['word', 'mark'] as const) {
      const img = logos[kind];
      const count = this.logoSlots.filter((s) => s.kind === kind).length;
      if (!img || !count) continue;
      const mat = new THREE.MeshLambertMaterial({ map: logoTexture(img, t), transparent: true, alphaTest: L.alphaTest, depthWrite: false });
      mat.onBeforeCompile = (sh) => rimShader(sh, t);
      const mesh = new THREE.InstancedMesh(new THREE.PlaneGeometry(1, 1), mat, total * count);
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.frustumCulled = false;
      this.logoMeshes[kind] = mesh;
      this.group.add(mesh);
    }

    this.shadow = new THREE.InstancedMesh(
      new THREE.PlaneGeometry(t.athlete.shadowM, t.athlete.shadowM).rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ map: blobTexture(), transparent: true, depthWrite: false, opacity: t.athlete.shadowOpacity }),
      total,
    );
    this.shadow.frustumCulled = false;
    this.shadow.renderOrder = -1;
    this.group.add(this.shadow);

    // Bodies: the main one and any other looks on the same skeleton, each with its own kit measurements.
    const bodies = [model, ...model.looks].map((m) => {
      m.scene.updateMatrixWorld(true);
      const body = findBody(m.scene);
      const baseMat = body.material as THREE.MeshStandardMaterial;
      if (hd && !(baseMat.userData as Partial<HdExtras>).kitAverage?.parts) throw new Error('HD athlete model has no kit measurements');
      return {
        m,
        baseMat,
        cuts: kitCuts(body, t),
        hdCuts: hd ? hdBands(body, t, m.collarUp) : null,
        skinAverage: new THREE.Vector3().fromArray((baseMat.userData['skinAverage'] as number[] | undefined) ?? [1, 1, 1]),
      };
    });
    const c = new THREE.Color();
    let i = 0;
    for (const squad of squads) {
      this.offsets.push(i);
      const u = squad.uniform;
      for (let k = 0; k < squad.numbers.length; k++, i++) {
        const skin = t.look.skinTones[(i * 7 + 3) % t.look.skinTones.length]!;
        const kit = [skin, u.jersey, u.pants, u.socks, u.stripe, t.look.cleat].map((hex, r) =>
          r === 0 ? new THREE.Color(hex) : liftDark(new THREE.Color(hex), t.look.blackLift),
        );
        // Looks spread through each squad so neighbours differ.
        const b = bodies[(k + this.offsets.length) % bodies.length]!;
        // Collar, cuffs and the sock band in the kit's trim colour; a one-colour kit takes its number colour.
        const trim = liftDark(new THREE.Color(u.stripe !== u.jersey ? u.stripe : u.numbers), t.look.blackLift);
        const lift = (hex: string) => liftDark(new THREE.Color(hex), t.look.blackLift);
        // Panels (raglan sleeves, chest chevron, shorts stripes) in the kit's panel colour; the sock band in the
        // jersey colour, or two hoops in the number colour when the socks are the jersey colour (reference/13).
        const style = {
          panel: lift(u.stripe),
          sockHoop: lift(u.socks !== u.jersey ? u.jersey : u.numbers),
          hoops: u.socks === u.jersey,
          trimShade: t.athlete.hd.jersey.trimShade,
        };
        const mat = b.hdCuts ? hdKitMaterial(b.m, kit, u, b.baseMat.userData as HdExtras, b.hdCuts, t, trim, style) : kitMaterial(b.m, kit, b.skinAverage, b.cuts, t);
        this.materials.push(mat);
        const holder = new THREE.Group();
        const inst = cloneSkinned(b.m.scene);
        inst.scale.setScalar(A.scale);
        inst.traverse((o) => {
          if ((o as THREE.SkinnedMesh).isSkinnedMesh) {
            const sm = o as THREE.SkinnedMesh;
            sm.material = mat;
            sm.frustumCulled = false;
            sm.castShadow = true;
          }
        });
        holder.add(inst);
        holder.visible = false;
        this.group.add(holder);
        const bones = findBones(inst);
        const mixer = new THREE.AnimationMixer(inst);
        const actions = {} as Record<Clip, THREE.AnimationAction>;
        const weights = {} as Record<Clip, number>;
        for (const cl of CLIPS) {
          const a = mixer.clipAction(clips[cl]);
          if (cl === 'jog' || cl === 'sprint') a.timeScale = 0;
          if (cl === 'fall' || cl === 'kick') {
            a.setLoop(THREE.LoopOnce, 1);
            a.clampWhenFinished = true;
            a.timeScale = cl === 'fall' ? A.fallTimeScale : 1;
          }
          a.play();
          a.setEffectiveWeight(0);
          actions[cl] = a;
          weights[cl] = 0;
        }
        this.list.push({
          holder,
          mixer,
          actions,
          weights,
          bones,
          x: 0,
          z: 0,
          px: 0,
          pz: 0,
          yaw: Math.PI,
          faceYaw: null,
          vx: 0,
          vz: 0,
          speed: 0,
          cycle: (i * 0.37) % 1,
          action: 'idle',
          actionT: 0,
          pitch: 0,
          lift: 0,
          danceYaw: 0,
          roll: 0,
          twist: 0,
          chestClip: bones.chest.quaternion.clone(),
          overlayL: 0,
          overlayR: 0,
          poseL: armPose(READY),
          poseR: armPose(READY),
          armClip: armBones(bones).map((b) => b.quaternion.clone()),
          visible: false,
        });
        this.branded.push(!!squad.branded);
        for (const mesh of Object.values(this.logoMeshes)) {
          const per = mesh.count / total;
          for (let k = 0; k < per; k++) mesh.setColorAt(i * per + k, c.set(u.numbers));
        }
        this.gear.helmet.setColorAt(i, liftDark(c.set(u.helmet), t.look.blackLift));
        this.gear.stripe.setColorAt(i, liftDark(c.set(u.stripe), t.look.blackLift));
        this.gear.mask.setColorAt(i, liftDark(c.set(u.facemask), t.look.blackLift));
        this.gear.pads.setColorAt(i, liftDark(c.set(u.jersey), t.look.blackLift));
        this.gear.shoeL.setColorAt(i, c.set(t.look.cleat));
        this.gear.shoeR.setColorAt(i, c.set(t.look.cleat));
      }
    }
    for (const mesh of [...Object.values(this.gear), ...Object.values(this.logoMeshes)]) if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  }

  private addGear(name: GearName, geo: THREE.BufferGeometry, mat: THREE.Material, total: number): void {
    const mesh = new THREE.InstancedMesh(geo, mat, total);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.frustumCulled = false;
    this.gear[name] = mesh;
    this.group.add(mesh);
  }

  index(squad: number, slot: number): number {
    return (this.offsets[squad] ?? 0) + slot;
  }

  place(i: number, x: number, z: number, action?: Action, face?: number | null): void {
    const a = this.list[i];
    if (!a) return;
    if (!a.visible) {
      a.px = x;
      a.pz = z;
      a.vx = a.vz = 0;
    }
    a.visible = true;
    a.x = x;
    a.z = z;
    if (face !== undefined) a.faceYaw = face;
    if (action && action !== a.action) this.setAction(a, action);
  }

  teleport(i: number, x: number, z: number, action: Action, face: number): void {
    const a = this.list[i];
    if (!a) return;
    a.x = a.px = x;
    a.z = a.pz = z;
    a.yaw = face;
    a.faceYaw = face;
    a.vx = a.vz = a.speed = 0;
    a.visible = true;
    this.setAction(a, action);
    // Land in the pose at once: no blend in from wherever the last play ended.
    const w = this.targetWeights(a);
    for (const c of CLIPS) a.weights[c] = w[c];
    const o = this.overlay(a);
    a.overlayL = o.left ? 1 : 0;
    a.overlayR = o.right ? 1 : 0;
    if (o.left) setPose(a.poseL, o.left);
    if (o.right) setPose(a.poseR, o.right);
    a.pitch = 0;
    a.lift = 0;
    a.danceYaw = 0;
    a.roll = 0;
  }

  private setAction(a: Rigged, action: Action): void {
    a.action = action;
    a.actionT = 0;
    if (action === 'down') a.actions.fall.reset().play();
    if (action === 'kick') {
      a.actions.kick.reset().play();
      a.actions.kick.time = this.t.athlete.kickClipStartSeconds;
    }
  }

  hide(i: number): void {
    const a = this.list[i];
    if (a) a.visible = false;
  }

  actionOf(i: number): Action {
    return this.list[i]?.action ?? 'idle';
  }

  handPosition(i: number, side: 0 | 1, out: THREE.Vector3): THREE.Vector3 {
    const a = this.list[i];
    if (!a) return out.set(0, 0, 0);
    const b = a.bones;
    (side === 0 ? b.handL : b.handR).getWorldPosition(out);
    (side === 0 ? b.palmL : b.palmR).getWorldPosition(v);
    return out.add(v).multiplyScalar(0.5);
  }

  carryPosition(i: number, out: THREE.Vector3): THREE.Vector3 {
    const a = this.list[i];
    if (!a) return out.set(0, 0, 0);
    const B = this.t.ball;
    // The right hand (Jonny, 16 Nov).
    this.handPosition(i, 1, out);
    // From the palm toward the chest, level: the ball sits in that gap with its side on the palm, so the hand
    // wraps the front of the ball instead of sinking into it.
    a.bones.chest.getWorldPosition(v);
    v.sub(out).setY(0);
    const reach = v.length();
    if (reach < 1e-4) return out;
    v.divideScalar(reach);
    // The ball is long along the way he faces: its surface toward the palm is as far out as the ellipse is in
    // that direction (the pointed end when the hand is in front, the belly when it is at the side).
    const yaw = this.facing(i);
    const c = Math.abs(v.x * Math.sin(yaw) + v.z * Math.cos(yaw));
    const half = (B.lengthM / 2) * B.displayScale;
    const r = B.radiusM * B.displayScale;
    const extent = 1 / Math.sqrt((c * c) / (half * half) + (1 - c * c) / (r * r));
    return out.addScaledVector(v, Math.min(extent + B.palmGapM, reach));
  }

  facing(i: number): number {
    const a = this.list[i];
    return a ? a.yaw + a.danceYaw : 0;
  }

  headPosition(i: number, out: THREE.Vector3): THREE.Vector3 {
    this.gear.helmet.getMatrixAt(i, this.m);
    return out.set(0, this.t.athlete.helmetTop, 0).applyMatrix4(this.m);
  }

  update(dt: number): void {
    const A = this.t.athlete;
    const kb = 1 - Math.exp(-A.blendRate * dt);
    const ko = 1 - Math.exp(-A.overlayRate * dt);
    const kp = 1 - Math.exp(-A.poseRate * dt);
    for (let i = 0; i < this.list.length; i++) {
      const a = this.list[i]!;
      a.holder.visible = a.visible;
      if (!a.visible) {
        this.writeGear(i, null);
        continue;
      }
      const dx = a.x - a.px;
      const dz = a.z - a.pz;
      const dist = Math.hypot(dx, dz);
      stepHeading(a, dx, dz, dt, a.faceYaw, a.action === 'block' || a.action === 'down' || a.action === 'tackled' || a.action === 'tackling' || a.action === 'wrap', A);
      a.px = a.x;
      a.pz = a.z;
      a.actionT += dt;

      // Clips: weights ease toward the action's mix; the run cycle follows the ground covered.
      const target = this.targetWeights(a);
      let sum = 0;
      for (const c of CLIPS) {
        // A kick is quick: it blends in faster than the run.
        a.weights[c] += (target[c] - a.weights[c]) * (a.action === 'kick' ? Math.min(1, kb * 3) : kb);
        sum += a.weights[c];
      }
      const sprintMix = this.sprintMix(a.speed);
      a.cycle = (a.cycle + dist / THREE.MathUtils.lerp(this.strideJog, this.strideSprint, sprintMix)) % 1;
      for (const c of CLIPS) a.actions[c].setEffectiveWeight(sum > 0 ? a.weights[c] / sum : c === 'idle' ? 1 : 0);
      a.actions.jog.time = a.cycle * a.actions.jog.getClip().duration;
      a.actions.sprint.time = a.cycle * a.actions.sprint.getClip().duration;
      // The mixer only writes a bone whose clip value changed, so put back the clip pose under last frame's aim.
      const arms = armBones(a.bones);
      for (let k = 0; k < 4; k++) arms[k]!.quaternion.copy(a.armClip[k]!);
      a.bones.chest.quaternion.copy(a.chestClip);
      a.mixer.update(dt);
      for (let k = 0; k < 4; k++) a.armClip[k]!.copy(arms[k]!.quaternion);
      a.chestClip.copy(a.bones.chest.quaternion);

      // Whole body: dives tip forward from the feet; a scorer dances.
      let pitch = 0;
      let lift = 0;
      let yaw = 0;
      let roll = 0;
      // A tackle is set outright, frame by frame: easing it would soften the hit.
      let set = false;
      if (a.action === 'dive') {
        pitch = A.divePitch * Math.min(1, a.actionT / A.diveSeconds);
        lift = A.diveLiftM * Math.sin(Math.min(1, a.actionT / A.diveLiftSeconds) * Math.PI);
      } else if (a.action === 'wrap') {
        pitch = A.wrapPitch * Math.min(1, a.actionT / A.wrapSeconds);
        set = true;
      } else if (a.action === 'tackled' || a.action === 'tackling') {
        // Held round the legs, the body topples forward from the feet and speeds up as it falls.
        const u = Math.max(0, Math.min(1, (a.actionT - A.tackledDelaySeconds) / A.tackledFallSeconds));
        pitch = A.tackledPitch * u * u;
        roll = A.tackledRoll * u;
        if (a.action === 'tackling') {
          // The tackler launches off his feet into the legs, then the two land together.
          lift = A.tackleLiftM * Math.sin(Math.min(1, a.actionT / A.tackleLiftSeconds) * Math.PI);
        } else if (u >= 1) {
          // The carrier hits the turf and bounces once.
          const k = a.actionT - A.tackledDelaySeconds - A.tackledFallSeconds;
          lift = A.landBounceM * Math.max(0, Math.sin(k * Math.PI / A.landBounceSeconds)) * (k < A.landBounceSeconds ? 1 : 0);
        }
        set = true;
      } else if (a.action === 'celebrate') {
        const d = danceAt(a.actionT, A.dance);
        pitch = d.pitch;
        lift = d.lift;
        yaw = d.yaw;
        roll = d.roll;
      }
      const dancing = a.action === 'celebrate';
      // The dance sets the body outright (it is smooth already); everything else eases.
      a.pitch = dancing ? pitch : a.pitch + (pitch - a.pitch) * kp;
      a.lift = dancing || set ? lift : a.lift + (lift - a.lift) * kp;
      a.danceYaw = dancing ? yaw : a.danceYaw * (1 - kp);
      a.roll = dancing || set ? roll : a.roll * (1 - kp);
      if (set) a.pitch = pitch;
      a.holder.position.set(a.x, a.lift, a.z);
      euler.set(a.pitch, a.yaw + a.danceYaw, a.roll, 'YXZ');
      a.holder.quaternion.setFromEuler(euler);
      a.holder.updateMatrixWorld(true);

      // The pass turns the shoulders: wound toward the ball at the hip, then through toward the target.
      const twist = this.passTwist(a);
      a.twist = twist === null ? a.twist * (1 - kp) : twist;
      if (Math.abs(a.twist) > 1e-3) this.twistChest(a);

      // Arms aimed on top of the clip.
      const o = this.overlay(a);
      if (o.left) easePose(a.poseL, o.left, a.overlayL > 0.01 ? ko : 1);
      if (o.right) easePose(a.poseR, o.right, a.overlayR > 0.01 ? ko : 1);
      a.overlayL += ((o.left ? 1 : 0) - a.overlayL) * ko;
      a.overlayR += ((o.right ? 1 : 0) - a.overlayR) * ko;
      if (a.overlayL > 0.01 || a.overlayR > 0.01) {
        qHolder.copy(a.holder.quaternion);
        a.bones.chest.getWorldQuaternion(qTorso).multiply(this.chestBindInv);
        if (a.overlayL > 0.01) this.aimArm(a.bones.upL, a.bones.loL, this.axisUpL, this.axisLoL, a.poseL, 1, a.overlayL);
        if (a.overlayR > 0.01) this.aimArm(a.bones.upR, a.bones.loR, this.axisUpR, this.axisLoR, a.poseR, -1, a.overlayR);
      }
      this.writeGear(i, a);
    }
    for (const mesh of [...Object.values(this.gear), ...Object.values(this.logoMeshes)]) mesh.instanceMatrix.needsUpdate = true;
    this.shadow.instanceMatrix.needsUpdate = true;
  }

  /** Where a passer's shoulders are turned this frame (null when not passing). */
  private passTwist(a: Rigged): number | null {
    if (a.action !== 'passL' && a.action !== 'passR') return null;
    const A = this.t.athlete;
    const s = a.action === 'passL' ? 1 : -1;
    const tt = a.actionT;
    // Wind up, swing through fast, then hold toward the target and ease back.
    const u = tt < A.passLoadSeconds ? -tt / A.passLoadSeconds : tt < A.passSwingSeconds ? -1 + (2 * (tt - A.passLoadSeconds)) / (A.passSwingSeconds - A.passLoadSeconds) : 1;
    return s * A.passTwistRad * u;
  }

  /** Turns the chest bone about the body's up axis by a.twist. */
  private twistChest(a: Rigged): void {
    const chest = a.bones.chest;
    const parent = chest.parent;
    if (!parent) return;
    v.set(0, 1, 0).applyQuaternion(a.holder.quaternion);
    qa.setFromAxisAngle(v, a.twist);
    chest.getWorldQuaternion(qb).premultiply(qa);
    parent.getWorldQuaternion(qc);
    chest.quaternion.copy(qc.invert().multiply(qb));
    chest.updateMatrixWorld(true);
  }

  private sprintMix(speed: number): number {
    return THREE.MathUtils.smoothstep(speed, this.speedJog, this.speedSprint);
  }

  private targetWeights(a: Rigged): Record<Clip, number> {
    const A = this.t.athlete;
    const w: Record<Clip, number> = { idle: 0, jog: 0, sprint: 0, crouch: 0, push: 0, fall: 0, kick: 0 };
    const moving = a.speed > A.movingMps;
    const run = () => {
      const s = this.sprintMix(a.speed);
      w.jog = 1 - s;
      w.sprint = s;
    };
    switch (a.action) {
      case 'down':
        w.fall = 1;
        break;
      case 'kick':
        w.kick = 1;
        break;
      case 'block':
        w.push = 1;
        break;
      case 'dive':
        run();
        break;
      case 'wrap':
        w.crouch = 0.6;
        w.jog = 0.4;
        break;
      case 'tackled':
        // The knees go as he is held.
        w.crouch = A.tackledCrouch;
        w.idle = (1 - A.tackledCrouch) / 2;
        w.jog = (1 - A.tackledCrouch) / 2;
        break;
      case 'tackling':
        // Bent at the hips, legs driving behind.
        w.crouch = A.tacklingCrouch;
        w.jog = 1 - A.tacklingCrouch;
        break;
      case 'stance':
        if (moving) run();
        else {
          w.crouch = A.stanceCrouch;
          w.idle = 1 - A.stanceCrouch;
        }
        break;
      case 'lineStance':
        if (moving) run();
        else w.crouch = 1;
        break;
      case 'qbReady':
        if (moving) run();
        else {
          w.crouch = A.qbCrouch;
          w.idle = 1 - A.qbCrouch;
        }
        break;
      case 'run':
      case 'carry':
        if (moving) run();
        else w.idle = 1;
        break;
      default:
        if (moving) run();
        else w.idle = 1;
    }
    return w;
  }

  private overlay(a: Rigged): Overlay {
    const A = this.t.athlete;
    const moving = a.speed > A.movingMps;
    switch (a.action) {
      case 'carry':
        return { left: null, right: TUCK };
      case 'down':
        return { left: null, right: TUCK };
      case 'qbReady':
        return moving ? NO_OVERLAY : { left: READY, right: READY };
      case 'lineStance':
        return moving ? NO_OVERLAY : { left: null, right: HAND_DOWN };
      case 'block':
        return { left: BLOCK, right: BLOCK };
      case 'catch':
        return { left: HANDS_UP, right: HANDS_UP };
      case 'reach':
        return { left: REACH, right: REACH };
      case 'dive':
        return { left: DIVE, right: DIVE };
      case 'wrap':
        return { left: WRAP, right: WRAP };
      case 'tackled':
        return { left: PRESENT, right: PRESENT };
      case 'tackling': {
        const arms = a.actionT < A.wrapCloseSeconds ? WRAP : WRAP_CLOSED;
        return { left: arms, right: arms };
      }
      case 'celebrate': {
        const d = danceAt(a.actionT, A.dance);
        return { left: DANCE_ARMS[d.left], right: DANCE_ARMS[d.right] };
      }
      case 'passL':
      case 'passR': {
        const tt = a.actionT;
        const p = tt < A.passLoadSeconds ? PASS_LOAD : tt < A.passSwingSeconds ? PASS_SWING : PASS_FOLLOW;
        return a.action === 'passL' ? { left: p.own, right: p.far } : { left: p.far, right: p.own };
      }
      case 'receive':
        return { left: RECEIVE, right: RECEIVE };
      case 'throw': {
        const tt = a.actionT;
        const right = tt < A.throwWindSeconds ? THROW_WIND : tt < A.throwReleaseSeconds ? THROW_RELEASE : THROW_FOLLOW;
        return { left: GUIDE_HAND, right };
      }
      default:
        return NO_OVERLAY;
    }
  }

  /** Turns the upper arm, then the forearm, toward body-space directions (side +1 left, -1 right). */
  private aimArm(up: THREE.Bone, lo: THREE.Bone, axisUp: THREE.Vector3, axisLo: THREE.Vector3, pose: ArmPose, side: number, w: number): void {
    const frame = pose.ground ? qHolder : qTorso;
    this.aimBone(up, axisUp, pose.up, side, w, frame);
    this.aimBone(lo, axisLo, pose.lo, side, w, frame);
  }

  private aimBone(bone: THREE.Bone, axis: THREE.Vector3, dir: THREE.Vector3, side: number, w: number, frame: THREE.Quaternion): void {
    const parent = bone.parent;
    if (!parent) return;
    v.set(dir.x * side, dir.y, dir.z).normalize().applyQuaternion(frame);
    bone.getWorldQuaternion(qa);
    v2.copy(axis).applyQuaternion(qa);
    qb.setFromUnitVectors(v2, v).multiply(qa);
    parent.getWorldQuaternion(qc);
    qb.premultiply(qc.invert());
    bone.quaternion.slerp(qb, w);
    bone.updateMatrixWorld(true);
  }

  private writeGear(i: number, a: Rigged | null): void {
    this.writeLogos(i, a);
    if (!a) {
      for (const mesh of Object.values(this.gear)) mesh.setMatrixAt(i, this.hidden);
      this.shadow.setMatrixAt(i, this.hidden);
      return;
    }
    for (const name of Object.keys(this.gear) as GearName[]) {
      if (name === 'numFront' && this.branded[i] && this.frontWord) {
        this.gear[name].setMatrixAt(i, this.hidden);
        continue;
      }
      const bone = a.bones[this.gearBone[name]];
      this.m.multiplyMatrices(bone.matrixWorld, this.gearLocal[name]);
      this.gear[name].setMatrixAt(i, this.m);
    }
    const s = a.action === 'down' || a.action === 'dive' || a.action === 'tackled' || a.action === 'tackling' ? this.t.athlete.shadowDownScale : 1;
    this.m.makeScale(s, 1, s).setPosition(a.x, this.t.athlete.shadowLiftM, a.z);
    this.shadow.setMatrixAt(i, this.m);
  }

  private writeLogos(i: number, a: Rigged | null): void {
    const next: Partial<Record<LogoKind, number>> = {};
    for (const slot of this.logoSlots) {
      const mesh = this.logoMeshes[slot.kind];
      if (!mesh) continue;
      const per = mesh.count / this.list.length;
      const k = next[slot.kind] ?? 0;
      next[slot.kind] = k + 1;
      if (!a || !this.branded[i]) mesh.setMatrixAt(i * per + k, this.hidden);
      else mesh.setMatrixAt(i * per + k, this.m.multiplyMatrices(a.bones[slot.bone].matrixWorld, slot.local));
    }
  }

  dispose(): void {
    for (const mesh of [...Object.values(this.gear), ...Object.values(this.logoMeshes), this.shadow]) {
      mesh.geometry.dispose();
      const mat = mesh.material as THREE.MeshLambertMaterial;
      mat.map?.dispose();
      mat.dispose();
    }
    for (const m of this.materials) m.dispose();
    for (const a of this.list) a.mixer.stopAllAction();
  }
}

/** Shoulder pads in metres, centred on the shoulder line: a raised cap over each shoulder on a chest and back shell. */
function padsGeo(): THREE.BufferGeometry {
  const cap = (side: number) => new THREE.SphereGeometry(0.13, 12, 8).scale(1.05, 0.7, 1.2).translate(side * 0.16, 0.01, 0).toNonIndexed();
  const shell = new THREE.SphereGeometry(0.17, 14, 8).scale(1.25, 0.7, 0.85).translate(0, 0, 0).toNonIndexed();
  return mergeGeometries([cap(1), cap(-1), shell])!;
}

/** A cleat in metres: a rounded block from heel to toe, sole on y 0, toe toward +z. */
function shoeGeo(t: Tunables): THREE.BufferGeometry {
  const [w, h, l] = t.athlete.gear.shoeSize as [number, number, number];
  return new THREE.CapsuleGeometry(w / 2, l - w, 4, 10).rotateX(Math.PI / 2).scale(1, h / w, 1).translate(0, h / 2, 0);
}

function armPose(aim: ArmAim): ArmPose {
  return setPose({ up: new THREE.Vector3(), lo: new THREE.Vector3(), ground: false }, aim);
}

function setPose(p: ArmPose, aim: ArmAim): ArmPose {
  p.up.fromArray(aim.up).normalize();
  p.lo.fromArray(aim.lo).normalize();
  p.ground = !!aim.ground;
  return p;
}

/** Moves an arm's aim part of the way (k) toward a new one; directions stay unit length. */
function easePose(p: ArmPose, aim: ArmAim, k: number): void {
  p.up.lerp(v.fromArray(aim.up).normalize(), k).normalize();
  p.lo.lerp(v.fromArray(aim.lo).normalize(), k).normalize();
  p.ground = !!aim.ground;
}

function armBones(b: Bones): [THREE.Bone, THREE.Bone, THREE.Bone, THREE.Bone] {
  return [b.upL, b.loL, b.upR, b.loR];
}

/** Width over height of a loaded image, 1 when it is missing or has no size. */
function imageAspect(img: HTMLImageElement | null): number {
  return img && img.naturalWidth && img.naturalHeight ? img.naturalWidth / img.naturalHeight : 1;
}

/** The logo artwork as a white texture (tinted per kit by the instance colour), at a fixed height in pixels. */
function logoTexture(img: HTMLImageElement, t: Tunables): THREE.CanvasTexture {
  const h = t.athlete.gear.logos.texturePx;
  const w = Math.max(1, Math.round(imageAspect(img) * h));
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d');
  if (!ctx) throw new Error('2D canvas not available');
  ctx.drawImage(img, 0, 0, w, h);
  ctx.globalCompositeOperation = 'source-in';
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = t.render.anisotropy;
  return tex;
}

function findBones(root: THREE.Object3D): Bones {
  const get = (name: string): THREE.Bone => {
    const o = root.getObjectByName(name);
    if (!o || !(o as THREE.Bone).isBone) throw new Error(`athlete model has no ${name} bone`);
    return o as THREE.Bone;
  };
  return {
    head: get('Head'),
    chest: get('spine_03'),
    footL: get('foot_l'),
    footR: get('foot_r'),
    upL: get('upperarm_l'),
    loL: get('lowerarm_l'),
    handL: get('hand_l'),
    palmL: get('middle_01_l'),
    upR: get('upperarm_r'),
    loR: get('lowerarm_r'),
    handR: get('hand_r'),
    palmR: get('middle_01_r'),
  };
}

function findBody(root: THREE.Object3D): THREE.SkinnedMesh {
  let body: THREE.SkinnedMesh | null = null;
  root.traverse((o) => {
    if (!body && (o as THREE.SkinnedMesh).isSkinnedMesh) body = o as THREE.SkinnedMesh;
  });
  if (!body) throw new Error('athlete model has no skinned mesh');
  return body;
}

/**
 * Kit seams as cuts through the bind pose (T-pose), in the mesh's own coordinates: sleeves and gloves by
 * distance from the spine along the arms, collar, waist, knee and sock line by height. Straight seams,
 * whatever the triangles.
 */
function kitCuts(body: THREE.SkinnedMesh, t: Tunables): { a: THREE.Vector4; b: THREE.Vector4 } {
  const c = t.athlete.kitCuts;
  const bones = body.skeleton.bones;
  const at = (name: string): THREE.Vector3 => {
    const j = bones.findIndex((b) => b.name === name);
    if (j < 0) throw new Error(`athlete model has no ${name} bone`);
    return new THREE.Vector3()
      .setFromMatrixPosition(body.skeleton.boneInverses[j]!.clone().invert())
      .applyMatrix4(body.bindMatrixInverse);
  };
  const lerp = (p: string, q: string, f: number) => at(p).lerp(at(q), f);
  const cx = at('pelvis').x;
  return {
    a: new THREE.Vector4(
      cx,
      Math.abs(lerp('upperarm_l', 'lowerarm_l', c.sleeve).x - cx),
      Math.abs(lerp('lowerarm_l', 'hand_l', c.glove).x - cx),
      lerp('spine_03', 'neck_01', c.collar).y,
    ),
    b: new THREE.Vector4(lerp('pelvis', 'spine_01', c.waist).y, lerp('calf_l', 'foot_l', c.knee).y, lerp('calf_l', 'foot_l', c.sock).y, lerp('thigh_l', 'calf_l', c.shorts).y),
  };
}

/** What tools/athlete-hd.mjs measured on the HD texture (linear colours). */
interface HdExtras {
  skinAverage: number[];
  /** Accent and grey: average colours. Parts: average brightness of the dark texels on helmet, glove, jersey, pants, socks, cleat. */
  kitAverage: { accent: number[]; grey: number[]; parts: number[] };
}

/**
 * The HD body's parts in its bind space, from its joints (as kitCuts does): above the neck is helmet, past the
 * wrists gloves, then jersey down to the hips, pants to the knees, socks to the ankles, cleats below. The build
 * (tools/athlete-hd.mjs) splits the body the same way.
 */
function hdBands(body: THREE.SkinnedMesh, t: Tunables, collarUp?: number): HdCuts {
  const bones = body.skeleton.bones;
  const idx = (name: string): number => {
    const j = bones.findIndex((b) => b.name === name);
    if (j < 0) throw new Error(`athlete model has no ${name} bone`);
    return j;
  };
  const at = (name: string): THREE.Vector3 =>
    new THREE.Vector3().setFromMatrixPosition(body.skeleton.boneInverses[idx(name)]!.clone().invert()).applyMatrix4(body.bindMatrixInverse);
  const cx = at('pelvis').x;
  const J = t.athlete.hd.jersey;
  // Bone chains with how far along the limb each bone starts, so a vertex gets one smooth "metres from the
  // shoulder" (or hip) value however it is weighted between the bones.
  const chain = (names: string[]) => {
    const pts = names.map(at);
    const out: { j: number; from: THREE.Vector3; dir: THREE.Vector3; start: number; len: number }[] = [];
    let start = 0;
    names.forEach((n, k) => {
      const from = pts[k]!;
      const to = pts[k + 1] ?? pts[k]!.clone().add(pts[k]!.clone().sub(pts[k - 1]!));
      const len = from.distanceTo(to);
      out.push({ j: idx(n), from, dir: to.clone().sub(from).normalize(), start, len });
      start += len;
    });
    return out;
  };
  const arms = [chain(['upperarm_l', 'lowerarm_l', 'hand_l']), chain(['upperarm_r', 'lowerarm_r', 'hand_r'])];
  const legs = [chain(['thigh_l', 'calf_l', 'foot_l', 'ball_l']), chain(['thigh_r', 'calf_r', 'foot_r', 'ball_r'])];
  const g = body.geometry;
  const pos = g.getAttribute('position');
  const si = g.getAttribute('skinIndex');
  const sw = g.getAttribute('skinWeight');
  const kit = new Float32Array(pos.count * 2);
  const p = new THREE.Vector3();
  const along = (ch: ReturnType<typeof chain>[], i: number): number => {
    // Weighted metres along whichever limb this vertex hangs on; off the limb it reads OFF (negative).
    let w = 0;
    let v = 0;
    for (const c of ch) {
      for (const b of c) {
        for (let k = 0; k < 4; k++) {
          if (si.getComponent(i, k) !== b.j) continue;
          const wk = sw.getComponent(i, k);
          w += wk;
          v += wk * (b.start + Math.max(0, p.clone().sub(b.from).dot(b.dir)));
        }
      }
    }
    return v + (1 - w) * J.offLimb;
  };
  for (let i = 0; i < pos.count; i++) {
    p.fromBufferAttribute(pos, i);
    kit[i * 2] = along(arms, i);
    kit[i * 2 + 1] = along(legs, i);
  }
  g.setAttribute('aKit', new THREE.BufferAttribute(kit, 2));
  const upArm = arms[0]![0]!.len;
  const thigh = legs[0]![0]!.len;
  const calf = legs[0]![1]!.len;
  const neck = at('neck_01');
  const neckLen = neck.distanceTo(at('Head'));
  const pelvis = at('pelvis');
  const torso = neck.y - pelvis.y;
  const shoulder = at('upperarm_l');
  const thigh0 = at('thigh_l');
  return {
    design: new THREE.Vector4(cx, at('spine_03').z, Math.abs(shoulder.x - cx), shoulder.y - upArm * J.raglanDrop),
    chevron: new THREE.Vector3(pelvis.y + torso * J.chevronAt, J.chevronSlope, torso * J.chevronWidth),
    hip: new THREE.Vector3(Math.abs(thigh0.x - cx), thigh0.z, J.stripeAngle),
    bands: new THREE.Vector4(neck.y, at('pelvis').y, at('calf_l').y, at('foot_l').y),
    wrist: Math.abs(at('lowerarm_l').lerp(at('hand_l'), t.athlete.hd.gloveAt).x - cx),
    collar: neck.y + neckLen * (collarUp ?? J.collarUp),
    collarBand: neckLen * J.collarBand,
    sleeve: upArm * J.sleeve,
    cuff: upArm * J.cuff,
    hem: at('pelvis').lerp(at('spine_01'), J.hemAt).y,
    shorts: thigh * J.shorts,
    sockTop: thigh + calf * J.sockTop,
    sockBand: calf * J.sockBand,
    boot: thigh + calf * J.boot,
  };
}

/** Where the HD kit's seams fall: heights in bind space, and metres along the arm (from the shoulder) and leg (from the hip). */
interface HdCuts {
  /** x: body centre, y: spine depth (front is +z), z: half shoulder width, w: armpit height (raglan seams). */
  design: THREE.Vector4;
  /** Chest chevron: centre height, rise per metre out, width. */
  chevron: THREE.Vector3;
  /** Shorts side stripes: hip joint half width and depth, how wide the stripe reads (dz / dx). */
  hip: THREE.Vector3;
  bands: THREE.Vector4;
  wrist: number;
  collar: number;
  collarBand: number;
  sleeve: number;
  cuff: number;
  hem: number;
  shorts: number;
  sockTop: number;
  sockBand: number;
  boot: number;
}

/**
 * The HD athlete's kit, repainted per team from its own texture. Each texel is sorted into accent trim, skin,
 * grey (the facemask) or dark (the kit), the same test the build used (tunables athlete.hd.classify). Skin
 * is retinted to the athlete's tone; kit texels take the team colour for that part of the body, keeping the
 * texture's shading relative to that kind's average brightness.
 */
function hdKitMaterial(
  textures: Pick<AthleteModel, 'skin' | 'normal'>,
  kit: THREE.Color[],
  _u: SquadSpec['uniform'],
  x: HdExtras,
  cuts: HdCuts,
  t: Tunables,
  trim: THREE.Color,
  kitStyle: { panel: THREE.Color; sockHoop: THREE.Color; hoops: boolean; trimShade: number },
): THREE.MeshStandardMaterial {
  const H = t.athlete.hd;
  const c = H.classify;
  const lift = (hex: string) => liftDark(new THREE.Color(hex), t.look.blackLift);
  // Physically based, so skin and fabric catch the floodlights and the stadium's soft reflections differently
  // (skin a little sheen, the kit matte), as broadcast-style sports games look; Lambert read flat and plastic.
  const mat = new THREE.MeshStandardMaterial({ map: textures.skin, normalMap: textures.normal, metalness: 0, roughness: H.material.kitRoughness, envMapIntensity: H.material.envIntensity });
  mat.normalScale.set(1, -1);
  const lum = (a: number[]) => 0.2126 * a[0]! + 0.7152 * a[1]! + 0.0722 * a[2]!;
  mat.onBeforeCompile = (shader) => {
    rimShader(shader, t);
    const uniforms: Record<string, unknown> = {
      uSkin: kit[0],
      uSkinAvg: new THREE.Vector3().fromArray(x.skinAverage),
      // Rugby: no helmet, so the head band is hair (dark texels) and skin; pale texels there are skin too.
      uHelmet: lift(t.look.hair),
      uMask: kit[0],
      uJersey: kit[1],
      uPants: kit[2],
      uSocks: kit[3],
      uStripe: kit[4],
      uCleat: kit[5],
      uLum: new THREE.Vector2(lum(x.kitAverage.accent), lum(x.kitAverage.grey)),
      uPartLum: x.kitAverage.parts,
      uBands: cuts.bands,
      uWrist: cuts.wrist,
      uShadeMax: H.shadeMax,
      uAccent: new THREE.Vector3(c.accentMin, c.accentGreenOverRed, c.accentBlueOverGreen),
      uSkinTest: new THREE.Vector4(c.skinMin, c.skinBlueOverGreen, c.skinSaturationMin, 0),
      uGrey: new THREE.Vector2(c.greyMin, c.greySaturationMax),
      uTrim: trim,
      // The band at the top of the socks: the jersey colour, so it shows on socks in the trim colour.
      uSockHoop: kitStyle.sockHoop,
      uHoops: kitStyle.hoops ? 1 : 0,
      uPanelCol: kitStyle.panel,
      uTrimShade: kitStyle.trimShade,
      uRaglanCurve: H.jersey.raglanCurve,
      uDesign: cuts.design,
      uChevron: cuts.chevron,
      uHip: cuts.hip,
      uShadeRange: new THREE.Vector3(H.jersey.shadeMin, H.jersey.shadeMax, H.jersey.shadeMix),
      uCollar: cuts.collar,
      uCollarBand: cuts.collarBand,
      uCollarShade: H.jersey.collarShade,
      uSleeve: cuts.sleeve,
      uCuff: cuts.cuff,
      uHem: cuts.hem,
      uShorts: cuts.shorts,
      uSockTop: cuts.sockTop,
      uSockBand: cuts.sockBand,
      uBoot: cuts.boot,
    };
    for (const [k, value] of Object.entries(uniforms)) shader.uniforms[k] = { value };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vBind;\nattribute vec2 aKit;\nvarying vec2 vKit;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvBind = position;\nvKit = aKit;');
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        varying vec3 vBind;
        uniform vec3 uSkin, uSkinAvg, uHelmet, uMask, uJersey, uPants, uSocks, uStripe, uCleat, uAccent, uSkinTest;
        uniform vec4 uBands;
        uniform vec2 uGrey, uLum;
        uniform float uPartLum[6];
        uniform float uWrist, uShadeMax;
        uniform vec3 uTrim, uShadeRange, uSockHoop, uPanelCol, uChevron, uHip;
        uniform vec4 uDesign;
        uniform float uHoops, uTrimShade, uRaglanCurve, uCollarShade;
        uniform float uCollar, uCollarBand, uSleeve, uCuff, uHem, uShorts, uSockTop, uSockBand, uBoot;
        varying vec2 vKit;
        float kitLum(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }`,
      )
      .replace(
        '#include <map_fragment>',
        `// A real rugby kit, cut by the body not by the texture (the generated model's own shirt sits low and
        // loose): jersey from the hips to a collar round the base of the neck, short sleeves with a cuff, shorts
        // to mid-thigh, bare knees, socks with a band at the top, boots. Seams are measured along each limb from
        // the bone weights (vKit: metres from the shoulder, metres from the hip), so they wrap the arm and leg
        // whatever the rest pose. The texture only lends its shading. Head and hands keep their skin and hair.
        float armAt = vKit.x;
        float legAt = vKit.y;
        float y = vBind.y;
        int kitPart; // 0 head, 1 skin, 2 jersey, 3 shorts, 4 socks, 5 boot, 6 trim (collar, cuffs, sock band)
        if (legAt > 0.0) {
          kitPart = legAt < uShorts ? 3 : legAt < uSockTop ? 1 : legAt < uSockTop + uSockBand ? 7 : legAt < uBoot ? 4 : 5;
          if (legAt < uShorts && y > uHem) kitPart = 2;
        } else if (armAt > 0.0) {
          kitPart = armAt < uSleeve - uCuff ? 2 : armAt < uSleeve ? 6 : 1;
        } else if (y > uCollar) kitPart = 0;
        else if (y > uCollar - uCollarBand) kitPart = 6;
        else kitPart = y > uHem ? 2 : 3;
        // The kit's design (reference/11 and 13): raglan shoulders and sleeves in the panel colour, a chevron
        // across the chest, stripes down the side of the shorts. Invisible on a one-colour kit (panels = jersey).
        #ifdef USE_MAP
          // A beard or hair hanging to the collar stays hair: the generated shirt is white, so a dark texel by the
          // collar is never kit.
          vec3 texC = texture2D(map, vMapUv).rgb;
          if (armAt <= 0.0 && legAt <= 0.0 && y > uCollar - uCollarBand * 3.0 && max(texC.r, max(texC.g, texC.b)) < uGrey.x) kitPart = 0;
        #endif
        float sideX = abs(vBind.x - uDesign.x);
        if (kitPart == 2 && armAt > 0.0) kitPart = 8;
        if (kitPart == 2 && armAt <= 0.0) {
          // The raglan seam: from the collar near the neck, curving down to the armpit at the shoulder.
          float k = pow(clamp(sideX / uDesign.z, 0.0, 1.0), uRaglanCurve);
          if (y > mix(uCollar, uDesign.w, k)) kitPart = 8;
          float chev = uChevron.x + uChevron.y * sideX;
          if (vBind.z > uDesign.y && abs(y - chev) < uChevron.z) kitPart = 8;
        }
        if (kitPart == 3) {
          float dx = sideX - uHip.x;
          if (dx > 0.0 && abs(vBind.z - uHip.y) < dx * uHip.z) kitPart = 8;
        }
        // Cuffs and collar: the jersey colour on a panelled kit, a shade darker on a plain one.
        bool isCuff = kitPart == 6 && armAt > 0.0;
        vec3 part = kitPart == 2 ? uJersey : kitPart == 3 ? uPants : kitPart == 4 ? uSocks : kitPart == 5 ? uCleat : kitPart == 7 ? uSockHoop : kitPart == 8 ? uPanelCol : isCuff ? uJersey * uTrimShade : (y > uCollar - uCollarBand * 0.22 ? uPanelCol : uJersey * uTrimShade);
        // Plain socks (socks = jersey) get two thin hoops in the band instead of one solid band.
        if (kitPart == 7 && uHoops > 0.5 && fract((legAt - uSockTop) / uSockBand * 2.5) < 0.5) part = uSocks;
        #ifdef USE_MAP
          vec3 tex = texture2D(map, vMapUv).rgb;
          float mx = max(tex.r, max(tex.g, tex.b));
          float sat = mx > 0.0 ? (mx - min(tex.r, min(tex.g, tex.b))) / mx : 0.0;
          bool skinTex = mx > uSkinTest.x && tex.r > tex.g && tex.g > tex.b && tex.b > tex.g * uSkinTest.y && sat > uSkinTest.z;
          bool paleTex = mx > uGrey.x && sat < uGrey.y;
          // Shading relative to what kind of texel this is, eased toward flat so seams of the old shirt vanish.
          float ref = skinTex ? kitLum(uSkinAvg) : paleTex ? uLum.y : uPartLum[2];
          float shade = mix(1.0, clamp(kitLum(tex) / max(ref, 1e-3), uShadeRange.x, uShadeRange.y), uShadeRange.z);
          vec3 kitCol;
          if (kitPart == 0) kitCol = skinTex ? uSkin * tex / uSkinAvg : paleTex ? uSkin * shade : uHelmet * min(kitLum(tex) / uPartLum[0], uShadeMax);
          else if (kitPart == 1) kitCol = skinTex ? uSkin * tex / uSkinAvg : uSkin * shade;
          // The collar is painted up over the neck: it takes no shading from the skin under it (a chain, stubble
          // and neck folds would show through and read as see-through cloth).
          else if (kitPart == 6 && !isCuff) kitCol = part * uCollarShade;
          else kitCol = part * shade;
        #else
          vec3 kitCol = kitPart <= 1 ? uSkin : part;
        #endif
        diffuseColor.rgb *= kitCol;`,
      )
      .replace(
        '#include <roughnessmap_fragment>',
        `#include <roughnessmap_fragment>
        roughnessFactor = kitPart <= 1 ? uSkinRough : roughnessFactor;`,
      );
    shader.uniforms['uSkinRough'] = { value: H.material.skinRoughness };
    shader.fragmentShader = shader.fragmentShader.replace('#include <common>', '#include <common>\nuniform float uSkinRough;');
    realismShader(shader, t);
  };
  return mat;
}

/**
 * Realism for the HD athletes (Jonny, 16 Nov: "make it realistic"), all cheap enough for 14 players on a phone:
 * - cloth: a soft sheen at grazing angles, the way knit fabric catches light (plain diffuse reads as plastic);
 * - ground occlusion: legs darken toward the boots, as grass and the body itself shut out the sky;
 * - skin: light scattering through it, a warm red where it turns from the sun (skin without it looks waxy).
 * Needs the kitPart and vBind of hdKitMaterial. Numbers in tunables athlete.hd.realism.
 */
function realismShader(shader: THREE.WebGLProgramParametersWithUniforms, t: Tunables): void {
  const R = t.athlete.hd.realism;
  shader.uniforms['uSheen'] = { value: new THREE.Vector2(R.fabricSheen, R.fabricSheenPower) };
  shader.uniforms['uSheenCol'] = { value: new THREE.Color(R.fabricSheenColor) };
  shader.uniforms['uOcclusion'] = { value: new THREE.Vector2(R.groundOcclusion, R.occlusionTopShare) };
  shader.uniforms['uScatter'] = { value: new THREE.Vector2(R.skinScatter, R.skinScatterWrap) };
  shader.uniforms['uScatterCol'] = { value: new THREE.Color(R.skinScatterColor) };
  shader.uniforms['uSunDir'] = { value: new THREE.Vector3().fromArray(t.look.keyLightPosition).normalize() };
  shader.uniforms['uFolds'] = { value: new THREE.Vector4(R.folds, R.foldScale, R.waistBunch, R.sleeveRings) };
  shader.uniforms['uShortsFolds'] = { value: R.shortsFolds };
  shader.fragmentShader = shader.fragmentShader
    .replace(
      '#include <common>',
      `#include <common>
      uniform vec2 uSheen, uOcclusion, uScatter;
      uniform vec3 uSheenCol, uScatterCol, uSunDir;
      uniform vec4 uFolds;
      uniform float uShortsFolds;
      float foldHash(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }
      float foldNoise(vec3 p) {
        vec3 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(mix(foldHash(i), foldHash(i + vec3(1, 0, 0)), f.x), mix(foldHash(i + vec3(0, 1, 0)), foldHash(i + vec3(1, 1, 0)), f.x), f.y),
                   mix(mix(foldHash(i + vec3(0, 0, 1)), foldHash(i + vec3(1, 0, 1)), f.x), mix(foldHash(i + vec3(0, 1, 1)), foldHash(i + vec3(1, 1, 1)), f.x), f.y), f.z);
      }`,
    )
    .replace(
      '#include <normal_fragment_maps>',
      `#include <normal_fragment_maps>
      // Cloth folds, as a bump on the kit only, in the body's own space so they move with it: soft creases over
      // the torso (stretched sideways, like a shirt pulled across the chest), bunching at the waist, rings round
      // the sleeves and long folds down the shorts.
      if (kitPart >= 2 && kitPart != 5) {
        vec3 q = vBind * uFolds.y;
        float h;
        if (armAt > 0.0) h = 0.5 + 0.5 * sin(armAt * uFolds.w + foldNoise(q * 1.7) * 4.0);
        else if (kitPart == 3 || (kitPart == 8 && legAt > 0.0)) h = 0.5 + 0.5 * sin(vBind.x * uShortsFolds + foldNoise(q * vec3(1.0, 0.3, 1.0)) * 5.0);
        else {
          h = foldNoise(q * vec3(0.6, 1.6, 0.6)) * 0.65 + foldNoise(q * vec3(1.4, 3.2, 1.4)) * 0.35;
          float waist = 1.0 - smoothstep(0.0, uCollar * 0.12, abs(y - uHem - uCollar * 0.05));
          h *= 1.0 + uFolds.z * waist;
        }
        // Fold depth in metres (uFolds.x); the standard screen-space bump (three's perturbNormalArb).
        vec2 dH = vec2(dFdx(h), dFdy(h)) * uFolds.x;
        vec3 sx = dFdx(-vViewPosition), sy = dFdy(-vViewPosition);
        vec3 r1 = cross(sy, normal), r2 = cross(normal, sx);
        float det = dot(sx, r1) * faceDirection;
        vec3 grad = sign(det) * (dH.x * r1 + dH.y * r2);
        normal = normalize(abs(det) * normal - grad);
      }`,
    )
    .replace(
      '#include <opaque_fragment>',
      `{
        vec3 viewDir = normalize(vViewPosition);
        float facing = saturate(dot(normal, viewDir));
        // Height up the body, 0 at the ankle joint to 1 at the collar.
        float up = saturate((vBind.y - uBands.w) / max(uCollar - uBands.w, 1e-3));
        float occ = mix(1.0 - uOcclusion.x, 1.0, smoothstep(0.0, uOcclusion.y, up));
        outgoingLight *= occ;
        if (kitPart >= 2 && kitPart != 5) {
          outgoingLight += uSheenCol * uSheen.x * pow(1.0 - facing, uSheen.y) * diffuseColor.rgb * occ;
        } else if (kitPart <= 1) {
          vec3 sun = normalize((viewMatrix * vec4(uSunDir, 0.0)).xyz);
          float ndl = dot(normal, sun);
          float wrap = saturate((ndl + uScatter.y) / (1.0 + uScatter.y)) - saturate(ndl);
          outgoingLight += uScatterCol * diffuseColor.rgb * wrap * uScatter.x;
        }
      }
      #include <opaque_fragment>`,
    );
}

/**
 * The body material: the skin texture retinted to the player's skin tone, flat kit colours elsewhere
 * (the muscle normal map is mostly flattened on cloth), plus the stadium rim light. Without the textures
 * (they failed to load) it still compiles: flat skin tones, no muscle relief.
 */
function kitMaterial(
  textures: Pick<AthleteModel, 'skin' | 'normal'>,
  kit: THREE.Color[],
  skinAverage: THREE.Vector3,
  cuts: { a: THREE.Vector4; b: THREE.Vector4 },
  t: Tunables,
): THREE.MeshLambertMaterial {
  const A = t.athlete;
  // Lambert, like the rest of the athletes: matte kits that stay black at night, and cheaper on phones.
  const mat = new THREE.MeshLambertMaterial({ map: textures.skin, normalMap: textures.normal });
  // A glTF normal map on a model without tangents needs y flipped in three (as GLTFLoader does), or the muscles light from below.
  mat.normalScale.set(1, -1);
  mat.onBeforeCompile = (shader) => {
    rimShader(shader, t);
    shader.uniforms['uKit'] = { value: kit };
    shader.uniforms['uSkinAvg'] = { value: skinAverage };
    shader.uniforms['uKitFlatten'] = { value: A.kitNormalFlatten };
    shader.uniforms['uCutA'] = { value: cuts.a };
    shader.uniforms['uCutB'] = { value: cuts.b };
    shader.uniforms['uPanel'] = { value: cuts.a.y * A.kitCuts.panel };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vBind;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvBind = position;');
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>\nvarying vec3 vBind;\nuniform vec3 uKit[${KIT_REGIONS}];\nuniform vec3 uSkinAvg;\nuniform float uKitFlatten;\nuniform vec4 uCutA;\nuniform vec4 uCutB;\nuniform float uPanel;`,
      )
      .replace(
        '#include <map_fragment>',
        `// 0 skin, 1 jersey, 4 shoulder panels and sleeves, 2 shorts, 0 bare knee, 3 socks, 5 boot. No gloves in rugby: that cut sits past the hand.
        float kitArm = abs(vBind.x - uCutA.x);
        int kitRegion = 5;
        if (kitArm > uCutA.z) kitRegion = 4;
        else if (kitArm > uCutA.y || vBind.y > uCutA.w) kitRegion = 0;
        else if (vBind.y > uCutB.x) kitRegion = kitArm > uPanel ? 4 : 1;
        else if (vBind.y > uCutB.w) kitRegion = 2;
        else if (vBind.y > uCutB.y) kitRegion = 0;
        else if (vBind.y > uCutB.z) kitRegion = 3;
        #ifdef USE_MAP
          vec3 kitSkin = uKit[0] * texture2D(map, vMapUv).rgb / uSkinAvg;
        #else
          vec3 kitSkin = uKit[0];
        #endif
        diffuseColor.rgb *= kitRegion == 0 ? kitSkin : uKit[kitRegion];`,
      )
      .replace(
        '#include <normal_fragment_maps>',
        '#include <normal_fragment_maps>\nif (kitRegion > 0) normal = normalize(mix(normal, nonPerturbedNormal, uKitFlatten));',
      );
  };
  return mat;
}
