import * as THREE from 'three';
import type { Brand } from '../brand/types';
import { Rng } from '../sim/rng';
import type { Tunables } from '../sim/tunables';

/** Where one front-row seat is: world position and the way it faces (toward the pitch). */
export interface Seat {
  x: number;
  y: number;
  z: number;
  /** Rotation about y so the fan's +z faces the pitch. */
  rotY: number;
}

/** Short crowd reactions on top of the mood (GDD audio and presentation: the crowd tied to play). */
export type CrowdReaction = 'homeJoy' | 'awayJoy' | 'groan' | 'applause';

export interface CrowdFans {
  mesh: THREE.InstancedMesh;
  /** 0 seated to 1 on their feet, from the crowd mood. */
  setCheer(level: number): void;
  react(kind: CrowdReaction): void;
  update(dt: number): void;
}

// Body part ids, read by the vertex shader to pose each fan.
const LEGS = 0;
const BODY = 1;
const HEAD = 2;
const ARM_L = 3;
const ARM_R = 4;
const FLAG = 5;

/**
 * The front rows as 3D fans (one instanced mesh, about 60 triangles each), so the nearest supporters have depth
 * and move: they rise as play builds, jump and wave flags on a try, put their hands on their heads at a miss
 * and clap a kick. Home fans wear the brand colours (blocks of them), away fans the away kit, the rest plain
 * clothes; the painted stand behind carries the rows further back.
 */
export function createCrowdFans(brand: Brand, awayShirt: string, t: Tunables, seats: Seat[]): CrowdFans {
  const c = t.crowd3d;
  const geo = fanGeometry(c);
  const rng = new Rng(c.seed);
  const n = seats.length;
  const shirt = new Float32Array(n * 3);
  const skin = new Float32Array(n * 3);
  const info = new Float32Array(n * 4); // hash, home (1) / away (0) / neutral (0.5), flag, seat side
  const tmp = new THREE.Color();
  const homeCols = [brand.colors.primary, brand.colors.primary, brand.colors.text, brand.colors.accent];
  const plain = t.look.crowdClothes;
  const tones = t.look.skinTones;
  const mesh = new THREE.InstancedMesh(geo, undefined as unknown as THREE.Material, n);
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const up = new THREE.Vector3(0, 1, 0);
  const one = new THREE.Vector3(1, 1, 1);
  // Supporters sit in blocks along each stand.
  const block = (s: Seat) => Math.floor((s.x + s.z) / c.blockM);
  const blockKind = new Map<number, number>();
  for (let i = 0; i < n; i++) {
    const s = seats[i]!;
    const b = block(s);
    if (!blockKind.has(b)) {
      const r = rng.next();
      blockKind.set(b, r < c.awayBlockShare ? 0 : r < c.awayBlockShare + c.homeBlockShare ? 1 : 0.5);
    }
    const kind = blockKind.get(b)!;
    const loyal = rng.next() < c.blockLoyalty;
    const side = loyal ? kind : 0.5;
    const col = side === 1 ? homeCols[rng.int(0, homeCols.length - 1)]! : side === 0 ? (rng.next() < 0.75 ? awayShirt : '#f2f2f2') : plain[rng.int(0, plain.length - 1)]!;
    tmp.set(col);
    shirt.set([tmp.r, tmp.g, tmp.b], i * 3);
    tmp.set(tones[rng.int(0, tones.length - 1)]!);
    skin.set([tmp.r, tmp.g, tmp.b], i * 3);
    info.set([rng.next(), side, side !== 0.5 && rng.next() < c.flagShare ? 1 : 0, 0], i * 4);
    const scale = c.heightMin + rng.next() * (c.heightMax - c.heightMin);
    q.setFromAxisAngle(up, s.rotY + rng.range(-c.turnRad, c.turnRad));
    m.compose(new THREE.Vector3(s.x, s.y, s.z), q, one.clone().multiplyScalar(scale));
    mesh.setMatrixAt(i, m);
  }
  geo.setAttribute('aShirt', new THREE.InstancedBufferAttribute(shirt, 3));
  geo.setAttribute('aSkin', new THREE.InstancedBufferAttribute(skin, 3));
  geo.setAttribute('aInfo', new THREE.InstancedBufferAttribute(info, 4));

  const flag = new THREE.Color(brand.colors.accent);
  const awayFlag = new THREE.Color(awayShirt);
  const legs = new THREE.Color(c.legsColor);
  const uniforms = {
    uTime: { value: 0 },
    uCheer: { value: 0 },
    uHomeJoy: { value: 0 },
    uAwayJoy: { value: 0 },
    uGroan: { value: 0 },
    uClap: { value: 0 },
  };
  const g = (v: number) => v.toFixed(4);
  const mat = new THREE.MeshLambertMaterial();
  mat.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, uniforms, {
      uFlag: { value: flag },
      uAwayFlag: { value: awayFlag },
      uLegs: { value: legs },
    });
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <common>',
        `#include <common>
        attribute float part;
        attribute vec3 aShirt;
        attribute vec3 aSkin;
        attribute vec4 aInfo;
        uniform float uTime, uCheer, uHomeJoy, uAwayJoy, uGroan, uClap;
        varying vec3 vFanColor;
        varying float vPart;
        varying float vHome;
        vec3 rotX(vec3 p, vec3 pivot, float a) {
          vec3 d = p - pivot;
          float c = cos(a), s = sin(a);
          return pivot + vec3(d.x, d.y * c - d.z * s, d.y * s + d.z * c);
        }`,
      )
      .replace(
        '#include <begin_vertex>',
        `vec3 transformed = position;
        float h = aInfo.x;
        float home = aInfo.y;
        vHome = home;
        vPart = part;
        vFanColor = part < 0.5 ? vec3(0.0) : part < 1.5 ? aShirt : part < 2.5 ? aSkin : part < 4.5 ? aShirt : vec3(0.0);
        // Who is happy, who is not: a home try lifts home fans and sinks away fans, and the reverse.
        float joy = home > 0.75 ? uHomeJoy : home < 0.25 ? uAwayJoy : max(uHomeJoy, uAwayJoy) * 0.5;
        float gloom = (home > 0.75 ? uAwayJoy : home < 0.25 ? uHomeJoy : 0.0) + uGroan * (home < 0.25 ? 0.3 : 1.0);
        gloom = clamp(gloom, 0.0, 1.0);
        // Stand up fan by fan as the mood rises; everyone up for joy or a groan.
        float stand = clamp((uCheer * ${g(c.cheerStandShare)} + ${g(c.baseStandShare)} - h) * 8.0, 0.0, 1.0);
        stand = max(stand, max(joy, gloom * 0.8));
        float lift = stand * ${g(c.standLiftM)};
        float jump = joy * abs(sin(uTime * ${g(c.jumpHz * Math.PI)} + h * 6.2832)) * ${g(c.jumpM)};
        float sway = sin(uTime * ${g(c.swayHz * 2 * Math.PI)} + h * 6.2832) * ${g(c.swayRad)} * (0.3 + uCheer);
        if (part > 0.5) transformed.y += lift + jump;
        else transformed.y += jump;
        // Arms: up with the cheer (each on his own beat), high and waving for joy, on the head for a groan,
        // forward and together for a clap.
        float armsUp = max(stand * clamp(uCheer * 1.6 - 0.4 + (h - 0.5) * 0.6, 0.0, 1.0), joy) * (1.0 - gloom);
        float wave = sin(uTime * ${g(c.waveHz * 2 * Math.PI)} + h * 9.0) * 0.35 * armsUp;
        float clap = uClap * (1.0 - joy) * (1.0 - gloom);
        float clapBeat = abs(sin(uTime * ${g(c.clapHz * Math.PI)} + h * 3.0));
        vec3 shoulder = vec3(0.0, ${g(c.shoulderM)} + lift + jump, 0.0);
        if (part > 2.5 && part < 5.5) {
          float a = armsUp * 2.8 + wave + gloom * 2.5 + clap * 1.3;
          transformed = rotX(transformed, shoulder, -a);
          float side = part < 3.5 ? 1.0 : -1.0;
          // Hands meet over the head (groan) or in front (clap).
          transformed.x -= side * (gloom * 0.12 + clap * clapBeat * 0.14) * clamp((transformed.y - shoulder.y + 0.1) * 3.0, 0.0, 1.0);
        }
        if (part > 0.5) transformed.x += (transformed.y - ${g(c.hipM)}) * sway;
        // The flag: only flag holders, and only once their arms are up.
        if (part > 4.5) {
          float show = aInfo.z * step(0.4, armsUp);
          transformed *= show;
          vFanColor = home > 0.75 ? vec3(-1.0) : vec3(-2.0);
        }`,
      );
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>
        uniform vec3 uFlag, uAwayFlag, uLegs;
        varying vec3 vFanColor;
        varying float vPart;
        varying float vHome;`,
      )
      .replace(
        '#include <color_fragment>',
        `#include <color_fragment>
        diffuseColor.rgb = vPart < 0.5 ? uLegs : vFanColor.x < -1.5 ? uAwayFlag : vFanColor.x < -0.5 ? uFlag : vFanColor;`,
      );
  };
  mesh.material = mat;
  mesh.frustumCulled = false;
  mesh.castShadow = false;
  mesh.receiveShadow = false;

  let cheer = 0;
  let cheerTarget = 0;
  return {
    mesh,
    setCheer(level) {
      cheerTarget = Math.max(0, Math.min(1, level));
    },
    react(kind) {
      if (kind === 'homeJoy') uniforms.uHomeJoy.value = 1;
      else if (kind === 'awayJoy') uniforms.uAwayJoy.value = 1;
      else if (kind === 'groan') uniforms.uGroan.value = 1;
      else uniforms.uClap.value = 1;
    },
    update(dt) {
      uniforms.uTime.value += dt;
      cheer += (cheerTarget - cheer) * (1 - Math.exp(-c.ease * dt));
      uniforms.uCheer.value = cheer;
      const fade = (u: { value: number }, secs: number) => (u.value = Math.max(0, u.value - dt / secs));
      fade(uniforms.uHomeJoy, c.joySeconds);
      fade(uniforms.uAwayJoy, c.joySeconds);
      fade(uniforms.uGroan, c.groanSeconds);
      fade(uniforms.uClap, c.clapSeconds);
    },
  };
}

/** One fan, seated, facing +z, feet at the origin: boxes for legs, body, head and arms, and a flag on a pole. */
function fanGeometry(c: Tunables['crowd3d']): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const add = (g: THREE.BufferGeometry, part: number) => {
    const n = g.getAttribute('position').count;
    g.setAttribute('part', new THREE.Float32BufferAttribute(new Array(n).fill(part), 1));
    parts.push(g.toNonIndexed());
  };
  const box = (w: number, h: number, d: number, x: number, y: number, z: number) => new THREE.BoxGeometry(w, h, d).translate(x, y, z);
  // Seated: thighs forward at seat height, shins down.
  add(box(0.34, c.hipM, 0.22, 0, c.hipM / 2, 0.22), LEGS);
  add(box(0.4, c.shoulderM - c.hipM + 0.05, 0.24, 0, (c.shoulderM + c.hipM) / 2, 0), BODY);
  add(box(0.21, 0.25, 0.23, 0, c.shoulderM + 0.17, 0.01), HEAD);
  const armLen = 0.58;
  add(box(0.1, armLen, 0.1, 0.25, c.shoulderM - armLen / 2 + 0.03, 0.02), ARM_L);
  add(box(0.1, armLen, 0.1, -0.25, c.shoulderM - armLen / 2 + 0.03, 0.02), ARM_R);
  // Held in the right hand: when the arm swings up, the flag goes over the head with it.
  add(new THREE.PlaneGeometry(0.5, 0.32).translate(-0.25 - 0.27, c.shoulderM - armLen - 0.1, 0.02).rotateY(0), FLAG);
  const merged = mergeParts(parts);
  merged.computeVertexNormals();
  return merged;
}

function mergeParts(parts: THREE.BufferGeometry[]): THREE.BufferGeometry {
  const names = ['position', 'normal', 'part'] as const;
  const out = new THREE.BufferGeometry();
  for (const name of names) {
    const size = parts[0]!.getAttribute(name).itemSize;
    const total = parts.reduce((s, p) => s + p.getAttribute(name).count, 0);
    const arr = new Float32Array(total * size);
    let o = 0;
    for (const p of parts) {
      const a = p.getAttribute(name).array as Float32Array;
      arr.set(a, o);
      o += a.length;
    }
    out.setAttribute(name, new THREE.Float32BufferAttribute(arr, size));
  }
  return out;
}
