import type { Tunables } from '../sim/tunables';
import { el, onTap } from './dom';

/** One card of the intro: the word in the accent, a short line, and the real controls it lights. */
interface Card {
  word: string;
  line: string;
  /** data-testid of the controls to light. */
  targets: string[];
  /** A class on the overlay that plays a small demo (the knob pushing up, a press, a hold). */
  demo: string;
  /** The buttons as this card describes them: attacking (PASS) or defending (SWITCH and TACKLE). */
  mode: 'attack' | 'defence';
}

const CARDS: readonly Card[] = [
  { word: 'RUN', line: 'Drag the stick. Swipe right to sidestep', targets: ['stick'], demo: 'demo-run', mode: 'attack' },
  { word: 'SPRINT', line: 'Hold it to burst. The ring is your legs', targets: ['sprint'], demo: 'demo-hold', mode: 'attack' },
  { word: 'PASS', line: 'Tap ◀ or ▶ to pass. Double tap skips', targets: ['pass-left', 'pass-right'], demo: 'demo-tap', mode: 'attack' },
  { word: 'KICK', line: 'Kick-off: swipe from the ball. In play: hold KICK', targets: ['kick'], demo: 'demo-hold', mode: 'attack' },
  // The buttons turn into SWITCH and TACKLE while this card is up, so what is lit matches what it says (Jonny).
  { word: 'DEFEND', line: 'Same buttons: SWITCH, and TACKLE (hold to chase)', targets: ['pass-left', 'pass-right'], demo: 'demo-tap', mode: 'defence' },
];

/**
 * The 10 second how to play at the start of a match (Jonny, 14 Nov 2026): one card at a time over the real
 * controls, each lit as it is named. The match holds while it is up. Tap to go on, SKIP or any key to close.
 */
export class HowTo {
  readonly root = el('div', 'howto');
  private readonly word = el('div', 'howto-word');
  private readonly line = el('div', 'howto-line');
  private readonly dots = el('div', 'howto-dots');
  private readonly skip = el('button', 'howto-skip', 'SKIP');
  private readonly rings: HTMLElement[] = [];
  private index = -1;
  private left = 0;
  private done = false;

  constructor(
    private readonly t: Tunables,
    /** Where the controls live, to find and light them. */
    private readonly controls: HTMLElement,
    private readonly onDone: () => void,
  ) {
    const panel = el('div', 'howto-panel');
    panel.append(el('div', 'howto-title', 'HOW TO PLAY'), this.word, this.line, this.dots);
    for (let i = 0; i < CARDS.length; i++) this.dots.append(el('span', 'howto-dot'));
    this.root.append(panel, this.skip);
    this.skip.dataset.testid = 'howto-skip';
    onTap(this.skip, (e) => {
      e.stopPropagation();
      this.close();
    });
    onTap(this.root, () => this.show(this.index + 1));
    // Capture, so the key closes the intro and does not also kick or pass.
    window.addEventListener('keydown', this.onKey, true);
    this.show(0);
  }

  get active(): boolean {
    return !this.done;
  }

  /** How the controls should read for the card on show. */
  get mode(): 'attack' | 'defence' {
    return CARDS[Math.max(0, this.index)]!.mode;
  }

  /** The card on show is about KICK, so the button must be there to light. */
  get kickShown(): boolean {
    return CARDS[Math.max(0, this.index)]!.targets.includes('kick');
  }

  /** Per frame while active. */
  update(dt: number): void {
    if (this.done) return;
    // A long first frame (the stadium compiling) must not eat a card.
    this.left -= Math.min(dt, this.t.howTo.maxFrameSeconds);
    if (this.left <= 0) this.show(this.index + 1);
    else this.placeRings();
  }

  close(): void {
    if (this.done) return;
    this.done = true;
    window.removeEventListener('keydown', this.onKey, true);
    this.light([]);
    this.root.remove();
    this.onDone();
  }

  private readonly onKey = (e: KeyboardEvent) => {
    e.stopPropagation();
    e.preventDefault();
    this.close();
  };

  private show(i: number): void {
    if (i >= CARDS.length) {
      this.close();
      return;
    }
    const card = CARDS[i]!;
    this.index = i;
    this.left = this.t.howTo.cardSeconds;
    this.word.textContent = card.word;
    this.line.textContent = card.line;
    [...this.dots.children].forEach((d, k) => d.classList.toggle('on', k <= i));
    for (const c of CARDS) this.root.classList.remove(c.demo);
    // Restart the demo animation for this card.
    void this.root.offsetWidth;
    this.root.classList.add(card.demo);
    this.light(card.targets);
  }

  /** Lights the named controls and puts a pulsing ring over each. */
  private light(ids: string[]): void {
    for (const n of this.controls.querySelectorAll('.howto-lit')) n.classList.remove('howto-lit');
    this.controls.classList.toggle('howto-on', ids.length > 0);
    for (const r of this.rings) r.remove();
    this.rings.length = 0;
    for (const id of ids) {
      const n = this.controls.querySelector<HTMLElement>(`[data-testid="${id}"]`);
      if (!n) continue;
      n.classList.add('howto-lit');
      const ring = el('div', 'howto-ring');
      ring.dataset.for = id;
      this.root.append(ring);
      this.rings.push(ring);
    }
    this.placeRings();
  }

  /** Rings follow the controls (the stick sits in a zone, so its ring goes on the stick itself). */
  private placeRings(): void {
    const box = this.root.getBoundingClientRect();
    for (const ring of this.rings) {
      const id = ring.dataset.for!;
      const n = this.controls.querySelector<HTMLElement>(id === 'stick' ? '.stick-base' : `[data-testid="${id}"]`);
      if (!n) continue;
      const r = n.getBoundingClientRect();
      const size = Math.max(r.width, r.height) + this.t.howTo.ringPadPx * 2;
      ring.style.width = ring.style.height = `${size}px`;
      ring.style.left = `${r.left - box.left + r.width / 2 - size / 2}px`;
      ring.style.top = `${r.top - box.top + r.height / 2 - size / 2}px`;
    }
  }
}
