import * as THREE from 'three';
import type { Tunables } from '../sim/tunables';

/** Behind-the-play camera (GDD section 3). Always attacking up the screen. */
export function createCamera(t: Tunables, aspect: number): THREE.PerspectiveCamera {
  const c = t.camera;
  return new THREE.PerspectiveCamera(c.fovDeg, aspect, c.near, c.far);
}

/**
 * call: low behind the play, the hero shot over the play cards (reference/25).
 * carrier: high behind and above the ball carrier, attacking up the screen (GDD section 3). chase: low behind the ball carrier.
 * ball: pulled back and up for passes in the air. celebrate: in front of the scorer looking back at them.
 * tackle: low and to the side of the pile, under the result banner (reference 07).
 */
export type CameraMode = 'call' | 'carrier' | 'chase' | 'ball' | 'celebrate' | 'tackle' | 'aim';

/**
 * Smoothly follows a focus point. Shake decays on its own. A lens shift (fraction of screen height,
 * positive moves the picture up) keeps the subject clear of the cards and banners.
 */
export class CameraRig {
  private mode: CameraMode = 'carrier';
  private readonly focus = new THREE.Vector3();
  private readonly pos = new THREE.Vector3();
  private readonly look = new THREE.Vector3();
  private readonly wantPos = new THREE.Vector3();
  private readonly wantLook = new THREE.Vector3();
  private shake = 0;
  private jolt = 0;
  private time = 0;
  private shift = 0;
  private wantShift = 0;
  /** -1 attacks toward -z (up the screen from the home end), +1 the other way (it flips at half time). */
  private dir = -1;
  private extraBack = 0;
  /** 'aim': the unit direction the shot looks along (x, z), e.g. from a kicker to the posts. */
  private aimDir = { x: 0, z: -1 };

  constructor(
    private readonly camera: THREE.PerspectiveCamera,
    private readonly t: Tunables,
  ) {}

  setMode(mode: CameraMode, dir: 1 | -1 = -1): void {
    this.mode = mode;
    this.dir = dir;
  }

  /** For 'aim': look along this direction (it need not be up the pitch), e.g. from the kicker to the posts. */
  setAim(dx: number, dz: number): void {
    const l = Math.hypot(dx, dz) || 1;
    this.aimDir = { x: dx / l, z: dz / l };
  }

  /** Extra pull back for long throws (metres). */
  setPullback(metres: number): void {
    this.extraBack = metres;
  }

  /** Jumps straight to the focus (between plays). */
  snapTo(x: number, z: number): void {
    this.follow(x, z);
    this.compute();
    this.pos.copy(this.wantPos);
    this.look.copy(this.wantLook);
    this.shift = this.wantShift;
    this.apply();
  }

  follow(x: number, z: number): void {
    // The focus stays on the field, so the camera never ends up staring into the stands.
    const half = this.t.field.lengthM / 2;
    this.focus.set(x, 0, Math.max(-half, Math.min(half, z)));
  }

  /** Rattle that decays on its own. With jolt the camera also dips on the hit and springs back. */
  addShake(amount: number, jolt = false): void {
    this.shake = Math.min(1, this.shake + amount);
    if (jolt) this.jolt = 1;
  }

  update(dt: number): void {
    this.time += dt;
    this.compute();
    const t = this.t;
    const rate =
      this.mode === 'carrier'
        ? t.cameraFollow.lerpPerSecond
        : this.mode === 'call'
          ? t.cameraCall.lerpPerSecond
          : this.mode === 'celebrate'
            ? t.cameraCelebrate.lerpPerSecond
            : this.mode === 'aim'
              ? t.cameraAim.lerpPerSecond
            : this.mode === 'tackle'
              ? t.cameraTackle.lerpPerSecond
              : t.cameraChase.lerpPerSecond;
    const k = 1 - Math.exp(-rate * dt);
    this.pos.lerp(this.wantPos, k);
    this.look.lerp(this.wantLook, k);
    this.shift += (this.wantShift - this.shift) * k;
    this.shake = Math.max(0, this.shake - t.fx.shakeDecayPerSecond * dt * this.shake - dt * 0.2);
    this.jolt *= Math.exp(-t.fx.joltDecayPerSecond * dt);
    this.apply();
  }

  private compute(): void {
    const t = this.t;
    const c = t.camera;
    const ch = t.cameraChase;
    const f = this.focus;
    const d = this.dir;
    if (this.mode === 'call') {
      const cc = t.cameraCall;
      this.wantPos.set(0, cc.upM, f.z - d * cc.backM);
      this.wantLook.set(0, cc.lookHeightM, f.z + d * cc.lookAheadM);
      this.wantShift = cc.shift;
    } else if (this.mode === 'carrier') {
      this.wantPos.set(f.x * c.followXPos, c.upM, f.z - d * c.backM);
      this.wantLook.set(f.x * c.followXLook, c.lookHeightM, f.z + d * c.lookAheadM);
      this.wantShift = c.shift;
    } else if (this.mode === 'chase') {
      this.wantPos.set(f.x, ch.upM, f.z - d * ch.backM);
      this.wantLook.set(f.x, ch.lookHeightM, f.z + d * ch.lookAheadM);
      this.wantShift = ch.shift;
    } else if (this.mode === 'ball') {
      this.wantPos.set(f.x * 0.7, ch.ballUpM + this.extraBack * 0.35, f.z - d * (ch.ballBackM + this.extraBack));
      this.wantLook.set(f.x, ch.lookHeightM, f.z + d * ch.lookAheadM);
      this.wantShift = ch.shift;
    } else if (this.mode === 'aim') {
      // Low behind the focus on the aim line (a kicker lined up on the posts, as broadcasts show a kick at goal).
      const ca = t.cameraAim;
      const a = this.aimDir;
      this.wantPos.set(f.x - a.x * ca.backM, ca.upM, f.z - a.z * ca.backM);
      this.wantLook.set(f.x + a.x * ca.lookAheadM, ca.lookHeightM, f.z + a.z * ca.lookAheadM);
      this.wantShift = ca.shift;
    } else if (this.mode === 'celebrate') {
      const cc = t.cameraCelebrate;
      const side = f.x > 0 ? -1 : 1;
      this.wantPos.set(f.x + side * cc.sideM, cc.upM, f.z + d * cc.frontM);
      this.wantLook.set(f.x, cc.lookHeightM, f.z);
      this.wantShift = cc.shift;
    } else {
      const ct = t.cameraTackle;
      const side = f.x > 0 ? -1 : 1;
      this.wantPos.set(f.x + side * ct.sideM, ct.upM, f.z - d * ct.backM);
      this.wantLook.set(f.x, ct.lookHeightM, f.z);
      this.wantShift = ct.shift;
    }
    // Stay inside the stadium bowl: never behind the end stands.
    const limit = t.field.lengthM / 2 + c.insideFieldM;
    this.wantPos.z = Math.max(-limit, Math.min(limit, this.wantPos.z));
  }

  private apply(): void {
    const fx = this.t.fx;
    const s = this.shake * fx.shakeM;
    const ox = Math.sin(this.time * 47) * s;
    const oy = Math.cos(this.time * 53) * s * 0.7 - this.jolt * fx.joltM;
    this.camera.position.set(this.pos.x + ox, this.pos.y + oy, this.pos.z);
    this.camera.lookAt(this.look.x + ox * 0.5, this.look.y + oy * 0.5, this.look.z);
    // setViewOffset also sets the aspect from the full size, so pass the current one through.
    const aspect = this.camera.aspect;
    if (Math.abs(this.shift) > 1e-4) this.camera.setViewOffset(aspect, 1, 0, this.shift, aspect, 1);
    else if (this.camera.view?.enabled) this.camera.clearViewOffset();
  }
}
