import * as THREE from 'three';
import type { Brand } from '../brand/types';
import type { Tunables } from '../sim/tunables';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { createCamera } from './camera';
import { createPitch, type PitchView } from './pitch';
import { createStadium, type StadiumView } from './stadium';
import { QualityGovernor } from './quality';

export interface SceneStats {
  fps: number;
  drawCalls: number;
  pixelRatio: number;
}

export interface Stage {
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  pitch: PitchView;
  stadium: StadiumView;
  stats: SceneStats;
  /** Current canvas size in CSS px. */
  size: { width: number; height: number };
  /** Centres the key light's shadow on the play (x, z), so the players cast real shadows where the camera looks. */
  shadowFocus(x: number, z: number): void;
  start(onFrame: (dt: number) => void): void;
  dispose(): void;
}

/** Renderer, lights, pitch, camera, resize and the frame loop with resolution scaling. */
export function createStage(container: HTMLElement, brand: Brand, logo: HTMLImageElement | null, mark: HTMLImageElement | null, t: Tunables): Stage {
  const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  const quality = new QualityGovernor(t, window.devicePixelRatio || 1);
  renderer.setPixelRatio(quality.pixelRatio);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  // Neutral keeps the kit and grass colours saturated under bright floodlights (ACES greys them out).
  renderer.toneMapping = t.look.toneMapping === 'neutral' ? THREE.NeutralToneMapping : THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = t.look.toneExposure;
  container.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(t.look.sky);
  scene.fog = new THREE.Fog(t.look.fog, t.look.fogNear, t.look.fogFar);
  // Soft image lighting for the physically based players: a neutral room, blurred, so skin and kit pick up gentle
  // reflections and fill instead of going flat where the key light does not reach.
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), t.look.environmentBlur).texture;
  scene.environmentIntensity = t.look.environmentIntensity;
  pmrem.dispose();
  scene.add(new THREE.HemisphereLight(t.look.hemisphereSky, t.look.hemisphereGround, t.look.hemisphereIntensity));
  const key = new THREE.DirectionalLight(t.look.keyLight, t.look.keyLightIntensity);
  key.position.fromArray(t.look.keyLightPosition);
  scene.add(key, key.target);
  // Real shadows from the key light, cast by the players only, in a box that follows the play.
  const r = t.render;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  key.castShadow = true;
  key.shadow.mapSize.set(r.shadowMapPx, r.shadowMapPx);
  key.shadow.bias = r.shadowBias;
  key.shadow.normalBias = r.shadowNormalBias;
  const sc = key.shadow.camera;
  sc.left = sc.bottom = -r.shadowHalfM;
  sc.right = sc.top = r.shadowHalfM;
  sc.near = 1;
  sc.far = r.shadowFar;
  sc.updateProjectionMatrix();
  const keyOffset = new THREE.Vector3().fromArray(t.look.keyLightPosition);
  // A soft fill from behind the camera (which always looks up the pitch): the players' faces and kits read evenly,
  // as in a broadcast, instead of falling into shadow on the side away from the key light.
  const fill = new THREE.DirectionalLight(t.look.fillLight, t.look.fillLightIntensity);
  fill.position.fromArray(t.look.fillLightPosition);
  scene.add(fill);
  const rim = new THREE.DirectionalLight(t.look.rimLight, t.look.rimLightIntensity);
  rim.position.fromArray(t.look.rimLightPosition);
  scene.add(rim);

  const pitch = createPitch(brand, t, logo, mark, renderer.capabilities.getMaxAnisotropy());
  scene.add(pitch.group);
  const stadium = createStadium(brand, t, logo, renderer.capabilities.getMaxAnisotropy());
  scene.add(stadium.group);

  const camera = createCamera(t, 1);
  const size = { width: 1, height: 1 };
  const resize = () => {
    size.width = container.clientWidth;
    size.height = container.clientHeight;
    renderer.setSize(size.width, size.height, false);
    camera.aspect = size.width / Math.max(1, size.height);
    camera.updateProjectionMatrix();
  };
  const observer = new ResizeObserver(resize);
  observer.observe(container);
  resize();

  const stats: SceneStats = { fps: 0, drawCalls: 0, pixelRatio: quality.pixelRatio };
  const timer = new THREE.Timer();

  return {
    renderer,
    scene,
    camera,
    pitch,
    stadium,
    stats,
    size,
    shadowFocus(x, z) {
      key.target.position.set(x, 0, z);
      key.position.set(x + keyOffset.x, keyOffset.y, z + keyOffset.z);
    },
    start(onFrame) {
      renderer.setAnimationLoop((time) => {
        timer.update(time);
        const dt = Math.min(timer.getDelta(), t.render.maxFrameSeconds);
        if (quality.tick(timer.getDelta())) {
          renderer.setPixelRatio(quality.pixelRatio);
          resize();
        }
        // A phone that cannot hold the frame rate even at the lowest resolution loses the player shadows
        // first: smooth control matters more than the look.
        if (key.castShadow && quality.fps > 0 && quality.fps < r.shadowOffFps && quality.pixelRatio <= quality.floor) {
          key.castShadow = false;
          renderer.shadowMap.enabled = false;
        }
        onFrame(dt);
        renderer.render(scene, camera);
        stats.fps = quality.fps;
        stats.drawCalls = renderer.info.render.calls;
        stats.pixelRatio = quality.pixelRatio;
      });
    },
    dispose() {
      renderer.setAnimationLoop(null);
      observer.disconnect();
      renderer.dispose();
      renderer.domElement.remove();
    },
  };
}
