import type { Tunables } from '../sim/tunables';
import { el } from './dom';

export interface ControlHandlers {
  /** PASS LEFT (-1) or PASS RIGHT (1): to the next man in the line on that side. */
  onPass(side: -1 | 1): void;
  /** The same button again quickly: a longer pass that skips the next man. */
  onSkip(side: -1 | 1): void;
  /** A swipe on the right of the screen: step left or right, fend (up) or spin (down). */
  onMove(kind: 'step' | 'fend' | 'spin', side: -1 | 1): void;
  /** Defending: SWITCH (the left button). */
  onSwitch(): void;
  /** Defending: TACKLE tapped (the right button): a standing tackle. */
  onTackle(): void;
  /** Defending: TACKLE held: the defender chases the carrier (addendum 4). */
  onChase(on: boolean): void;
  /** Defending: TACKLE let go after a chase: the dive. */
  onDive(): void;
  /** Attacking: a kick from the menu (a tap on KICK is a grubber). */
  onKick(type: KickType): void;
  /** Kick-off: KICK held fills the power ring; on release, the kick with that power (0 to 1). */
  onKickoff(power: number): void;
}

export type KickType = 'grubber' | 'chip' | 'box' | 'touch';
/** attack: running and passing. defence: SWITCH and TACKLE. kickoff: KICK with a power ring. */
export type ControlMode = 'attack' | 'defence' | 'kickoff';

/**
 * On-screen controls (Jonny's pick 12 Nov 2026, after Rugby Nations; replaces GDD 6.1's single PASS): a floating
 * semi-transparent joystick bottom left; bottom right SPRINT (held, stamina ring), PASS◀ and PASS▶ (a tap passes
 * to the next man on that side, a double tap skips him) and KICK (M3); swipes anywhere else on the right half step,
 * fend or spin. Keyboard for desktop testing: WASD or arrows to run, J sprint, K pass left, L pass right, Q and E
 * step left and right, R fend, F spin.
 */
export class Controls {
  readonly root = el('div', 'controls');
  /** Stick output: x right, y up the screen, each -1 to 1. */
  readonly stick = { x: 0, y: 0 };
  sprint = false;
  private readonly zone = el('div', 'stick-zone');
  /** Right of the screen, under the buttons: swipes for moves (GDD 6.4). */
  private readonly swipe = el('div', 'swipe-zone');
  private readonly base = el('div', 'stick-base');
  private readonly knob = el('div', 'stick-knob');
  private readonly sprintBtn = el('button', 'ctl-btn ctl-sprint');
  private readonly passL = el('button', 'ctl-btn ctl-pass-l');
  private readonly passR = el('button', 'ctl-btn ctl-pass-r');
  private readonly kickBtn = el('button', 'ctl-btn ctl-kick');
  private readonly staminaArc: SVGCircleElement;
  private stickId = -1;
  private stickOrigin = { x: 0, y: 0 };
  private sprintHeld = false;
  /** When each pass button was last pressed (ms), for the double tap. */
  private readonly lastTap = { [-1]: -Infinity, [1]: -Infinity } as Record<-1 | 1, number>;
  private readonly keys = new Set<string>();
  private enabled = true;
  private mode: ControlMode = 'attack';
  private readonly labelL: HTMLElement;
  private readonly labelR: HTMLElement;
  /** When TACKLE went down (ms), for the big hit. */
  private tackleDown = -1;
  private chasing = false;
  /** KICK held: when (ms), and the menu if it has opened. */
  private kickDown = -1;
  private readonly menu = el('div', 'kick-menu');
  private menuOn = false;
  private menuPick: KickType | null = null;
  private readonly kickArc: SVGCircleElement;
  private readonly kickSweet: SVGCircleElement;
  private touchFinder = false;
  /** Kick-off power, 0 to 1, rising and falling while KICK is held. */
  power = 0;

  constructor(
    private readonly t: Tunables,
    private readonly h: ControlHandlers,
  ) {
    this.base.append(this.knob);
    this.zone.append(this.base);
    this.zone.dataset.testid = 'stick';
    const s = t.controls;
    this.sprintBtn.style.setProperty('--size', `${s.sprintPx}px`);
    this.passL.style.setProperty('--size', `${s.passPx}px`);
    this.passR.style.setProperty('--size', `${s.passPx}px`);
    this.kickBtn.style.setProperty('--size', `${s.kickPx}px`);
    this.staminaArc = ringSvg(this.sprintBtn);
    this.sprintBtn.append(el('span', 'ctl-label', 'SPRINT'));
    this.labelL = el('span', 'ctl-label', '◀ PASS');
    this.labelR = el('span', 'ctl-label', 'PASS ▶');
    this.passL.append(this.labelL);
    this.passR.append(this.labelR);
    this.kickArc = ringSvg(this.kickBtn);
    setRing(this.kickArc, 0);
    // The green band on the KICK ring for goal kicks: let go inside it.
    this.kickSweet = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    for (const [k, v] of [['cx', '50'], ['cy', '50'], ['r', String(RING_R)], ['class', 'ctl-sweet']]) this.kickSweet.setAttribute(k!, v!);
    this.kickArc.parentNode!.insertBefore(this.kickSweet, this.kickArc);
    this.setSweet(null);
    this.kickBtn.append(el('span', 'ctl-label', 'KICK'));
    this.kickBtn.dataset.testid = 'kick';
    for (const k of ['chip', 'box', 'grubber', 'touch'] as const) {
      const opt = el('div', `kick-opt kick-${k}`, k === 'touch' ? 'TOUCH' : k === 'box' ? 'BOX' : k.toUpperCase());
      opt.dataset.kick = k;
      this.menu.append(opt);
    }
    this.menu.hidden = true;
    this.sprintBtn.dataset.testid = 'sprint';
    this.passL.dataset.testid = 'pass-left';
    this.passR.dataset.testid = 'pass-right';
    const pad = el('div', 'ctl-pad');
    pad.append(this.menu, this.kickBtn, this.passL, this.passR, this.sprintBtn);
    this.swipe.dataset.testid = 'swipe';
    this.root.append(this.zone, this.swipe, pad);
    this.restStick();
    this.wireStick();
    this.wireSprint();
    this.wirePass(this.passL, -1);
    this.wirePass(this.passR, 1);
    this.wireSwipe();
    this.wireKick();
    this.wireKeys();
  }

  /** Dims the pass buttons while the ball is not in hand. The stick and SPRINT keep tracking the thumbs. */
  setEnabled(on: boolean): void {
    if (on === this.enabled) return;
    this.enabled = on;
    this.root.classList.toggle('off', !on);
  }

  /** Attack, defence or kick-off: relabels the two big buttons and what they do. */
  setMode(mode: ControlMode): void {
    if (mode === this.mode) return;
    this.mode = mode;
    this.labelL.textContent = mode === 'defence' ? 'SWITCH' : '◀ PASS';
    this.labelR.textContent = mode === 'defence' ? 'TACKLE' : 'PASS ▶';
    this.root.classList.toggle('defence', mode === 'defence');
    this.root.classList.toggle('kickoff', mode === 'kickoff');
    if (mode !== 'defence') this.tackleDown = -1;
    this.closeMenu();
    this.power = 0;
    setRing(this.kickArc, 0);
  }

  /** KICK shows only when a kick is on (addendum 4). */
  setKickOn(on: boolean): void {
    this.kickBtn.classList.toggle('hide', !on && this.mode === 'attack');
  }

  /** Shows the green band on the KICK ring (centre and half width, 0 to 1), or hides it. */
  setSweet(band: { centre: number; half: number } | null): void {
    this.kickSweet.style.display = band ? '' : 'none';
    if (!band) return;
    this.kickSweet.setAttribute('stroke-dasharray', `${RING_C * 2 * band.half} ${RING_C}`);
    this.kickSweet.setAttribute('stroke-dashoffset', String(-RING_C * (band.centre - band.half)));
  }

  /** Within reach of a touchline: TOUCH is offered in the kick menu. */
  setTouchFinder(on: boolean): void {
    this.touchFinder = on;
  }

  /** Lights TACKLE while the carrier is within reach (or an intercept is on). */
  setTackleReady(on: boolean): void {
    this.passR.classList.toggle('ready', on);
  }

  /** The tackle moment: the PASS buttons pulse, a tap now is an offload. */
  setOffload(on: boolean): void {
    this.root.classList.toggle('offload', on);
  }

  /** Lights the pass button that has somebody to pass to. */
  setPassable(left: boolean, right: boolean): void {
    this.passL.classList.toggle('none', !left);
    this.passR.classList.toggle('none', !right);
  }

  /** Stamina 0 to 100 on the SPRINT ring; the ring goes grey while exhausted. */
  setStamina(pct: number, exhausted = false): void {
    setRing(this.staminaArc, pct / 100);
    this.sprintBtn.classList.toggle('tired', exhausted);
  }

  /** Per frame: the keyboard feeds the stick when no thumb is on it. */
  update(): void {
    if (this.stickId < 0) {
      const x = (this.keys.has('d') || this.keys.has('arrowright') ? 1 : 0) - (this.keys.has('a') || this.keys.has('arrowleft') ? 1 : 0);
      const y = (this.keys.has('w') || this.keys.has('arrowup') ? 1 : 0) - (this.keys.has('s') || this.keys.has('arrowdown') ? 1 : 0);
      const len = Math.hypot(x, y) || 1;
      this.stick.x = x / len;
      this.stick.y = y / len;
    }
    this.sprint = this.sprintHeld || this.keys.has('j');
    if (this.tackleDown >= 0 && !this.chasing && this.mode === 'defence' && (performance.now() - this.tackleDown) / 1000 >= this.t.userDefence.chaseHoldSeconds) {
      this.chasing = true;
      this.h.onChase(true);
    }
    if (this.kickDown >= 0) {
      const held = (performance.now() - this.kickDown) / 1000;
      if (this.mode === 'kickoff') {
        // The power ring rises and falls: let go at the top for the longest kick.
        const ph = (held / this.t.controls.kickoffPowerSeconds) % 2;
        this.power = ph < 1 ? ph : 2 - ph;
        setRing(this.kickArc, this.power);
      } else if (this.mode === 'attack' && !this.menuOn && held >= this.t.controls.kickMenuSeconds) {
        this.menuOn = true;
        this.menu.hidden = false;
        this.menu.classList.toggle('touch', this.touchFinder);
      }
    }
  }

  /** Keeps the whole ring on screen, a ring's reach in from the left and bottom edges. */
  private clampOrigin(): void {
    const box = this.zone.getBoundingClientRect();
    const inset = (this.t.controls.stickRingPx / 2) * this.t.controls.stickEdgeInset;
    this.stickOrigin.x = Math.max(box.left + inset, this.stickOrigin.x);
    this.stickOrigin.y = Math.min(box.bottom - inset, this.stickOrigin.y);
  }

  private placeBase(): void {
    const box = this.zone.getBoundingClientRect();
    this.base.style.left = `${this.stickOrigin.x - box.left}px`;
    this.base.style.top = `${this.stickOrigin.y - box.top}px`;
  }

  private restStick(): void {
    this.base.classList.add('rest');
    this.base.style.left = '';
    this.base.style.top = '';
    this.knob.style.transform = 'translate(-50%, -50%)';
  }

  private wireStick(): void {
    const r = this.t.controls.stickRingPx / 2;
    const start = (id: number, x: number, y: number) => {
      // A new thumb always takes the stick. If the phone ever dropped the lift of the last one, waiting for it
      // would leave the stick dead until a reload.
      this.stickId = id;
      // A thumb that lands near the edge of the screen still gets the whole ring: the stick centres a ring's
      // reach in from the edge, so a push toward the edge is a full push (Jonny, 14 Nov 2026: hold left, keep going left).
      // A thumb on the drawn stick presses it where it lands: pressing its left side is a push left at once, held
      // for as long as the thumb stays (Jonny, 15 Nov 2026: holding left must keep going left, not a nudge).
      // Anywhere else in the zone the stick floats to the thumb as before.
      const rest = this.base.getBoundingClientRect();
      const cx = rest.left + rest.width / 2;
      const cy = rest.top + rest.height / 2;
      const onStick = this.base.classList.contains('rest') && Math.hypot(x - cx, y - cy) <= r * this.t.controls.stickGrab;
      this.stickOrigin = onStick ? { x: cx, y: cy } : { x, y };
      this.clampOrigin();
      this.base.classList.remove('rest');
      this.placeBase();
      if (onStick) move(id, x, y);
    };
    const move = (id: number, x: number, y: number) => {
      if (id !== this.stickId) return;
      let dx = x - this.stickOrigin.x;
      let dy = y - this.stickOrigin.y;
      const len = Math.hypot(dx, dy);
      if (len > r) {
        // Past the rim the stick follows the thumb, so the push keeps its direction and turning back is instant.
        this.stickOrigin.x += (dx / len) * (len - r);
        this.stickOrigin.y += (dy / len) * (len - r);
        this.clampOrigin();
        this.placeBase();
        dx = (dx / len) * r;
        dy = (dy / len) * r;
      }
      this.knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
      const k = Math.hypot(dx, dy) / r;
      const dead = this.t.controls.stickDeadzone;
      // Full speed well before the rim: a held push is a full push, even as the thumb drifts.
      const full = this.t.controls.stickFullAt;
      const scale = k < dead ? 0 : Math.min(1, (k - dead) / (full - dead)) / Math.max(k, 1e-6);
      this.stick.x = (dx / r) * scale;
      this.stick.y = (-dy / r) * scale;
    };
    const end = (id: number) => {
      if (id !== this.stickId) return;
      this.stickId = -1;
      this.stick.x = this.stick.y = 0;
      this.restStick();
    };
    if ('ontouchstart' in window) {
      // Phones: raw touch events with the default blocked, so iOS cannot take the drag for a scroll, a bounce or
      // a back swipe and cancel it (pointer events lose the thumb when that happens).
      const opts = { passive: false } as const;
      this.zone.addEventListener(
        'touchstart',
        (e) => {
          e.preventDefault();
          const tch = e.changedTouches[0];
          if (tch) start(tch.identifier, tch.clientX, tch.clientY);
        },
        opts,
      );
      this.zone.addEventListener(
        'touchmove',
        (e) => {
          e.preventDefault();
          for (const tch of Array.from(e.changedTouches)) move(tch.identifier, tch.clientX, tch.clientY);
        },
        opts,
      );
      const lift = (e: TouchEvent) => {
        for (const tch of Array.from(e.changedTouches)) end(tch.identifier);
      };
      this.zone.addEventListener('touchend', lift);
      this.zone.addEventListener('touchcancel', lift);
      window.addEventListener('touchend', lift);
      // Nothing on this page scrolls: stop the browser treating any drag as a scroll or bounce.
      document.addEventListener('touchmove', (e) => e.preventDefault(), opts);
      return;
    }
    // Desktop: the mouse.
    this.zone.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.zone.setPointerCapture(e.pointerId);
      start(e.pointerId, e.clientX, e.clientY);
    });
    this.zone.addEventListener('pointermove', (e) => move(e.pointerId, e.clientX, e.clientY));
    const lift = (e: PointerEvent) => end(e.pointerId);
    this.zone.addEventListener('pointerup', lift);
    this.zone.addEventListener('pointercancel', lift);
    this.zone.addEventListener('lostpointercapture', lift);
    window.addEventListener('pointerup', lift);
  }

  private wireSprint(): void {
    const b = this.sprintBtn;
    b.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      b.setPointerCapture(e.pointerId);
      this.sprintHeld = true;
      b.classList.add('down');
    });
    const up = () => {
      this.sprintHeld = false;
      b.classList.remove('down');
    };
    b.addEventListener('pointerup', up);
    b.addEventListener('pointercancel', up);
  }

  /** A pass fires on touch down: no waiting for the finger to lift (late passes are what players hate most). */
  private wirePass(b: HTMLButtonElement, side: -1 | 1): void {
    b.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      b.classList.add('down');
      if (this.mode === 'defence') {
        if (side < 0) this.h.onSwitch();
        else this.tackleDown = performance.now();
        return;
      }
      this.tap(side);
    });
    const up = () => {
      b.classList.remove('down');
      if (side > 0) this.releaseTackle();
    };
    b.addEventListener('pointerup', up);
    b.addEventListener('pointercancel', up);
    b.addEventListener('pointerleave', up);
  }

  private wireSwipe(): void {
    let id = -1;
    let x0 = 0;
    let y0 = 0;
    let t0 = 0;
    this.swipe.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      id = e.pointerId;
      x0 = e.clientX;
      y0 = e.clientY;
      t0 = performance.now();
      this.swipe.setPointerCapture(e.pointerId);
    });
    const end = (e: PointerEvent) => {
      if (e.pointerId !== id) return;
      id = -1;
      const dx = e.clientX - x0;
      const dy = e.clientY - y0;
      const c = this.t.controls;
      if ((performance.now() - t0) / 1000 > c.swipeMaxSeconds || Math.hypot(dx, dy) < c.swipeMinPx || !this.enabled) return;
      if (Math.abs(dx) > Math.abs(dy)) this.h.onMove('step', dx < 0 ? -1 : 1);
      else this.h.onMove(dy < 0 ? 'fend' : 'spin', 1);
    };
    this.swipe.addEventListener('pointerup', end);
    this.swipe.addEventListener('pointercancel', () => (id = -1));
    this.swipe.addEventListener('lostpointercapture', () => (id = -1));
  }

  /** TACKLE let go: a tap tackles, a hold past the big-hit time is a big hit. */
  private releaseTackle(): void {
    if (this.tackleDown < 0) return;
    this.tackleDown = -1;
    if (this.chasing) {
      this.chasing = false;
      this.h.onDive();
    } else if (this.mode === 'defence') this.h.onTackle();
  }


  /**
   * KICK. Attacking: a tap is a grubber; held, a menu opens round the button (chip, box kick, grubber, and touch
   * finder near a touchline): slide onto one and let go. Kick-off: held, the power ring fills and empties; let go
   * to kick at that power.
   */
  private wireKick(): void {
    const b = this.kickBtn;
    const c = this.t.controls;
    b.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      if (!this.enabled) return;
      b.setPointerCapture(e.pointerId);
      b.classList.add('down');
      this.kickDown = performance.now();
      this.menuPick = null;
    });
    b.addEventListener('pointermove', (e) => {
      if (!this.menuOn) return;
      const hit = document.elementFromPoint(e.clientX, e.clientY) as HTMLElement | null;
      const k = (hit?.dataset.kick ?? null) as KickType | null;
      this.menuPick = k && (k !== 'touch' || this.touchFinder) ? k : null;
      for (const opt of Array.from(this.menu.children) as HTMLElement[]) opt.classList.toggle('on', opt.dataset.kick === this.menuPick);
    });
    const up = () => {
      b.classList.remove('down');
      if (this.kickDown < 0) return;
      const held = (performance.now() - this.kickDown) / 1000;
      this.kickDown = -1;
      if (this.mode === 'kickoff') {
        this.h.onKickoff(this.power);
        this.power = 0;
        setRing(this.kickArc, 0);
        return;
      }
      if (this.mode !== 'attack') return;
      if (this.menuOn) {
        const pick = this.menuPick;
        this.closeMenu();
        if (pick) this.h.onKick(pick);
      } else if (held < c.kickMenuSeconds) this.h.onKick('grubber');
    };
    b.addEventListener('pointerup', up);
    b.addEventListener('pointercancel', () => {
      this.kickDown = -1;
      this.closeMenu();
    });
  }

  private closeMenu(): void {
    this.menuOn = false;
    this.menu.hidden = true;
    this.menuPick = null;
  }

  /** One tap passes at once (no waiting to see if a second comes); a second tap soon after turns it into a skip pass. */
  private tap(side: -1 | 1): void {
    const now = performance.now();
    const double = now - this.lastTap[side] < this.t.passing.doubleTapSeconds * 1000;
    this.lastTap[side] = double ? -Infinity : now;
    if (double) this.h.onSkip(side);
    else if (this.enabled) this.h.onPass(side);
  }

  private wireKeys(): void {
    window.addEventListener('keydown', (e) => {
      const k = e.key.toLowerCase();
      if (!this.keys.has(k) && this.mode === 'defence') {
        if (k === 'k') this.h.onSwitch();
        if (k === 'l') this.tackleDown = performance.now();
      } else if (!this.keys.has(k) && this.mode === 'kickoff' && k === 'u') {
        this.kickDown = performance.now();
      } else if (!this.keys.has(k) && this.enabled) {
        if (k === 'k') this.tap(-1);
        if (k === 'l') this.tap(1);
        if (k === 'u') this.h.onKick('grubber');
        if (k === 'i') this.h.onKick('chip');
        if (k === 'o') this.h.onKick('box');
        if (k === 'p' && this.touchFinder) this.h.onKick('touch');
        if (k === 'q') this.h.onMove('step', -1);
        if (k === 'e') this.h.onMove('step', 1);
        if (k === 'r') this.h.onMove('fend', 1);
        if (k === 'f') this.h.onMove('spin', 1);
      }
      this.keys.add(k);
    });
    window.addEventListener('keyup', (e) => {
      const k = e.key.toLowerCase();
      this.keys.delete(k);
      if (k === 'l') this.releaseTackle();
      if (k === 'u' && this.mode === 'kickoff' && this.kickDown >= 0) {
        this.kickDown = -1;
        this.h.onKickoff(this.power);
        this.power = 0;
        setRing(this.kickArc, 0);
      }
    });
    window.addEventListener('blur', () => this.keys.clear());
  }
}

const RING_R = 46;
const RING_C = 2 * Math.PI * RING_R;

function ringSvg(host: HTMLElement): SVGCircleElement {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 100 100');
  svg.setAttribute('class', 'ctl-ring');
  const c = document.createElementNS(ns, 'circle');
  c.setAttribute('cx', '50');
  c.setAttribute('cy', '50');
  c.setAttribute('r', String(RING_R));
  c.setAttribute('stroke-dasharray', String(RING_C));
  svg.append(c);
  host.append(svg);
  setRing(c, 1);
  return c;
}

function setRing(c: SVGCircleElement, k: number): void {
  c.setAttribute('stroke-dashoffset', String(RING_C * (1 - Math.max(0, Math.min(1, k)))));
}
