import type { Tunables } from '../sim/tunables';
import { el, onTap } from './dom';

/**
 * The addendum 13 Nov screens over the match (section 4): the ruck arc with ADD PLAYER and CALL PLAY, the result
 * word over the ruck, the swipe at goal with its lime trail, and the wind box. Brand tokens from CSS only.
 */
export interface AddendumHandlers {
  onAddPlayer(): void;
  onCallPlay(): void;
  /** A swipe at goal in screen pixels (x right, y up) and its speed (px per second). */
  onSwipe(dx: number, dy: number, pxPerSecond: number): void;
  /** Keyboard stand-in for the swipe (G): straight at the posts with the power that reaches them. */
  onStraightKick(): void;
}

export interface AddendumView {
  ruck: { on: boolean; chance: number; defending: boolean; canAdd: boolean; x: number; y: number } | null;
  ruckWord: string;
  callChip: boolean;
  goalSwipe: boolean;
  /** Which swipe the pad is for: each has its own first-time hand. */
  swipeKind: 'goal' | 'kickoff';
  /** The ball and where to swipe to on screen, for the hand that shows the swipe. */
  goalLine: { bx: number; by: number; px: number; py: number } | null;
  wind: { mph: number; arrowDeg: number };
}

export class AddendumUi {
  readonly root = el('div', 'add-ui');
  private readonly arc = el('div', 'ruck-arc');
  private readonly fill: SVGPathElement;
  private readonly word = el('div', 'ruck-word');
  private readonly addBtn = el('button', 'pill add-player', 'ADD PLAYER');
  private readonly callBtn = el('button', 'pill call-chip', 'CALL PLAY');
  private readonly pad = el('div', 'goal-pad');
  private readonly trail: SVGPolylineElement;
  private readonly wind = el('div', 'wind');
  private readonly windArrow = el('span', 'wind-arrow', '↑');
  private readonly windMph = el('span', 'wind-mph');
  private view: AddendumView | null = null;
  /** The little white hand that shows the swipe at goal, until the first swipe on this device. */
  private readonly hand = el('div', 'goal-hand');
  /** The white streak the hand leaves behind it, and a pulsing ring on the ball where the swipe starts. */
  private readonly streak = el('div', 'hand-streak');
  private readonly ballRing = el('div', 'hand-ball');
  private readonly handDone = { goal: readFlag(HAND_KEY.goal), kickoff: readFlag(HAND_KEY.kickoff) };

  constructor(
    private readonly t: Tunables,
    private readonly h: AddendumHandlers,
  ) {
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', '-50 -50 100 55');
    const back = document.createElementNS(ns, 'path');
    back.setAttribute('d', arcPath(1));
    back.setAttribute('class', 'arc-back');
    this.fill = document.createElementNS(ns, 'path');
    this.fill.setAttribute('class', 'arc-fill');
    svg.append(back, this.fill);
    this.arc.style.width = `${t.ruck.arcPx}px`;
    this.arc.append(svg, this.word);
    this.addBtn.dataset.testid = 'add-player';
    this.callBtn.dataset.testid = 'call-chip';
    onTap(this.addBtn, () => h.onAddPlayer());
    onTap(this.callBtn, () => h.onCallPlay());
    const tsvg = document.createElementNS(ns, 'svg');
    tsvg.setAttribute('class', 'goal-trail');
    this.trail = document.createElementNS(ns, 'polyline');
    tsvg.append(this.trail);
    this.pad.dataset.testid = 'goal-pad';
    this.pad.append(tsvg);
    this.wind.append(this.windArrow, this.windMph);
    this.hand.innerHTML = HAND_SVG;
    this.hand.hidden = true;
    this.streak.hidden = this.ballRing.hidden = true;
    this.root.append(this.pad, this.ballRing, this.streak, this.hand, this.arc, this.addBtn, this.callBtn, this.wind);
    this.wireSwipe();
    window.addEventListener('keydown', (e) => {
      const v = this.view;
      if (!v || e.repeat) return;
      const k = e.key.toLowerCase();
      if ((k === 'h' || k === ' ') && v.ruck?.canAdd) h.onAddPlayer();
      if (k === 'c' && v.callChip) h.onCallPlay();
      if (k === 'g' && v.goalSwipe) h.onStraightKick();
    });
  }

  update(v: AddendumView): void {
    this.view = v;
    const r = v.ruck;
    this.arc.hidden = !r || (!r.on && !v.ruckWord);
    if (r) {
      this.arc.style.left = `${r.x}px`;
      this.arc.style.top = `${r.y}px`;
      this.fill.setAttribute('d', arcPath(r.chance / 100));
      this.arc.classList.toggle('defending', r.defending);
    }
    this.word.textContent = v.ruckWord;
    this.addBtn.hidden = !r?.canAdd;
    this.callBtn.hidden = !v.callChip;
    this.pad.hidden = !v.goalSwipe;
    if (!v.goalSwipe) this.trail.setAttribute('points', '');
    // The kick-off hand shows at every kick-off (Jonny, 14 Nov 2026); the goal kick's only until the first swipe.
    const g = v.goalSwipe && (v.swipeKind === 'kickoff' || !this.handDone[v.swipeKind]) ? v.goalLine : null;
    this.hand.hidden = this.streak.hidden = this.ballRing.hidden = !g;
    if (g) {
      // From the ball most of the way to the target, on a loop, a white streak growing behind it.
      const k = this.t.goal.handReach;
      const dx = (g.px - g.bx) * k;
      const dy = (g.py - g.by) * k;
      for (const n of [this.hand, this.streak, this.ballRing]) {
        n.style.left = `${g.bx}px`;
        n.style.top = `${g.by}px`;
      }
      this.hand.style.setProperty('--dx', `${dx}px`);
      this.hand.style.setProperty('--dy', `${dy}px`);
      this.streak.style.width = `${Math.hypot(dx, dy)}px`;
      this.streak.style.transform = `rotate(${Math.atan2(dy, dx)}rad)`;
    }
    this.windMph.textContent = `${v.wind.mph} mph`;
    this.windArrow.style.transform = `rotate(${v.wind.arrowDeg}deg)`;
  }

  /** From touch down to lift: direction and speed; the lime trail follows the finger. */
  private wireSwipe(): void {
    let id = -1;
    let pts: { x: number; y: number; t: number }[] = [];
    const draw = () => this.trail.setAttribute('points', pts.map((p) => `${p.x},${p.y}`).join(' '));
    this.pad.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      id = e.pointerId;
      this.pad.setPointerCapture(e.pointerId);
      pts = [{ x: e.clientX, y: e.clientY, t: performance.now() }];
      draw();
    });
    this.pad.addEventListener('pointermove', (e) => {
      if (e.pointerId !== id) return;
      pts.push({ x: e.clientX, y: e.clientY, t: performance.now() });
      if (pts.length > this.t.goal.trailPoints) pts.shift();
      draw();
    });
    this.pad.addEventListener('pointerup', (e) => {
      if (e.pointerId !== id) return;
      id = -1;
      const first = pts[0];
      if (!first) return;
      const dx = e.clientX - first.x;
      const dy = first.y - e.clientY;
      const len = Math.hypot(dx, dy);
      const secs = Math.max(0.03, (performance.now() - first.t) / 1000);
      if (len >= this.t.goal.minSwipePx && dy > 0) {
        this.h.onSwipe(dx, dy, len / secs);
        const kind = this.view?.swipeKind ?? 'goal';
        if (!this.handDone[kind]) writeFlag(HAND_KEY[kind]);
        this.handDone[kind] = true;
      }
    });
    this.pad.addEventListener('pointercancel', () => (id = -1));
  }
}

/** A half-ring arc from the left, filled to fraction k (0 to 1). */
function arcPath(k: number): string {
  const a = Math.PI * Math.max(0.001, Math.min(1, k));
  const r = 40;
  return `M ${-r} 0 A ${r} ${r} 0 0 1 ${(-r * Math.cos(a)).toFixed(2)} ${(-r * Math.sin(a)).toFixed(2)}`;
}

const HAND_KEY = { goal: 'rugby.hints.goalHand', kickoff: 'rugby.hints.kickoffHand' } as const;

/** A per-device convenience: if storage is blocked the hand just shows again. */
function readFlag(key: string): boolean {
  try {
    return localStorage.getItem(key) === '1';
  } catch {
    return false;
  }
}

function writeFlag(key: string): void {
  try {
    localStorage.setItem(key, '1');
  } catch {
    // Storage blocked: the hand shows again next time.
  }
}

/** A white pointing hand, fingertip at the top centre (0, 0 of its box is offset in CSS). */
const HAND_SVG = `<svg viewBox="0 0 48 64" aria-hidden="true"><path d="M20 4a5 5 0 0 1 10 0v22l2-1a5 5 0 0 1 6 3l1 1a5 5 0 0 1 6 4v14c0 9-7 16-16 16h-4c-6 0-10-3-13-8L4 40a5 5 0 0 1 8-6l8 8z" fill="currentColor" stroke="rgb(0 0 0 / 0.55)" stroke-width="2.5" stroke-linejoin="round"/></svg>`;
