import { brandAsset, loadBrandSvg } from '../brand/loadBrand';
import type { Brand } from '../brand/types';
import { el, onTap } from './dom';

/** The loader: the 4x4 pixel grid flickering (docs/BRAND.md placement 12). */
export function gridLoader(): HTMLElement {
  const box = el('div', 'fe-loader');
  box.dataset.testid = 'loader';
  for (let i = 0; i < 16; i++) {
    const c = el('span');
    // A fixed scatter so cells do not blink in reading order.
    c.style.animationDelay = `${((i * 7) % 16) * 0.06}s`;
    box.append(c);
  }
  return box;
}

/**
 * The title screen (GDD section 11 screen 1, reference/21): animated logo, title, tagline, TAP TO PLAY. Every word,
 * colour and logo comes from brand.json. The tap goes straight into a match (Jonny, 16 Nov: no menu or team
 * select), and it is the gesture that lets the sound start.
 */
export class FrontEnd {
  readonly root = el('div', 'fe');
  private screen: HTMLElement | null = null;
  private resolve: () => void = () => {};
  private logo: Promise<SVGSVGElement | null>;

  constructor(private brand: Brand) {
    this.root.dataset.testid = 'front-end';
    if (brand.title?.hero) this.root.style.setProperty('--fe-hero', `url("${brandAsset(brand, brand.title.hero)}")`);
    this.logo = brand.logo.animatedSvg ? loadBrandSvg(brand, brand.logo.animatedSvg) : Promise.resolve(null);
    this.root.append(el('div', 'fe-bg'));
  }

  /** Resolves when TAP TO PLAY is tapped. */
  run(): Promise<void> {
    void this.showTitle();
    return new Promise((res) => (this.resolve = res));
  }

  private swap(next: HTMLElement): void {
    this.screen?.remove();
    this.screen = next;
    this.root.append(next);
  }

  /** The game's name as brand.json sets it out: lines of big type (some in the accent) and the format line. */
  private wordmark(skipName: boolean): HTMLElement {
    const box = el('div', 'fe-wordmark big');
    const all = this.brand.title?.lines ?? [{ text: this.brand.name }, { text: this.brand.gameSubtitle, accent: true }];
    // Under the animated logo, the line that just repeats the brand's name is left out.
    const lines = skipName ? all.filter((l) => l.text.toLowerCase() !== this.brand.name.toLowerCase()) : all;
    for (const l of lines) box.append(el('div', l.accent ? 'fe-line accent' : 'fe-line', l.text.toUpperCase()));
    const fmt = this.brand.title?.formatLine;
    if (fmt) box.append(el('div', 'fe-format', fmt.toUpperCase()));
    return box;
  }

  private async showTitle(): Promise<void> {
    const s = el('section', 'fe-screen fe-title');
    s.dataset.testid = 'title-screen';
    const logoBox = el('div', 'fe-logo');
    const head = el('div', 'fe-title-head');
    const logo = await this.logo;
    if (logo) logoBox.append(logo);
    head.append(logoBox, this.wordmark(logo !== null));
    const tag = el('div', 'fe-tagline');
    tag.append(el('span', 'fe-rule'), el('span', '', this.brand.tagline.toUpperCase()), el('span', 'fe-rule'));
    head.append(tag);
    const tap = el('button', 'fe-tap');
    tap.dataset.testid = 'tap-to-play';
    tap.append(el('span', 'fe-tap-ring'), el('span', 'fe-tap-ring two'), el('span', 'fe-tap-label', 'TAP TO PLAY'));
    const mark = el('img', 'fe-corner-mark');
    mark.src = brandAsset(this.brand, this.brand.logo.mark);
    mark.alt = '';
    s.append(mark, head, tap);
    // The whole screen is the button, as the words say.
    onTap(s, () => this.resolve());
    this.swap(s);
  }

  /** After TAP TO PLAY: the loader until the match is ready. */
  loading(): void {
    const s = el('section', 'fe-screen fe-loading');
    s.append(gridLoader(), el('div', 'fe-loading-text', 'LOADING'));
    this.swap(s);
  }

  close(): void {
    this.root.remove();
  }
}
