import type { Rng } from './rng';
import type { Ratings } from './types';
import type { Tunables } from './tunables';

/** The four attack plays (GDD 6.3). */
export type PlayCard = 'CRASH' | 'WIDE' | 'SWITCH' | 'CHIP';
export const PLAY_CARDS: readonly PlayCard[] = ['CRASH', 'WIDE', 'SWITCH', 'CHIP'];

/** How the AI defence sets up for a restart, hidden from the user; one card is strong against each. */
export type DefenceShape = 'RUSH' | 'NARROW' | 'DRIFT' | 'HIGH';
export const DEFENCE_SHAPES: readonly DefenceShape[] = ['RUSH', 'NARROW', 'DRIFT', 'HIGH'];

/** GDD 6.3: CRASH BALL sucks in a narrow, fast line; GO WIDE beats a narrow one on the edge; SWITCH beats the drift; CHIP beats a high line. */
export const STRONG_AGAINST: Record<DefenceShape, PlayCard> = { RUSH: 'CRASH', NARROW: 'WIDE', DRIFT: 'SWITCH', HIGH: 'CHIP' };

/** Lineout jumpers (GDD 6.10). */
export type Jumper = 0 | 1 | 2;
export const JUMPERS = ['FRONT', 'MIDDLE', 'BACK'] as const;

/**
 * Lineout (GDD 7): clean win if the defence did not guess the jumper, 90 + (LIN - 70) / 3; guessed, a contest
 * 50 + (ourLIN - theirLIN) / 2. A throw off the sweet spot costs 20 (and may not be straight: see notStraightPct).
 */
export function lineoutWinChance(ourLin: number, theirLin: number, guessed: boolean, onSpot: boolean, t: Tunables): number {
  const l = t.lineout;
  const base = guessed ? l.contestBase + (ourLin - theirLin) / 2 : l.cleanBase + (ourLin - 70) / 3;
  return Math.max(l.min, Math.min(l.max, base - (onSpot ? 0 : l.offSpotPenalty)));
}

/** Where the throw marker is on the timing bar at time s (0 to 1, back and forth). */
export function throwMarker(seconds: number, t: Tunables): number {
  const ph = (seconds / t.lineout.barSeconds) % 2;
  return ph < 1 ? ph : 2 - ph;
}

export function onSweetSpot(marker: number, t: Tunables): boolean {
  return Math.abs(marker - t.lineout.sweetCentre) <= t.lineout.sweetHalf;
}

/** Average of one rating over a few players. */
export function avgRating(players: { ratings: Ratings }[], key: keyof Ratings): number {
  return players.reduce((n, p) => n + p.ratings[key], 0) / Math.max(1, players.length);
}

/**
 * Scrum (GDD 7). The user taps the PUSH meter three times; each tap in the zone is a hit. Feeding: 2 of 3 is clean
 * ball, 1 of 3 scrappy (kept at keepOnOnePct), none lost; 3 of 3 with a 10+ rating edge, a chance of a penalty.
 * Defending the feed: hits give a chance to steal. The SCR difference moves every chance a little.
 */
export function scrumOutcome(hits: number, userFeeds: boolean, ourScr: number, theirScr: number, t: Tunables): { keepPct: number; penaltyPct: number } {
  const s = t.scrum;
  const edge = (ourScr - theirScr) * s.perScrPoint;
  if (userFeeds) {
    const keep = hits >= 2 ? 100 : hits === 1 ? s.keepOnOnePct + edge : s.keepOnNonePct + edge;
    const pen = hits >= 3 && ourScr - theirScr >= s.penaltyEdge ? s.penaltyPct : hits >= 3 ? s.penaltyPctNoEdge : 0;
    return { keepPct: Math.max(0, Math.min(100, keep)), penaltyPct: pen };
  }
  // The away side feeds: its keep chance falls with the user's hits.
  const steal = hits >= 3 ? s.stealOnThreePct : hits === 2 ? s.stealOnTwoPct : 0;
  return { keepPct: Math.max(0, Math.min(100, 100 - steal - edge)), penaltyPct: 0 };
}

/** Where the scrum needle points at time s (0 to 1 round the dial). */
export function scrumNeedle(seconds: number, t: Tunables): number {
  return (seconds / t.scrum.needleSeconds) % 1;
}

export function inScrumZone(needle: number, t: Tunables): boolean {
  return Math.abs(needle - t.scrum.zoneCentre) <= t.scrum.zoneHalf;
}

/**
 * Goal kicks (GDD 7): 96 - 1.1 x max(0, distance - 22), less the miss for letting go away from the middle of the
 * green band on the power ring. No wind in phase 1.
 */
export function goalChance(distanceM: number, powerOffset: number, t: Tunables): number {
  const g = t.goal;
  return Math.max(g.min, Math.min(g.max, g.base - g.perMOver * Math.max(0, distanceM - g.freeM) - g.offsetPenalty * Math.abs(powerOffset)));
}

/** Wind for the match: speed (mph) and direction across the pitch (world x), addendum 4. */
export function rollWind(rng: Rng, t: Tunables): { mph: number; dirX: -1 | 1 } {
  return { mph: Math.round(rng.next() * t.goal.windMaxMph), dirX: rng.next() < 0.5 ? -1 : 1 };
}

/** How far a swiped kick at power 0 to 1 carries (metres). */
export function kickReach(power: number, t: Tunables): number {
  const g = t.goal;
  return g.reachMinM + Math.max(0, Math.min(1, power)) * (g.reachMaxM - g.reachMinM);
}

/** The power that just reaches `metres`. */
export function powerFor(metres: number, t: Tunables): number {
  const g = t.goal;
  return Math.max(0, Math.min(1, (metres - g.reachMinM) / (g.reachMaxM - g.reachMinM)));
}

/** The heading (radians from straight up the pitch, positive toward +x) that aims dead centre at the posts. */
export function aimAngle(from: { x: number; z: number }, posts: { x: number; z: number }): number {
  return Math.atan2(posts.x - from.x, Math.abs(posts.z - from.z));
}

export interface SwipeKick {
  good: boolean;
  short: boolean;
  /** Metres wide of the middle of the posts where it crosses their line (signed, world x). */
  missX: number;
  distance: number;
  why: string;
}

/**
 * A swiped kick at goal (addendum 4): the angle sets the direction, the swipe speed the power, the wind drifts
 * it, the kicker's KCK and over-hitting add scatter. Good when it carries to the posts between the uprights.
 */
export function swipeKick(from: { x: number; z: number }, posts: { x: number; z: number }, angle: number, power: number, wind: { mph: number; dirX: -1 | 1 }, kick: number, rng: Rng, t: Tunables): SwipeKick {
  const g = t.goal;
  const along = Math.abs(posts.z - from.z);
  const distance = Math.hypot(posts.x - from.x, along);
  const reach = kickReach(power, t);
  const over = Math.max(0, power - powerFor(distance, t));
  const scatterSd = (100 - kick) * g.scatterPerPoint * distance + over * g.overPowerScatter * distance;
  const xAtPosts = from.x + Math.tan(angle) * along + wind.dirX * wind.mph * g.driftPerMph * distance + (rng.next() * 2 - 1) * scatterSd;
  const missX = xAtPosts - posts.x;
  const short = reach < distance;
  const good = !short && Math.abs(missX) <= t.goalpost.uprightGapM / 2;
  const why = short
    ? `Kick ${Math.round(reach)} m, needed ${Math.round(distance)} m: SHORT`
    : `Kick ${Math.round(distance)} m, wind ${wind.mph} mph, ${Math.abs(missX).toFixed(1)} m ${missX < 0 ? 'left' : 'right'} of centre: ${good ? 'GOOD' : 'WIDE'}`;
  return { good, short, missX, distance, why };
}
